//! Agent supervisor module
//!
//! Houses the per-session ledger, SESSION_STATE / SESSION_SIDEBAND broadcast
//! senders, the CODE_INPUT dispatcher, and the state machine that owns the
//! spawn/dispatch/merge lifecycle for Claude Code sessions.
//!
//! # Lock-order invariant
//!
//! The supervisor holds three async mutexes: the outer ledger map, the
//! `client_sessions` map, and per-session `Mutex<LedgerEntry>` entries
//! reached through the outer map. To avoid deadlock, all code in this module
//! acquires locks in the following order and never in reverse:
//!
//! 1. **Ledger outer mutex** (`self.ledger`).
//! 2. **`client_sessions` mutex** (`self.client_sessions`) — may be acquired
//!    while the ledger mutex is held, during an atomic get-or-insert +
//!    affinity update.
//! 3. **Per-session `Mutex<LedgerEntry>`** — acquired only after releasing
//!    the outer locks, never while the outer locks are held.
//!
//! The TOCTOU fix for [R06] depends on this ordering: `do_spawn_session` and
//! `do_close_session` take the ledger mutex + `client_sessions` mutex as a
//! single atomic critical section so a concurrent close/spawn cannot
//! interleave between the ledger mutation and the affinity mutation.
//!
use std::collections::{BTreeMap, HashMap, HashSet, VecDeque};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex as StdMutex};
use std::time::{Duration, Instant};

use thiserror::Error;
use tokio::sync::{Mutex, broadcast, mpsc, watch};
use tokio_stream::StreamExt;
use tokio_stream::wrappers::ReceiverStream;
use tokio_util::sync::CancellationToken;
use tracing::{debug, warn};
use tugcast_core::protocol::{FeedId, Frame, TugSessionId};

use super::agent_bridge::{
    ChildSpawner, CrashBudget, DEFAULT_RETRY_DELAY, SessionMode, TugcodeSpawner, run_session_bridge,
};
use super::code::{parse_tug_session_id, splice_tug_session_id};
use super::session_metadata::{
    is_activity_delta, is_background_tasks_changed, is_rate_limit_event, is_session_capabilities,
    is_system_metadata, is_task_edge, is_task_progress, is_tool_use, is_turn_end, is_wake_started,
};
use super::session_scoped::SessionScopedFeed;
use super::workspace_registry::{WorkspaceError, WorkspaceKey, WorkspaceRegistry};
#[cfg(test)]
use tugcast_core::LagPolicy;

/// Capacity of per-session CODE_INPUT buffering queues.
pub const BOUNDED_QUEUE_CAP: usize = 256;

/// WebSocket connection identifier. Matches the router's existing
/// `client_id_counter` type.
pub type ClientId = u64;

/// The card-id prefix a tripwire's own session carries.
///
/// `spawn_headless_session` writes it and the tripwire engine reads it back
/// off a fact's session: a fact from a tripwire's session never trips
/// anything, because a work-tier tripwire that re-tripped on its own commits
/// would be a loop with no floor. Writer and reader share the one definition
/// so the two halves cannot drift apart.
pub(crate) const TRIPWIRE_CARD_PREFIX: &str = "tripwire:";

// ---------------------------------------------------------------------------
// SpawnState
// ---------------------------------------------------------------------------

/// Lifecycle state of a session's backing subprocess.
///
/// The allowed transitions follow the internal supervisor state machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpawnState {
    /// Intent registered, no subprocess yet.
    Idle,
    /// Subprocess starting; CODE_INPUT is being buffered in the per-session queue.
    Spawning,
    /// Subprocess running normally.
    Live,
    /// Crash budget exhausted; awaiting `reset_session`.
    Errored,
    /// Session explicitly closed by `close_session`.
    Closed,
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum SpawnStateError {
    #[error("invalid spawn-state transition: {from:?} -> {to:?}")]
    InvalidTransition { from: SpawnState, to: SpawnState },
}

impl SpawnState {
    /// Attempt to advance the state machine. Returns `Err` if the transition
    /// is not permitted by the supervisor's guard rules.
    pub fn try_transition(&mut self, next: SpawnState) -> Result<(), SpawnStateError> {
        use SpawnState::*;
        let allowed = matches!(
            (*self, next),
            // Normal happy path
            (Idle, Spawning)
                | (Spawning, Live)
                // Failure paths
                | (Spawning, Errored)
                | (Live, Errored)
                // Close paths (close is legal from any non-terminal state;
                // `Spawning → Closed` covers the "user kills card while
                // subprocess is coming up" case)
                | (Idle, Closed)
                | (Spawning, Closed)
                | (Live, Closed)
                | (Errored, Closed)
                // Reset paths (close → re-arm)
                | (Closed, Idle)
                | (Errored, Idle)
        );
        if allowed {
            *self = next;
            Ok(())
        } else {
            Err(SpawnStateError::InvalidTransition {
                from: *self,
                to: next,
            })
        }
    }
}

// ---------------------------------------------------------------------------
// BoundedQueue
// ---------------------------------------------------------------------------

/// Result of pushing onto a [`BoundedQueue`]. Marked `#[must_use]` so callers
/// cannot silently drop frames on overflow — every push site must either
/// branch on the result or explicitly acknowledge the known-safe invariant.
#[must_use]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueuePush {
    /// Item accepted.
    Ok,
    /// Queue at capacity — item dropped.
    Overflow,
}

/// Fixed-capacity FIFO queue used to buffer CODE_INPUT frames during the
/// `Spawning` window. Pushes past capacity are dropped and signalled to the
/// caller.
#[derive(Debug)]
pub struct BoundedQueue<T> {
    inner: VecDeque<T>,
    cap: usize,
}

impl<T> BoundedQueue<T> {
    /// Construct a queue with the default capacity ([`BOUNDED_QUEUE_CAP`]).
    pub fn new() -> Self {
        Self::with_capacity(BOUNDED_QUEUE_CAP)
    }

    /// Construct a queue with an explicit capacity.
    pub fn with_capacity(cap: usize) -> Self {
        Self {
            inner: VecDeque::with_capacity(cap),
            cap,
        }
    }

    /// Maximum number of items the queue will hold.
    #[cfg(test)]
    pub fn capacity(&self) -> usize {
        self.cap
    }

    /// Current item count.
    #[cfg(test)]
    pub fn len(&self) -> usize {
        self.inner.len()
    }

    /// `true` if empty.
    #[cfg(test)]
    pub fn is_empty(&self) -> bool {
        self.inner.is_empty()
    }

    /// Push an item; returns [`QueuePush::Overflow`] if at capacity.
    pub fn push(&mut self, item: T) -> QueuePush {
        if self.inner.len() >= self.cap {
            QueuePush::Overflow
        } else {
            self.inner.push_back(item);
            QueuePush::Ok
        }
    }

    /// Push an item at the **front** of the queue; returns
    /// [`QueuePush::Overflow`] if at capacity.
    ///
    /// Used by [`AgentSupervisor::do_request_replay`] (Step R4 / [D12])
    /// to ensure a `request_replay` verb queued during the Spawning
    /// window drains *before* any CODE_INPUT (user_message) the
    /// dispatcher may have buffered. This makes the verb's
    /// "rehydrate the freshly-mounted store" semantics precede any
    /// user input arriving in the same window — relevant for the
    /// Smoke D mid-turn case where the user types instantly after
    /// rebind. See [Phase A-R3](arc/tugplan-dev-transcript-resume.md#phase-a-r3)
    /// for the broader coordination story; R4's front-push is the
    /// minimum needed to keep cold-boot Spawning-window ordering
    /// sane without solving Smoke D end-to-end.
    pub fn push_front(&mut self, item: T) -> QueuePush {
        if self.inner.len() >= self.cap {
            QueuePush::Overflow
        } else {
            self.inner.push_front(item);
            QueuePush::Ok
        }
    }

    /// Pop the oldest item.
    pub fn pop(&mut self) -> Option<T> {
        self.inner.pop_front()
    }

    /// The queued items, oldest first, without consuming them — so a test can
    /// read what a dispatch left behind and still assert on it again.
    #[cfg(test)]
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        self.inner.iter()
    }
}

impl<T> Default for BoundedQueue<T> {
    fn default() -> Self {
        Self::new()
    }
}

// ---------------------------------------------------------------------------
// LedgerEntry
// ---------------------------------------------------------------------------

/// A segment's staged **provenance** ([P04]) — what a `session_segment`
/// announcement carried, waiting for the `session_init` that names its id.
///
/// Provenance only. Identity is the line's and the entry already knows which
/// line that is, so there is nothing here to inherit and nothing a mismatch
/// could strand.
#[derive(Debug, Clone)]
pub struct PendingSegment {
    /// The new claude session id this announcement precedes the init of.
    pub new_session_id: String,
    /// The session being left: the one a rewind forked from, the one a
    /// rotation replaced, the one a respawn re-identified away from.
    pub parent_session_id: String,
    /// What made the id change. Only `new` births a line ([P03]).
    pub kind: String,
    /// The prompt uuid of the rewind point, or `None` for a stage rotation.
    ///
    /// A stage has no branch point because nothing was copied, and the column
    /// is written `NULL` rather than given an invented value: the provenance
    /// columns are what tells a rewind from a rotation.
    pub fork_point: Option<String>,
    /// What a rotation seated this session as — the stage label the divider
    /// renders — or `None` for a rewind-fork, which seats nothing ([P10]).
    pub stage_label: Option<String>,
    /// The model the rotation seated it on, or `None` for the account default.
    pub stage_model: Option<String>,
}

/// What opened a turn — the distinction [P02] rests on.
///
/// A turn the *harness* opened is not a turn the stage was asked. A
/// backgrounded job completing re-invokes the model with a
/// `<task-notification>`, and that re-invocation ends a turn like any other;
/// six of them in a row are six turn ends and exactly one ask. The arc
/// runner's quiet-turn horizon counts answers, so it counts only the turns a
/// prompt opened, and that is the whole of what this enum is for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TurnOpener {
    /// A `user_message` reached the dispatcher — somebody, or the wheel,
    /// asked.
    Prompt,
    /// A `wake_started` marker opened it — the harness did.
    Wake,
}

/// Per-session ledger record, keyed by [`TugSessionId`] in the supervisor.
///
/// Shape follows the supervisor ledger contract. Notably, there is no
/// `ReplayBuffer` field — the CODE_OUTPUT replay buffer stays shared at the
/// router level per [D06]; the supervisor only routes `system_metadata`
/// per-session.
pub struct LedgerEntry {
    /// Client-authoritative UUID for this session.
    pub tug_session_id: TugSessionId,
    /// Populated once `session_init` arrives from the subprocess.
    pub claude_session_id: Option<String>,
    /// Canonical `WorkspaceKey` returned by `WorkspaceRegistry::get_or_create`.
    /// Used by `do_close_session` to call `registry.release`.
    pub workspace_key: WorkspaceKey,
    /// Caller-supplied path (pre-canonicalization). Passed to
    /// `ChildSpawner::spawn_child` in `run_session_bridge` as the spawned
    /// Claude Code process's cwd, and retained for reset-session to
    /// respawn without losing the binding.
    pub project_dir: PathBuf,
    /// User's spawn-time new-vs-resume choice.
    /// Forwarded as `--session-mode new|resume` to the tugcode subprocess.
    /// Reconnects reuse this value so the tugcode side of the session
    /// doesn't flip modes mid-life.
    pub session_mode: SessionMode,
    /// Deck-wide / per-card default permission mode tugdeck resolved at the
    /// first `spawn_session` for this session, forwarded to the tugcode
    /// subprocess as `--permission-mode` so the spawned claude starts in the
    /// right mode. Set once on the fresh insert and preserved across reconnects
    /// / crash-loop respawns (like `session_mode`) so the tugcode side doesn't
    /// flip modes mid-life. `None` when tugdeck sent no mode — tugcode keeps
    /// its own default.
    pub permission_mode: Option<String>,
    /// Provisional mnemonic tag tugdeck minted "from the drop" and sent on the
    /// first `spawn_session`. Set once on the fresh insert and preserved across
    /// reconnects (like `permission_mode`); the ledger's `record_spawn` claims
    /// or suffixes it authoritatively, and the final value rides back on
    /// `session_updated`. `None` when tugdeck sent no tag. Tug-side only — never
    /// forwarded into the child spawn args ([P07]).
    pub tag: Option<String>,
    /// The line of work this card is on ([P01]). Every segment the bridge
    /// records joins it **by reference** — the entry is asked, never the
    /// ledger — which is what makes an id change cost nothing to attach.
    ///
    /// `None` only between [`LedgerEntry::new`] and the spawn payload's
    /// arrival: `do_spawn_session` sets it from the payload (or, on a resume
    /// that carries none, from the row it is resuming), and
    /// `rebind_from_ledger` sets it from the row.
    pub line_id: Option<String>,
    /// Announced segments waiting for the `session_init` that names them
    /// ([P04]).
    ///
    /// A **queue**, not a slot: two announcements can be in flight before
    /// either init arrives, and a single slot let the second overwrite the
    /// first — which left one segment attached to nothing. Each init takes
    /// the entry whose `new_session_id` matches, so an init for anything else
    /// cannot consume one.
    pub pending_segments: std::collections::VecDeque<PendingSegment>,
    /// Lifecycle state.
    pub spawn_state: SpawnState,
    /// Whether a tugcode subprocess for this entry has ever reached `Live`
    /// **in this tugcast process**.
    ///
    /// The one fact that tells the two `Idle`s apart, and they mean opposite
    /// things to anything judging a card. An entry rebound from tugbank at
    /// startup sits `Idle` because nothing has spawned it yet — a wait, and
    /// reading it as a death would stop every in-flight arc on every relaunch
    /// ([`crate::feeds::arc_runner`]). An entry that ran here and is
    /// `Idle` again lost the child it was running: a killed claude, a reset.
    /// That is not a wait, and the ninety seconds an arc spent sitting over
    /// one is what this field exists to end.
    ///
    /// In memory on purpose, like [`Self::context_window_tokens`]: it is a
    /// claim about *this* process's own observations, so a restart clearing it
    /// is the correct reading rather than lost state.
    pub ever_live_here: bool,
    /// Whether this entry currently owns a `WorkspaceRegistry` refcount for its
    /// `workspace_key`. Exactly one refcount belongs to a live entry for its
    /// lifetime; this flag is the single authority for who releases it.
    ///
    /// A fresh spawn (or the first spawn of an entry rebound from the ledger)
    /// adopts the `get_or_create` refcount and sets this `true`; a genuine
    /// reconnect of an entry that already owns one releases the excess and
    /// leaves this `true`; `do_close_session` releases iff this is `true`.
    ///
    /// Critically, an entry rebound by `rebind_from_ledger` starts `false` — the
    /// rebind registers no workspace (lazy, to avoid a boot-time canonicalize /
    /// TCC storm) — so `!inserted` alone must NOT be read as "a refcount is
    /// held." That mis-read tore down a resumed project's workspace on restore.
    pub holds_workspace_refcount: bool,
    /// Per-session crash budget (3 crashes / 60s by convention).
    pub crash_budget: CrashBudget,
    /// CODE_INPUT buffer used during the `Spawning` window.
    pub queue: BoundedQueue<Frame>,
    /// Latest `system_metadata` payload for this session, for on-subscribe
    /// replay per [D14].
    pub latest_metadata: Option<Frame>,
    /// Latest `session_capabilities` payload for this session, for
    /// on-subscribe replay. Distinct from `latest_metadata`: capabilities
    /// (the turn-free `initialize` model list / command catalog) are
    /// broadcast once per spawn, so a card that subscribes *after* that
    /// frame flew — reconnect, HMR remount, a late-binding card — would
    /// otherwise never see the model list and the `/model` picker would
    /// have no data. Retained here and replayed on bind, the same shape
    /// `latest_metadata` uses for `system_metadata`. In-memory only (not
    /// persisted to sqlite): capabilities are re-emitted fresh on the
    /// next spawn's handshake, so they need not survive a tugcast restart.
    pub latest_capabilities: Option<Frame>,
    /// Latest `rate_limit_event` payload for this session, for
    /// on-subscribe replay. Distinct slot from `latest_metadata` /
    /// `latest_capabilities`: the per-turn quota broadcast carries the
    /// Z4B rate-limit chip's state, and a card that binds *after* the
    /// last broadcast flew (reconnect, HMR remount) would otherwise show
    /// no quota state until the next turn re-broadcasts. That tail
    /// matters most precisely when the session is hard rate-limited — the
    /// user cannot start a turn to refresh it — so the last-known frame
    /// is replayed on bind, the same shape `latest_capabilities` uses.
    /// In-memory only (not persisted to sqlite): `resetsAt` is an
    /// absolute time that self-corrects on the next live broadcast, so a
    /// stale value need not survive a tugcast restart.
    pub latest_rate_limit: Option<Frame>,
    /// OS pid of the live tugcode child, captured at spawn as the activity
    /// sampler's subtree root ([P08]). `None` between spawns (before the
    /// bridge spawns, and after the relay tears the child down).
    pub child_pid: Option<u32>,
    /// When this entry last lost its child with nothing having replaced it —
    /// `None` while a child is running, and while none has ever run.
    ///
    /// **The fact that makes a dead stage sayable.** `spawn_state` says what
    /// the *bridge* believes, and a bridge whose child crashed is retrying, so
    /// it goes on saying `Live` — correctly, for the second it takes to spawn
    /// again. What it cannot say is that the retry never came back. Driven in
    /// `at0505`: the stage's tugcode is killed, nothing replaces it, tugcast
    /// holds no child for the card at all, and the entry reads `Live`
    /// indefinitely — so `session_live` was true over a session with no
    /// process, and the arc had no reason to stop and no reason to move.
    ///
    /// A stamp rather than a flag, because the honest reading is a *duration*:
    /// a child gone for a second is a respawn in flight, and a child gone for
    /// [`CHILD_GONE_GRACE`] is a session that is not coming back. The reader
    /// is [`crate::feeds::arc_runner`]'s `session_snapshot`, which is the
    /// one place that turns this into `SessionGone`.
    ///
    /// In memory, like [`Self::context_window_tokens`]: it is a claim about
    /// this process's own observations, and a restart clearing it is the right
    /// reading rather than lost state.
    pub child_gone_at: Option<std::time::Instant>,
    /// The child's process start time (seconds since epoch), captured
    /// alongside `child_pid` as the PID-reuse guard baseline ([P20]). The
    /// sampler attributes the subtree only while the live pid's start time
    /// still matches this. `None` between spawns.
    pub child_start_time: Option<u64>,
    /// True while a turn is in flight — set by the dispatcher's inbound
    /// `user_message` intercept (and the merger's `wake_started` marker),
    /// cleared when the merger sees `turn_complete` / `turn_cancelled` or
    /// the relay tears the child down. The activity sampler attributes OS
    /// work only while this is set: Pulse measures the session *working*,
    /// not the idle claude process's event-loop heartbeat.
    pub turn_active: bool,
    /// How many turns the claude session named by `claude_session_id` has
    /// ended — counted at the same edge that clears `turn_active`, reset
    /// when a `session_init` names a different claude session, and seeded
    /// from the ledger row on rebind. Zero is the state between a spawn and
    /// its first `turn_complete`: seated, idle, and never yet run.
    pub turns_ended: u32,
    /// What opened the turn now in flight, or `None` between turns and for a
    /// turn whose opener was never recorded ([P02]).
    ///
    /// Written `Prompt` by the dispatcher's `user_message` intercept and
    /// `Wake` by the merger's `wake_started` fold; cleared at the same edge
    /// that increments `turns_ended`. A turn tugcast inherited across a
    /// restart has none, and an absent opener counts as `Prompt` at the
    /// turn's end — today's behaviour, and the direction Risk R05 accepts.
    pub turn_opener: Option<TurnOpener>,
    /// How many of `turns_ended` were opened by a prompt — the count the arc
    /// runner's horizon, its `stage_turn_ended`, and its in-flight retirement
    /// read ([P02]). An unrecorded opener counts here.
    pub prompt_turns_ended: u32,
    /// How many of `turns_ended` were opened by a wake. Still motion for the
    /// arc's clock and still an idle edge for the settle; never an answer.
    pub wake_turns_ended: u32,
    /// The most recent turn ended in an API error (`turn_complete` with
    /// `is_api_error`) — the stage did not run. Overwritten at every turn end,
    /// reset when a `session_init` names a different claude session.
    pub turn_api_error: bool,
    /// The most recent turn was cancelled **by the user** (`turn_cancelled`
    /// with no `is_recovery` marker). Overwritten at every turn end, reset
    /// when a `session_init` names a different claude session.
    ///
    /// A user cancel only, because that reset cannot cover the other kind:
    /// tugcode's wedge recovery force-terminates claude and respawns
    /// `--resume` against the *same* claude id, so no `session_init` ever
    /// names a different one and the flag would latch on a session that is
    /// still alive and still working. The cause rides the frame instead.
    pub turn_cancelled: bool,
    /// The step this session closed (`arc step done` / `withdraw`) **in the
    /// turn now in flight**, or `None` when the turn has closed none.
    ///
    /// The turn boundary is the single most load-bearing discipline in an
    /// arc: the Wheel acts only between turns, so a stage that closes a
    /// step and keeps working locks it out of pacing, `/compact`, rotation and
    /// the idle clock alike. Enforcing that needs one fact the PreToolUse hook
    /// cannot have — the hook is a fresh process with no notion of a turn, and
    /// turns are tugcast's. So the verb reports the close here, the gate asks,
    /// and this clears at the same edge that increments `turns_ended`.
    ///
    /// In memory, like `deck_model` and `context_window_tokens`: a restart
    /// drops it, and dropping it degrades the gate **open**, which is the only
    /// direction a gate over ordinary editing may fail in.
    pub step_closed_this_turn: Option<u32>,
    /// Background jobs this session has launched and not yet seen end, from
    /// claude's `task_id` to the job's **liveness stamp** — a `Bash` or an
    /// `Agent` running with `run_in_background: true`, and the `Monitor`
    /// watchers that share their lifecycle.
    ///
    /// `turn_active` alone cannot answer whether a session is finished. A turn
    /// ends the moment the model stops speaking; work it backgrounded — a test
    /// sweep, a subagent — keeps running, and its completion wakes a *new*
    /// turn. So between the `turn_complete` and that wake there is a window
    /// where the session looks idle and is not, and this set is exactly that
    /// window. [`is_quiet`](LedgerEntry::is_quiet) is the two facts read
    /// together.
    ///
    /// Opened by `task_started`, closed by `task_updated` or `wake_started`
    /// carrying a terminal status — the wake because a job whose only terminal
    /// is claude's `task_notification` reaches this wire under no other name.
    /// Cleared wholesale when the relay tears the child down, because
    /// a job whose claude is gone will never report and a set that leaked
    /// would leave the session permanently un-quiet.
    ///
    /// **Two kinds of key live here.** A confirmed job is keyed by its
    /// `task_id`. A job that has been *launched* and not yet confirmed is
    /// keyed `launch:<tool_use_id>` — opened by the launching `tool_use`
    /// itself rather than by the `task_started` that follows it, because the
    /// window this set exists to cover starts at the launch. The incident's
    /// six background completions each opened and closed inside that window,
    /// and a latch armed only at `task_started` is a latch the runner can
    /// read around. A `task_started` naming the launch **re-keys** the entry
    /// to its `task_id`, carrying the launch's own stamp across so the reaper
    /// clocks the job from when it actually began.
    ///
    /// A provisional key is retired three ways: by the `task_started` that
    /// confirms it, by any `wake_started` (the model is speaking again, so
    /// the gap the latch covers is over), and by the reaper, which treats it
    /// exactly like any other key. That third one is what bounds Risk R02 —
    /// a `Monitor` call whose `task_started` never arrives holds the session
    /// busy until its wake or the horizon, never forever.
    ///
    /// The stamp is the guarantee layer behind those two corrections: set at
    /// the open, refreshed by `task_progress` heartbeats, and read by
    /// [`LedgerEntry::reap_stuck_jobs`] so a wire shape nothing here foresaw
    /// degrades `holders_busy` to *late*, never *forever*.
    pub open_jobs: std::collections::BTreeMap<String, std::time::Instant>,
    /// The last `model_change` selector a **WebSocket client** sent for this
    /// session — the deck's own choice ([P15]).
    ///
    /// The arc hands the card back on this value when it ends, because
    /// tugcode records a selector on its manager and reuses it for every later
    /// spawn: a card whose arc ended on the implement model would otherwise
    /// stay there. `None` means the deck never sent one, which restores as
    /// `"default"` — the honest expression of "no `--model`".
    ///
    /// Deliberately in memory rather than in the ledger: it is a live fact
    /// about a running card, and a tugcast restart mid-arc resumes on whatever
    /// the deck sends next, which its own mount restore already handles.
    /// Frames the runner originates never write it — only the dispatcher does,
    /// and the runner bypasses the dispatcher.
    pub deck_model: Option<String>,
    /// Stdin sender when `Live`.
    pub input_tx: Option<mpsc::Sender<Frame>>,
    /// Cancels the per-session worker on `close_session`.
    pub cancel: CancellationToken,
    /// Card id this session is bound to. Set on the first
    /// `spawn_session` and preserved across lifecycle transitions
    /// (close, errored, crash-exhausted) so the persisted ledger row
    /// retains the binding for client-side restore. Liveness is encoded
    /// in `spawn_state`, not by nullity of this field; the
    /// "live-elsewhere" check in `do_spawn_session` gates on
    /// `spawn_state ∈ {Spawning, Live}` plus a card mismatch.
    pub card_id: Option<String>,
    /// Count of replay brackets currently in flight on this session's
    /// outbound stream — incremented on each `replay_started` the merger
    /// observes, saturating-decremented on each `replay_complete`. The
    /// merger's `apply_outbound_turn_intercept` skips its FIFO journal-pop
    /// work while this counter is non-zero, so replay-emitted
    /// `turn_complete` frames (from `translateJsonlSession`'s
    /// committed-turn output) don't get treated as live `turn_complete`s
    /// and don't pop the user's still-pending journal row. Mid-turn-replay
    /// [Step 5.10](arc/tugplan-dev-mid-turn-replay.md#step-5) is the
    /// post-Step-5.9 fix for the HMR-mid-stream regression.
    ///
    /// Counter (not bool) because a bridge that dies between emitting
    /// `replay_started` and emitting `replay_complete` (kill -9, panic,
    /// OOM before the `finally` runs) would, with a bool, leave the gate
    /// stuck-open forever. Using `u32::saturating_sub(1)` on
    /// `replay_complete` means stray closes are no-ops rather than
    /// underflowing into an enormous u32. tugcode's `runReplay`
    /// re-entrancy guard prevents legitimate overlapping brackets, so
    /// in healthy operation the counter is 0 between brackets and 1
    /// during a bracket; the counter shape is purely defense-in-depth
    /// against bridge-crash-mid-replay leaving stale state.
    pub replay_brackets_open: u32,
    /// The resident context window after this session's latest turn, in
    /// tokens — the four-token sum of `cost_update.usage`, which tugcode
    /// documents as exactly that figure.
    ///
    /// The persisted `context_breakdown_latest` row cannot answer this: it
    /// carries the *static* half of the breakdown (`context_max` plus the
    /// session-stable categories) and deliberately no total and no `messages`
    /// category, both of which the deck derives feed-exact. So the arc's
    /// rotation reading is this window over that row's `context_max`
    /// ([P07]).
    ///
    /// In memory, like [`Self::deck_model`]: a tugcast restart drops it, and
    /// the runner's declared fallback for a missing reading is to continue the
    /// stage rather than act on a guess. It moves *live*: every
    /// `streaming_usage` frame of the open turn overwrites it, and the
    /// turn-final `cost_update` is the authoritative last write. A
    /// `session_init` naming a different claude clears it, so a fresh session
    /// is never judged on the window of the one it replaced.
    pub context_window_tokens: Option<i64>,
    /// The session ids the most recent `request_replay` carried, oldest
    /// first, or `None` when it carried no lineage ([B02]).
    ///
    /// The `replay_complete` stamp sums `engine_turn_count` over exactly
    /// these files, so the bar's denominator counts the population its
    /// numerator was built from. Remembered rather than recomputed: what a
    /// replay *walked* is a fact about that request, and recomputing the
    /// chain at stamp time would usually agree without ever guaranteeing it.
    ///
    /// `None` on every card that is not an arc, and on any entry whose last
    /// replay predates this field — both sum the tip alone, which is the
    /// behaviour before this existed.
    ///
    /// In memory, like [`Self::context_window_tokens`]: it describes a
    /// request this process forwarded, and a restart with no replay behind it
    /// has nothing to remember.
    pub replayed_lineage: Option<Vec<String>>,
}

impl LedgerEntry {
    /// Create a fresh `Idle` entry for a newly registered session.
    pub fn new(
        tug_session_id: TugSessionId,
        workspace_key: WorkspaceKey,
        project_dir: PathBuf,
        session_mode: SessionMode,
        crash_budget: CrashBudget,
    ) -> Self {
        Self {
            tug_session_id,
            claude_session_id: None,
            workspace_key,
            project_dir,
            session_mode,
            permission_mode: None,
            tag: None,
            line_id: None,
            pending_segments: std::collections::VecDeque::new(),
            deck_model: None,
            context_window_tokens: None,
            replayed_lineage: None,
            spawn_state: SpawnState::Idle,
            ever_live_here: false,
            holds_workspace_refcount: false,
            crash_budget,
            queue: BoundedQueue::new(),
            latest_metadata: None,
            latest_capabilities: None,
            latest_rate_limit: None,
            child_pid: None,
            child_gone_at: None,
            child_start_time: None,
            turn_active: false,
            turns_ended: 0,
            turn_opener: None,
            prompt_turns_ended: 0,
            wake_turns_ended: 0,
            turn_api_error: false,
            turn_cancelled: false,
            step_closed_this_turn: None,
            open_jobs: std::collections::BTreeMap::new(),
            input_tx: None,
            cancel: CancellationToken::new(),
            card_id: None,
            replay_brackets_open: 0,
        }
    }
}

impl LedgerEntry {
    /// Whether this session is **finished**, not merely between frames.
    ///
    /// One reading of a fact that is genuinely two: the model is not speaking
    /// *and* nothing it started is still running. Every surface that waits for
    /// a session to be done asks this rather than `turn_active` alone, because
    /// the two disagree for exactly as long as a backgrounded test sweep takes
    /// to finish — the window in which an arc would otherwise be offered for
    /// joining while its own tests were still deciding whether it works.
    ///
    /// A provisional `launch:` entry counts exactly as a confirmed job does,
    /// which is the whole of [P04]: the window opens at the launch, so the
    /// answer here has to be *busy* from the launch and not from the
    /// `task_started` that confirms it.
    pub fn is_quiet(&self) -> bool {
        !self.turn_active && self.open_jobs.is_empty()
    }

    /// Drop every open job whose stamp has gone stale with the turn ended —
    /// the bound that turns an unforeseen wire shape from *wedged forever*
    /// into *offered late*, the one direction the busy latch is allowed to
    /// fail in. Reaping only after the turn has ended keeps a long turn's own
    /// silence off the clock, and each reaped job `warn!`s with its ids so
    /// the trace names what happened.
    ///
    /// A provisional `launch:` key is reaped like any other, and that is the
    /// bound under Risk R02: a `Monitor` call whose `task_started` never
    /// arrives holds the session busy until its wake or this horizon, and
    /// never past it.
    ///
    /// `now` is the caller's clock, injected so tests need no real one.
    pub fn reap_stuck_jobs(&mut self, now: std::time::Instant) {
        if self.turn_active {
            return;
        }
        self.open_jobs.retain(|task, stamp| {
            let stale = now.saturating_duration_since(*stamp) > JOB_REAP_HORIZON;
            if stale {
                warn!(
                    target: "dev::ledger",
                    event = "job_reaped",
                    session_id = %self.tug_session_id,
                    task_id = %task,
                    "background job silent past the reap horizon with its turn \
                     ended — dropped so the session cannot read busy forever",
                );
            }
            !stale
        });
    }
}

/// How long an open job may sit silent — no edge, no `task_progress` — after
/// its turn has ended before the reap drops it. Generous on purpose: a
/// backgrounded bash job emits no progress frames at all, so a tight horizon
/// would reap real work and offer its join early (Risk R01's residual is a
/// silent job longer than this, accepted as the cost of never wedging).
const JOB_REAP_HORIZON: std::time::Duration = std::time::Duration::from_secs(30 * 60);

// ---------------------------------------------------------------------------
// Ledger alias
// ---------------------------------------------------------------------------

/// Shared ledger map. Outer mutex guards membership; per-session mutex guards
/// the entry's mutable fields.
pub type Ledger = Arc<Mutex<HashMap<TugSessionId, Arc<Mutex<LedgerEntry>>>>>;

/// The process's one supervisor ledger, published for readers that are not on
/// the supervisor's own call graph.
///
/// Whether a session is finished ([`LedgerEntry::is_quiet`]) lives only in
/// memory — it is derived from frames as they cross the pipe and is deliberately
/// not persisted, so a reader like the changeset recompute cannot go and look it
/// up in `sessions.db`. Rather than mirror the fact into a second home and let
/// the two drift, the ledger itself is published here and read directly. Set
/// once, at supervisor construction; `None` in tests that never build one, where
/// every session then reads as quiet — the honest answer when there is no
/// supervisor to say otherwise.
static LEDGER_HANDLE: std::sync::OnceLock<Ledger> = std::sync::OnceLock::new();

/// Every session that is **not** finished right now — mid-turn, or holding a
/// background job that has not reported.
///
/// One snapshot per caller, so a recompute asking about many arcs locks the
/// ledger once. Empty when no supervisor is running.
pub async fn busy_session_ids() -> HashSet<String> {
    let Some(ledger) = LEDGER_HANDLE.get() else {
        return HashSet::new();
    };
    // The membership lock is released before any entry lock is taken: an entry
    // is held across `await` points elsewhere, and holding the outer map while
    // waiting on one would serialize the whole supervisor behind it.
    let entries: Vec<(String, Arc<Mutex<LedgerEntry>>)> = {
        let map = ledger.lock().await;
        map.iter()
            .map(|(id, entry)| (id.to_string(), Arc::clone(entry)))
            .collect()
    };
    let mut busy = HashSet::new();
    for (id, entry) in entries {
        let mut entry = entry.lock().await;
        // The read point is the reap point: no timer task, just the recompute
        // that consults busyness pruning what has gone stale on its way past.
        entry.reap_stuck_jobs(std::time::Instant::now());
        if !entry.is_quiet() {
            busy.insert(id);
        }
    }
    busy
}

/// A session with a live tugcode child and its captured `(pid, start_time)` —
/// the activity sampler's per-session subtree root and reuse-guard baseline
/// ([P08], [P10], [P20]). Produced by [`AgentSupervisor::live_session_processes`].
#[derive(Debug, Clone)]
pub struct LiveSessionProcess {
    pub tug_session_id: TugSessionId,
    pub pid: u32,
    pub start_time: u64,
}

// ---------------------------------------------------------------------------
// SessionsRecorder — writer trait for the per-session ledger
// ---------------------------------------------------------------------------

/// Per-session metadata captured at session_init time.
///
/// The recorder uses `session_id` as the row key (the claude session id —
/// also the JSONL file name on disk). `card_id` populates the row's
/// `card_id` column on `record_spawn` and is preserved across
/// `mark_closed` / `mark_failed` so the persisted ledger retains the
/// binding for client-side restore.
#[derive(Debug, Clone, Copy)]
pub struct SessionRecord<'a> {
    pub session_id: &'a str,
    pub workspace_key: &'a str,
    pub project_dir: &'a str,
    pub card_id: &'a str,
    /// Provisional mnemonic tag carried from the `LedgerEntry`, claimed
    /// authoritatively by `record_spawn`. `None` when tugdeck sent none.
    pub tag: Option<&'a str>,
    /// The line this segment joins ([P04]). `None` where the caller has no
    /// line to name — a path that has not been taught about lines yet — and
    /// the segment then takes a line of its own.
    pub line_id: Option<&'a str>,
}

/// Writer for the per-session ledger.
///
/// Replaces the pre-ledger pair of `TugbankSessionsRecorder` (sessions
/// record) and `TugbankLiveSessionsTracker` (live-sessions broadcast). One
/// trait now expresses the full lifecycle: `record` (insert/promote to
/// live), `record_turn` (assistant turn complete), `mark_closed`
/// (close_session / clean exit), `mark_failed` (resume_failed / crash
/// budget exhausted), and `remove` (Trash UX in step 6).
///
/// No method has a default impl. Adding a method to this trait must force
/// every implementor to opt in explicitly — silently inheriting an old
/// behavior was the regression-shape that motivated the redesign.
pub trait SessionsRecorder: Send + Sync {
    /// Insert a fresh row, or transition an existing row back to `live` and
    /// rebind it to `record.card_id`. Called from the bridge on
    /// `session_init`, when the claude session id is first known.
    fn record(&self, record: SessionRecord<'_>);

    /// Increment turn count and bump `last_used_at`. No-op if the row is
    /// missing or not in `live` state — see the trash-vs-late-turn race
    /// note in the plan's risk table.
    fn record_turn(&self, session_id: &str);

    /// Overwrite the row's `turn_count` with the authoritative value — the
    /// `totalTurns` a successful replay reports. Unlike `record_turn` (which
    /// increments), this SETs, reconciling any prior estimate / `MAX` seed to
    /// the segmenter's exact count. Live `record_turn`s then build on this
    /// base. No-op if the row is missing or not in `live` state.
    fn set_turn_count(&self, session_id: &str, count: i64);

    /// `engine(session file)` for `session_id` under `project_dir` — the
    /// single count authority ([P08]). The resume reconcile reads this (the
    /// fingerprint-validated cached value, or the engine run on the resolved
    /// file when no cache entry exists) instead of the wire's `totalTurns`,
    /// so the picker count never shifts on open. `None` when the file is
    /// missing/unreadable or foreign (cwd/sessionId mismatch).
    fn engine_turn_count(&self, session_id: &str, project_dir: &str) -> Option<i64>;

    /// Capture the most-recent user-message text for a session,
    /// truncated to the picker-snippet length. Overwrites the previous
    /// snippet on every call — the picker shows the latest prompt so the
    /// user recognizes the most-recent thread of conversation.
    fn record_user_prompt(&self, session_id: &str, prompt: &str);

    /// Transition the row to `closed` and clear the live-card binding.
    /// Called on `close_session` and on bridge teardown after a successful
    /// `result` event.
    fn mark_closed(&self, session_id: &str);

    /// Transition the row to `failed` and clear the live-card binding.
    /// Called on `resume_failed` and crash-budget exhaustion. Replaces the
    /// pre-ledger semantic of removing the row entirely; the row survives
    /// as a diagnostic crumb until age eviction or explicit Trash.
    fn mark_failed(&self, session_id: &str);

    /// Insert a fresh row in the submission journal for this session.
    /// Called from the supervisor's `dispatch_one` intercept on every
    /// inbound `user_message`, BEFORE the frame is forwarded to tugcode.
    /// The "row-persisted-before-forwarded" invariant means a failure
    /// here drops the inbound frame (the supervisor emits an error frame
    /// on CONTROL); a forwarded frame with no row is structurally
    /// impossible because the forward only happens after this call
    /// returns `Ok`. The journal id is internal to tugcast — it is not
    /// surfaced on the wire and tugcode never sees it. See [DM08] in the
    /// mid-turn-replay plan for the never-drop chain audit.
    ///
    /// Returns `Result` because the dispatcher's decision to forward
    /// depends on insert success. Sibling
    /// `delete_oldest_pending_for_session` runs after the wire-side
    /// broadcast (forward-before-mutate), so its `Result` is treated as
    /// telemetry — the wire is the source of truth for the live UI; the
    /// journal lagging by one update is a warn, not a user-facing error.
    fn insert_pending_turn(
        &self,
        session_id: &str,
        journal_id: &str,
        user_text: &str,
        user_attachments: &[serde_json::Value],
        now: i64,
    ) -> Result<(), crate::session_ledger::LedgerError>;

    /// Delete the oldest pending journal row for `session_id` (FIFO match
    /// by `created_at` ASC). Called from the supervisor's merger
    /// intercept on every outbound `turn_complete` / `turn_cancelled` —
    /// claude has acknowledged the user's submission, so the journal
    /// row's reason for existing (rendering the submission as
    /// awaiting-response on resume) is gone.
    ///
    /// Returns the deleted row's content for logging, or `None` if
    /// there were no pending rows for the session. The frame has
    /// already been broadcast on the code_output feed before this fires
    /// (forward-before-mutate), so a `LedgerError` here is a
    /// telemetry warn, not a user-visible failure.
    fn delete_oldest_pending_for_session(
        &self,
        session_id: &str,
    ) -> Result<Option<crate::session_ledger::JournalRow>, crate::session_ledger::LedgerError>;

    /// Record one prompt the **wheel** put on the wire, so a reload can say
    /// who wrote it.
    ///
    /// Claude's JSONL records a prompt the wheel sent exactly as it records
    /// one the user typed — that file is claude's, and Tug cannot stamp
    /// authorship into it. This is Tug's own record, and it is what the
    /// replay translator reads to state authorship instead of inferring it
    /// from where a prompt sits in the file.
    ///
    /// Called by the wheel itself, after the submission is away, from both
    /// doors it speaks through: a rotation's opening prompt and an arc's
    /// later prompts. Failure is telemetry — the submission has already been
    /// dispatched, and a missing record costs a name on one row of a resumed
    /// transcript, never the turn.
    fn record_wheel_prompt(&self, session_id: &str, text: &str);

    /// The ordered chain of claude session ids this session's line of work
    /// passed through — oldest ancestor first, `session_id` last ([P10]).
    ///
    /// A card with no fork edges answers with itself, which is what makes the
    /// restore path that reads this a no-op for every session that is not an
    /// arc. Best-effort by contract: a failed walk answers with what it
    /// walked, never an error, because a restore that shows less history is a
    /// worse restore and a restore that fails is no restore at all.
    fn lineage_chain(&self, session_id: &str) -> Vec<String>;

    /// The arc a session is bound to, if any — the key an arc record is read
    /// under, so the restore can name each stage in the chain.
    fn arc_name_for(&self, session_id: &str) -> Option<String>;

    /// What a rotation seated a session as — its stage label and the model it
    /// seated it on ([P10]).
    ///
    /// On the trait rather than reached for through a `SessionLedger` because
    /// the restore path takes a `&dyn SessionsRecorder`: a writer alone would
    /// leave the columns unreadable from the one place they exist to be read.
    fn stage_provenance(&self, session_id: &str) -> Option<(String, Option<String>)>;
}

/// Production implementation backed by a shared [`SessionLedger`].
///
/// Optionally broadcasts a `session_updated` push frame on the CONTROL feed
/// after each successful write so connected clients can patch their local
/// caches without re-fetching. Production uses the broadcast-enabled
/// constructor; tests use the no-broadcast variant.
pub struct LedgerSessionsRecorder {
    ledger: Arc<crate::session_ledger::SessionLedger>,
    control_tx: Option<broadcast::Sender<Frame>>,
    /// The aggregate-changeset recomposition signal, when the recorder was
    /// given one. Only the rotation seat rings it — see [`SessionsRecorder::record`].
    changeset_all_bump: Option<Arc<tokio::sync::Notify>>,
}

impl LedgerSessionsRecorder {
    #[cfg(test)]
    pub fn new(ledger: Arc<crate::session_ledger::SessionLedger>) -> Self {
        Self {
            ledger,
            control_tx: None,
            changeset_all_bump: None,
        }
    }

    pub fn with_broadcast(
        ledger: Arc<crate::session_ledger::SessionLedger>,
        control_tx: broadcast::Sender<Frame>,
    ) -> Self {
        Self {
            ledger,
            control_tx: Some(control_tx),
            changeset_all_bump: None,
        }
    }

    /// Give the recorder the registry's aggregate-changeset bump, so a seated
    /// binding refreshes the masthead's arc index the way every other binding
    /// writer does. A builder rather than a constructor argument because the
    /// registry outranks the recorder in main's construction order and every
    /// test that wants a recorder wants it without one.
    pub fn with_changeset_bump(mut self, bump: Arc<tokio::sync::Notify>) -> Self {
        self.changeset_all_bump = Some(bump);
        self
    }

    /// Broadcast the current state of `session_id`'s ledger row, if a
    /// control feed is configured. No-op if the row was already deleted by
    /// the time we look it up (eviction race) — the deletion path emits its
    /// own `session_updated { removed: true }` push.
    fn broadcast_row(&self, session_id: &str) {
        let Some(tx) = self.control_tx.as_ref() else {
            return;
        };
        // A push names the line of work, not whichever segment is seated —
        // which is what the row already holds, by the join ([P02]).
        match self.ledger.get(session_id) {
            Ok(Some(row)) => {
                let _ = tx.send(build_session_updated_frame(
                    &row,
                    self.scan_metrics(session_id),
                    self.usage(session_id),
                ));
            }
            Ok(None) => {}
            Err(err) => warn!(error = %err, session_id, "ledger get for broadcast failed"),
        }
    }

    /// The scan-cache pair for a push, best-effort: a read failure degrades to
    /// `None`, which the frame builder turns into "no size, the ledger's own
    /// count" rather than into a failed broadcast.
    fn scan_metrics(&self, session_id: &str) -> Option<crate::session_ledger::SessionScanMetrics> {
        match self.ledger.scan_metrics_for(session_id) {
            Ok(metrics) => metrics,
            Err(err) => {
                warn!(error = %err, session_id, "ledger scan_metrics_for for broadcast failed");
                None
            }
        }
    }

    /// The segment's usage for a push, on the same best-effort terms as
    /// [`Self::scan_metrics`]: a read failure degrades to `None` — the same
    /// value a segment with no telemetry carries — rather than to no push.
    fn usage(&self, session_id: &str) -> Option<crate::session_ledger::SessionUsage> {
        match self.ledger.usage_for(session_id) {
            Ok(usage) => usage,
            Err(err) => {
                warn!(error = %err, session_id, "ledger usage_for for broadcast failed");
                None
            }
        }
    }

    /// The handle a fact files a session under: its callsign when it has one,
    /// else the session id. Read before the transition that prompted the fact,
    /// since some of those transitions are the last moment the row is legible.
    fn session_handle(&self, session_id: &str) -> String {
        self.ledger
            .get(session_id)
            .ok()
            .flatten()
            .and_then(|row| row.tag)
            .unwrap_or_else(|| session_id.to_owned())
    }

    /// Revive a demoted row on live-borne evidence, best-effort. The caller
    /// vouches the event could not have come from replay backfill; the
    /// ledger's own write primitives stay non-resurrecting. A failed revive
    /// warns and the activity write proceeds — it may then no-op on the
    /// still-closed row, which is the pre-existing behavior, not a new hole.
    fn revive_on_activity(&self, session_id: &str, now: i64) {
        match self.ledger.revive_on_activity(session_id, now) {
            Ok(true) => {
                tracing::info!(
                    target: "dev::session-lifecycle",
                    event = "ledger.revive_on_activity",
                    session_id,
                );
                self.broadcast_row(session_id);
            }
            Ok(false) => {}
            Err(err) => {
                warn!(error = %err, session_id, "ledger revive_on_activity failed");
            }
        }
    }

    /// Write one lifecycle fact, best-effort. A failed write warns; it never
    /// gates the transition it describes.
    fn record_lifecycle_fact(&self, fact: &crate::session_ledger::NewFact) {
        if let Err(err) = self.ledger.record_fact(fact) {
            warn!(
                error = %err,
                kind = %fact.kind,
                "lifecycle fact write failed; the session row is unaffected"
            );
        }
    }
}

impl SessionsRecorder for LedgerSessionsRecorder {
    fn record(&self, record: SessionRecord<'_>) {
        let now = crate::session_ledger::now_millis();
        if let Err(err) = self.ledger.record_spawn(
            record.session_id,
            record.workspace_key,
            record.project_dir,
            record.card_id,
            now,
            record.line_id.unwrap_or(record.session_id),
            record.tag,
        ) {
            warn!(error = %err, session_id = record.session_id, "ledger record_spawn failed");
            return;
        }
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "ledger.record_spawn",
            session_id = record.session_id,
            workspace_key = record.workspace_key,
            project_dir = record.project_dir,
            card_id = record.card_id,
        );
        // A rotation mints this segment on a card that may be mid-arc, and
        // the binding is on the segment it just replaced. Carry it forward
        // and announce the mating so the card wears it — the deck's binding
        // store has no other mover, and the surface a rotation blanked could
        // not be repaired by any gesture from inside the seated session
        // ([D167]).
        //
        // The row push goes **before** the `bind_arc_ok`, because the deck
        // routes that announcement by walking segment → line → card and this
        // segment is seconds old: the push carrying `(session_id, line_id)`
        // is how the deck learns the pair at all. Announced first, the walk
        // resolves nothing and the deck drops the frame — the card wears
        // "unbound" for the rest of its arc with no gesture able to repair it.
        // Two frames on one ordered channel, and the order is the whole fix.
        // The announcement carries the line and the card itself as well, so a
        // deck that missed the push still routes: belt and braces, on the one
        // surface nobody inside the card can put right.
        let seated = match self.ledger.seat_line_binding(record.session_id) {
            Ok(seated) => seated,
            Err(err) => {
                warn!(error = %err, session_id = record.session_id, "seat_line_binding failed");
                None
            }
        };
        self.broadcast_row(record.session_id);
        if let Some((arc_id, arc_name)) = seated {
            if let Some(tx) = self.control_tx.as_ref() {
                broadcast_bind_arc_ok(
                    tx,
                    record.session_id,
                    &arc_id,
                    &arc_name,
                    record.line_id,
                    Some(record.card_id),
                );
            }
            // The masthead's arc index derives from `CHANGESET_ALL`, and a
            // seat moves which session an arc reports as bound — the same
            // fact every other binding writer bumps for. Without it the index
            // keeps naming the retired segment until something unrelated
            // happens to recompose it.
            if let Some(bump) = self.changeset_all_bump.as_ref() {
                bump.notify_one();
            }
            tracing::info!(
                target: "dev::ledger",
                event = "ledger.seat_line_binding",
                session_id = record.session_id,
                card_id = record.card_id,
                arc_id = arc_id.as_str(),
            );
        }
    }

    fn record_turn(&self, session_id: &str) {
        let now = crate::session_ledger::now_millis();
        // A live turn is proof of a running subprocess — the bridge only
        // calls this outside replay. A row the startup demote closed under
        // a surviving agent revives here, or the live-gated write below
        // silently no-ops and the ledger goes on misreporting the session.
        self.revive_on_activity(session_id, now);
        if let Err(err) = self.ledger.record_turn(session_id, now) {
            warn!(error = %err, session_id, "ledger record_turn failed");
            return;
        }
        tracing::debug!(
            target: "dev::session-lifecycle",
            event = "ledger.record_turn",
            session_id,
        );
        self.broadcast_row(session_id);
    }

    fn set_turn_count(&self, session_id: &str, count: i64) {
        let now = crate::session_ledger::now_millis();
        if let Err(err) = self.ledger.set_turn_count(session_id, count, now) {
            warn!(error = %err, session_id, count, "ledger set_turn_count failed");
            return;
        }
        tracing::debug!(
            target: "dev::session-lifecycle",
            event = "ledger.set_turn_count",
            session_id,
            count,
        );
        self.broadcast_row(session_id);
    }

    fn engine_turn_count(&self, session_id: &str, project_dir: &str) -> Option<i64> {
        crate::external_sessions::engine_turn_count(&self.ledger, project_dir, session_id)
    }

    fn record_user_prompt(&self, session_id: &str, prompt: &str) {
        // A prompt only arrives on the live input relay — never from replay
        // backfill — so it is proof of activity the same way a turn is.
        self.revive_on_activity(session_id, crate::session_ledger::now_millis());
        if let Err(err) = self.ledger.record_user_prompt(session_id, prompt) {
            // `NotFound` means the row was never created (claude_session_id
            // was missing from `session_init`). Other errors are real
            // sqlite failures worth logging at warn level.
            match err {
                crate::session_ledger::LedgerError::NotFound(_) => {}
                _ => warn!(error = %err, session_id, "ledger record_user_prompt failed"),
            }
            return;
        }
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "ledger.record_user_prompt",
            session_id,
            len = prompt.chars().count(),
        );
        self.broadcast_row(session_id);
    }

    fn mark_closed(&self, session_id: &str) {
        let handle = self.session_handle(session_id);
        let transitioned = match self.ledger.mark_closed(session_id) {
            Ok(transitioned) => transitioned,
            Err(err) => {
                warn!(error = %err, session_id, "ledger mark_closed failed");
                return;
            }
        };
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "ledger.mark_closed",
            session_id,
        );
        // The fact rides the durable transition rather than any one of the
        // several `closed` publish sites, and only when a row really moved —
        // so a session that ended once has one ending in the fact base however
        // many paths call this for it.
        if transitioned {
            self.record_lifecycle_fact(&crate::feeds::facts_library::session_end_fact(
                crate::session_ledger::now_millis(),
                session_id,
                false,
                &handle,
                None,
            ));
        }
        self.broadcast_row(session_id);
    }

    fn mark_failed(&self, session_id: &str) {
        let handle = self.session_handle(session_id);
        let transitioned = match self.ledger.mark_failed(session_id) {
            Ok(transitioned) => transitioned,
            Err(err) => {
                warn!(error = %err, session_id, "ledger mark_failed failed");
                return;
            }
        };
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "ledger.mark_failed",
            session_id,
        );
        if transitioned {
            self.record_lifecycle_fact(&crate::feeds::facts_library::session_end_fact(
                crate::session_ledger::now_millis(),
                session_id,
                true,
                &handle,
                None,
            ));
        }
        self.broadcast_row(session_id);
    }

    fn insert_pending_turn(
        &self,
        session_id: &str,
        journal_id: &str,
        user_text: &str,
        user_attachments: &[serde_json::Value],
        now: i64,
    ) -> Result<(), crate::session_ledger::LedgerError> {
        self.ledger.insert_pending_turn(
            session_id,
            journal_id,
            user_text,
            user_attachments,
            now,
        )?;
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "ledger.insert_pending_turn",
            session_id,
            journal_id,
        );
        Ok(())
    }

    fn delete_oldest_pending_for_session(
        &self,
        session_id: &str,
    ) -> Result<Option<crate::session_ledger::JournalRow>, crate::session_ledger::LedgerError> {
        let popped = self.ledger.delete_oldest_pending_for_session(session_id)?;
        if let Some(row) = popped.as_ref() {
            tracing::info!(
                target: "dev::ledger",
                event = "turn_seen_journal_row_deleted",
                session_id,
                journal_id = %row.journal_id,
            );
        }
        Ok(popped)
    }

    fn record_wheel_prompt(&self, session_id: &str, text: &str) {
        let prompt_id = uuid::Uuid::new_v4().to_string();
        match self.ledger.record_wheel_prompt(
            session_id,
            &prompt_id,
            text,
            crate::session_ledger::now_millis(),
        ) {
            Ok(true) => tracing::info!(
                target: "dev::session-lifecycle",
                event = "ledger.record_wheel_prompt",
                session_id,
                prompt_id,
            ),
            Ok(false) => tracing::warn!(
                target: "dev::session-lifecycle",
                event = "ledger.record_wheel_prompt_unknown_session",
                session_id,
                "the wheel spoke on a session the ledger does not carry; a reload \
                 will attribute this prompt to the user",
            ),
            Err(err) => tracing::warn!(
                target: "dev::session-lifecycle",
                event = "ledger.record_wheel_prompt_failed",
                session_id,
                error = %err,
            ),
        }
    }

    fn lineage_chain(&self, session_id: &str) -> Vec<String> {
        self.ledger.lineage_chain(session_id)
    }

    fn stage_provenance(&self, session_id: &str) -> Option<(String, Option<String>)> {
        self.ledger.stage_provenance(session_id)
    }

    fn arc_name_for(&self, session_id: &str) -> Option<String> {
        match self.ledger.get(session_id) {
            Ok(row) => row.and_then(|r| r.arc_name),
            Err(err) => {
                warn!(error = %err, session_id, "ledger get for the arc binding failed");
                None
            }
        }
    }
}

/// The ordered lineage a `request_replay` carries, or `None` when there is
/// nothing to carry ([P10]).
///
/// An arc spreads one line of work across a JSONL per stage, and a card that
/// replays only its own shows a transcript that begins in the middle. This
/// walks the fork edges parent-ward and names each session in the chain,
/// attaching the stage each one runs from the arc log's `arc-stage` lines —
/// the same record the runner drives the arc from, so what the transcript
/// says a stage was and what the arc actually did cannot drift.
///
/// `None` on the two cases that are the same case: a chain of one (no forks,
/// which is nearly every card) and a chain with no arc record behind it (a
/// rewind-fork lineage, which tugcode already replays correctly by resuming
/// the tip). Both leave the request byte-identical to today's.
fn replay_lineage(
    recorder: &dyn SessionsRecorder,
    claude_session_id: &str,
    project_dir: &Path,
) -> Option<Vec<serde_json::Value>> {
    let chain = recorder.lineage_chain(claude_session_id);
    if chain.len() < 2 {
        return None;
    }
    // The binding lives on the card's own row — the tug session id the deck
    // spawned with, which is the chain's oldest entry. A stage row never
    // carries it: a rotation's `session_init` records a fresh row, and only
    // `arc bind` / `arc run` ever write a binding — so asking the head alone
    // would find nothing on every arc that has rotated once.
    // An arc, if there is one. There need not be: a rotation with nothing
    // driving it has no arc binding and no arc record, and its transcript is
    // just as much an invariant of the rotation as an arc's ([B05]). So
    // the arc supplies only the two facts that are genuinely its — the arc
    // name and the document it opened on — and the rest comes off the row.
    let arc = chain
        .iter()
        .find_map(|id| recorder.arc_name_for(id))
        .and_then(|arc| tugarc_core::arc::read_arc(project_dir, &arc).map(|record| (arc, record)));
    let entries: Vec<serde_json::Value> = chain
        .iter()
        .map(|session_id| {
            let recorded = recorder.stage_provenance(session_id);
            let logged = arc
                .as_ref()
                .and_then(|(_, record)| record.stages.iter().find(|s| &s.session_id == session_id));
            // The row is the answer; the arc record is the fallback for a row
            // written before the columns existed, so an arc that rotated on an
            // older build replays exactly as it did.
            let seated = recorded
                .map(|(label, model)| (label, model.unwrap_or_default()))
                .or_else(|| {
                    logged.map(|stage| {
                        (
                            stage.stage.as_str().to_string(),
                            stage.model.clone().unwrap_or_default(),
                        )
                    })
                });
            let mut entry = serde_json::Map::new();
            entry.insert("sessionId".into(), serde_json::json!(session_id));
            if let Some((label, model)) = seated {
                entry.insert("stage".into(), serde_json::json!(label));
                entry.insert("model".into(), serde_json::json!(model));
                // The arc's own two facts, and only where an arc seated this
                // entry — an arcless rotation names neither.
                if let (Some((arc, record)), Some(_)) = (arc.as_ref(), logged) {
                    entry.insert("arc".into(), serde_json::json!(arc));
                    if let Some(document) = record.plan.as_ref().or(record.document.as_ref()) {
                        entry.insert("document".into(), serde_json::json!(document));
                    }
                }
            }
            serde_json::Value::Object(entry)
        })
        .collect();
    // A chain whose every entry is stage-less is a fork lineage, not a
    // rotation's — nothing to divide, so nothing to send.
    if entries.iter().all(|e| e.get("stage").is_none()) {
        return None;
    }
    Some(entries)
}

/// Build the `session_updated` push payload for a row's current state.
/// Public so the `do_trash_session` / `do_trash_project_dir_sessions`
/// handlers can emit the matching frame after their batch writes.
///
/// `metrics` is the session's `external_scan_cache` pair, and **every** caller
/// looks it up — not just the one pushing after a turn. The client replaces its
/// cached row wholesale on a push, so a push that omits a fact downgrades it:
/// without the lookup, an unrelated rename push would null a known `file_size`
/// and knock a scan-derived `turn_count` to whatever sparse `0` the `sessions`
/// row happens to hold. `None` (no scan-cache row — a session the scanner has
/// never seen) emits a null size and the ledger row's own count, which is the
/// right answer for that case.
///
/// Kept pure — it takes the pair, not a ledger handle — so each caller does its
/// own lookup beside the `ledger.get` it already performs.
pub fn build_session_updated_frame(
    row: &crate::session_ledger::SessionRow,
    metrics: Option<crate::session_ledger::SessionScanMetrics>,
    usage: Option<crate::session_ledger::SessionUsage>,
) -> Frame {
    let body = serde_json::json!({
        "action": "session_updated",
        "session_id": row.session_id,
        "fields": {
            "session_id": row.session_id,
            "workspace_key": row.workspace_key,
            "project_dir": row.project_dir,
            "created_at": row.created_at,
            "last_used_at": row.last_used_at,
            "turn_count": metrics.map_or(row.turn_count, |m| m.turn_count),
            "file_size": metrics.map(|m| m.file_size),
            "last_user_prompt": row.last_user_prompt,
            "state": row.state,
            "card_id": row.card_id,
            // The line this segment belongs to ([P01]). Every identity field
            // beside it is the line's, read through the join, so a push that
            // omitted this would hand the deck a name it could not key.
            "line_id": row.line_id,
            "name": row.name,
            "name_user_set": row.name_user_set,
            "tag": row.tag,
            "synopsis": row.synopsis,
            // Privacy is a resting state, so it has to reach the deck: a chip
            // that only showed the transition ack would go quiet on reload and
            // leave a session silently un-narrated with nothing saying why
            // ([P05]).
            "private": row.private,
        },
        // What the segment cost, beside the row rather than on it: `usage` is
        // a `SUM` over another table, not a `sessions` column, and the arc
        // receipt's stage row is the surface that reads it. Looked up by every
        // caller for the same reason `metrics` is — the client replaces its
        // cached entry wholesale, so a push that omitted it would blank a
        // figure the reader is looking at.
        "usage": usage,
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_updated serializes"),
    )
}

/// Build the `session_line_rebound` push — a card's line changed under it.
///
/// Sent on exactly one gesture: a plain `/new`, which is the one id change
/// that means "a different conversation" and so births a line rather than
/// joining the card's ([P03]). Everything else is another segment of the line
/// the card already has, and needs no push because nothing moved.
///
/// The deck's binding follows this, and with it every store keyed by line —
/// the name, the callsign, the description, the side-question history.
pub fn build_session_line_rebound_frame(
    card_id: &str,
    tug_session_id: &str,
    line: &crate::session_ledger::LineRow,
) -> Frame {
    let body = serde_json::json!({
        "action": "session_line_rebound",
        "card_id": card_id,
        "tug_session_id": tug_session_id,
        "line_id": line.line_id,
        "tag": line.tag,
        "name": line.name,
        "name_user_set": line.name_user_set,
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_line_rebound serializes"),
    )
}

/// Build the `session_line_seated` push — the card's line moved to a new
/// segment, and the card's seat must move with it.
///
/// **`session_line_rebound`'s twin, for the case that is not a new line.** A
/// plain `/new` births a line and has its own frame; every other id change — a
/// rotation above all — is another segment of the line the card already has,
/// and the comment on that frame used to say such a change "needs no push
/// because nothing moved". Something did move: which segment the card is
/// seated on, which is what every identity read of a live card resolves
/// through. Without this frame the deck's answer was derived from whichever
/// row push landed last, and two live rows on one line — which is exactly what
/// a rotation leaves, since the retired segment's row stays `live` until the
/// card closes — made that answer a coin toss (`at0503` caught it as one).
///
/// So the seat is announced rather than inferred: the card by name, the
/// segment, and the line, from the one place that knows all three at once.
/// Skew is free in both directions — an older deck ignores an action it has no
/// handler for, and a newer deck against an older server simply never learns
/// the seat moved, which is where it was before this frame existed.
pub fn build_session_line_seated_frame(
    card_id: &str,
    tug_session_id: &str,
    session_id: &str,
    line_id: &str,
) -> Frame {
    let body = serde_json::json!({
        "action": "session_line_seated",
        "card_id": card_id,
        "tug_session_id": tug_session_id,
        "session_id": session_id,
        "line_id": line_id,
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_line_seated serializes"),
    )
}

/// Build the `session_updated { removed: true }` push for a deleted row.
pub fn build_session_removed_frame(session_id: &str) -> Frame {
    let body = serde_json::json!({
        "action": "session_updated",
        "session_id": session_id,
        "removed": true,
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_updated removed serializes"),
    )
}

// ---------------------------------------------------------------------------
// AgentSupervisor
// ---------------------------------------------------------------------------

/// Runtime configuration for [`AgentSupervisor`].
///
/// Per-session `project_dir` — the supervisor no longer has a global
/// workspace path ([D12]). Per-session paths come from the CONTROL
/// `spawn_session` payload and live on `LedgerEntry.project_dir`.
///
/// P13 added `max_concurrent_sessions` and `max_spawns_per_minute` as safety
/// caps so a buggy client or a user with many open cards cannot run the host
/// out of subprocess slots. See [`AgentSupervisor::do_spawn_session`] for the
/// enforcement path.
///
/// The two move together. A fresh insert spends both budgets, and after a
/// host restart the in-memory ledger is empty, so every session restored
/// from disk is a fresh insert rather than a reconnect. A per-minute bucket
/// below the concurrent cap would therefore make the cap unreachable from a
/// cold start: the restore pass would fill the bucket and the remaining
/// cards would be refused. Keep `max_spawns_per_minute` above
/// `max_concurrent_sessions`.
#[derive(Debug, Clone)]
pub struct AgentSupervisorConfig {
    /// Absolute path to the tugcode binary (or `.ts` entry for bun fallback).
    /// Only consumed by the default [`TugcodeSpawner`] factory.
    pub tugcode_path: PathBuf,
    /// Hard cap on concurrent `Spawning` + `Live` ledger entries. A
    /// `spawn_session` CONTROL frame that would push the count at or above
    /// this bound is rejected with
    /// `ControlError::CapExceeded { reason: "concurrent_session_cap_exceeded" }`
    /// and a `SESSION_STATE = errored` broadcast. Idle and Errored entries
    /// do NOT consume slots — only sessions with a running or starting
    /// subprocess count.
    ///
    /// The bound is a memory budget. A live session is a `tugcode` process
    /// plus the `claude` it supervises, which together cost roughly 240 MB
    /// of private memory — measured as `phys_footprint`, which excludes the
    /// file-backed pages every `claude` maps from the same binary and shares.
    /// Resident-set figures count those shared pages once per process and so
    /// read about three times higher; sizing against RSS undercounts what the
    /// host can carry.
    pub max_concurrent_sessions: usize,
    /// Leaky-bucket rate limit on fresh spawn-session intents. Trailing 60s
    /// window; the N+1th spawn within the window is rejected with
    /// `ControlError::CapExceeded { reason: "spawn_rate_limited" }`.
    /// Reconnects (spawns for an existing ledger entry) do not consume
    /// budget.
    ///
    /// Held above `max_concurrent_sessions` so a cold-start restore of a
    /// full deck cannot exhaust the bucket before it reaches the cap.
    pub max_spawns_per_minute: usize,
    /// Override for the Claude Code terminal-liveness registry root
    /// (`~/.claude/sessions/` in production). `None` resolves the
    /// default at use time; tests inject a tempdir (or a nonexistent
    /// path) so they never read the developer's real registry.
    pub terminal_registry_root: Option<PathBuf>,
}

impl Default for AgentSupervisorConfig {
    fn default() -> Self {
        Self {
            tugcode_path: PathBuf::new(),
            max_concurrent_sessions: 64,
            max_spawns_per_minute: 96,
            terminal_registry_root: None,
        }
    }
}

/// Factory that yields a fresh [`ChildSpawner`] for each session spawn. The
/// default factory returns [`TugcodeSpawner`]; tests pass a closure returning
/// a mock spawner so they can drive the bridge without a real subprocess.
pub type SpawnerFactory = Arc<dyn Fn() -> Arc<dyn ChildSpawner> + Send + Sync>;

/// Build the default production spawner factory from an
/// [`AgentSupervisorConfig`]. Each call to the factory clones the configured
/// `tugcode_path` into a fresh [`TugcodeSpawner`]. `config.project_dir` is
/// **not** captured — the per-session workspace path is passed to
/// `spawn_child` per call (see [`ChildSpawner::spawn_child`]).
pub fn default_spawner_factory(config: &AgentSupervisorConfig) -> SpawnerFactory {
    let tugcode_path = config.tugcode_path.clone();
    Arc::new(move || Arc::new(TugcodeSpawner::new(tugcode_path.clone())) as Arc<dyn ChildSpawner>)
}

/// Result of dispatching a CONTROL frame's `action` to the supervisor.
///
/// A single value covers the three outcomes the router needs to
/// distinguish:
///
/// * [`ControlOutcome::Handled`] — the action belongs to the supervisor
///   and ran cleanly.
/// * [`ControlOutcome::Error`] — the action belongs to the supervisor
///   but the payload was malformed or rejected; the router maps the
///   variant to a wire-side `detail` string and emits a CONTROL error
///   frame on the in-scope socket.
/// * [`ControlOutcome::PassThrough`] — the action does not belong to
///   the supervisor; the router falls through to its legacy
///   `dispatch_action` pipeline (relaunch, dev-mode toggles, etc.).
///
/// Returning the outcome from [`AgentSupervisor::handle_control`] makes
/// the match arms inside `handle_control` the single source of truth
/// for "which CONTROL actions the supervisor owns." The router does not
/// keep a separate allowlist that has to be maintained alongside the
/// dispatch table — drift between the two surfaces is impossible by
/// construction. A new arm in `handle_control` is automatically
/// reachable from the websocket; an action with no arm naturally falls
/// to `PassThrough` via the catch-all.
#[derive(Debug)]
pub enum ControlOutcome {
    /// Action handled successfully.
    Handled,
    /// Action handled, with the reply body it broadcast on CONTROL. The
    /// WebSocket ingress treats this exactly like `Handled` (its clients
    /// already received the broadcast); the `/api/tell` bridge returns the
    /// body to the HTTP caller — which is what lets `tugtool claim` report
    /// what actually happened instead of inferring success from a bare 200.
    HandledWith(serde_json::Value),
    /// Action belongs to the supervisor but failed validation or
    /// payload parsing. The router emits a CONTROL error frame.
    Error(ControlError),
    /// Action does not belong to the supervisor. The router falls
    /// through to `dispatch_action`.
    PassThrough,
}

#[cfg(test)]
impl ControlOutcome {
    /// Test-only: panic unless the outcome is `Handled`. Mirrors the
    /// `Result::unwrap` ergonomics tests had before `handle_control`'s
    /// signature changed.
    pub(crate) fn expect_handled(self) {
        match self {
            ControlOutcome::Handled | ControlOutcome::HandledWith(_) => {}
            other => panic!("expected ControlOutcome::Handled, got {other:?}"),
        }
    }

    /// Test-only: panic with `msg` unless the outcome is `Handled`.
    /// Mirrors `Result::expect`. Used where a test wants to attach
    /// context to the failure ("first spawn admitted", etc.).
    pub(crate) fn expect_handled_with(self, msg: &str) {
        match self {
            ControlOutcome::Handled | ControlOutcome::HandledWith(_) => {}
            other => panic!("{msg}: expected ControlOutcome::Handled, got {other:?}"),
        }
    }

    /// Test-only: extract the `ControlError` from an `Error` outcome.
    /// Panics on any other variant.
    pub(crate) fn expect_error(self) -> ControlError {
        match self {
            ControlOutcome::Error(e) => e,
            other => panic!("expected ControlOutcome::Error, got {other:?}"),
        }
    }

    pub(crate) fn is_handled(&self) -> bool {
        matches!(
            self,
            ControlOutcome::Handled | ControlOutcome::HandledWith(_)
        )
    }
}

/// Errors returned from [`AgentSupervisor::handle_control`]. Consumed by
/// `handle_client` (wired in Step 8) to emit a CONTROL error frame on the
/// in-scope socket.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum ControlError {
    #[error("control payload missing card_id")]
    MissingCardId,
    #[error("control payload missing tug_session_id")]
    MissingSessionId,
    #[error("control payload is not valid JSON")]
    Malformed,
    /// The payload's `project_dir` field is missing or fails validation.
    /// `reason` is a compile-time string from the set defined in
    /// `"missing_project_dir"`, `"does_not_exist"`, `"permission_denied"`,
    /// `"not_a_directory"`, `"metadata_error"`.
    #[error("invalid project_dir: {reason}")]
    InvalidProjectDir { reason: &'static str },
    /// P13 spawn-budget rejection. `reason` is one of:
    /// `"concurrent_session_cap_exceeded"` (hit
    /// `AgentSupervisorConfig::max_concurrent_sessions`) or
    /// `"spawn_rate_limited"` (hit `max_spawns_per_minute`). Router maps
    /// both to a CONTROL error frame on the in-scope socket; the
    /// supervisor also broadcasts `SESSION_STATE = errored` with the same
    /// `detail` so any other observer of the session sees the failure.
    #[error("spawn budget exceeded: {reason}")]
    CapExceeded { reason: &'static str },
    /// A `mode=new` spawn carried no `line_id` ([P03]). A line is born in
    /// exactly one place and the deck mints its id from the drop, so a fresh
    /// spawn that names none is refused rather than served under a line the
    /// server invented — which the deck's per-line tugbank keys would then
    /// point past, silently.
    #[error("spawn_session is missing line_id")]
    MissingLineId,
}

/// Central owner of all Claude Code sessions for a single tugcast process.
pub struct AgentSupervisor {
    /// Per-session ledger (see [`LedgerEntry`]).
    pub ledger: Ledger,
    /// The SESSION_STATE feed — a session-scoped publishing surface
    /// (splice discipline + lag policy live on the handle).
    pub session_state: SessionScopedFeed,
    /// The SESSION_SIDEBAND feed. Broadcast — not watch — per [D14] so
    /// concurrent per-session metadata updates cannot clobber one another.
    pub session_sideband: SessionScopedFeed,
    /// Per-client session affinity, used by the P5 authorization cross-check.
    pub client_sessions: Arc<Mutex<HashMap<ClientId, HashSet<TugSessionId>>>>,
    /// The shared supervisor-wide CODE_OUTPUT feed. Publishing through
    /// the handle keeps the lag-recovery replay buffer fed ([D06]: the
    /// buffer is cross-session; the deck filter provides isolation [D11]).
    pub code_output: SessionScopedFeed,
    /// The ACTIVITY feed ([P14], `FeedId::ACTIVITY`). The merger diverts
    /// tugcode's `activity_delta` frames onto it (re-tagged, splice
    /// preserved) so a per-session activity sample stream reaches the deck
    /// without riding the high-churn CODE_OUTPUT transcript. Broadcast with
    /// `LagPolicy::Warn` ([P17]): a dropped sample bin is a negligible gap.
    pub activity: SessionScopedFeed,
    /// Outbound CONTROL broadcast sender — used for `session_unknown`,
    /// `session_backpressure`, and other supervisor-emitted error frames.
    pub control_tx: broadcast::Sender<Frame>,
    /// Writer for the per-session ledger. The bridge calls `record` on
    /// `session_init`, `record_turn` on each tugcode `result` event, and
    /// `mark_failed` on `resume_failed` / crash exhaustion. The supervisor
    /// calls `mark_closed` on `do_close_session`. The Trash UX (step 6)
    /// uses `remove`. The live-elsewhere check during spawn reads the
    /// in-memory `LedgerEntry::card_id` and gates on `spawn_state`; the
    /// ledger row's `card_id` mirrors the in-memory value so the
    /// client-side restore can reconstruct the binding after a tugcast
    /// restart.
    pub sessions_recorder: Arc<dyn SessionsRecorder>,
    /// Read handle to the same [`SessionLedger`] the recorder writes to.
    /// Used for the read-side CONTROL ops (`list_sessions`, the picker's
    /// query path) and the batch Trash paths. Named `session_ledger` to
    /// avoid colliding with the in-memory `ledger` field above. Optional
    /// so unit tests that pass a `NoopSessionsRecorder` aren't forced to
    /// wire a ledger they won't read from. `None` makes the new ledger
    /// CONTROL ops short-circuit with an empty / no-op response.
    pub session_ledger: Option<Arc<crate::session_ledger::SessionLedger>>,
    /// The shell-exchange ledger, read by the `list_shell_exchanges` CONTROL op
    /// (the shell service writes it; the supervisor reads it). `None` in tests
    /// that don't exercise the shell restore path — the read yields an empty
    /// array. Set via [`AgentSupervisor::set_shell_ledger`] in `main.rs`.
    pub shell_ledger: Option<Arc<crate::shell_ledger::ShellLedger>>,
    /// The refs ledger, read by the `list_refs` CONTROL op (the refs
    /// dispatcher writes it; the supervisor reads it). `None` in tests that
    /// don't exercise refs restore — the read yields a null run. Set via
    /// [`AgentSupervisor::set_refs_ledger`] in `main.rs`.
    pub refs_ledger: Option<Arc<crate::refs_ledger::RefsLedger>>,
    /// The changeset scribe ([P11]/[P21]) — spawner + model resolver behind the
    /// maintained-draft engine. `None` (tests, or a boot without wiring) makes
    /// [`AgentSupervisor::start_draft_engine`] a no-op. Set via
    /// [`AgentSupervisor::set_scribe`] in `main.rs`.
    pub scribe: Option<ScribeContext>,
    /// Per-spawn factory for the backing subprocess. Swapped for a mock in
    /// tests so unit tests do not need a real tugcode binary.
    pub spawner_factory: SpawnerFactory,
    /// Register side of the merger task's per-session stream map. Each
    /// `spawn_session_worker` call pushes a `(tug_session_id, output_rx)`
    /// pair through here; `merger_task` inserts it into its internal
    /// `StreamMap` and fans the frames into the shared CODE_OUTPUT
    /// broadcast + SESSION_SIDEBAND broadcast.
    pub merger_register_tx: mpsc::Sender<MergerRegistration>,
    /// Runtime configuration.
    pub config: AgentSupervisorConfig,
    /// Per-workspace feed registry. `do_spawn_session` calls
    /// `registry.get_or_create`; `do_close_session` calls
    /// `registry.release`. Shared across the whole tugcast process.
    pub registry: Arc<WorkspaceRegistry>,
    /// Process-wide cancel token, cloned into `registry.get_or_create`
    /// calls so each new workspace entry derives a child cancel from
    /// the shared root. Firing this (e.g. on process shutdown) tears
    /// down every workspace's tasks.
    pub cancel: CancellationToken,
    /// P13 leaky-bucket state. Holds the timestamps of every successful
    /// fresh spawn intent within the trailing 60s window, in insertion
    /// order. Trimmed + checked + pushed inside `do_spawn_session`'s
    /// Phase 1 critical section so the rate-limit decision is atomic with
    /// the ledger insert. `std::sync::Mutex` (not tokio's async mutex)
    /// because the critical section is bounded, non-awaiting, and never
    /// crosses an `.await` point.
    pub spawn_timestamps: Arc<StdMutex<VecDeque<Instant>>>,
    /// Latest CHANGESET_ALL aggregate watch receiver, stored at boot by
    /// [`AgentSupervisor::start_draft_engine`]. `do_changeset_draft_request`
    /// borrows its current frame to resolve an on-demand draft against the
    /// latest snapshot ([P03]). `None` (its unset state) when the draft path
    /// isn't wired (tests, or a boot without the aggregate feed).
    pub changeset_watch: std::sync::OnceLock<watch::Receiver<Frame>>,
    /// In-flight Auto-Message generation tasks, keyed by entry identity. A
    /// `changeset_draft_cancel` (or a superseding request) aborts the live
    /// handle; aborting kills only that draft's headless scribe child, never
    /// the interactive session's turn ([P06]).
    pub draft_tasks: crate::feeds::draft_engine::DraftTaskRegistry,
    /// Optional "this session's turn just ended" signal, carrying the session
    /// id. The base-motion engine listens here: its gate refuses to move a
    /// branch under a session that is mid-turn, and "the base moved during a
    /// turn" is the common shape of the problem — so a turn ending is the wake
    /// that lets a parked arc catch up seconds later rather than at the next
    /// unrelated commit. Unset in tests and in any boot without the engine,
    /// where the send is simply skipped.
    pub turn_complete_tx: std::sync::OnceLock<mpsc::Sender<String>>,
    /// The same idle transition, for the arc runner ([P05]).
    ///
    /// A sibling channel rather than a second receiver on `turn_complete_tx`:
    /// an mpsc has one consumer, and the two engines want the same edge for
    /// unrelated reasons — base-motion to catch a parked arc up, the arc to
    /// rotate its next stage. Both are fed from the one place the supervisor
    /// recognizes the transition, so neither re-derives it.
    pub arc_tick_tx: std::sync::OnceLock<mpsc::Sender<String>>,
    /// The same idle transition again, for the wheel ([P04]).
    ///
    /// A third sibling for the reason there is a second: an mpsc has one
    /// consumer, and a rotation asked for mid-turn must land at *that* turn's
    /// end — the edge computed here and nowhere else.
    pub wheel_tick_tx: std::sync::OnceLock<mpsc::Sender<String>>,
}

/// Registration sent through [`AgentSupervisor::merger_register_tx`] so the
/// merger task learns about a newly-spawned session worker's output stream.
pub type MergerRegistration = (TugSessionId, mpsc::Receiver<Frame>);

/// Wire shape of the `terminal_live` annotation on a listed session:
/// present iff a live process outside this supervisor (typically the
/// Claude Code terminal app) currently holds the session, carrying its
/// busy/idle status.
#[derive(Debug, serde::Serialize)]
pub struct TerminalLiveWire {
    pub status: &'static str,
}

/// One row of `list_sessions_ok` — the persisted/synthesized
/// `SessionRow` fields plus provenance (`origin`) and the
/// terminal-liveness annotation. `origin: "tug"` rows come from the
/// sqlite ledger; `origin: "external"` rows were discovered on disk
/// (sessions Tug never spawned, typically terminal-created) and have
/// their `SessionRow` fields synthesized: `state: "closed"`,
/// `card_id: null`, `workspace_key` set to the encoded claude project
/// directory name (no canonical workspace was ever registered for
/// them).
#[derive(Debug, serde::Serialize)]
pub struct ListedSession {
    #[serde(flatten)]
    pub row: crate::session_ledger::SessionRow,
    pub origin: &'static str,
    pub terminal_live: Option<TerminalLiveWire>,
    /// On-disk JSONL size in bytes, from the external scan. `None` when the
    /// session has not been scanned (e.g. a live ledger row in the phase-1
    /// preview, before the scan settles). The picker renders this instead of
    /// a turn count — an orthogonal "how big" signal, not a message proxy.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file_size: Option<i64>,
}

/// Build the picker's `list_sessions` row union from a ledger snapshot, a
/// terminal-liveness map, and (optionally) an external-session scan.
///
/// Ledger rows are tagged `origin: "tug"`; external scan rows not already
/// owned by the ledger are tagged `origin: "external"` with their
/// `SessionRow` fields synthesized (`state: closed`, `card_id: null`,
/// `workspace_key`/`project_dir` set to the scan's canonical dir — the form
/// claude's directory name encodes, so trash re-derives the JSONL path).
/// Every row is annotated with `terminal_live` from `live`, and the result
/// is sorted newest-first by `last_used_at`.
///
/// `scan: None` yields the ledger-only preview (phase 1); `Some` yields the
/// settled union (phase 2). Both phases route through this one builder so
/// their annotation, dedupe, and ordering can never drift.
///
/// Content-empty rows ([`is_empty_session`]) are dropped from both phases —
/// they never reach the wire.
///
/// Segments of one line do not list on their own: the picker offers **lines
/// of work**, and every id a card has lived through is one line. See
/// [`fold_lines`].
fn build_listed_union(
    rows: Vec<crate::session_ledger::SessionRow>,
    live: &HashMap<String, crate::terminal_registry::TerminalLiveEntry>,
    scan: Option<crate::external_sessions::ScanOutcome>,
) -> Vec<ListedSession> {
    let annotate = |session_id: &str| {
        live.get(session_id).map(|e| TerminalLiveWire {
            status: e.status.as_wire_str(),
        })
    };
    let mut listed: Vec<ListedSession> = Vec::with_capacity(rows.len());
    for row in rows {
        let terminal_live = annotate(&row.session_id);
        listed.push(ListedSession {
            row,
            origin: "tug",
            terminal_live,
            // Backfilled below from the scan meta when this session is on
            // disk; stays None for live-only ledger rows.
            file_size: None,
        });
    }
    if let Some(scan) = scan {
        // Index the scan metas so ledger rows can absorb fresher on-disk
        // content; whatever remains un-absorbed becomes a synthesized
        // external row.
        let mut metas_by_id: HashMap<String, crate::external_sessions::ExternalSessionMeta> = scan
            .metas
            .into_iter()
            .map(|m| (m.session_id.clone(), m))
            .collect();
        for entry in &mut listed {
            let Some(meta) = metas_by_id.remove(&entry.row.session_id) else {
                continue;
            };
            // Surface the on-disk size for the picker's size readout.
            entry.file_size = Some(meta.file_size);
            // The ledger row owns identity and lifecycle (state, card
            // binding, user-assigned name); the transcript on disk owns
            // content. When the JSONL is newer than the ledger's last
            // write — a session continued in the terminal, or a ledger
            // row that predates the transcript's tail — surface the
            // scan's content fields. Holes (zero turns, missing
            // prompt/name) backfill from the scan regardless of
            // recency: a sparser row never beats a richer one.
            let disk_fresher = meta.file_mtime > entry.row.last_used_at;
            if disk_fresher {
                entry.row.last_used_at = meta.last_used_at;
            }
            if (disk_fresher && meta.last_user_prompt.is_some())
                || entry.row.last_user_prompt.is_none()
            {
                entry.row.last_user_prompt = meta.last_user_prompt;
            }
            entry.row.turn_count = entry.row.turn_count.max(meta.turn_count);
            // A user-set name on the line outranks everything: it is the
            // user's own word, and the scan's `name` is an `aiTitle`. The
            // ledger row usually carries it already (the listing joins
            // `lines`), so this matters for the row the scan owns — but
            // preferring it here too means the two paths cannot disagree.
            if meta.line_name_user_set && meta.line_name.is_some() {
                entry.row.name = meta.line_name;
                entry.row.name_user_set = true;
            } else if entry.row.name.is_none() {
                entry.row.name = meta.name;
            }
            // A ledger row whose line has no callsign yet shows the one the
            // scan minted for it.
            if entry.row.tag.is_none() {
                entry.row.tag = meta.tag;
            }
        }
        let synthetic_workspace_key =
            crate::session_ledger::encode_claude_project_name(&scan.canonical_project_dir);
        for (_, meta) in metas_by_id {
            let terminal_live = annotate(&meta.session_id);
            let file_size = Some(meta.file_size);
            listed.push(ListedSession {
                row: crate::session_ledger::SessionRow {
                    session_id: meta.session_id,
                    workspace_key: synthetic_workspace_key.clone(),
                    project_dir: scan.canonical_project_dir.clone(),
                    created_at: meta.created_at,
                    last_used_at: meta.last_used_at,
                    turn_count: meta.turn_count,
                    last_user_prompt: meta.last_user_prompt,
                    state: crate::session_ledger::SessionState::Closed,
                    card_id: None,
                    // The **line's** name when the user typed one, else the
                    // transcript's `aiTitle`. A scanned `aiTitle` is never a
                    // user rename, but the line this session belongs to may
                    // carry one — and it does exactly when the `sessions` row
                    // is gone and the name outlived it. Reading only the
                    // `aiTitle` here is what made such a session list under a
                    // machine's guess instead of the user's own word.
                    name: if meta.line_name_user_set && meta.line_name.is_some() {
                        meta.line_name
                    } else {
                        meta.name
                    },
                    name_user_set: meta.line_name_user_set,
                    // The callsign of the line the scan birthed for this
                    // session ([P07]) — the picker sees a real tag before the
                    // session is ever adopted, and adoption seats that same
                    // line on the card rather than minting a second identity.
                    tag: meta.tag,
                    // A scanned session is a root until it is forked from.
                    // The description is ledger state; a session with no
                    // `sessions` row has none until it is adopted.
                    synopsis: None,
                    // So is the privacy flag, and an absent row reads as
                    // public everywhere the flag is enforced.
                    private: false,
                    // A scanned session has no ledger row, so nothing has
                    // ever bound it to an arc.
                    arc_id: None,
                    arc_name: None,
                    // The card-less line the scan birthed, so a fold groups a
                    // scanned session's segments exactly as it groups a
                    // ledger row's.
                    line_id: meta.line_id.unwrap_or_default(),
                },
                origin: "external",
                terminal_live,
                file_size,
            });
        }
    }
    listed.retain(|entry| !is_empty_session(&entry.row));
    let mut listed = fold_lines(listed);
    listed.sort_by(|a, b| b.row.last_used_at.cmp(&a.row.last_used_at));
    listed
}

/// Collapse each line of work into one row.
///
/// A card accumulates a session id per rotation, per rewind-fork, per
/// respawn, and the user has one conversation. They are all segments of one
/// line ([P01]), so the picker groups by `line_id`:
///
/// - The **row offered** is the line's newest *live* segment, else its newest
///   segment. That is the resume target that keeps the whole scroll: a card
///   replays parent-ward from the session it is seated on, so seating the
///   line's tip replays every stage and the conversation they grew from,
///   while seating the root would show the history and drop the arc.
/// - The **identity shown** needs no choosing: every member already carries
///   the line's callsign and name, because that is what the join reads.
/// - **Size and turns sum** across the line, because that is what the line
///   holds; the segment's own numbers would understate a card the user has
///   been working in all afternoon.
///
/// A row with no line — a synthesized shape no ledger wrote — is its own
/// group of one and passes through untouched.
fn fold_lines(listed: Vec<ListedSession>) -> Vec<ListedSession> {
    let mut order: Vec<String> = Vec::new();
    let mut groups: HashMap<String, Vec<ListedSession>> = HashMap::new();
    for entry in listed {
        let key = if entry.row.line_id.is_empty() {
            entry.row.session_id.clone()
        } else {
            entry.row.line_id.clone()
        };
        groups.entry(key.clone()).or_insert_with(|| {
            order.push(key.clone());
            Vec::new()
        });
        groups
            .get_mut(&key)
            .expect("group just inserted")
            .push(entry);
    }
    let mut folded = Vec::with_capacity(order.len());
    for key in order {
        let mut members = groups.remove(&key).expect("every ordered key has a group");
        if members.len() == 1 {
            folded.push(members.pop().expect("one member"));
            continue;
        }
        let turn_count: i64 = members.iter().map(|m| m.row.turn_count).sum();
        let file_size: Option<i64> = members
            .iter()
            .filter_map(|m| m.file_size)
            .reduce(|a, b| a + b);
        // Newest live segment, else newest segment.
        members.sort_by(|a, b| {
            let live = |m: &ListedSession| m.row.state == crate::session_ledger::SessionState::Live;
            live(b)
                .cmp(&live(a))
                .then(b.row.last_used_at.cmp(&a.row.last_used_at))
        });
        let mut base = members.swap_remove(0);
        base.row.turn_count = turn_count;
        base.file_size = file_size;
        folded.push(base);
    }
    folded
}

/// A session that holds nothing: no turns, no recorded user prompt, and no
/// title (neither a user rename nor a scanned `aiTitle`). Claude writes a
/// JSONL for every launch, so a session abandoned before its first prompt
/// leaves a transcript with nothing to resume into. The picker rendered these
/// as "No prompts yet" rows; they are dropped from `list_sessions` instead.
fn is_empty_session(row: &crate::session_ledger::SessionRow) -> bool {
    let blank = |s: &Option<String>| s.as_deref().unwrap_or("").trim().is_empty();
    row.turn_count == 0 && blank(&row.last_user_prompt) && blank(&row.name)
}

/// The session mode to stamp on an `Idle` rebound entry when a client spawn
/// request's mode differs from the entry's current mode.
///
/// Normally the request wins — a rebound-but-not-yet-spawned entry adopts the
/// request's intent (a card can legitimately open fresh in place). The one
/// exception: never downgrade to `New` while the entry still has a transcript
/// worth protecting — a persisted `claude_session_id` whose session is not
/// content-empty. A `new`-mode spawn reuses the id via `--session-id`, which
/// collides with the existing on-disk transcript ("Session ID … is already in
/// use") and crash-loops the card to `errored`. The client only requests `New`
/// for such an entry by mis-classifying a session that has a JSONL as
/// turn-count-zero on restore; hold the ledger-derived mode instead. A genuine
/// discard clears `claude_session_id` first (`do_reset`), so this guard never
/// blocks a real fresh-in-place spawn.
fn reconcile_idle_session_mode(
    current: SessionMode,
    requested: SessionMode,
    has_resumable_transcript: bool,
) -> SessionMode {
    if requested == SessionMode::New && has_resumable_transcript {
        current
    } else {
        requested
    }
}

/// Owned form of a parsed CONTROL payload.
struct OwnedControlPayload {
    card_id: String,
    tug_session_id: TugSessionId,
    /// per-session workspace path. `None` for close/reset
    /// payloads (which don't need it); `Some` for spawn payloads and
    /// rejected with `InvalidProjectDir { reason: "missing_project_dir" }`
    /// if absent on the spawn path.
    project_dir: Option<String>,
    /// New-vs-resume choice. Absent values default to
    /// `SessionMode::New` so pre-4.5 payloads keep the step-4k behavior.
    session_mode: SessionMode,
    /// Deck-wide / per-card default permission mode tugdeck resolved at spawn
    /// time, forwarded to tugcode as `--permission-mode`. `None` when the
    /// payload omits it (older client, or a card with no configured default) —
    /// the string is passed through opaquely; tugcode validates it.
    permission_mode: Option<String>,
    /// Provisional mnemonic tag tugdeck minted for a fresh spawn. `None` on
    /// close/reset payloads and on older clients. Stored on the `LedgerEntry`
    /// and claimed authoritatively by `record_spawn`; never forwarded to the
    /// child ([P07]).
    tag: Option<String>,
    /// The line of work a `mode=new` spawn is birthing, minted by the deck
    /// from the drop beside the tag ([P03]). Required on `mode=new`; on a
    /// resume it is the binding's, and absent it is read off the row being
    /// resumed.
    line_id: Option<String>,
}

fn parse_control_payload_owned(payload: &[u8]) -> Result<OwnedControlPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let card_id = value
        .get("card_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingCardId)?
        .to_string();
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string());
    let session_mode =
        SessionMode::from_wire_str(value.get("session_mode").and_then(|v| v.as_str()));
    let permission_mode = value
        .get("permission_mode")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string());
    let tag = value
        .get("tag")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string());
    let line_id = value
        .get("line_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string());
    Ok(OwnedControlPayload {
        card_id,
        tug_session_id: TugSessionId::new(tug_session_id),
        project_dir,
        session_mode,
        permission_mode,
        tag,
        line_id,
    })
}

/// Parse a CONTROL payload that carries `{ project_dir: "..." }`. The
/// picker's `list_sessions` request uses this so the lookup matches the
/// raw user-typed path (the value originally recorded by `record_spawn`).
/// `MissingSessionId`-shaped error semantics: a missing identifier the
/// lookup needs.
fn parse_project_dir_payload(payload: &[u8]) -> Result<String, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let pd = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    Ok(pd)
}

/// The ids a `resolve_sessions` request asks about ([D132]).
///
/// Capped rather than unbounded: the caller is a History card asking about the
/// commits on screen, and a request naming ten thousand ids is a bug on the
/// other side of the wire, not a query. Over the cap the extra ids are dropped
/// with a warning rather than the whole request refused — a truncated answer
/// renders as a few unresolved chips, where a refusal renders as none at all.
fn parse_session_ids_payload(payload: &[u8]) -> Result<Vec<String>, ControlError> {
    /// The most ids one request may name.
    const MAX_IDS: usize = 512;
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let ids = value
        .get("ids")
        .and_then(|v| v.as_array())
        .ok_or(ControlError::Malformed)?;
    if ids.len() > MAX_IDS {
        warn!(
            asked = ids.len(),
            cap = MAX_IDS,
            "resolve_sessions: request over the cap, answering the first {MAX_IDS}"
        );
    }
    Ok(ids
        .iter()
        .filter_map(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .take(MAX_IDS)
        .map(str::to_owned)
        .collect())
}

/// The changeset scribe's runtime wiring ([P11]): the spawner (production:
/// `ClaudeScribeSpawner`; tests: a fake) plus the model resolver (tugbank
/// default `dev.tugapp.changeset`/`scribe_model`, fallback `sonnet` —
/// resolved per request so a settings change applies immediately).
#[derive(Clone)]
pub struct ScribeContext {
    pub spawner: Arc<dyn crate::scribe::ScribeSpawner>,
    pub model: Arc<dyn Fn() -> String + Send + Sync>,
}

/// Parsed `changeset_commit` request: project dir, repo-relative file list,
/// commit message (Spec S03). The file list may parse empty — the handler
/// refuses it with a `changeset_commit_err` the card can render, rather than
/// a protocol error.
struct ChangesetCommitPayload {
    project_dir: String,
    files: Vec<String>,
    message: String,
    /// Optional session id for the `Tug-Session:` trailer (Spec S01). The
    /// trailer's display name is resolved from the ledger by id — the client
    /// stopped sending a `session_name` beside it.
    session_id: Option<String>,
    /// Optional per-path hunk election (Spec S03): repo-relative path → the
    /// ids of the hunks to land. Absent means whole-file staging for every
    /// path, which is what every caller sent before hunks existed.
    hunks: Option<BTreeMap<String, Vec<String>>>,
}

fn parse_changeset_commit_payload(payload: &[u8]) -> Result<ChangesetCommitPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let files = value
        .get("files")
        .and_then(|v| v.as_array())
        .ok_or(ControlError::Malformed)?
        .iter()
        .map(|v| {
            v.as_str()
                .map(str::to_string)
                .ok_or(ControlError::Malformed)
        })
        .collect::<Result<Vec<String>, ControlError>>()?;
    let message = value
        .get("message")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let session_id = value
        .get("session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    let hunks = parse_hunk_election(&value, &files)?;
    Ok(ChangesetCommitPayload {
        project_dir,
        files,
        message,
        session_id,
        hunks,
    })
}

/// Read the optional `hunks` map (Spec S03) off a `changeset_commit` payload.
///
/// Every key must also appear in `files` — an election naming a path the
/// commit is not landing is a malformed request, not a silent no-op. An
/// absent or empty map reads as `None`, which keeps the whole-file path
/// byte-for-byte what it was.
fn parse_hunk_election(
    value: &serde_json::Value,
    files: &[String],
) -> Result<Option<BTreeMap<String, Vec<String>>>, ControlError> {
    let Some(raw) = value.get("hunks") else {
        return Ok(None);
    };
    if raw.is_null() {
        return Ok(None);
    }
    let object = raw.as_object().ok_or(ControlError::Malformed)?;
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for (path, ids) in object {
        if !files.iter().any(|f| f == path) {
            return Err(ControlError::Malformed);
        }
        let ids = ids
            .as_array()
            .ok_or(ControlError::Malformed)?
            .iter()
            .map(|v| {
                v.as_str()
                    .map(str::to_string)
                    .ok_or(ControlError::Malformed)
            })
            .collect::<Result<Vec<String>, ControlError>>()?;
        map.insert(path.clone(), ids);
    }
    Ok(if map.is_empty() { None } else { Some(map) })
}

/// A `changeset_claim` CONTROL request: a session claims the listed files
/// outright — the intentional promotion of files it touched but never
/// proof-edited (a `perl`/`sed` edit, a hand save) from "likely" hints into
/// its changeset. `session_id` is required (a claim is by a specific session);
/// `files` are repo-relative, exactly as the changeset surfaces them.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ChangesetClaimPayload {
    project_dir: String,
    session_id: String,
    files: Vec<String>,
}

fn parse_changeset_claim_payload(payload: &[u8]) -> Result<ChangesetClaimPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let session_id = value
        .get("session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let files = value
        .get("files")
        .and_then(|v| v.as_array())
        .ok_or(ControlError::Malformed)?
        .iter()
        .map(|v| {
            v.as_str()
                .map(str::to_string)
                .ok_or(ControlError::Malformed)
        })
        .collect::<Result<Vec<String>, ControlError>>()?;
    Ok(ChangesetClaimPayload {
        project_dir,
        session_id,
        files,
    })
}

/// A `deck_seatings` CONTROL request: the deck's full-replacement report of
/// which tug sessions its open Session cards are seated on. Only the session
/// ids matter server-side (the changeset compose folds them into liveness);
/// the `card_id` each entry carries is observability the payload keeps for
/// the wire log. An empty list is a valid report — "seated on nothing".
fn parse_deck_seatings_payload(payload: &[u8]) -> Result<HashSet<String>, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let seatings = value
        .get("seatings")
        .and_then(|v| v.as_array())
        .ok_or(ControlError::Malformed)?;
    let mut session_ids = HashSet::new();
    for entry in seatings {
        let id = entry
            .get("tug_session_id")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .ok_or(ControlError::Malformed)?;
        session_ids.insert(id.to_string());
    }
    Ok(session_ids)
}

/// A `changeset_disclaim` CONTROL request: a session renounces the listed
/// files — the inverse of a claim. Same shape as the claim payload; the
/// session's own rows for those paths are deleted, so the file falls to
/// another live owner or to unattributed.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ChangesetDisclaimPayload {
    project_dir: String,
    session_id: String,
    files: Vec<String>,
}

fn parse_changeset_disclaim_payload(
    payload: &[u8],
) -> Result<ChangesetDisclaimPayload, ControlError> {
    let claim = parse_changeset_claim_payload(payload)?;
    Ok(ChangesetDisclaimPayload {
        project_dir: claim.project_dir,
        session_id: claim.session_id,
        files: claim.files,
    })
}

/// The commit message enriched with the session trailer pair ([P13], Spec
/// S03): `Tug-Session` carrying the human citation `<tag> (<shortid8>)` and
/// `Tug-Session-Id` the full uuid a reader joins against the ledger. Without a
/// session id the message is returned byte-for-byte. Idempotent via
/// `append_trailers`.
///
/// **The citation names the line, the id pins the segment.** A card that has
/// rotated through eight ids has one line of work, and a reader following a
/// commit back wants the conversation rather than whichever segment happened
/// to be seated — so the short id in parentheses is the line's. `Tug-Session-Id`
/// beside it is still the segment's full uuid, which is what opens the exact
/// transcript the commit was made from.
///
/// `tag` and `line_id` are resolved from the ledger by the caller, not taken
/// from the deck's payload — the ledger is the authority on a callsign, and
/// the deck may still be holding the optimistic one it minted at spawn. The
/// citation grammar itself lives in `tugchanges_core::session_citation`,
/// shared with the arc lane so the two can never drift.
fn changeset_commit_message(
    request: &ChangesetCommitPayload,
    tag: Option<&str>,
    line_id: Option<&str>,
) -> String {
    let Some(id) = request.session_id.as_deref().filter(|s| !s.is_empty()) else {
        return request.message.clone();
    };
    let citation = tugchanges_core::session_citation(tag, line_id.unwrap_or(id));
    tugchanges_core::append_trailers(
        &request.message,
        &[("Tug-Session", &citation), ("Tug-Session-Id", id)],
    )
}

/// Parsed `changeset_draft_request` (Spec S01): the entry identity an on-demand
/// draft is requested for. `owner_id` may be empty (the unattributed pseudo-
/// entry), so it is not filtered non-empty. `force` is the confirmed
/// Regenerate — the only path that overwrites an edited draft ([P03]).
///
/// The project is named by `workspace_key`, the registry's canonical spelling
/// ([L29]) — never a `project_dir`, which is raw and has as many spellings as
/// the checkout has symlinks pointing at it.
struct ChangesetDraftRequestPayload {
    workspace_key: String,
    owner_kind: String,
    owner_id: String,
    force: bool,
}

fn parse_changeset_draft_request_payload(
    payload: &[u8],
) -> Result<ChangesetDraftRequestPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let workspace_key = value
        .get("workspace_key")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_workspace_key",
        })?
        .to_string();
    let owner_kind = value
        .get("owner_kind")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let owner_id = value
        .get("owner_id")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let force = value
        .get("force")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    Ok(ChangesetDraftRequestPayload {
        workspace_key,
        owner_kind,
        owner_id,
        force,
    })
}

/// Parsed `changeset_draft_cancel` ([P06]): the entry identity whose in-flight
/// Auto-Message the user cancelled. Same identity shape as the request; no
/// force / message fields.
struct ChangesetDraftCancelPayload {
    workspace_key: String,
    owner_kind: String,
    owner_id: String,
}

fn parse_changeset_draft_cancel_payload(
    payload: &[u8],
) -> Result<ChangesetDraftCancelPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let workspace_key = value
        .get("workspace_key")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_workspace_key",
        })?
        .to_string();
    let owner_kind = value
        .get("owner_kind")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let owner_id = value
        .get("owner_id")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    Ok(ChangesetDraftCancelPayload {
        workspace_key,
        owner_kind,
        owner_id,
    })
}

/// Parsed `changeset_draft_set` (Spec S01): a partial upsert of one draft
/// row — the composer's debounced message edits, immediate selection-toggle
/// writes, and the post-landing `clear`. Absent fields leave the stored
/// value untouched; `selection: null` clears the overrides; `clear: true`
/// deletes the whole row.
struct ChangesetDraftSetPayload {
    workspace_key: String,
    owner_kind: String,
    owner_id: String,
    message: Option<String>,
    /// `None` = field absent (keep); `Some(None)` = explicit null (clear);
    /// `Some(Some(json))` = replace with the serialized overrides.
    selection: Option<Option<String>>,
    edited: bool,
    clear: bool,
}

fn parse_changeset_draft_set_payload(
    payload: &[u8],
) -> Result<ChangesetDraftSetPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let workspace_key = value
        .get("workspace_key")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_workspace_key",
        })?
        .to_string();
    let owner_kind = value
        .get("owner_kind")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let owner_id = value
        .get("owner_id")
        .and_then(|v| v.as_str())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let message = value
        .get("message")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let selection = value.get("selection").map(|v| {
        if v.is_null() {
            None
        } else {
            Some(v.to_string())
        }
    });
    let edited = value
        .get("edited")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let clear = value
        .get("clear")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    Ok(ChangesetDraftSetPayload {
        workspace_key,
        owner_kind,
        owner_id,
        message,
        selection,
        edited,
        clear,
    })
}

/// Parsed `changeset_join` request (Spec S03): the project checkout, the arc
/// name, an optional strategy (`squash`|`merge`|`rebase`, default squash), an
/// optional override message, and whether this is an in-memory `--preview`.
struct ChangesetJoinPayload {
    project_dir: String,
    arc: String,
    strategy: tugarc_core::JoinStrategy,
    message: Option<String>,
    preview: bool,
    /// A pre-resolved candidate commit to land ([P31]/[P32], Spec S12): when
    /// present the join takes its resolved bytes instead of merging the arc
    /// branch, staleness-guarded by ancestry. `strategy` still decides the
    /// shape — a candidate never turns a squash into anything else.
    candidate: Option<String>,
    /// Resume an interrupted teardown from the journal (Spec S04).
    continue_join: bool,
    /// The calling card's tug session id, for the receipt's shell-ledger row
    /// ([P06]). Absent, the landing still succeeds and leaves no receipt.
    session_id: Option<String>,
}

fn parse_changeset_join_payload(payload: &[u8]) -> Result<ChangesetJoinPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let arc = value
        .get("arc")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let strategy = match value.get("strategy").and_then(|v| v.as_str()) {
        None | Some("squash") => tugarc_core::JoinStrategy::Squash,
        Some("merge") => tugarc_core::JoinStrategy::Merge,
        Some("rebase") => tugarc_core::JoinStrategy::Rebase,
        Some(_) => return Err(ControlError::Malformed),
    };
    let message = value
        .get("message")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let preview = value
        .get("preview")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let candidate = value
        .get("candidate")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let continue_join = value
        .get("continue")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let session_id = parse_optional_session_id(&value);
    Ok(ChangesetJoinPayload {
        project_dir,
        arc,
        strategy,
        message,
        preview,
        candidate,
        continue_join,
        session_id,
    })
}

/// The optional `session_id` the landing verbs carry for their receipt row
/// ([P06]). Missing or empty is not an error — the receipt is simply skipped.
fn parse_optional_session_id(value: &serde_json::Value) -> Option<String> {
    value
        .get("session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string)
}

/// Parsed `changeset_join_resolve` request (Spec S12): the project checkout and
/// the arc name.
struct ChangesetJoinResolvePayload {
    project_dir: String,
    arc: String,
}

fn parse_changeset_join_resolve_payload(
    payload: &[u8],
) -> Result<ChangesetJoinResolvePayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let arc = value
        .get("arc")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    Ok(ChangesetJoinResolvePayload { project_dir, arc })
}

/// Parsed `changeset_join_question_answer` request ([P06]): the user's answer
/// to a resolver escalation.
///
/// The `request_id` is what makes the answer safe: a resolve that already
/// expired, or a second one raised since, must not be resolved by an answer to
/// a different question.
struct ChangesetJoinQuestionAnswerPayload {
    project_dir: String,
    arc: String,
    request_id: String,
    /// An option label or free text — handed to the resolver verbatim.
    answer: String,
}

fn parse_changeset_join_question_answer_payload(
    payload: &[u8],
) -> Result<ChangesetJoinQuestionAnswerPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let field = |key: &str| {
        value
            .get(key)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .ok_or(ControlError::Malformed)
    };
    Ok(ChangesetJoinQuestionAnswerPayload {
        project_dir,
        arc: field("arc")?,
        request_id: field("request_id")?,
        answer: field("answer")?,
    })
}

/// Parsed `changeset_discard` request: the project checkout and the arc name.
struct ChangesetDiscardPayload {
    project_dir: String,
    arc: String,
    /// The calling card's tug session id, for the receipt's row ([P06]).
    session_id: Option<String>,
}

fn parse_changeset_discard_payload(
    payload: &[u8],
) -> Result<ChangesetDiscardPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let arc = value
        .get("arc")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let session_id = parse_optional_session_id(&value);
    Ok(ChangesetDiscardPayload {
        project_dir,
        arc,
        session_id,
    })
}

/// Parsed `changeset_replay` request: the project checkout and the arc name.
struct ChangesetReplayPayload {
    project_dir: String,
    arc: String,
    /// The calling card's tug session id, for the outcome's notice.
    session_id: Option<String>,
}

fn parse_changeset_replay_payload(payload: &[u8]) -> Result<ChangesetReplayPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let arc = value
        .get("arc")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let session_id = parse_optional_session_id(&value);
    Ok(ChangesetReplayPayload {
        project_dir,
        arc,
        session_id,
    })
}

/// One land press, as the deck reported it, ready to be written down.
///
/// The deck's own log dies with a reload, and the 2026-08-17 incident contained
/// one — so the only durable record an instance has of a landing gesture is
/// this crate's log. What lands here is what the deck's land gate actually
/// judged: the press, its verdict, and the inputs behind it.
struct LandingReceiptPayload {
    kind: String,
    verdict: String,
    reason: String,
    gate: String,
}

/// Read a receipt without ever refusing one.
///
/// Every field is optional and a missing one logs as `-`. A receipt that could
/// be rejected would be a diagnostic with a failure mode of its own, and the
/// press it describes has already happened either way.
fn parse_landing_receipt_payload(payload: &[u8]) -> LandingReceiptPayload {
    let value: serde_json::Value =
        serde_json::from_slice(payload).unwrap_or(serde_json::Value::Null);
    let field = |name: &str| {
        value
            .get(name)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("-")
            .to_string()
    };
    let gate = value
        .get("gate")
        .map(|g| g.to_string())
        .unwrap_or_else(|| "-".to_string());
    LandingReceiptPayload {
        kind: field("kind"),
        verdict: field("verdict"),
        reason: field("reason"),
        gate,
    }
}

fn parse_session_id_payload(payload: &[u8]) -> Result<String, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    // Reuse the `MissingSessionId` variant — semantically the same shape:
    // a CONTROL action that needs an id and didn't get one.
    let id = value
        .get("session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    Ok(id)
}

/// Parse a `trash_session` CONTROL payload: `{ session_id, project_dir? }`.
/// `project_dir` is optional — the picker supplies it for external rows
/// (sessions with no ledger row) so the JSONL can be located without a
/// `project_dir` column to consult.
fn parse_trash_session_payload(payload: &[u8]) -> Result<(String, Option<String>), ControlError> {
    let session_id = parse_session_id_payload(payload)?;
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string());
    Ok((session_id, project_dir))
}

/// Parse a `rename_session` CONTROL payload: `{ line_id, name }`. A missing /
/// empty / whitespace-only `name` clears the name (`None`); otherwise the
/// trimmed name is kept.
///
/// **A rename names a line, not a segment** ([P11]). The name is the line's
/// title, so the address is the line's id — an id the deck holds for every
/// card it has a binding for, and one that does not move when the card's
/// claude id rotates mid-rename.
fn parse_rename_session_payload(payload: &[u8]) -> Result<(String, Option<String>), ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let id = value
        .get("line_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingLineId)?
        .to_string();
    let name = value
        .get("name")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    Ok((id, name))
}

/// Parse a `set_session_private` CONTROL payload: `{ session_id, private }`.
/// A missing or non-boolean `private` reads as `true` — the payload's only
/// reason to exist is to mark a session, and defaulting the other way would
/// silently do nothing to a session the user just asked to hide.
fn parse_set_session_private_payload(payload: &[u8]) -> Result<(String, bool), ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let id = value
        .get("session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let private = value
        .get("private")
        .and_then(|v| v.as_bool())
        .unwrap_or(true);
    Ok((id, private))
}

/// Parse a CONTROL payload that carries `{ tug_session_id: "..." }` only.
/// `request_replay` per [D12] uses this shape: a verb that addresses a
/// specific Live session by its tug-side id and carries no other state
/// (no card_id — the verb is dispatch-side bookkeeping; no project_dir —
/// the supervisor already knows the workspace from the ledger entry).
///
/// Returning `MissingSessionId` matches the variant `parse_control_payload_owned`
/// uses when its `tug_session_id` field is absent — same semantics, same
/// wire-side error category.
/// A `bind_arc` request: which session is taking up which arc, in which
/// project (Spec S03).
struct BindArcPayload {
    tug_session_id: String,
    project_dir: String,
    arc: String,
}

fn parse_bind_arc_payload(payload: &[u8]) -> Result<BindArcPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let project_dir = value
        .get("project_dir")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::InvalidProjectDir {
            reason: "missing_project_dir",
        })?
        .to_string();
    let arc = value
        .get("arc")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    Ok(BindArcPayload {
        tug_session_id,
        project_dir,
        arc,
    })
}

/// Build a CODE_INPUT frame from a payload the caller composed.
pub(crate) fn code_input_frame(payload: &serde_json::Value) -> Frame {
    Frame::new(
        FeedId::CODE_INPUT,
        serde_json::to_vec(payload).expect("stage frame payload serializes"),
    )
}

/// The resident context window a `cost_update` reports, in tokens ([P07]).
///
/// `usage` on a `cost_update` is the turn's **last** tool-loop iteration, and
/// tugcode's wire docs state plainly that `input + cache_read +
/// cache_creation + output` on that iteration is the resident window after the
/// turn. `result.usage` would be the sum across every API call of the turn,
/// which over-counts by roughly the number of tool calls — so this reads the
/// frame's own `usage` and never a total.
/// A `turn_complete` whose result was an API error — tugcode marks the frame
/// when claude's result text began `API Error:`.
pub(crate) fn turn_ended_in_api_error(payload: &[u8]) -> bool {
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(payload) else {
        return false;
    };
    value.get("type").and_then(|t| t.as_str()) == Some("turn_complete")
        && value.get("is_api_error").and_then(|v| v.as_bool()) == Some(true)
}

/// A `turn_cancelled` the **user** caused — tugcode leaves the frame unmarked
/// for their cancel and sets `is_recovery` when it force-terminated a wedged
/// claude to recover it. A frame from a build before that marker existed
/// carries no field and reads as a user cancel, which is what it was.
pub(crate) fn turn_ended_in_user_cancel(payload: &[u8]) -> bool {
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(payload) else {
        return false;
    };
    value.get("type").and_then(|t| t.as_str()) == Some("turn_cancelled")
        && value.get("is_recovery").and_then(|v| v.as_bool()) != Some(true)
}

/// The prefix that marks a provisional [`LedgerEntry::open_jobs`] key — one
/// opened at a launching `tool_use` and not yet confirmed by a `task_started`.
///
/// A `task_id` from claude is a short opaque token (`bfxxjpakz`), so it cannot
/// collide with this; the prefix is named here rather than spelled inline so
/// the writer, the re-key, and the wake's sweep cannot spell it three ways.
const LAUNCH_KEY_PREFIX: &str = "launch:";

/// The provisional key for a launching call's `tool_use_id`.
fn launch_key(tool_use_id: &str) -> String {
    format!("{LAUNCH_KEY_PREFIX}{tool_use_id}")
}

/// What a `task_started` / `task_updated` / `wake_started` frame does to a
/// session's set of open background jobs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum JobEdge {
    /// A job began — its `task_id` joins the open set.
    Opened(String),
    /// A job reported a terminal status — its `task_id` leaves the open set.
    Closed(String),
}

/// Read a job edge off a frame, if it carries one.
///
/// The statuses are claude's own: `completed`, `failed`, and the `killed` a
/// stop or a `Monitor` timeout produces. Anything else on a `task_updated` is a
/// mid-life status the wire has not shown us, and leaves the job open — the
/// conservative direction, since the cost of holding a job open too long is a
/// join offered a beat late, while closing it early is the bug this exists to
/// prevent.
///
/// A `wake_started` closes too. tugcode translates claude's
/// `system/task_notification` into `wake_started{wake_trigger:{task_id,
/// tool_use_id, status}}` (`buildWakeStartedMessage` in
/// `tugcode/src/session.ts`), so `task_notification` never reaches this wire
/// under that name and the id lives under `wake_trigger` rather than at the top
/// level. Its status vocabulary is `completed` / `failed` / `stopped`, where a
/// missing status defaults to `stopped` on tugcode's side. The deck reads its
/// close off the same field (`terminalJobStatusFromWire`), which is what keeps
/// the two readers of this wire in agreement.
///
/// A background **agent**'s terminal `task_updated` can land after the wake its
/// completion drives, which is harmless: the wake has already reopened the turn
/// by then, so the session is un-quiet either way and the set closes when the
/// frame arrives.
pub(crate) fn parse_job_edge(payload: &[u8]) -> Option<JobEdge> {
    let value: serde_json::Value = serde_json::from_slice(payload).ok()?;
    // The task id is read per shape, not once up front: a `wake_started`
    // carries none at the top level, so a single leading read would return
    // `None` for every one of them before the match was ever consulted.
    match value.get("type")?.as_str()? {
        "task_started" => Some(JobEdge::Opened(nonempty_task_id(&value)?)),
        "task_updated" => {
            let task_id = nonempty_task_id(&value)?;
            match value.get("status")?.as_str()? {
                "completed" | "failed" | "killed" => Some(JobEdge::Closed(task_id)),
                _ => None,
            }
        }
        "wake_started" => {
            // Every wake closes. A wake naming a job in a terminal status
            // closes that job by name; every other wake — the scheduler's own
            // re-init carrying no `wake_trigger` or an empty `task_id`, and a
            // named job reporting a status the wire has not shown us — closes
            // with an empty name, which the `Closed` arm reads as "nothing
            // named". That still matters, because a wake is the model
            // speaking again, and the provisional launches the arm sweeps are
            // exactly the entries whose gap the wake has just ended. Leaving
            // a named job open on an unknown status is the same conservative
            // direction the `task_updated` arm takes.
            let named = value.get("wake_trigger").and_then(|trigger| {
                let task_id = nonempty_task_id(trigger)?;
                let status = trigger.get("status")?.as_str()?;
                matches!(status, "completed" | "failed" | "stopped").then_some(task_id)
            });
            Some(JobEdge::Closed(named.unwrap_or_default()))
        }
        _ => None,
    }
}

/// The frame's `task_id`, or `None` when it is absent or empty.
///
/// An empty one is the harness-owned scheduler's re-init shape — a wake with no
/// job behind it, and nothing to track.
fn nonempty_task_id(value: &serde_json::Value) -> Option<String> {
    let task_id = value.get("task_id")?.as_str()?;
    (!task_id.is_empty()).then(|| task_id.to_owned())
}

/// The `tool_use_id` of a `tool_use` frame whose call launches background
/// work — `run_in_background: true` in the input, or the `Monitor` tool,
/// which is background activity by nature. This is the deck's `isJobLaunch`
/// gate (`select-jobs.ts`), applied at tugcast's fold so the two readers of
/// one wire count the same jobs. Everything else — including a foreground
/// `Agent` call, whose later `task_started` must open nothing — answers
/// `None`.
fn parse_background_launch(payload: &[u8]) -> Option<String> {
    let value: serde_json::Value = serde_json::from_slice(payload).ok()?;
    if value.get("type")?.as_str()? != "tool_use" {
        return None;
    }
    let tool_use_id = value.get("tool_use_id")?.as_str()?;
    if tool_use_id.is_empty() {
        return None;
    }
    let backgrounded = value
        .get("input")
        .and_then(|i| i.get("run_in_background"))
        .and_then(|b| b.as_bool())
        == Some(true);
    let monitor = value.get("tool_name").and_then(|n| n.as_str()) == Some("Monitor");
    (backgrounded || monitor).then(|| tool_use_id.to_owned())
}

/// The `tool_use_id` a `task_started` frame names as its launching call, for
/// matching against [`LedgerEntry::background_launches`].
fn parse_task_started_launch_id(payload: &[u8]) -> Option<String> {
    let value: serde_json::Value = serde_json::from_slice(payload).ok()?;
    let tool_use_id = value.get("tool_use_id")?.as_str()?;
    (!tool_use_id.is_empty()).then(|| tool_use_id.to_owned())
}

/// The frame family a job edge came from, for the edge trace — so a trace
/// reading `job_closed` says whether the close arrived on the status flip or on
/// the wake behind it.
fn frame_family(payload: &[u8]) -> &'static str {
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(payload) else {
        return "unknown";
    };
    match value.get("type").and_then(|t| t.as_str()) {
        Some("task_started") => "task_started",
        Some("task_updated") => "task_updated",
        Some("wake_started") => "wake_started",
        _ => "unknown",
    }
}

/// What one frame says about the session's resident context window.
enum ContextWindowUpdate {
    /// A usage frame's reading, held until the next one replaces it.
    Measured(i64),
    /// A compaction: whatever was being held measures a context that no longer
    /// exists.
    Retired,
}

/// The window reading a frame writes, or `None` for the frames that say
/// nothing about it.
///
/// **A compact turn produces no usage frame of its own**, so before this the
/// pre-compaction figure stood as the session's reading straight through the
/// compaction and into the tick that judged it — and the arc, reading a number
/// still above its threshold, would rotate the stage to a fresh session over a
/// context it had just brought down. Retiring it says the true thing instead:
/// there is no measurement of this context yet. A missing reading is no reason
/// to strand a stage that has steps left, so the arc walks on and the next
/// real turn's first `streaming_usage` writes the size that matters.
///
/// The boundary carries a `post_tokens` of its own, and it is deliberately not
/// read here: it counts the compacted transcript rather than the resident
/// window, and turning one into the other would need an estimate of the
/// session's base — a second measurement of the same thing.
fn context_window_update(payload: &[u8]) -> Option<ContextWindowUpdate> {
    let value: serde_json::Value = serde_json::from_slice(payload).ok()?;
    // The frame's own `type`, never a substring of its bytes. The merger's
    // other gates are needles because they run in front of a parse nobody
    // else is paying for; this one runs in front of the reading below, which
    // parses every frame anyway — so a needle here buys nothing and costs the
    // false match, and an assistant message quoting a boundary frame (this
    // feature's own documents do) would retire a reading nothing replaced.
    if value.get("type").and_then(|ty| ty.as_str()) == Some("compact_boundary") {
        return Some(ContextWindowUpdate::Retired);
    }
    parse_context_window(&value).map(ContextWindowUpdate::Measured)
}

fn parse_context_window(value: &serde_json::Value) -> Option<i64> {
    match value.get("type")?.as_str()? {
        // Turn-final and main-lane only, so it needs no guard.
        "cost_update" => {}
        // Emitted once per `message_start` / `message_delta`, so the most
        // recent one is the window right now. A background subagent lane gets
        // its own frames, stamped with the tool use that spawned them — that
        // usage is the subagent's small window rather than the session's
        // resident one, and summing it here would misreport both.
        "streaming_usage" => {
            if value
                .get("parent_tool_use_id")
                .is_some_and(|id| !id.is_null())
            {
                return None;
            }
        }
        _ => return None,
    }
    let usage = value.get("usage")?.as_object()?;
    let total: i64 = [
        "input_tokens",
        "output_tokens",
        "cache_creation_input_tokens",
        "cache_read_input_tokens",
    ]
    .iter()
    .filter_map(|key| usage.get(*key).and_then(serde_json::Value::as_i64))
    .sum();
    (total > 0).then_some(total)
}

/// The `model` field of a `model_change` CODE_INPUT frame ([P15]). A blank
/// selector reads as absent — there is no model named "".
fn parse_model_selector(payload: &[u8]) -> Option<String> {
    let value: serde_json::Value = serde_json::from_slice(payload).ok()?;
    let model = value.get("model")?.as_str()?.trim();
    (!model.is_empty()).then(|| model.to_owned())
}

/// The four spellings of the two doors, as a prompt's first token.
const ARC_DOOR_PREFIXES: [&str; 4] = ["/arc", "/arc-plan", "/tugplug:arc", "/tugplug:arc-plan"];

/// The arc a door prompt names, or `None` for every other prompt.
///
/// A prompt whose first token is one of the two doors — `/arc`, `/arc-plan`,
/// or their `/tugplug:` spellings — and whose one and only other token is a
/// well-formed arc name (alphanumerics and hyphens, at least two characters,
/// and one `validate_arc_name` would accept, so a reserved word like
/// `status` never binds) names the arc the door is about to open. That is
/// the earliest moment the arc exists anywhere, and it is when the Session
/// card should start reading `ARC` over the session.
///
/// Deliberately narrow: a name is never guessed from prose. `/arc make the
/// ring pulse` opens on an idea whose first word happens to be a legal
/// name, and `/arc` alone opens on nothing yet; both return `None`, and that
/// door settles its name in conversation and binds itself when it writes
/// the brief. The lone-argument form is the one the door itself reads as a
/// name ("a lone argument that names an existing arc is a continuation").
fn arc_door_target(text: &str) -> Option<&str> {
    let mut tokens = text.split_whitespace();
    let door = tokens.next()?;
    if !ARC_DOOR_PREFIXES.contains(&door) {
        return None;
    }
    let name = tokens.next()?;
    if tokens.next().is_some() {
        return None;
    }
    let shaped = name.len() >= 2 && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-');
    if !shaped || tugarc_core::validate_arc_name(name).is_err() {
        return None;
    }
    Some(name)
}

fn parse_tug_session_id_payload(payload: &[u8]) -> Result<TugSessionId, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    Ok(TugSessionId::new(id))
}

/// Stamp `tug_session_id` onto a persisted SESSION_SIDEBAND replay payload
/// so it passes the client-side session filter ([D06]/[D11]). Parses the
/// JSON and sets the field (overwriting any stale value from a prior
/// binding), preserving every other field. A payload that fails to parse
/// falls back to [`splice_tug_session_id`] — same insert-after-first-brace
/// semantics the live relay path uses, with its pass-through-unchanged
/// behavior for hopeless blobs. Cold path (runs once per bind), so the
/// parse cost is irrelevant.
fn stamp_tug_session_id(payload: Vec<u8>, tug_session_id: &str) -> Vec<u8> {
    match serde_json::from_slice::<serde_json::Value>(&payload) {
        Ok(serde_json::Value::Object(mut obj)) => {
            obj.insert(
                "tug_session_id".to_owned(),
                serde_json::Value::String(tug_session_id.to_owned()),
            );
            serde_json::to_vec(&serde_json::Value::Object(obj)).unwrap_or(payload)
        }
        _ => splice_tug_session_id(&payload, tug_session_id),
    }
}

/// Extract the optional recency `window` from a `request_replay` CONTROL
/// payload. The supervisor forwards it verbatim into the `request_replay`
/// verb it pushes to tugcode, which validates the shape at its handler
/// boundary; an absent / null / malformed payload yields `None` ⇒ a full
/// replay (the legacy behavior). Parse failures are intentionally
/// swallowed here — `parse_tug_session_id_payload` already rejected a
/// truly malformed payload before this is called.
fn parse_request_replay_window(payload: &[u8]) -> Option<serde_json::Value> {
    serde_json::from_slice::<serde_json::Value>(payload)
        .ok()
        .and_then(|v| v.get("window").cloned())
        .filter(|w| !w.is_null())
}

/// Parsed payload of the `record_turn_telemetry` CONTROL action.
/// Tugdeck → tugcast: the reducer dispatches this from
/// `handleTurnComplete` (live path only — replayed turns aren't
/// re-persisted) carrying the per-turn telemetry block the reducer
/// just computed. The supervisor's `do_record_turn_telemetry` resolves
/// `tug_session_id` to the claude `session_id` (the ledger PK) and
/// writes the row.
///
/// Field names mirror the wire-shape of tugdeck's `TurnTelemetry`
/// (camelCase nested inside `telemetry`). The outer envelope uses
/// snake_case to match the rest of the CONTROL action conventions.
#[derive(Debug)]
struct RecordTurnTelemetryPayload {
    tug_session_id: TugSessionId,
    msg_id: String,
    cost_input_tokens: i64,
    cost_output_tokens: i64,
    cost_cache_creation_input_tokens: i64,
    cost_cache_read_input_tokens: i64,
    cost_total_cost_usd: f64,
    wall_clock_ms: i64,
    awaiting_approval_ms: i64,
    transport_downtime_ms: i64,
    active_ms: i64,
    ttft_ms: Option<i64>,
    ttftc_ms: Option<i64>,
    reconnect_count: i64,
    max_stream_gap_ms: i64,
    /// Session-level `window(0)`; carried on every turn's telemetry so
    /// a resumed session restores it. `None` when the client never
    /// captured a first iteration.
    session_init_tokens: Option<i64>,
    ended_at: i64,
}

fn parse_record_turn_telemetry_payload(
    payload: &[u8],
) -> Result<RecordTurnTelemetryPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let msg_id = value
        .get("msg_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let telemetry = value.get("telemetry").ok_or(ControlError::Malformed)?;
    let cost = telemetry.get("cost").ok_or(ControlError::Malformed)?;
    let ended_at = value
        .get("ended_at")
        .and_then(|v| v.as_i64())
        .ok_or(ControlError::Malformed)?;
    let i64_or = |obj: &serde_json::Value, key: &str| -> Result<i64, ControlError> {
        obj.get(key)
            .and_then(|v| v.as_i64())
            .ok_or(ControlError::Malformed)
    };
    let optional_i64 = |obj: &serde_json::Value, key: &str| -> Option<i64> {
        match obj.get(key) {
            Some(v) if v.is_null() => None,
            Some(v) => v.as_i64(),
            None => None,
        }
    };
    Ok(RecordTurnTelemetryPayload {
        tug_session_id: TugSessionId::new(tug_session_id),
        msg_id,
        cost_input_tokens: i64_or(cost, "inputTokens")?,
        cost_output_tokens: i64_or(cost, "outputTokens")?,
        cost_cache_creation_input_tokens: i64_or(cost, "cacheCreationInputTokens")?,
        cost_cache_read_input_tokens: i64_or(cost, "cacheReadInputTokens")?,
        cost_total_cost_usd: cost
            .get("totalCostUsd")
            .and_then(|v| v.as_f64())
            .ok_or(ControlError::Malformed)?,
        wall_clock_ms: i64_or(telemetry, "wallClockMs")?,
        awaiting_approval_ms: i64_or(telemetry, "awaitingApprovalMs")?,
        transport_downtime_ms: i64_or(telemetry, "transportDowntimeMs")?,
        active_ms: i64_or(telemetry, "activeMs")?,
        ttft_ms: optional_i64(telemetry, "ttftMs"),
        ttftc_ms: optional_i64(telemetry, "ttftcMs"),
        reconnect_count: i64_or(telemetry, "reconnectCount")?,
        max_stream_gap_ms: i64_or(telemetry, "maxStreamGapMs")?,
        session_init_tokens: optional_i64(telemetry, "sessionInitTokens"),
        ended_at,
    })
}

/// Parsed payload of the `record_context_breakdown` CONTROL action.
/// Tugdeck → tugcast: the reducer dispatches this for every
/// `context_breakdown` event it consumes (live frames from tugcode +
/// the supervisor's bind-time re-emit). The supervisor's
/// `do_record_context_breakdown` resolves `tug_session_id` to the
/// claude `session_id` (the ledger PK) and writes the row.
///
/// `payload_bytes` is the serialized JSON of the wire-frame body
/// (the `payload` sub-object of the CONTROL frame, NOT the full
/// CONTROL envelope). The supervisor stores it verbatim in the
/// `context_breakdown_latest.payload` BLOB; the next bind reads it
/// back and re-emits it as a synthetic `context_breakdown` wire
/// frame.
struct RecordContextBreakdownPayload {
    tug_session_id: TugSessionId,
    payload_bytes: Vec<u8>,
    captured_at: i64,
}

/// Parsed payload of the `record_session_state_change` CONTROL action.
/// Tugdeck → tugcast: the per-card store wrapper compares the prev/new
/// indicator-tone triple after every `reduce()` and dispatches this
/// when any axis changed.
///
/// `do_record_session_state_change` resolves `tug_session_id` to the
/// claude `session_id` (the ledger PK) and writes one
/// `session_state_changes` row. The sqlite layer dedupes against the
/// most-recent persisted triple as a race safety-net; the per-card
/// pre-check is the primary dedupe.
struct RecordSessionStateChangePayload {
    tug_session_id: TugSessionId,
    at_ms: i64,
    phase: String,
    transport_state: String,
    interrupt_in_flight: bool,
}

fn parse_record_session_state_change_payload(
    payload: &[u8],
) -> Result<RecordSessionStateChangePayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let at_ms = value
        .get("at_ms")
        .and_then(|v| v.as_i64())
        .ok_or(ControlError::Malformed)?;
    let phase = value
        .get("phase")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let transport_state = value
        .get("transport_state")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::Malformed)?
        .to_string();
    let interrupt_in_flight = value
        .get("interrupt_in_flight")
        .and_then(|v| v.as_bool())
        .ok_or(ControlError::Malformed)?;
    Ok(RecordSessionStateChangePayload {
        tug_session_id: TugSessionId::new(tug_session_id),
        at_ms,
        phase,
        transport_state,
        interrupt_in_flight,
    })
}

/// Parsed payload of the `list_session_state_changes` CONTROL action.
/// Tugdeck → tugcast read: the popover-side reader asks the supervisor
/// for the persisted history of triples for a given session. The
/// supervisor resolves `tug_session_id → claude_session_id`, reads
/// every row from `session_state_changes`, and broadcasts
/// `list_session_state_changes_ok` back on CONTROL.
struct ListSessionStateChangesPayload {
    tug_session_id: TugSessionId,
}

fn parse_list_session_state_changes_payload(
    payload: &[u8],
) -> Result<ListSessionStateChangesPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    Ok(ListSessionStateChangesPayload {
        tug_session_id: TugSessionId::new(tug_session_id),
    })
}

fn parse_record_context_breakdown_payload(
    payload: &[u8],
) -> Result<RecordContextBreakdownPayload, ControlError> {
    let value: serde_json::Value =
        serde_json::from_slice(payload).map_err(|_| ControlError::Malformed)?;
    let tug_session_id = value
        .get("tug_session_id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or(ControlError::MissingSessionId)?
        .to_string();
    let captured_at = value
        .get("captured_at")
        .and_then(|v| v.as_i64())
        .ok_or(ControlError::Malformed)?;
    // Re-serialize the `payload` sub-object so the supervisor stores
    // it as a stable blob shape (it round-trips back through
    // `serde_json` even if the CONTROL frame's whitespace / key order
    // differed). The sub-object must be present and an object.
    let payload_obj = value.get("payload").ok_or(ControlError::Malformed)?;
    if !payload_obj.is_object() {
        return Err(ControlError::Malformed);
    }
    let payload_bytes = serde_json::to_vec(payload_obj).map_err(|_| ControlError::Malformed)?;
    Ok(RecordContextBreakdownPayload {
        tug_session_id: TugSessionId::new(tug_session_id),
        payload_bytes,
        captured_at,
    })
}

/// Canonical constructor for `SESSION_STATE` wire frames. Shared between
/// `agent_supervisor` (pending/spawning/closed/errored on control events)
/// and `agent_bridge` (live after session_init, errored on crash-budget
/// exhaustion). A single source of truth prevents wire-level drift between
/// publish sites.
pub(super) fn build_session_state_frame(
    tug_session_id: &TugSessionId,
    state: &str,
    detail: Option<&str>,
) -> Frame {
    let body = serde_json::json!({
        "tug_session_id": tug_session_id.as_str(),
        "state": state,
        "detail": detail,
    });
    let bytes = serde_json::to_vec(&body).expect("SESSION_STATE payload serializes");
    Frame::new(FeedId::SESSION_STATE, bytes)
}

fn build_session_unknown_frame(tug_session_id: &TugSessionId) -> Frame {
    let body = serde_json::json!({
        "type": "error",
        "detail": "session_unknown",
        "tug_session_id": tug_session_id.as_str(),
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_unknown payload serializes"),
    )
}

/// P13 spawn-budget check. Run inside `do_spawn_session`'s Phase 1 critical
/// section under the ledger lock. Returns the `detail` string that should be
/// stamped into both the `SESSION_STATE = errored` broadcast and the
/// returned `ControlError::CapExceeded`, or `None` if the spawn is
/// admissible. On admission the current `Instant` is appended to
/// `spawn_timestamps` so the rate-limit window advances atomically with
/// the cap decision.
///
/// Concurrent cap counts `Spawning` + `Live` entries only — `Idle` (intent
/// without subprocess) and `Errored` (crashed, awaiting reset) do not
/// consume slots. The per-entry `try_lock` is non-blocking; a contended
/// entry is counted conservatively as active so the cap cannot be
/// bypassed by a racing dispatcher.
fn cap_check_reason(
    ledger: &HashMap<TugSessionId, Arc<Mutex<LedgerEntry>>>,
    max_concurrent_sessions: usize,
    spawn_timestamps: &StdMutex<VecDeque<Instant>>,
    max_spawns_per_minute: usize,
) -> Option<&'static str> {
    let mut active = 0usize;
    for entry_arc in ledger.values() {
        let counted = match entry_arc.try_lock() {
            Ok(entry) => {
                matches!(entry.spawn_state, SpawnState::Spawning | SpawnState::Live)
            }
            Err(_) => true,
        };
        if counted {
            active += 1;
            if active >= max_concurrent_sessions {
                return Some("concurrent_session_cap_exceeded");
            }
        }
    }
    let mut ts = spawn_timestamps
        .lock()
        .expect("spawn_timestamps mutex poisoned");
    let now = Instant::now();
    let cutoff = now.checked_sub(Duration::from_secs(60)).unwrap_or(now);
    while ts.front().is_some_and(|&t| t < cutoff) {
        ts.pop_front();
    }
    if ts.len() >= max_spawns_per_minute {
        return Some("spawn_rate_limited");
    }
    ts.push_back(now);
    None
}

fn build_backpressure_frame(tug_session_id: &TugSessionId) -> Frame {
    let body = serde_json::json!({
        "type": "session_backpressure",
        "tug_session_id": tug_session_id.as_str(),
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("session_backpressure payload serializes"),
    )
}

/// Build the CONTROL error frame the dispatcher emits when the ledger
/// `insert_pending_turn` write fails for an inbound `user_message`.
/// Mirrors the wire shape of [`build_session_unknown_frame`] so tugdeck
/// surfaces it through the same error-frame path. The user-visible
/// behavior is identical to a `session_unknown`: the inbound frame is
/// dropped (not forwarded to tugcode), tugdeck shows an error, and the
/// session state is unchanged.
fn build_ledger_failure_frame(tug_session_id: &TugSessionId) -> Frame {
    let body = serde_json::json!({
        "type": "error",
        "detail": "ledger_insert_failed",
        "tug_session_id": tug_session_id.as_str(),
    });
    Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("ledger_insert_failed payload serializes"),
    )
}

/// Routing decision produced by the CODE_INPUT dispatcher under the per-session
/// lock and consumed outside the lock so await-heavy sends never race the
/// lock's critical section.
enum Decision {
    Drop,
    Spawn,
    Forward(mpsc::Sender<Frame>, Frame),
    Backpressure,
}

/// Which arcs a repo still has a **record** of — or that it could not be
/// asked, which is a different thing and must stay one.
///
/// `Known` is an answer: these owner-key stems have a record, and a binding
/// naming anything else names an arc that is gone. `Unreadable` is not an
/// answer — `git` could not be run at all, and an empty set there is
/// indistinguishable from a repo with no arcs in it. Collapsed into "no
/// arcs", a moved repo or a stale `project_dir` spelling silently unbinds
/// every card on the machine at once.
///
/// Built by [`AgentSupervisor::live_arc_records`], read by
/// [`AgentSupervisor::reported_binding`].
enum ArcRecords {
    Known(std::collections::HashSet<String>),
    Unreadable,
}

/// Announce a completed session↔arc mating to every connected deck.
///
/// A bind has two doors — the `bind_arc` CONTROL verb a card sends, and
/// `POST /api/arc` the CLI posts (which is what `tugtool arc create`'s
/// auto-bind rides) — and it is the same fact through either one. Both call
/// this, because a deck that learns about one door's binds but not the other's
/// wears a chip that disagrees with the ledger until something else happens to
/// repaint it.
///
/// `line_id` and `card_id` are the deck's **routing** halves, and they are the
/// difference between an announcement that lands and one that is dropped. The
/// deck walks segment → line → card to find the card wearing a session; on the
/// rotation seat the segment named here is seconds old and the deck has never
/// heard of it, so that walk resolves nothing. A caller that knows where the
/// segment sits says so and the routing needs no walk at all. `None` is for
/// the doors where the row is old news and the walk cannot fail.
pub(crate) fn broadcast_bind_arc_ok(
    control_tx: &broadcast::Sender<Frame>,
    tug_session_id: &str,
    arc_id: &str,
    arc_name: &str,
    line_id: Option<&str>,
    card_id: Option<&str>,
) {
    let mut body = serde_json::json!({
        "action": "bind_arc_ok",
        "tug_session_id": tug_session_id,
        "arc_id": arc_id,
        "arc_name": arc_name,
    });
    if let Some(map) = body.as_object_mut() {
        if let Some(line_id) = line_id {
            map.insert("line_id".into(), serde_json::Value::from(line_id));
        }
        if let Some(card_id) = card_id {
            map.insert("card_id".into(), serde_json::Value::from(card_id));
        }
    }
    let _ = control_tx.send(Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("bind_arc_ok serializes"),
    ));
}

/// The unmating half of [`broadcast_bind_arc_ok`], with the same two doors.
pub(crate) fn broadcast_unbind_arc_ok(control_tx: &broadcast::Sender<Frame>, tug_session_id: &str) {
    let body = serde_json::json!({
        "action": "unbind_arc_ok",
        "tug_session_id": tug_session_id,
    });
    let _ = control_tx.send(Frame::new(
        FeedId::CONTROL,
        serde_json::to_vec(&body).expect("unbind_arc_ok serializes"),
    ));
}

impl AgentSupervisor {
    /// Construct a supervisor with pre-made broadcast senders, a sessions
    /// recorder, and a spawner factory. Returns `(supervisor,
    /// merger_register_rx)` — the caller is expected to `tokio::spawn`
    /// [`AgentSupervisor::merger_task`] with the returned receiver.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        session_state: SessionScopedFeed,
        session_sideband: SessionScopedFeed,
        code_output: SessionScopedFeed,
        activity: SessionScopedFeed,
        control_tx: broadcast::Sender<Frame>,
        sessions_recorder: Arc<dyn SessionsRecorder>,
        spawner_factory: SpawnerFactory,
        config: AgentSupervisorConfig,
        registry: Arc<WorkspaceRegistry>,
        cancel: CancellationToken,
    ) -> (Self, mpsc::Receiver<MergerRegistration>) {
        Self::new_with_ledger(
            session_state,
            session_sideband,
            code_output,
            activity,
            control_tx,
            sessions_recorder,
            None,
            spawner_factory,
            config,
            registry,
            cancel,
        )
    }

    /// Construct a supervisor with an explicit `Arc<SessionLedger>` for the
    /// read-side CONTROL ops. Production wires this in `main.rs`; unit tests
    /// that don't exercise the ledger CONTROL paths use [`Self::new`] and
    /// get `None`.
    #[allow(clippy::too_many_arguments)]
    pub fn new_with_ledger(
        session_state: SessionScopedFeed,
        session_sideband: SessionScopedFeed,
        code_output: SessionScopedFeed,
        activity: SessionScopedFeed,
        control_tx: broadcast::Sender<Frame>,
        sessions_recorder: Arc<dyn SessionsRecorder>,
        session_ledger: Option<Arc<crate::session_ledger::SessionLedger>>,
        spawner_factory: SpawnerFactory,
        config: AgentSupervisorConfig,
        registry: Arc<WorkspaceRegistry>,
        cancel: CancellationToken,
    ) -> (Self, mpsc::Receiver<MergerRegistration>) {
        let (merger_register_tx, merger_register_rx) = mpsc::channel(64);
        let sup = Self {
            ledger: Arc::new(Mutex::new(HashMap::new())),
            session_state,
            session_sideband,
            client_sessions: Arc::new(Mutex::new(HashMap::new())),
            code_output,
            activity,
            control_tx,
            sessions_recorder,
            session_ledger,
            shell_ledger: None,
            refs_ledger: None,
            scribe: None,
            spawner_factory,
            merger_register_tx,
            config,
            registry,
            cancel,
            spawn_timestamps: Arc::new(StdMutex::new(VecDeque::new())),
            changeset_watch: std::sync::OnceLock::new(),
            draft_tasks: crate::feeds::draft_engine::DraftTaskRegistry::default(),
            turn_complete_tx: std::sync::OnceLock::new(),
            arc_tick_tx: std::sync::OnceLock::new(),
            wheel_tick_tx: std::sync::OnceLock::new(),
        };
        // Published for the readers that need to know whether a session is
        // finished but have no path to the supervisor — the changeset
        // recompute, which will not offer an arc for joining while the session
        // that built it is still working.
        let _ = LEDGER_HANDLE.set(Arc::clone(&sup.ledger));
        (sup, merger_register_rx)
    }

    /// Snapshot every session that currently has a live tugcode child AND a
    /// turn in flight, with its captured `(pid, start_time)` — the input the
    /// activity sampler ([P10]) needs to root each session's subtree walk
    /// and apply the PID-reuse guard ([P20]). Sessions between spawns (no
    /// live child) and sessions idle between turns are omitted: Pulse
    /// attributes the session *working*, so an idle session's gauges decay
    /// to zero instead of reporting the claude process's idle heartbeat.
    pub async fn live_session_processes(&self) -> Vec<LiveSessionProcess> {
        let entries: Vec<Arc<Mutex<LedgerEntry>>> = {
            let ledger = self.ledger.lock().await;
            ledger.values().cloned().collect()
        };
        let mut out = Vec::new();
        for entry_arc in entries {
            let entry = entry_arc.lock().await;
            if !entry.turn_active {
                continue;
            }
            if let (Some(pid), Some(start_time)) = (entry.child_pid, entry.child_start_time) {
                out.push(LiveSessionProcess {
                    tug_session_id: entry.tug_session_id.clone(),
                    pid,
                    start_time,
                });
            }
        }
        out
    }

    /// Handle a CONTROL frame's action. `client_id` is the WebSocket
    /// connection id (see [D09]); it is distinct from `card_id` and is
    /// used only for the per-client session affinity map in [D14].
    ///
    /// Actions:
    /// * `spawn_session` — register intent + start the per-session
    ///   subprocess if Idle. Payload: `{card_id, tug_session_id,
    ///   project_dir, session_mode?}`.
    /// * `close_session` — stop the subprocess and drop the ledger
    ///   entry. Payload: `{card_id, tug_session_id}`.
    /// * `reset_session` — invalidate the persisted resume id and
    ///   re-arm the entry for a fresh spawn, preserving the workspace.
    ///   Payload: `{card_id, tug_session_id}`.
    /// * `list_sessions` — picker query. Payload: `{project_dir}`.
    /// * `trash_session` — drop a non-live persisted record.
    ///   Payload: `{session_id}`.
    /// * `trash_project_dir_sessions` — drop every non-live record
    ///   under a workspace. Payload: `{project_dir}`.
    /// * `request_replay` — recovery verb per [D12]. Forward
    ///   `{"type":"request_replay"}` to the live tugcode subprocess so
    ///   a freshly-mounted `CodeSessionStore` rehydrates from JSONL.
    ///   No-op if the entry is not Live. Payload: `{tug_session_id}`.
    ///
    /// Returns [`ControlOutcome::PassThrough`] for any action not
    /// matched above so the router can fall through to its legacy
    /// `dispatch_action` pipeline. The match arms here are the single
    /// source of truth for "which CONTROL actions the supervisor owns";
    /// the router does not maintain a separate allowlist.
    /// Compose the changeset aggregate fresh, on demand, over the current
    /// registry + ledger — the same call the `CHANGESET_ALL` feed makes on a
    /// bump. Read-only; used by the `/api/changesets` observability endpoint so
    /// a CLI can see exactly what compose produces right now (ground truth
    /// against the deck's "No changes"), independent of emission/diff-suppression.
    pub async fn compose_changeset_aggregate(
        &self,
    ) -> tugcast_core::types::WorkspacesChangesetSnapshot {
        super::changeset_all::compose_aggregate(&self.registry, self.session_ledger.as_deref())
            .await
    }

    pub async fn handle_control(
        &self,
        action: &str,
        payload: &[u8],
        client_id: ClientId,
    ) -> ControlOutcome {
        // Inner closure-style block returns a `Result<(), ControlError>`
        // for the supervisor-owned arms; the catch-all early-returns
        // `PassThrough` so unknown actions don't pay the wrap cost. The
        // outer match below maps Ok→Handled, Err→Error.
        let result: Result<(), ControlError> = match action {
            "spawn_session" => {
                let parsed = match parse_control_payload_owned(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected spawn_session");
                        return ControlOutcome::Error(e);
                    }
                };
                // project_dir is required on spawn per.
                let project_dir_str =
                    match parsed.project_dir.ok_or(ControlError::InvalidProjectDir {
                        reason: "missing_project_dir",
                    }) {
                        Ok(s) => s,
                        Err(e) => return ControlOutcome::Error(e),
                    };
                self.do_spawn_session(
                    &parsed.card_id,
                    parsed.tug_session_id,
                    project_dir_str,
                    parsed.session_mode,
                    parsed.permission_mode,
                    parsed.tag,
                    parsed.line_id,
                    client_id,
                )
                .await
            }
            "close_session" => {
                let parsed = match parse_control_payload_owned(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected close_session");
                        return ControlOutcome::Error(e);
                    }
                };
                self.do_close_session(&parsed.card_id, &parsed.tug_session_id)
                    .await;
                Ok(())
            }
            "reset_session" => {
                let parsed = match parse_control_payload_owned(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected reset_session");
                        return ControlOutcome::Error(e);
                    }
                };
                // W2 [D11]: reset preserves the workspace binding. We do NOT
                // close-then-spawn here because that would release the
                // workspace and (potentially) tear down its feeds.
                self.do_reset_session(&parsed.card_id, &parsed.tug_session_id, client_id)
                    .await;
                Ok(())
            }
            "list_sessions" => match parse_project_dir_payload(payload) {
                Ok(project_dir) => {
                    self.do_list_sessions(&project_dir).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "list_card_bindings" => {
                self.do_list_card_bindings().await;
                Ok(())
            }
            "bind_arc" => match parse_bind_arc_payload(payload) {
                Ok(parsed) => {
                    self.do_bind_arc(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            // Same payload as `bind_arc`, deliberately: a resume *is* a bind
            // with the stop cleared first, so a second shape would be a
            // second spelling of one fact.
            "arc_resume" => match parse_bind_arc_payload(payload) {
                Ok(parsed) => {
                    self.do_arc_resume(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "unbind_arc" => match parse_tug_session_id_payload(payload) {
                Ok(session_id) => {
                    self.do_unbind_arc(session_id.as_str()).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "resolve_sessions" => match parse_session_ids_payload(payload) {
                Ok(ids) => {
                    self.do_resolve_sessions(&ids).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_git_init" => match parse_project_dir_payload(payload) {
                Ok(project_dir) => {
                    self.do_changeset_git_init(&project_dir).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_commit" => match parse_changeset_commit_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_commit(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            // Claim and disclaim return their reply body: the WebSocket
            // ingress ignores it (the body was already broadcast on CONTROL),
            // and the `/api/tell` bridge hands it back over HTTP so the CLI
            // reports the actual outcome rather than inferring one from 200.
            "changeset_claim" => match parse_changeset_claim_payload(payload) {
                Ok(parsed) => {
                    let reply = self.do_changeset_claim(&parsed).await;
                    return ControlOutcome::HandledWith(reply);
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_disclaim" => match parse_changeset_disclaim_payload(payload) {
                Ok(parsed) => {
                    let reply = self.do_changeset_disclaim(&parsed).await;
                    return ControlOutcome::HandledWith(reply);
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            // Side-effect-free recompute nudge: fire the aggregate bump so an
            // open project re-scans its working tree. Emission is diff-
            // suppressed, so this is observable only when the tree actually
            // drifted from the cached snapshot (an orphan created while no FS
            // event landed) — the Changes shade fires it on open so looking is
            // always fresh. No payload, no reply.
            "changeset_refresh" => {
                self.registry.changeset_all_bump().notify_one();
                Ok(())
            }
            "deck_seatings" => {
                // Full-replacement report of which sessions this deck client
                // has seated on open Session cards. Keyed by the WebSocket
                // client id, so the state can never outlive the deck that
                // reported it (`on_client_disconnect` drops it; a reconnect
                // is a fresh id that starts empty).
                match parse_deck_seatings_payload(payload) {
                    Ok(session_ids) => {
                        if super::deck_seatings::set_deck_seatings(client_id, session_ids) {
                            self.registry.changeset_all_bump().notify_one();
                        }
                        Ok(())
                    }
                    Err(e) => return ControlOutcome::Error(e),
                }
            }
            "changeset_draft_request" => match parse_changeset_draft_request_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_draft_request(&parsed);
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_draft_cancel" => match parse_changeset_draft_cancel_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_draft_cancel(&parsed);
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_draft_set" => match parse_changeset_draft_set_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_draft_set(&parsed);
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "landing_receipt" => {
                let receipt = parse_landing_receipt_payload(payload);
                tracing::info!(
                    kind = %receipt.kind,
                    verdict = %receipt.verdict,
                    reason = %receipt.reason,
                    gate = %receipt.gate,
                    "landing-receipt"
                );
                Ok(())
            }
            "changeset_join" => match parse_changeset_join_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_join(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_join_resolve" => match parse_changeset_join_resolve_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_join_resolve(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            // The base-side resolve, which is a different act from the one
            // above: that reconciles a conflicted merge, this clears the
            // uncommitted base work refusing the merge in the first place.
            // They share a payload shape and nothing else.
            "changeset_join_resolve_base" => match parse_changeset_join_resolve_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_join_resolve_base(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            // And its reversal, offered beside the fold's own receipt. It
            // shares the payload shape for the same reason: one act, one arc,
            // named the same way.
            "changeset_join_resolve_base_undo" => {
                match parse_changeset_join_resolve_payload(payload) {
                    Ok(parsed) => {
                        self.do_changeset_join_resolve_base_undo(&parsed).await;
                        Ok(())
                    }
                    Err(e) => return ControlOutcome::Error(e),
                }
            }
            "changeset_join_question_answer" => {
                match parse_changeset_join_question_answer_payload(payload) {
                    Ok(parsed) => {
                        self.do_changeset_join_question_answer(&parsed);
                        Ok(())
                    }
                    Err(e) => return ControlOutcome::Error(e),
                }
            }
            "changeset_discard" => match parse_changeset_discard_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_discard(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "changeset_replay" => match parse_changeset_replay_payload(payload) {
                Ok(parsed) => {
                    self.do_changeset_replay(&parsed).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "trash_session" => match parse_trash_session_payload(payload) {
                Ok((session_id, project_dir)) => {
                    self.do_trash_session(&session_id, project_dir.as_deref())
                        .await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "rename_session" => match parse_rename_session_payload(payload) {
                Ok((line_id, name)) => {
                    self.do_rename_session(&line_id, name.as_deref()).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "set_session_private" => match parse_set_session_private_payload(payload) {
                Ok((session_id, private)) => {
                    self.do_set_session_private(&session_id, private).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "trash_project_dir_sessions" => match parse_project_dir_payload(payload) {
                Ok(project_dir) => {
                    self.do_trash_project_dir_sessions(&project_dir).await;
                    Ok(())
                }
                Err(e) => return ControlOutcome::Error(e),
            },
            "request_replay" => {
                let tug_session_id = match parse_tug_session_id_payload(payload) {
                    Ok(id) => id,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected request_replay");
                        return ControlOutcome::Error(e);
                    }
                };
                let window = parse_request_replay_window(payload);
                self.do_request_replay(&tug_session_id, window).await;
                Ok(())
            }
            "record_turn_telemetry" => {
                let parsed = match parse_record_turn_telemetry_payload(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected record_turn_telemetry");
                        return ControlOutcome::Error(e);
                    }
                };
                self.do_record_turn_telemetry(parsed).await;
                Ok(())
            }
            "record_context_breakdown" => {
                let parsed = match parse_record_context_breakdown_payload(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected record_context_breakdown");
                        return ControlOutcome::Error(e);
                    }
                };
                self.do_record_context_breakdown(parsed).await;
                Ok(())
            }
            "record_session_state_change" => {
                let parsed = match parse_record_session_state_change_payload(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected record_session_state_change");
                        return ControlOutcome::Error(e);
                    }
                };
                self.do_record_session_state_change(parsed).await;
                Ok(())
            }
            "list_session_state_changes" => {
                let parsed = match parse_list_session_state_changes_payload(payload) {
                    Ok(p) => p,
                    Err(e) => {
                        warn!(action, error = %e, "handle_control: rejected list_session_state_changes");
                        return ControlOutcome::Error(e);
                    }
                };
                self.do_list_session_state_changes(parsed).await;
                Ok(())
            }
            "list_pulse_lines" => {
                // App-scoped read — no session id, no payload fields.
                self.do_list_pulse_lines().await;
                Ok(())
            }
            "list_overview_posts" => {
                // App-scoped read — the Overview card's tail on mount, and
                // each older page as the reader scrolls back. Both arguments
                // are optional, and absent means "the tail", so a client that
                // sends neither is the pre-paging client and is served
                // identically.
                let args = serde_json::from_slice::<serde_json::Value>(payload).ok();
                let before_id = args
                    .as_ref()
                    .and_then(|v| v.get("before_id"))
                    .and_then(serde_json::Value::as_i64);
                let limit = args
                    .as_ref()
                    .and_then(|v| v.get("limit"))
                    .and_then(serde_json::Value::as_u64)
                    .map(|n| n as usize);
                self.do_list_overview_posts(before_id, limit).await;
                Ok(())
            }
            "deck_log" => {
                // The deck's `warn`/`error` dev-log entries, mirrored here so
                // they survive into `tugcast.log`. The DevTools Log tab is only
                // readable live, and a release build exposes no handle onto
                // that store — so without this a warning about, say, a restore
                // that came back short is written nowhere anyone can read
                // afterwards. Diagnostic echo only: never trusted, never acted
                // on, and bounded by the client's own 2000-char detail cap.
                let v = serde_json::from_slice::<serde_json::Value>(payload)
                    .unwrap_or(serde_json::Value::Null);
                let str_at = |k: &str| {
                    v.get(k)
                        .and_then(|s| s.as_str())
                        .unwrap_or_default()
                        .to_owned()
                };
                let (level, source, message, detail) = (
                    str_at("level"),
                    str_at("source"),
                    str_at("message"),
                    v.get("data")
                        .and_then(|s| s.as_str())
                        .unwrap_or_default()
                        .to_owned(),
                );
                if level == "error" {
                    tracing::error!(source, detail, "deck: {message}");
                } else {
                    warn!(source, detail, "deck: {message}");
                }
                Ok(())
            }
            "list_shell_exchanges" => {
                // Session-scoped read — the deck's shell-restore tail fetch.
                // `since_ms` is the replay window's oldest-turn timestamp when
                // the deck knows it, so ink rows span what the turns span.
                let parsed = serde_json::from_slice::<serde_json::Value>(payload).ok();
                let tug_session_id = parsed
                    .as_ref()
                    .and_then(|v| {
                        v.get("tug_session_id")
                            .and_then(|s| s.as_str())
                            .map(String::from)
                    })
                    .unwrap_or_default();
                let since_ms = parsed
                    .as_ref()
                    .and_then(|v| v.get("since_ms"))
                    .and_then(|s| s.as_i64());
                self.do_list_shell_exchanges(&tug_session_id, since_ms)
                    .await;
                Ok(())
            }
            "list_refs" => {
                // Session-scoped read — the deck's refs-restore fetch.
                let tug_session_id = serde_json::from_slice::<serde_json::Value>(payload)
                    .ok()
                    .and_then(|v| {
                        v.get("tug_session_id")
                            .and_then(|s| s.as_str())
                            .map(String::from)
                    })
                    .unwrap_or_default();
                self.do_list_refs(&tug_session_id).await;
                Ok(())
            }
            // Any action not above is not owned by the supervisor.
            // Caller falls through to `dispatch_action`.
            _ => return ControlOutcome::PassThrough,
        };

        match result {
            Ok(()) => ControlOutcome::Handled,
            Err(e) => ControlOutcome::Error(e),
        }
    }

    /// Build a `SESSION_SIDEBAND` replay frame from the persisted ledger
    /// row, for a bind whose in-memory `latest_metadata` slot is empty.
    ///
    /// claude is silent in stream-json mode until the first user message,
    /// so a resumed / known session would otherwise show no live model /
    /// version / mode until the user types. The sqlite `session_metadata`
    /// table holds the last-known merged payload (keyed by claude's
    /// session id), so we surface it the moment the card binds; the next
    /// live `system/init` replaces it wholesale on the first turn.
    ///
    /// Tries `claude_session_id` first (the metadata PK), then the tug
    /// session id (equal for un-forked sessions, where the binding's
    /// claude id may not yet be populated in memory). Returns `None` when
    /// there is no sqlite ledger handle or no persisted row (a genuinely
    /// brand-new session), so a fresh flow fires no replay — matching the
    /// `latest_metadata: None` behavior it falls back from. Payload is
    /// rewrapped as `FeedId::SESSION_SIDEBAND` (the wire byte the client's
    /// `register_stream(FeedId::SESSION_SIDEBAND, …)` subscription keys on,
    /// same as the live merger publish).
    ///
    /// The persisted payload carries no `tug_session_id`: the bridge merges
    /// and persists the RAW stdout line, splicing the id only onto the
    /// emitted wire copy (`agent_bridge.rs` — merge precedes the splice at
    /// the emit site). Clients filter SESSION_SIDEBAND by `tug_session_id`
    /// per [D06]/[D11], so an unstamped replay would be silently dropped
    /// and a resumed card would show no model / version / mode until its
    /// first turn. Stamp the BOUND session's id here ([`stamp_tug_session_id`]);
    /// stamping at replay time also keeps the frame correct when a claude
    /// session is re-bound under a different tug id.
    fn persisted_metadata_replay_frame(
        &self,
        claude_session_id: Option<&str>,
        tug_session_id: &str,
    ) -> Option<Frame> {
        let ledger = self.session_ledger.as_ref()?;
        // Try claude id first (the metadata PK), then the tug id — but only
        // the tug id when it differs (un-forked sessions share one id).
        let mut candidates: Vec<&str> = Vec::with_capacity(2);
        if let Some(id) = claude_session_id {
            candidates.push(id);
        }
        if !candidates.contains(&tug_session_id) {
            candidates.push(tug_session_id);
        }
        for candidate in candidates {
            match ledger.get_session_metadata(candidate) {
                Ok(Some(row)) => {
                    return Some(Frame::new(
                        FeedId::SESSION_SIDEBAND,
                        stamp_tug_session_id(row.payload, tug_session_id),
                    ));
                }
                Ok(None) => {}
                Err(e) => {
                    warn!(
                        error = %e,
                        session_id = candidate,
                        "get_session_metadata failed during bind replay (ignored)"
                    );
                }
            }
        }
        None
    }

    /// Build a `SESSION_SIDEBAND` replay frame from the persisted
    /// `session_capabilities` row, for a bind whose in-memory
    /// `latest_capabilities` slot is empty — the app-restart case: the
    /// slot died with the old process, and a resumed session's next
    /// handshake is health-gated (it answers seconds after spawn at the
    /// earliest). Without this fallback the card has no `/` command
    /// catalog and no version in that window; with it, the last-known
    /// catalog is on screen from the drop and the live handshake
    /// replaces it wholesale when it lands.
    ///
    /// Keyed by the tug session id only — capabilities are spawn-scoped
    /// (unlike `session_metadata`, which is keyed by claude's JSONL id).
    /// The persisted payload is the tagged wire copy, but the tag is the
    /// id of the ORIGINAL spawn; stamp the BOUND session's id so a
    /// claude session re-bound under a different tug id still passes the
    /// client-side [D06]/[D11] session filter
    /// ([`stamp_tug_session_id`] overwrites a stale tag).
    fn persisted_capabilities_replay_frame(&self, tug_session_id: &str) -> Option<Frame> {
        let ledger = self.session_ledger.as_ref()?;
        match ledger.get_session_capabilities(tug_session_id) {
            Ok(Some(row)) => Some(Frame::new(
                FeedId::SESSION_SIDEBAND,
                stamp_tug_session_id(row.payload, tug_session_id),
            )),
            Ok(None) => None,
            Err(e) => {
                warn!(
                    error = %e,
                    session_id = tug_session_id,
                    "get_session_capabilities failed during bind replay (ignored)"
                );
                None
            }
        }
    }

    /// Does this session hold nothing at all — nothing in the ledger
    /// ([`is_empty_session`]) AND no transcript on disk?
    ///
    /// Both signals must agree before a spawn is routed away from `resume`.
    /// The ledger side is the same emptiness the picker filters on; the disk
    /// side is the exact file a `--resume` would open. Requiring both means a
    /// path-encoding miss can never route a session that really has a
    /// transcript into a `--session-id` collision, and a ledger row that
    /// under-reports its content (turn counts that never flowed through a live
    /// `turn_complete`) is still protected by the file being there.
    ///
    /// `false` when there is no ledger to consult — with no way to tell empty
    /// from populated, the request's own mode stands.
    fn session_is_content_empty(&self, tug_session_id: &TugSessionId, project_dir: &str) -> bool {
        let Some(ledger) = self.session_ledger.as_ref() else {
            return false;
        };
        let Ok(Some(row)) = ledger.get(&tug_session_id.0) else {
            return false;
        };
        if !is_empty_session(&row) {
            return false;
        }
        let (dir, _canonical) =
            crate::session_ledger::claude_project_dir(ledger.claude_projects_root(), project_dir);
        let jsonl = dir.join(format!("{}.jsonl", tug_session_id.0));
        crate::external_sessions::stat_size_mtime(&jsonl).is_none()
    }

    #[allow(clippy::too_many_arguments)]
    async fn do_spawn_session(
        &self,
        card_id: &str,
        tug_session_id: TugSessionId,
        project_dir_str: String,
        session_mode: SessionMode,
        permission_mode: Option<String>,
        tag: Option<String>,
        line_id: Option<String>,
        client_id: ClientId,
    ) -> Result<(), ControlError> {
        let project_dir = PathBuf::from(&project_dir_str);
        // A fresh spawn births a line, and the deck mints its id from the drop
        // ([P03]). Refused here, before the workspace refcount is acquired, so
        // the refusal costs nothing and releases nothing.
        if session_mode == SessionMode::New && line_id.as_deref().unwrap_or_default().is_empty() {
            warn!(
                card_id,
                session = %tug_session_id,
                "spawn_session: a mode=new spawn carried no line_id"
            );
            return Err(ControlError::MissingLineId);
        }
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "spawn.supervisor_recv",
            card_id = card_id,
            tug_session_id = %tug_session_id,
            project_dir = %project_dir_str,
            session_mode = session_mode.as_wire_str(),
        );

        // Phase 0: validate + canonicalize + acquire workspace.
        // This must happen before we touch the ledger so validation errors
        // short-circuit with no ledger or client_sessions mutation. On
        // success the workspace refcount is bumped by 1; every error path
        // below that returns after this point must release the extra
        // refcount before returning ([D05]).
        let workspace_entry = self
            .registry
            .get_or_create(&project_dir, self.cancel.clone())
            .map_err(|e| match e {
                WorkspaceError::InvalidProjectDir { reason, .. } => {
                    warn!(
                        card_id,
                        session = %tug_session_id,
                        path = ?project_dir,
                        reason,
                        "spawn_session: invalid project_dir"
                    );
                    ControlError::InvalidProjectDir { reason }
                }
                WorkspaceError::UnknownKey(_) => {
                    unreachable!("get_or_create never returns UnknownKey")
                }
            })?;
        let workspace_key = workspace_entry.workspace_key.clone();
        drop(workspace_entry);

        // An empty session has nothing to resume. Claude writes a session's
        // JSONL only once a turn lands, so a session abandoned before its
        // first prompt leaves no transcript at all and `--resume` on its id
        // exits with "No conversation found" — surfacing a "couldn't resume"
        // alert for a session that never held a conversation. Those rows are
        // the same ones `build_listed_union` drops as empty, so spawn them
        // fresh instead, under the SAME id: the card opens on its project and
        // the id keeps keying the session's durable non-JSONL content — the
        // shell ledger's receipts and the refs ledger's last run — exactly as
        // the client's own zero-turn restore path does.
        //
        // That invariant needs no enforcing now: durable ink is keyed by
        // **line** ([P09]), so an id change moves nothing out from under it
        // and there is nothing to repair afterwards.
        //
        // `spawn_mode` is what the entry gets stamped with; `session_mode`
        // stays the mode the client asked for, so the ownership gates below
        // still read a resume request as a resume request.
        let content_empty = self.session_is_content_empty(&tug_session_id, &project_dir_str);
        let spawn_mode = if content_empty && session_mode == SessionMode::Resume {
            tracing::info!(
                target: "dev::session-lifecycle",
                event = "spawn.empty_session_spawned_fresh",
                card_id = card_id,
                tug_session_id = %tug_session_id,
            );
            SessionMode::New
        } else {
            session_mode
        };

        // Phase 1: ledger get-or-insert + per-client affinity insert, atomic
        // under the outer ledger lock AND the client_sessions lock. Holding
        // both together closes the TOCTOU window per [R06] — a concurrent
        // close cannot interleave between the ledger insert and the
        // client_sessions insert. Lock order invariant: ledger first, then
        // client_sessions; applied everywhere in this module.
        //
        // If the ledger already has an entry for this tug_session_id (a
        // reconnect), the or_insert_with closure does not run and we
        // reuse the existing entry. In that case the workspace refcount
        // bumped in Phase 0 is excess and must be released (the existing
        // ledger entry already holds its own refcount).
        //
        // P13: for fresh inserts only, enforce `max_concurrent_sessions`
        // (counting Spawning+Live entries via try_lock) and the
        // `max_spawns_per_minute` leaky bucket. Both checks run inside
        // the ledger critical section so the decision is atomic with the
        // insert. Reconnects bypass — the existing entry is already
        // counted and re-inserting it would not produce a new subprocess.
        let phase1 = {
            let mut ledger = self.ledger.lock().await;
            let was_inserted = !ledger.contains_key(&tug_session_id);
            if was_inserted {
                if let Some(reason) = cap_check_reason(
                    &ledger,
                    self.config.max_concurrent_sessions,
                    &self.spawn_timestamps,
                    self.config.max_spawns_per_minute,
                ) {
                    drop(ledger);
                    // Release the workspace refcount acquired in Phase 0;
                    // the ledger never saw this entry so no later Phase
                    // will release it for us.
                    if let Err(e) = self.registry.release(&workspace_key) {
                        warn!(
                            card_id,
                            session = %tug_session_id,
                            error = %e,
                            "spawn_session: cap-reject workspace release failed (ignored)"
                        );
                    }
                    // Broadcast SESSION_STATE errored so any observer of
                    // this session sees the failure, not just the client
                    // whose CONTROL frame we're about to reject.
                    self.session_state.publish_tagged(build_session_state_frame(
                        &tug_session_id,
                        "errored",
                        Some(reason),
                    ));
                    warn!(
                        card_id,
                        session = %tug_session_id,
                        reason,
                        "spawn_session: rejected by spawn budget"
                    );
                    return Err(ControlError::CapExceeded { reason });
                }
            }
            let arc = ledger
                .entry(tug_session_id.clone())
                .or_insert_with(|| {
                    Arc::new(Mutex::new(LedgerEntry::new(
                        tug_session_id.clone(),
                        workspace_key.clone(),
                        project_dir.clone(),
                        spawn_mode,
                        CrashBudget::new(3, Duration::from_secs(60)),
                    )))
                })
                .clone();
            let mut cs = self.client_sessions.lock().await;
            // Capture whether *any* live client connection already held
            // this session BEFORE this call's affinity insert. This is
            // the genuine "session_live_elsewhere" signal: a session
            // re-materialized by `rebind_from_ledger` is in no client's
            // set, while one another connected client is using is. Read
            // it here, pre-insert, so the resume check below isn't
            // fooled by the row this very call is about to add.
            let held_by_live_client_before = cs.values().any(|set| set.contains(&tug_session_id));
            cs.entry(client_id)
                .or_default()
                .insert(tug_session_id.clone());
            (arc, was_inserted, held_by_live_client_before)
        };
        let (entry_arc, inserted, held_by_live_client_before) = phase1;

        // Compute the *effective* session mode — the mode the bridge
        // will actually use when it spawns tugcode. For a fresh insert
        // (Phase 1's `or_insert_with` fired) the effective mode is the
        // request's mode. For an existing entry that's still `Idle`
        // (rebound from the ledger but not yet spawned), we propagate
        // the request's mode into the entry. The defense-in-depth is
        // gated on `Idle` so we never silently switch the mode of a
        // running subprocess: the running tugcode subprocess was
        // spawned with the original mode and silently switching it
        // client-side would misrepresent live state.
        let effective_session_mode = {
            let mut entry = entry_arc.lock().await;
            // Retry-clears-error: a spawn request for an `Errored` entry IS the
            // user asking to (re)spawn it — the picker's Retry. Clear the error
            // back to `Idle` so the eager-spawn + replay below fire, instead of
            // the dispatcher dropping every frame and `request_replay` skipping
            // in a terminal state (the 2026-07-22 commit-xp regression: Retry
            // re-spawned but the entry stayed `Errored`, so the card came back
            // empty even though the JSONL was intact). Crucially this preserves
            // `claude_session_id` + `session_mode` — unlike `reset_session`,
            // which wipes them to start fresh — so the respawn resumes the
            // intact transcript. `Closed` is genuinely terminal and left alone.
            if !inserted && entry.spawn_state == SpawnState::Errored {
                tracing::info!(
                    target: "dev::session-lifecycle",
                    event = "spawn.clear_errored_for_retry",
                    card_id = card_id,
                    tug_session_id = %tug_session_id,
                    had_claude_id = entry.claude_session_id.is_some(),
                );
                entry.spawn_state = SpawnState::Idle;
                // The retry is a spawn about to happen, and the `Idle` it
                // parks in is a step on the way to `Spawning` — not a death.
                // Cleared so a sweep landing in that window reads the wait it
                // is rather than stopping the arc; the promote below sets it
                // again, and a retry that fails lands back in `Errored`, which
                // already reads gone.
                entry.ever_live_here = false;
            }
            if !inserted
                && entry.spawn_state == SpawnState::Idle
                && entry.session_mode != spawn_mode
            {
                entry.session_mode = reconcile_idle_session_mode(
                    entry.session_mode,
                    spawn_mode,
                    entry.claude_session_id.is_some() && !content_empty,
                );
            }
            // Stamp the resolved permission mode onto the entry the same way:
            // on the fresh insert, or while still `Idle` (rebound but not yet
            // spawned). Never while running — the live tugcode was spawned with
            // the original `--permission-mode` and a post-spawn `permission_mode`
            // frame is the path for live changes. The bridge reads this field at
            // spawn time so the mode is correct from claude's first instant.
            if inserted || entry.spawn_state == SpawnState::Idle {
                entry.permission_mode = permission_mode;
                // The provisional tag is stamped on the same fresh/Idle path and
                // preserved across reconnects; `record_spawn` claims it
                // authoritatively when the bridge promotes the session.
                entry.tag = tag;
            }
            // The line the entry is on ([P03]/[P04]). The payload's is the
            // authority — the deck mints it from the drop on a fresh spawn and
            // sends the binding's on a resume. A resume that carries none
            // (every client before this model) reads it off the row it is
            // resuming, so a card restored by an older deck still lands on its
            // own line rather than starting a second one.
            if let Some(line_id) = line_id.filter(|id| !id.is_empty()) {
                entry.line_id = Some(line_id);
            } else if entry.line_id.is_none() {
                entry.line_id = entry
                    .claude_session_id
                    .as_deref()
                    .or(Some(tug_session_id.as_str()))
                    .and_then(|id| self.session_ledger.as_ref()?.line_of(id));
            }
            entry.session_mode
        };
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "spawn.effective_mode",
            card_id = card_id,
            tug_session_id = %tug_session_id,
            requested_mode = session_mode.as_wire_str(),
            effective_mode = effective_session_mode.as_wire_str(),
            inserted,
            mode_mismatch =
                session_mode != effective_session_mode && !inserted,
        );

        // Workspace refcount ownership. Phase 0's `get_or_create` bumped the
        // workspace refcount; exactly one refcount belongs to this ledger entry
        // for its lifetime (`do_close_session` releases it). Decide who owns the
        // one we just acquired — keyed on the entry's OWN record of ownership,
        // never on `inserted`:
        //   - the entry already owns one (a genuine reconnect of a live entry)
        //     → the Phase-0 refcount is excess, release it;
        //   - the entry owns none (a fresh insert, OR an entry rebound from the
        //     ledger making its first real spawn) → the entry adopts it.
        // A rebind entry is present in the ledger (`inserted == false`) yet holds
        // no refcount, so `!inserted` must NOT drive the release — reading it as
        // "a refcount is held" tore down a resumed project's workspace on restore.
        let phase0_refcount_is_excess = {
            let mut entry = entry_arc.lock().await;
            if entry.holds_workspace_refcount {
                true
            } else {
                entry.holds_workspace_refcount = true;
                false
            }
        };
        if phase0_refcount_is_excess {
            if let Err(e) = self.registry.release(&workspace_key) {
                warn!(
                    card_id,
                    session = %tug_session_id,
                    error = %e,
                    "spawn_session: reconnect release returned error (ignored)"
                );
            }
        }

        if !inserted {
            // Reject a `resume` only when a live client connection is
            // genuinely holding this session on a *different* card.
            //
            // The `card_id` field is the persistent "last bound"
            // record, preserved across close/errored — but the ledger
            // remembering a different card is NOT by itself a
            // conflict. After a tugcast restart, `rebind_from_ledger`
            // re-materializes every prior session as `Idle` carrying
            // its recorded `card_id`, and deliberately does NOT
            // populate `client_sessions` (there is no WebSocket client
            // behind a rebind). Likewise a page reload drops the old
            // WebSocket, and `on_client_disconnect` removes that
            // client's `client_sessions` row. In both cases the
            // recorded card is gone; a new card must be free to adopt
            // the session via `mode=resume`.
            //
            // The genuine conflict is "a connected client is holding
            // this session right now" — captured in
            // `held_by_live_client_before` (read in Phase 1 *before*
            // this call's own affinity insert, so it is not fooled by
            // the row we just added). A resume is rejected only when
            // all of:
            //   (a) the entry is in a not-closed `spawn_state`
            //       (Idle/Spawning/Live),
            //   (b) the ledger's `card_id` differs from the resuming
            //       card, AND
            //   (c) a live client connection already held this session
            //       before this call.
            // Same-card reconnects (WS drop + reconnect) clear (b);
            // rebind-from-ledger / post-reload adoptions clear (c);
            // `new` payloads never enter this block.
            if session_mode == SessionMode::Resume {
                let entry = entry_arc.lock().await;
                let still_held = matches!(
                    entry.spawn_state,
                    SpawnState::Idle | SpawnState::Spawning | SpawnState::Live
                );
                let holder_opt = if still_held {
                    entry.card_id.as_deref()
                } else {
                    None
                };
                if let Some(holder) = holder_opt {
                    if holder != card_id && held_by_live_client_before {
                        let holder_owned = holder.to_owned();
                        drop(entry);
                        // Drop the per-client affinity row we just
                        // inserted above so the rejected card doesn't
                        // appear bound.
                        let mut cs = self.client_sessions.lock().await;
                        if let Some(set) = cs.get_mut(&client_id) {
                            set.remove(&tug_session_id);
                        }
                        drop(cs);
                        warn!(
                            card_id,
                            session = %tug_session_id,
                            holder = %holder_owned,
                            "spawn_session: resume rejected — session live on another card"
                        );
                        self.session_state.publish_tagged(build_session_state_frame(
                            &tug_session_id,
                            "errored",
                            Some("session_live_elsewhere"),
                        ));
                        return Err(ControlError::CapExceeded {
                            reason: "session_live_elsewhere",
                        });
                    }
                }
            }
        }

        // Terminal-liveness gate: a resume whose target session is
        // currently held by a live process outside this supervisor —
        // the Claude Code terminal app, or another Tug instance — is
        // refused outright. Double-holding makes both processes append
        // divergent parentUuid branches into one JSONL; closing the
        // terminal frees the session immediately (its registry entry
        // is removed on exit).
        //
        // This check runs for BOTH Phase-1 outcomes. The fresh-insert
        // path is the primary case: the first-ever resume of an
        // external (terminal-created) session mints a new entry, so a
        // gate placed inside the `!inserted` reconnect branch above
        // would miss it entirely. Only resume mode is gated — a `new`
        // session has a fresh id no other process can hold. The
        // registry read shells out to `ps` and walks a directory, so
        // it runs on a blocking thread.
        if effective_session_mode == SessionMode::Resume {
            let registry_root = self.terminal_registry_root();
            let sid = tug_session_id.as_str().to_owned();
            let held = tokio::task::spawn_blocking(move || {
                Self::read_terminal_live_sessions(registry_root.as_deref()).contains_key(&sid)
            })
            .await
            .unwrap_or(false);
            if held {
                // Undo this call's bookkeeping. A fresh insert takes
                // its just-minted Idle entry and the Phase-0 workspace
                // refcount with it; a reconnect already released the
                // extra refcount above and keeps its pre-existing
                // entry. The affinity row this call added goes either
                // way. Lock order: ledger, then client_sessions.
                {
                    let mut ledger = self.ledger.lock().await;
                    if inserted {
                        ledger.remove(&tug_session_id);
                    }
                    let mut cs = self.client_sessions.lock().await;
                    if let Some(set) = cs.get_mut(&client_id) {
                        set.remove(&tug_session_id);
                    }
                }
                if inserted {
                    if let Err(e) = self.registry.release(&workspace_key) {
                        warn!(
                            card_id,
                            session = %tug_session_id,
                            error = %e,
                            "spawn_session: terminal-gate workspace release failed (ignored)"
                        );
                    }
                }
                warn!(
                    card_id,
                    session = %tug_session_id,
                    "spawn_session: resume rejected — session live in terminal"
                );
                self.session_state.publish_tagged(build_session_state_frame(
                    &tug_session_id,
                    "errored",
                    Some("session_live_in_terminal"),
                ));
                return Err(ControlError::CapExceeded {
                    reason: "session_live_in_terminal",
                });
            }
        }

        // Persistence of the (card_id → session) binding happens
        // through the sqlite-backed `SessionLedger` row that the bridge
        // writes on `session_init` (in `relay_session_io`). The
        // supervisor's in-memory `LedgerEntry` carries `card_id` and
        // `session_mode` for the lifetime of the entry; the bridge's
        // atomic-promote block calls `sessions_recorder.record(...)`
        // under a single lock, and the `LedgerSessionsRecorder`
        // translates that into a `record_spawn` ledger write keyed by
        // claude's session id. The client-side restore consults that
        // ledger via the `list_card_bindings` CONTROL verb.
        //
        // Phase 3: per-session mutation + publish + replay, under the
        // per-session lock. Reconnect flows observe the existing entry and
        // its `latest_metadata`; fresh flows observe a just-minted Idle
        // entry with `latest_metadata: None`.
        let (replay_frame, capabilities_frame, rate_limit_frame) = {
            let mut entry = entry_arc.lock().await;
            // Record the binding card. `card_id` is preserved across
            // lifecycle transitions (close/errored/crash-exhausted),
            // so this assignment is durable. The live-elsewhere check
            // gates on `spawn_state` instead of nullity. Same-card
            // reconnects overwrite with the same value (no-op).
            entry.card_id = Some(card_id.to_owned());
            // Prefer the in-memory slot (freshest — captured this process);
            // fall back to the persisted ledger row so a resumed/known
            // session surfaces its last-known model / version / mode the
            // moment the card binds, before any turn. claude is silent in
            // stream-json mode until the first user message, so without this
            // a fresh-process resume shows nothing live until the user types.
            // Keyed by claude's session id (the metadata PK); falls back to
            // the tug id for un-forked sessions where the two are equal.
            let metadata = match entry.latest_metadata.clone() {
                Some(frame) => Some(frame),
                None => self.persisted_metadata_replay_frame(
                    entry.claude_session_id.as_deref(),
                    tug_session_id.as_str(),
                ),
            };
            // Capabilities (the turn-free `initialize` model list +
            // command catalog) prefer the in-memory slot (freshest —
            // captured this process); fall back to the persisted
            // `session_capabilities` row so a resumed session's `/`
            // catalog and version survive an app restart — the slot dies
            // with the process, and the health-gated resume handshake
            // answers seconds after spawn at the earliest. The next live
            // capabilities frame replaces both wholesale.
            let capabilities = match entry.latest_capabilities.clone() {
                Some(frame) => Some(frame),
                None => self.persisted_capabilities_replay_frame(tug_session_id.as_str()),
            };
            // Rate-limit (the per-turn quota broadcast) is in-memory
            // only — replayed on reconnect / HMR remount so the Z4B
            // rate-limit chip keeps its state even though the last
            // per-turn broadcast already flew. Absent until the first turn
            // emits one.
            (metadata, capabilities, entry.latest_rate_limit.clone())
        };
        // Live-elsewhere visibility for cross-card pickers is driven by
        // the ledger row the bridge writes on `session_init` (with
        // `state="live"` and `card_id`). Pre-handshake spawns don't
        // appear in any picker — by then the user has already chosen.

        self.session_state.publish_tagged(build_session_state_frame(
            &tug_session_id,
            "pending",
            None,
        ));

        if let Some(frame) = replay_frame {
            self.session_sideband.publish_tagged(frame);
        }
        if let Some(frame) = capabilities_frame {
            self.session_sideband.publish_tagged(frame);
        }
        if let Some(frame) = rate_limit_frame {
            self.session_sideband.publish_tagged(frame);
        }

        // Eager spawn: transition Idle→Spawning and launch the tugcode
        // subprocess now, before the ack goes out. Resume failures
        // surface within ~1s of card open (claude exits fast on a
        // stale id), not 8+s after the user types and submits.
        //
        // The dispatcher's lazy Idle→Spawn branch stays in place as a
        // defense-in-depth path for ledger entries rebound from
        // tugbank at startup; in normal client flow it is unreachable
        // because do_spawn_session promotes Idle→Spawning before any
        // CODE_INPUT frame can arrive.
        let should_spawn = {
            let mut entry = entry_arc.lock().await;
            if entry.spawn_state == SpawnState::Idle {
                entry.spawn_state.try_transition(SpawnState::Spawning).ok();
                true
            } else {
                false
            }
        };
        if should_spawn {
            tracing::info!(
                target: "dev::session-lifecycle",
                event = "supervisor.eager_spawn",
                tug_session_id = %tug_session_id,
                card_id = card_id,
            );

            // (Migration bootstrap and supervisor-side spawn-time
            // reconciliation both removed by mid-turn-replay
            // [Step 5.2](#step-5-2) / [Step 5.6](#step-5-6).
            // Tug has no production users, so historical JSONL
            // → ledger migration is unneeded; the journal only ever
            // holds *currently pending* submissions, never historical
            // ones. Per-session pending rows are surfaced directly
            // by tugcode's `runReplay` via `injectPendingRowSynthetics`,
            // which reads the journal through the cross-process
            // bun:sqlite handle and emits a synthetic
            // `user_message_replay` for each pending row whose
            // `user_text` doesn't appear in JSONL — no supervisor
            // sweep step needed.)
            self.spawn_session_worker(&tug_session_id).await;
        }

        //
        // `workspace_key` so tugdeck can stamp it into the per-card binding
        // store without attempting client-side canonicalization (which
        // would miss macOS firmlinks). W1 had no explicit ack frame on this
        // code path — a successful `spawn_session` simply returned Ok(())
        // and the wire observation was the subsequent `pending`/`spawning`
        // SESSION_STATE transitions. Emitting the ack as an explicit CONTROL
        // frame here lets tugdeck's spawn-session handler populate the
        // binding store in the same round-trip.
        // The ack also echoes `session_mode` so tugdeck's
        // `cardSessionBindingStore` stamps the user's new-vs-resume choice
        // into the binding. Pre-4.5 clients ignore the extra field.
        //
        // For reconnects (entry already existed), echo the mode the ledger
        // *already* holds — not the one the incoming payload carried —
        // because the running tugcode subprocess was spawned with the
        // original mode and silently switching it client-side would
        // misrepresent live state.
        let effective_mode = if inserted {
            session_mode
        } else {
            entry_arc.lock().await.session_mode
        };
        // Carry the ledger's name/tag on the ack so tugdeck seeds the Z4B
        // chip's caches at bind time. A resume (row already exists) binds via
        // this ack alone: `session_updated` only pushes at turn boundaries, so
        // without this a mid-turn resume shows the id-hash for the whole
        // in-flight turn even though the ledger holds a good name/tag. A fresh
        // spawn's row doesn't exist yet (the bridge writes it on
        // `session_init`) — `None`/`false` here, which the client seeds
        // non-clobberingly so it can't wipe the optimistic tag.
        let row = self
            .session_ledger
            .as_ref()
            .and_then(|ledger| ledger.get(tug_session_id.as_str()).ok().flatten());
        let (row_name, row_name_user_set, row_tag, row_synopsis, row_private) = row
            .as_ref()
            .map(|row| {
                (
                    row.name.clone(),
                    row.name_user_set,
                    row.tag.clone(),
                    row.synopsis.clone(),
                    row.private,
                )
            })
            .unwrap_or((None, false, None, None, false));
        // The line the ack reports is the entry's — the row does not exist yet
        // on a fresh spawn, and the entry is where the payload's line landed.
        let row_line_id = match row.as_ref() {
            Some(row) if !row.line_id.is_empty() => Some(row.line_id.clone()),
            _ => {
                let entry = entry_arc.lock().await;
                entry.line_id.clone()
            }
        };
        // The arc binding rides the ack the same way `workspace_key` does —
        // it is what a card wears the moment it opens — and reads as unbound
        // when the arc's record is gone ([P05]). The ack is no longer the
        // binding store's only writer: `bind_arc_ok` moves it too, which is
        // what carries a rotation's seated binding onto the fresh segment.
        let (row_arc_id, row_arc_name) = match row.filter(|r| r.arc_id.is_some()) {
            Some(row) => {
                let project = row.project_dir.clone();
                // A panicked blocking task is not evidence the arc is gone
                // either — it reads as `Unreadable` for the same reason a
                // failed `git` does.
                let records = tokio::task::spawn_blocking(move || Self::live_arc_records(&project))
                    .await
                    .unwrap_or(ArcRecords::Unreadable);
                Self::reported_binding(&records, row.arc_id, row.arc_name)
            }
            None => (None, None),
        };
        let ack = serde_json::json!({
            "action": "spawn_session_ok",
            "card_id": card_id,
            "tug_session_id": tug_session_id.as_str(),
            "workspace_key": workspace_key.as_ref(),
            // Echo the pre-canonical path the client sent so tugdeck's
            // binding store carries the form the user actually chose.
            // The filter identity comes from `workspace_key`, not this
            // field — `project_dir` is informational for UI display.
            "project_dir": project_dir_str,
            "session_mode": effective_mode.as_wire_str(),
            // The line this card is on ([P03]). Every identity-shaped store on
            // the deck keys by it, and the ack is where a fresh spawn learns
            // the id the ledger actually settled on.
            "line_id": row_line_id,
            "name": row_name,
            "name_user_set": row_name_user_set,
            "tag": row_tag,
            // The description rides the ack for the same reason the callsign
            // does: a resumed card must not sit on an empty line waiting for
            // the next listing.
            "synopsis": row_synopsis,
            // Overview privacy rides the ack for the same reason: a resumed card
            // must show the marker immediately, not wait for the next push.
            "private": row_private,
            // The arc this session is working on, or null when unbound.
            "arc_id": row_arc_id,
            "arc_name": row_arc_name,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&ack).expect("spawn_session_ok serializes"),
        ));

        Ok(())
    }

    /// Spawn a session no card owns ([P11]).
    ///
    /// The pipeline is `do_spawn_session`'s minus everything that belongs to a
    /// client: no `client_sessions` affinity row, no `spawn_session_ok` ack,
    /// and none of the resume arbitration — a headless spawn always mints a
    /// fresh id, so there is no other holder to arbitrate against. What
    /// remains is what makes a session a session: the workspace refcount, the
    /// ledger entry, the P13 spawn budget, and the eager subprocess. The
    /// session is therefore ordinary everywhere downstream — it gets a
    /// transcript, a ledger row, a citation identity, and an id a deck client
    /// can later resume.
    ///
    /// The card id is `tripwire:<name>`. It names the tripwire that asked
    /// rather than addressing a card, because no card by that id exists; the
    /// tripwire engine reads the same prefix back off a fact's session to keep
    /// a tripwire from tripping on its own work.
    #[cfg_attr(not(test), allow(dead_code))] // the work tier is the caller
    pub(crate) async fn spawn_headless_session(
        &self,
        tripwire_name: &str,
        project_dir: &Path,
        permission_mode: Option<String>,
        tag: Option<String>,
    ) -> Result<TugSessionId, ControlError> {
        let card_id = format!("{TRIPWIRE_CARD_PREFIX}{tripwire_name}");
        let tug_session_id = TugSessionId::new(uuid::Uuid::new_v4().to_string());
        // A headless session is the only session on its line, and it mints the
        // line itself because no drop preceded it ([P03]).
        let line_id = uuid::Uuid::new_v4().to_string();

        // Phase 0: validate + canonicalize + acquire the workspace refcount,
        // before the ledger is touched, so a bad path costs nothing.
        let workspace_entry = self
            .registry
            .get_or_create(project_dir, self.cancel.clone())
            .map_err(|e| match e {
                WorkspaceError::InvalidProjectDir { reason, .. } => {
                    warn!(
                        card_id,
                        session = %tug_session_id,
                        path = ?project_dir,
                        reason,
                        "spawn_headless_session: invalid project_dir"
                    );
                    ControlError::InvalidProjectDir { reason }
                }
                WorkspaceError::UnknownKey(_) => {
                    unreachable!("get_or_create never returns UnknownKey")
                }
            })?;
        let workspace_key = workspace_entry.workspace_key.clone();
        drop(workspace_entry);

        // Phase 1: the budget check and the insert, atomic under the ledger
        // lock. The id is fresh, so this is always an insert and the
        // reconnect arithmetic `do_spawn_session` carries has nothing to
        // decide here. The budget is not waived: a wire's session is a real
        // subprocess and counts like every other.
        let entry_arc = {
            let mut ledger = self.ledger.lock().await;
            if let Some(reason) = cap_check_reason(
                &ledger,
                self.config.max_concurrent_sessions,
                &self.spawn_timestamps,
                self.config.max_spawns_per_minute,
            ) {
                drop(ledger);
                if let Err(e) = self.registry.release(&workspace_key) {
                    warn!(
                        card_id,
                        session = %tug_session_id,
                        error = %e,
                        "spawn_headless_session: cap-reject workspace release failed (ignored)"
                    );
                }
                warn!(
                    card_id,
                    session = %tug_session_id,
                    reason,
                    "spawn_headless_session: rejected by spawn budget"
                );
                return Err(ControlError::CapExceeded { reason });
            }
            let arc = Arc::new(Mutex::new(LedgerEntry::new(
                tug_session_id.clone(),
                workspace_key.clone(),
                project_dir.to_path_buf(),
                SessionMode::New,
                CrashBudget::new(3, Duration::from_secs(60)),
            )));
            ledger.insert(tug_session_id.clone(), Arc::clone(&arc));
            arc
        };

        // Phase 2: stamp the entry and claim the spawn. The refcount Phase 0
        // acquired is this entry's for its lifetime; `do_close_session`
        // releases it on the strength of this flag.
        {
            let mut entry = entry_arc.lock().await;
            entry.card_id = Some(card_id.clone());
            entry.permission_mode = permission_mode;
            entry.tag = tag;
            entry.line_id = Some(line_id);
            entry.holds_workspace_refcount = true;
            entry
                .spawn_state
                .try_transition(SpawnState::Spawning)
                .expect("a just-minted entry is Idle");
        }

        self.session_state.publish_tagged(build_session_state_frame(
            &tug_session_id,
            "pending",
            None,
        ));
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "supervisor.headless_spawn",
            tug_session_id = %tug_session_id,
            card_id = %card_id,
            project_dir = ?project_dir,
        );

        self.spawn_session_worker(&tug_session_id).await;

        Ok(tug_session_id)
    }

    /// Close a session `spawn_headless_session` opened. The close path is the
    /// card's own — the workspace refcount comes back, the ledger row goes
    /// `closed`, and the session-closed fact is recorded — because a headless
    /// session differs from a card's only in who asked for it.
    #[cfg_attr(not(test), allow(dead_code))] // the work tier is the caller
    pub(crate) async fn close_headless_session(
        &self,
        tripwire_name: &str,
        tug_session_id: &TugSessionId,
    ) {
        let card_id = format!("{TRIPWIRE_CARD_PREFIX}{tripwire_name}");
        self.do_close_session(&card_id, tug_session_id).await;
    }

    async fn do_close_session(&self, card_id: &str, tug_session_id: &TugSessionId) {
        // Phase 1: remove the ledger entry AND drop the id from every client's
        // affinity set, atomically under ledger_lock + client_sessions_lock.
        // Cleaning across all clients (not just `_client_id`) guarantees the
        // close/spawn race test's self-consistency invariant: after a close,
        // NO client_sessions set references the removed id. An unknown id
        // short-circuits here with no side effects (no tugbank interaction,
        // no SESSION_STATE publish, no lock on `client_sessions`).
        let entry_arc = {
            let mut ledger = self.ledger.lock().await;
            let removed = ledger.remove(tug_session_id);
            if removed.is_some() {
                let mut cs = self.client_sessions.lock().await;
                for set in cs.values_mut() {
                    set.remove(tug_session_id);
                }
            }
            removed
        };

        let Some(entry_arc) = entry_arc else {
            return;
        };

        // Phase 2: per-session mutation. Cancel the worker token AND flip
        // `spawn_state` to `Closed`. Flipping the state matters even though
        // the entry has just been removed from the map: a `spawn_session_worker`
        // that raced us — dispatcher flipped `Idle → Spawning`, called
        // `spawn_session_worker`, and the worker grabbed its own `Arc` clone
        // via `ledger.get(id)` BEFORE our `HashMap::remove` — is still
        // holding an `Arc<Mutex<LedgerEntry>>` clone and would otherwise
        // observe `spawn_state == Spawning` and proceed to publish
        // `SESSION_STATE = spawning` AFTER our `closed`. Setting the state to
        // `Closed` here lets the worker's early-bail check (`if state !=
        // Spawning { return }`) catch the close and skip its publish,
        // preserving frame order on the wire.
        //
        // Also snapshot the `workspace_key` and `claude_session_id` under
        // this same lock so Phase 3 can call `registry.release` and Phase 5
        // can mark the ledger row closed without re-acquiring it.
        let (workspace_key, claude_session_id, held_refcount) = {
            let mut entry = entry_arc.lock().await;
            entry.cancel.cancel();
            // Bare assignment (not `try_transition`) because the entry is
            // about to be dropped; we only care that any Arc-clone holder
            // observes `Closed` on its next lock acquire.
            entry.spawn_state = SpawnState::Closed;
            // Take the refcount ownership: release it below iff this entry
            // adopted one. A rebind entry closed before it ever spawned holds
            // none — releasing then would decrement another card's refcount for
            // the same workspace, or error on `UnknownKey`.
            let held = entry.holds_workspace_refcount;
            entry.holds_workspace_refcount = false;
            // `card_id` is preserved across close so the persisted
            // ledger row retains the binding for client-side restore;
            // liveness is encoded in `spawn_state`.
            (
                entry.workspace_key.clone(),
                entry.claude_session_id.clone(),
                held,
            )
        };

        // Phase 3: release the workspace refcount this entry owned. Errors on
        // this path (e.g. `UnknownKey` from a double-close race) are logged and
        // swallowed — they indicate a caller-side logic error, not a condition
        // worth propagating to the wire.
        if held_refcount {
            if let Err(e) = self.registry.release(&workspace_key) {
                warn!(
                    card_id,
                    session = %tug_session_id,
                    error = %e,
                    "close_session: workspace release failed, continuing"
                );
            }
        }

        // The persisted ledger row is preserved across close — a
        // closed card can be reopened with history through
        // `rebind_from_ledger` on the next startup. The explicit
        // `reset_session` flow is the only path that invalidates the
        // session_id; close is a "stop the subprocess but keep the
        // history pointer" operation.

        // Phase 5: publish `closed`. (The `Arc<Mutex<LedgerEntry>>` we hold
        // is dropped at the end of this scope.)
        self.session_state.publish_tagged(build_session_state_frame(
            tug_session_id,
            "closed",
            None,
        ));

        // Phase 6: transition the ledger row to `closed`. Pre-handshake
        // sessions never reached `session_init` and have no row, so the
        // `claude_session_id` snapshot is `None` — nothing to mark closed.
        if let Some(claude_id) = claude_session_id {
            // Before the row goes closed, while the binding still names the
            // arc: a card seated by a stage takes its arc out of the sweep
            // when it closes, and an arc that left with no record would say
            // `review` forever with nothing running.
            if let Some(ledger) = self.session_ledger.as_ref() {
                crate::arc_api::stop_an_on_arc_cards_arc_as_closed(ledger, &claude_id);
            }
            self.sessions_recorder.mark_closed(&claude_id);
        }
    }

    /// Resolved terminal-liveness registry root: the configured
    /// override, else the production default (`~/.claude/sessions/`).
    fn terminal_registry_root(&self) -> Option<PathBuf> {
        self.config
            .terminal_registry_root
            .clone()
            .or_else(crate::terminal_registry::default_registry_root)
    }

    /// Read the terminal-liveness registry. Fail-open: no resolvable
    /// root → empty map (no liveness data, never an error).
    fn read_terminal_live_sessions(
        registry_root: Option<&std::path::Path>,
    ) -> HashMap<String, crate::terminal_registry::TerminalLiveEntry> {
        match registry_root {
            Some(root) => crate::terminal_registry::read_live_sessions(root),
            None => HashMap::new(),
        }
    }

    /// Broadcast a `list_sessions_ok` frame. `scanning` is `true` for the
    /// cheap phase-1 emit (ledger rows only, external scan still running)
    /// and `false` for the settled phase-2 emit carrying the full union —
    /// the picker shows a scanning indicator while `true` and clears it
    /// when the `false` frame replaces the snapshot.
    fn send_list_sessions_ok(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        dir_exists: bool,
        sessions: &[ListedSession],
        scanning: bool,
    ) {
        let body = serde_json::json!({
            "action": "list_sessions_ok",
            "project_dir": project_dir,
            "dir_exists": dir_exists,
            "scanning": scanning,
            "sessions": sessions,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_sessions_ok serializes"),
        ));
    }

    fn send_list_sessions_err(control_tx: &broadcast::Sender<Frame>, project_dir: &str) {
        let body = serde_json::json!({
            "action": "list_sessions_err",
            "project_dir": project_dir,
            "reason": "ledger_read_failed",
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_sessions_err serializes"),
        ));
    }

    /// Handle a `list_sessions` CONTROL request. Broadcasts a
    /// `list_sessions_ok` response carrying the **union** of:
    ///
    /// - sqlite ledger rows whose `project_dir` matches the requested
    ///   path (`origin: "tug"`), and
    /// - on-disk session JSONLs discovered under the encoded claude
    ///   project directory that have no ledger row
    ///   (`origin: "external"` — typically terminal-created sessions).
    ///
    /// Deduped by session id (ledger wins — it carries richer,
    /// Tug-authored metadata), sorted newest-first by `last_used_at`.
    /// Every row — both origins — is annotated with `terminal_live`
    /// when a live process registered in `~/.claude/sessions/`
    /// currently holds it.
    ///
    /// Emitted in **two phases** so the picker never blocks on the scan
    /// (see the inline phase comments and Risk R03): a cheap phase-1
    /// `list_sessions_ok { scanning: true }` with the ledger rows lands
    /// immediately, then a settled phase-2 `{ scanning: false }` with the
    /// full union lands once the off-loop JSONL scan completes. The client
    /// replaces its snapshot on each, so external rows stream in.
    ///
    /// The response also carries `dir_exists` — a filesystem check on
    /// `project_dir` — so the picker can disable its Open button before
    /// a doomed `spawn_session` is ever sent. tugdeck has no filesystem
    /// access of its own, so this read piggybacks on the per-path query
    /// the picker already issues.
    async fn do_list_sessions(&self, project_dir: &str) {
        // `false` covers both a missing path and a non-directory — the
        // picker only needs the binary "is this an openable directory"
        // signal.
        let dir_exists = tokio::fs::metadata(project_dir)
            .await
            .map(|m| m.is_dir())
            .unwrap_or(false);
        let Some(ledger) = self.session_ledger.as_ref() else {
            // No ledger wired — emit an empty, settled response so a
            // confused client doesn't sit on a pending state forever.
            Self::send_list_sessions_ok(&self.control_tx, project_dir, dir_exists, &[], false);
            return;
        };

        let ledger_arc = Arc::clone(ledger);
        let registry_root = self.terminal_registry_root();
        let control_tx = self.control_tx.clone();
        let pd = project_dir.to_owned();

        // ── Phase 1: cheap reads (sqlite ledger + the handful of tiny
        //    `~/.claude/sessions` registry files). Emitted IMMEDIATELY so
        //    the picker shows "New session" plus every resumable ledger
        //    row without waiting on the JSONL scan — which on a large
        //    project dir (this repo's claude dir is ~1k files / multi-GB)
        //    can take many seconds (Risk R03). Pressing Cmd-N must never
        //    block on the scan; before this split it froze the dialog for
        //    the full scan duration.
        let phase1 = tokio::task::spawn_blocking({
            let ledger_arc = Arc::clone(&ledger_arc);
            let registry_root = registry_root.clone();
            let pd = pd.clone();
            move || {
                let rows = ledger_arc.list_for_project_dir(&pd)?;
                let live = Self::read_terminal_live_sessions(registry_root.as_deref());
                Ok::<_, crate::session_ledger::LedgerError>((rows, live))
            }
        })
        .await;
        let (rows, live) = match phase1 {
            Ok(Ok(t)) => t,
            Ok(Err(err)) => {
                warn!(error = %err, project_dir, "list_sessions phase 1 failed");
                Self::send_list_sessions_err(&control_tx, project_dir);
                return;
            }
            Err(join_err) => {
                warn!(error = %join_err, project_dir, "list_sessions worker panicked");
                Self::send_list_sessions_err(&control_tx, project_dir);
                return;
            }
        };

        // Phase 1 emit: ledger-only preview, scan still pending.
        let ledger_preview = build_listed_union(rows, &live, None);
        Self::send_list_sessions_ok(&control_tx, project_dir, dir_exists, &ledger_preview, true);

        // ── Phase 2: the expensive JSONL scan, run off the control loop in
        //    a detached task. Re-reads the ledger + liveness **fresh**
        //    alongside the scan, so any `session_updated` that lands during
        //    the scan window is reflected in the settled frame instead of
        //    being clobbered by the stale phase-1 snapshot. Emits the
        //    authoritative union (scanning: false); the client replaces its
        //    snapshot, so external/terminal rows stream in and the scanning
        //    indicator clears. The scan resolves the typed path to claude's
        //    canonical directory internally (the `claude_project_dir`
        //    chokepoint).
        let project_dir_owned = project_dir.to_owned();
        // Phase-1 preview, retained only as the settle-with-rows fallback if
        // the phase-2 worker panics (effectively unreachable — its body
        // cannot panic on well-formed input — but keeps the indicator from
        // ever spinning forever).
        let preview_fallback = ledger_preview;
        tokio::spawn(async move {
            let progress_tx = control_tx.clone();
            let built = tokio::task::spawn_blocking(move || {
                let rows = ledger_arc.list_for_project_dir(&pd).unwrap_or_else(|err| {
                    warn!(error = %err, "list_sessions phase 2 ledger re-read failed");
                    Vec::new()
                });
                let live = Self::read_terminal_live_sessions(registry_root.as_deref());
                // Throttled scan progress: `list_sessions_progress` frames
                // (≤ ~10 Hz, first and last ticks always) keyed by the
                // typed path — the client's cache key — so a cold or
                // whale-heavy scan reads as a moving count in the picker
                // instead of a silent stall. Pure-hit warm scans emit
                // nothing.
                let progress_pd = pd.clone();
                let last_emit: std::sync::Mutex<Option<std::time::Instant>> =
                    std::sync::Mutex::new(None);
                let scan = crate::external_sessions::scan_external_sessions_cached_with_progress(
                    &ledger_arc,
                    &pd,
                    |done, total| {
                        let now = std::time::Instant::now();
                        {
                            let mut last = last_emit.lock().expect("progress throttle mutex");
                            let boundary = done == 0 || done == total;
                            let due = last.is_none_or(|t| {
                                now.duration_since(t) >= std::time::Duration::from_millis(100)
                            });
                            if !boundary && !due {
                                return;
                            }
                            *last = Some(now);
                        }
                        let body = serde_json::json!({
                            "action": "list_sessions_progress",
                            "project_dir": progress_pd,
                            "parsed": done,
                            "total": total,
                        });
                        let _ = progress_tx.send(Frame::new(
                            FeedId::CONTROL,
                            serde_json::to_vec(&body).expect("list_sessions_progress serializes"),
                        ));
                    },
                );
                build_listed_union(rows, &live, Some(scan))
            })
            .await;
            match built {
                Ok(union) => {
                    Self::send_list_sessions_ok(
                        &control_tx,
                        &project_dir_owned,
                        dir_exists,
                        &union,
                        false,
                    );
                }
                Err(join_err) => {
                    warn!(
                        error = %join_err,
                        project_dir = %project_dir_owned,
                        "list_sessions phase 2 worker panicked",
                    );
                    // Settle with the phase-1 preview so the indicator clears
                    // and the user keeps their resumable rows.
                    Self::send_list_sessions_ok(
                        &control_tx,
                        &project_dir_owned,
                        dir_exists,
                        &preview_fallback,
                        false,
                    );
                }
            }
        });
    }

    /// Handle a `changeset_git_init` CONTROL request (Spec S07): `git init
    /// -b main` a non-repo project the changeset card offered to initialize.
    ///
    /// Guards, in order: `project_dir` must match a current
    /// `WorkspaceRegistry` entry (never init an arbitrary path off the wire),
    /// and it must not already be inside a git working tree. On success the
    /// process-global aggregate bump is fired so the card's section
    /// self-heals to a clean repo on the next recompute — there is no
    /// client-side state transition. Broadcasts `changeset_git_init_ok` /
    /// `changeset_git_init_err {detail}`.
    async fn do_changeset_git_init(&self, project_dir: &str) {
        let dir = std::path::Path::new(project_dir);

        // Guard 1: only an open workspace may be initialized.
        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_git_init_err(&self.control_tx, project_dir, "not an open project");
            return;
        }

        // Guard 2: refuse a directory already inside a git working tree.
        if crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_git_init_err(
                &self.control_tx,
                project_dir,
                "already a git repository",
            );
            return;
        }

        let output = tokio::process::Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(["init", "-b", "main"])
            .output()
            .await;

        match output {
            Ok(out) if out.status.success() => {
                // The next aggregate recompute sees a repo and the section
                // flips to a clean changeset — self-healing, no client flip.
                self.registry.changeset_all_bump().notify_one();
                Self::send_changeset_git_init_ok(&self.control_tx, project_dir);
            }
            Ok(out) => {
                let detail = String::from_utf8_lossy(&out.stderr).trim().to_string();
                Self::send_changeset_git_init_err(
                    &self.control_tx,
                    project_dir,
                    if detail.is_empty() {
                        "git init failed"
                    } else {
                        &detail
                    },
                );
            }
            Err(e) => {
                Self::send_changeset_git_init_err(&self.control_tx, project_dir, &e.to_string());
            }
        }
    }

    /// A `tug_session_id` → `claude_session_id` lookup over the in-memory
    /// ledger, for anything that needs to find a session's JSONL.
    ///
    /// Sync over the tokio async mutex: `try_lock` never blocks — under rare
    /// contention it degrades to "no claude id", which callers treat as missing
    /// context rather than as an error.
    pub fn session_resolver(&self) -> crate::feeds::draft_engine::SessionResolver {
        let inmem = Arc::clone(&self.ledger);
        Arc::new(move |tug_id: &str| {
            let map = inmem.try_lock().ok()?;
            let entry = map.get(&TugSessionId(tug_id.to_string()))?;
            let entry = entry.try_lock().ok()?;
            entry.claude_session_id.clone()
        })
    }

    /// Handle a `changeset_draft_request` CONTROL request ([P03], Spec S01): an
    /// explicit, on-demand commit-message draft for one changeset entry.
    ///
    /// Resolves the entry against the latest CHANGESET_ALL aggregate frame (the
    /// stored watch receiver) and spawns its generation on a detached task —
    /// this method NEVER awaits the scribe run, so the router's per-client
    /// socket loop stays live to deliver the streamed deltas (R02). It does
    /// nothing when the scribe, the read-side ledger, or the aggregate watch
    /// isn't wired (tests without the draft path) — but never *silently*:
    /// every exit from this method broadcasts a `changeset_draft_state
    /// { state: "error" }` naming what went wrong ([Q02], [L31]). The
    /// unmatched-owner case is the engine's own answer, which names the owner
    /// it could not place ([B04]).
    fn do_changeset_draft_request(&self, request: &ChangesetDraftRequestPayload) {
        // Every guard below answers before it returns ([L31]). A draft request
        // that falls out of this function in silence leaves the shade's
        // Auto-Message button idle forever with nothing anywhere saying why —
        // no frame for the deck, no line in the log — which is the failure
        // this arc exists to close, and the four bare `return`s that used to
        // stand here were the likeliest source of it.
        let Some(scribe) = self.scribe.clone() else {
            warn!("changeset draft request: no scribe configured");
            Self::send_changeset_draft_error(
                &self.control_tx,
                request,
                "Couldn't reach the scribe: this instance has none configured.",
            );
            return;
        };
        let Some(ledger) = self.session_ledger.clone() else {
            warn!("changeset draft request: no session ledger");
            Self::send_changeset_draft_error(
                &self.control_tx,
                request,
                "Couldn't reach the scribe: this instance has no session ledger.",
            );
            return;
        };
        let Some(watch_rx) = self.changeset_watch.get() else {
            warn!("changeset draft request: changeset watch not yet armed");
            Self::send_changeset_draft_error(
                &self.control_tx,
                request,
                "The changeset hasn't been composed yet — try again in a moment.",
            );
            return;
        };
        let frame = watch_rx.borrow().clone();
        let Ok(snapshot) = serde_json::from_slice::<tugcast_core::types::WorkspacesChangesetSnapshot>(
            &frame.payload,
        ) else {
            // The initial empty frame, or a decode miss.
            warn!("changeset draft request: changeset snapshot did not decode");
            Self::send_changeset_draft_error(
                &self.control_tx,
                request,
                "The changeset hasn't been composed yet — try again in a moment.",
            );
            return;
        };

        let resolver = self.session_resolver();

        // The engine answers its own miss, naming the owner it could not place
        // ([B04]) — so there is nothing to add here and a second frame would
        // only overwrite the better sentence with a vaguer one.
        crate::feeds::draft_engine::spawn_on_demand_draft(
            self.control_tx.clone(),
            ledger,
            Arc::clone(&self.registry),
            scribe,
            resolver,
            &self.draft_tasks,
            snapshot,
            &request.workspace_key,
            &request.owner_kind,
            &request.owner_id,
            request.force,
        );
    }

    /// Handle a `changeset_draft_cancel` CONTROL request ([P06]): the user
    /// cancelled an in-flight Auto-Message (the Z5 cancel button, Escape, or
    /// Cmd-.). Aborts the entry's live generation task — killing only its
    /// headless scribe child — and broadcasts a terminal `cancelled` state so
    /// the composer drops the wave caret and re-opens for typing.
    ///
    /// The `cancelled` broadcast is unconditional. Cancel is idempotent: a
    /// client whose overlay says `drafting` after this registry lost the task
    /// (a crashed generation, a terminal frame the deck never received) has no
    /// other exit, and answering only when a task existed leaves that client's
    /// composer read-only forever. A late cancel racing a just-landed `ready`
    /// folds the overlay to idle, which reads the persisted draft — harmless.
    fn do_changeset_draft_cancel(&self, request: &ChangesetDraftCancelPayload) {
        crate::feeds::draft_engine::cancel_draft(
            &self.draft_tasks,
            &request.workspace_key,
            &request.owner_kind,
            &request.owner_id,
        );
        crate::feeds::draft_engine::send_draft_cancelled(
            &self.control_tx,
            &request.workspace_key,
            &request.owner_kind,
            &request.owner_id,
        );
    }

    /// Handle a `changeset_draft_set` CONTROL request (Spec S01): a partial
    /// upsert of one draft row — message edits, selection dispositions, or
    /// the post-landing `clear`. The row is keyed by the request's canonical
    /// `workspace_key`, which is what every draft row is keyed by; the global
    /// aggregate bump fires so the next frame carries the change.
    fn do_changeset_draft_set(&self, request: &ChangesetDraftSetPayload) {
        let Some(ledger) = self.session_ledger.clone() else {
            return;
        };
        if request.clear {
            let _ = ledger.delete_changeset_draft(
                &request.owner_kind,
                &request.owner_id,
                &request.workspace_key,
            );
            self.registry.changeset_all_bump().notify_one();
            return;
        }
        let existing = crate::feeds::draft_engine::read_draft(
            &ledger,
            &request.owner_kind,
            &request.owner_id,
            &request.workspace_key,
        );
        let (fingerprint, prior_message, prior_edited, prior_selection) = existing
            .map(|e| (e.fingerprint, e.message, e.edited, e.selection))
            .unwrap_or_default();
        let row = crate::session_ledger::ChangesetDraftRow {
            owner_kind: request.owner_kind.clone(),
            owner_id: request.owner_id.clone(),
            project_dir: request.workspace_key.clone(),
            fingerprint,
            message: request.message.clone().unwrap_or(prior_message),
            updated_at: crate::feeds::draft_engine::now_millis(),
            // Monotonic through this verb: a human touch pins the draft;
            // only a confirmed forced regenerate resets it ([P03]).
            edited: request.edited || prior_edited,
            selection: match &request.selection {
                Some(replacement) => replacement.clone(),
                None => prior_selection,
            },
        };
        if let Err(err) = ledger.upsert_changeset_draft(&row) {
            warn!(error = %err, "changeset_draft_set: persist failed");
            return;
        }
        self.registry.changeset_all_bump().notify_one();
    }

    /// Post-landing cleanup for an arc's join draft ([P14]): joins and
    /// releases both delete the `arc:<branch>` row, so a reused arc name
    /// never inherits a dead arc's clobber-protected message.
    ///
    /// `project_dir` is whatever spelling the landing verb was called with, so
    /// it passes the [L29] gateway here — one call, at the boundary — to reach
    /// the key the row was written under.
    /// Handle a `bind_arc` CONTROL request (Spec S03): mate a session to an
    /// arc. Shares its ledger half with `POST /api/arc` so a bind issued
    /// from a card and one issued from the CLI cannot diverge.
    ///
    /// Broadcasts `bind_arc_ok {tug_session_id, arc_id, arc_name}` or
    /// `bind_arc_err {reason}`, and fires the aggregate changeset bump on
    /// success — the same bump a landing fires, so the Changes card recomposes
    /// with the new mating.
    async fn do_bind_arc(&self, request: &BindArcPayload) {
        let Some(ledger) = self.session_ledger.clone() else {
            Self::send_bind_arc_err(&self.control_tx, &request.tug_session_id, "no_ledger");
            return;
        };
        // The gateway ([L29]) — the same resolution `/api/arc` applies, so
        // both surfaces open the same repo for the same spelling.
        let project = crate::path_resolver::resolve_to_claude_form(std::path::Path::new(
            &request.project_dir,
        ));
        let session = request.tug_session_id.clone();
        let arc = request.arc.clone();
        let outcome = tokio::task::spawn_blocking(move || {
            crate::arc_api::bind(&ledger, &project, &session, &arc)
        })
        .await;

        match outcome {
            Ok(crate::arc_api::ArcApiOutcome::Bound {
                session_id,
                arc_id,
                arc_name,
            }) => {
                self.registry.changeset_all_bump().notify_one();
                // The segment the write landed on, not the one the request
                // named — see the door's own note on the expansion.
                //
                // No routing halves: this door binds a segment the card is
                // already seated on, so the deck's own walk resolves it. The
                // seat is the one caller whose segment the deck has never met.
                broadcast_bind_arc_ok(
                    &self.control_tx,
                    &session_id,
                    &arc_id,
                    &arc_name,
                    None,
                    None,
                );
            }
            Ok(crate::arc_api::ArcApiOutcome::UnknownSession) => {
                Self::send_bind_arc_err(
                    &self.control_tx,
                    &request.tug_session_id,
                    "unknown_session",
                );
            }
            Ok(crate::arc_api::ArcApiOutcome::Error(detail)) => {
                Self::send_bind_arc_err(&self.control_tx, &request.tug_session_id, &detail);
            }
            Ok(_) => {}
            Err(join_err) => {
                Self::send_bind_arc_err(
                    &self.control_tx,
                    &request.tug_session_id,
                    &format!("bind task failed: {join_err}"),
                );
            }
        }
    }

    /// Bind the calling session to the arc a door prompt named, at submit
    /// time — the same ledger half `do_bind_arc` and `/api/arc` share, so a
    /// bind from the keystroke, from the card, and from the CLI cannot
    /// diverge. A bind mints the arc's *id*, not its directory, and the
    /// aggregate lists an arc by its branch or its directory — neither of
    /// which a just-typed name has — so on success this also makes the
    /// documents directory, the same empty directory `arc documents
    /// --ensure` is about to make, which is what puts the arc on the wire
    /// for the card to read `ARC` against ([F03]).
    ///
    /// A refusal is logged and nothing else. This bind is a head start on the
    /// one the door's own first command makes with `arc documents --ensure
    /// --bind`, and that one reports its refusal on the transcript where the
    /// model reads it; raising a card bulletin here as well would say the
    /// same thing twice, once to nobody.
    async fn bind_arc_at_the_door(
        &self,
        tug_session_id: &TugSessionId,
        entry_arc: &Arc<Mutex<LedgerEntry>>,
        arc: &str,
    ) {
        let Some(ledger) = self.session_ledger.clone() else {
            return;
        };
        let project_dir = entry_arc.lock().await.project_dir.clone();
        // The gateway ([L29]) — the same resolution every other bind applies.
        let project = crate::path_resolver::resolve_to_claude_form(&project_dir);
        let session = tug_session_id.as_str().to_string();
        let name = arc.to_string();
        let outcome = tokio::task::spawn_blocking(move || {
            let outcome = crate::arc_api::bind(&ledger, &project, &session, &name);
            if matches!(outcome, crate::arc_api::ArcApiOutcome::Bound { .. }) {
                let dir = tugarc_core::documents_dir(&project, &name);
                match std::fs::create_dir_all(&dir) {
                    Ok(()) => tugarc_core::ensure_tug_excluded(&project),
                    Err(err) => warn!(
                        error = %err,
                        dir = %dir.display(),
                        "door prompt: bound, but could not make the documents directory",
                    ),
                }
            }
            outcome
        })
        .await;
        match outcome {
            Ok(crate::arc_api::ArcApiOutcome::Bound {
                session_id,
                arc_id,
                arc_name,
            }) => {
                self.registry.changeset_all_bump().notify_one();
                broadcast_bind_arc_ok(
                    &self.control_tx,
                    &session_id,
                    &arc_id,
                    &arc_name,
                    None,
                    None,
                );
            }
            Ok(crate::arc_api::ArcApiOutcome::Error(detail)) => {
                warn!(
                    tug_session_id = %tug_session_id,
                    arc,
                    detail,
                    "door prompt: bind refused; the door's own bind will say so",
                );
            }
            Ok(_) => {}
            Err(join_err) => {
                warn!(
                    tug_session_id = %tug_session_id,
                    arc,
                    error = %join_err,
                    "door prompt: bind task failed",
                );
            }
        }
    }

    /// Handle an `arc_resume` CONTROL request: pick a stopped arc back up on
    /// the card that sent it — the Resume button in a stop receipt's own row.
    ///
    /// Broadcasts **two** frames on success, because two things happened.
    /// `bind_arc_ok` is the mating, and it is the same fact through either
    /// door — a deck that learned about a bind from one door and not the
    /// other wears a chip that disagrees with the ledger. `arc_resume_ok` is
    /// the answer to the press, which is what lets the button stop being
    /// pending. A refusal sends `arc_resume_err` only: nothing was mated, so
    /// there is no mating to announce.
    async fn do_arc_resume(&self, request: &BindArcPayload) {
        let Some(ledger) = self.session_ledger.clone() else {
            Self::send_arc_resume_err(
                &self.control_tx,
                &request.tug_session_id,
                &request.arc,
                "no_ledger",
            );
            return;
        };
        // The gateway ([L29]) — the same resolution `bind_arc` and
        // `/api/arc` apply, so all three open the same repo for one spelling.
        let project = crate::path_resolver::resolve_to_claude_form(std::path::Path::new(
            &request.project_dir,
        ));
        let session = request.tug_session_id.clone();
        let arc = request.arc.clone();
        let outcome = tokio::task::spawn_blocking(move || {
            crate::arc_api::arc_resume(&ledger, &project, &session, &arc)
        })
        .await;

        match outcome {
            Ok(crate::arc_api::ArcApiOutcome::Bound {
                session_id,
                arc_id,
                arc_name,
            }) => {
                self.registry.changeset_all_bump().notify_one();
                broadcast_bind_arc_ok(
                    &self.control_tx,
                    &session_id,
                    &arc_id,
                    &arc_name,
                    None,
                    None,
                );
                Self::send_arc_resume_ok(&self.control_tx, &session_id, &arc_name);
            }
            Ok(crate::arc_api::ArcApiOutcome::UnknownSession) => {
                Self::send_arc_resume_err(
                    &self.control_tx,
                    &request.tug_session_id,
                    &request.arc,
                    "unknown_session",
                );
            }
            Ok(crate::arc_api::ArcApiOutcome::Error(detail)) => {
                Self::send_arc_resume_err(
                    &self.control_tx,
                    &request.tug_session_id,
                    &request.arc,
                    &detail,
                );
            }
            Ok(_) => {}
            Err(join_err) => {
                Self::send_arc_resume_err(
                    &self.control_tx,
                    &request.tug_session_id,
                    &request.arc,
                    &format!("resume task failed: {join_err}"),
                );
            }
        }
    }

    /// Handle an `unbind_arc` CONTROL request (Spec S03): drop the calling
    /// session's binding. Broadcasts `unbind_arc_ok {tug_session_id}`.
    async fn do_unbind_arc(&self, tug_session_id: &str) {
        let Some(ledger) = self.session_ledger.clone() else {
            Self::send_bind_arc_err(&self.control_tx, tug_session_id, "no_ledger");
            return;
        };
        let session = tug_session_id.to_string();
        let outcome =
            tokio::task::spawn_blocking(move || crate::arc_api::unbind(&ledger, &session)).await;

        match outcome {
            Ok(crate::arc_api::ArcApiOutcome::Unbound { session_id }) => {
                self.registry.changeset_all_bump().notify_one();
                broadcast_unbind_arc_ok(&self.control_tx, &session_id);
            }
            Ok(crate::arc_api::ArcApiOutcome::UnknownSession) => {
                Self::send_bind_arc_err(&self.control_tx, tug_session_id, "unknown_session");
            }
            Ok(crate::arc_api::ArcApiOutcome::Error(detail)) => {
                Self::send_bind_arc_err(&self.control_tx, tug_session_id, &detail);
            }
            Ok(_) => {}
            Err(join_err) => {
                Self::send_bind_arc_err(
                    &self.control_tx,
                    tug_session_id,
                    &format!("unbind task failed: {join_err}"),
                );
            }
        }
    }

    /// The press was answered. Named from the outcome's session, never the
    /// request's: the door expands a frozen id to its line's live segment,
    /// and a frame naming the posted id reaches no card.
    fn send_arc_resume_ok(control_tx: &broadcast::Sender<Frame>, tug_session_id: &str, arc: &str) {
        let body = serde_json::json!({
            "action": "arc_resume_ok",
            "tug_session_id": tug_session_id,
            "arc": arc,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("arc_resume_ok serializes"),
        ));
    }

    /// The press was refused, and `reason` is what the deck speaks through
    /// the pane bulletin ([B08]). It names the arc as well as the session,
    /// because a card can hold several stop receipts and only one of them
    /// was pressed.
    fn send_arc_resume_err(
        control_tx: &broadcast::Sender<Frame>,
        tug_session_id: &str,
        arc: &str,
        reason: &str,
    ) {
        let body = serde_json::json!({
            "action": "arc_resume_err",
            "tug_session_id": tug_session_id,
            "arc": arc,
            "reason": reason,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("arc_resume_err serializes"),
        ));
    }

    fn send_bind_arc_err(
        control_tx: &broadcast::Sender<Frame>,
        tug_session_id: &str,
        reason: &str,
    ) {
        let body = serde_json::json!({
            "action": "bind_arc_err",
            "tug_session_id": tug_session_id,
            "reason": reason,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("bind_arc_err serializes"),
        ));
    }

    /// The repo's arc records, keyed by legacy owner key (`tugarc/<name>`).
    ///
    /// **Two** `git` reads per repo, membership-tested in memory — not a
    /// `rev-parse` per arc ([P05]). The callers are the startup restore
    /// round-trip cards wait on behind `RESTORE_PASS_SETTLE_TIMEOUT_MS` and
    /// the per-spawn ack; neither may grow subprocess fan-out proportional to
    /// the arc count.
    ///
    /// **The branch is not the record.** An arc's durable identity is its
    /// `tugid` git-config entry, which `ensure_arc_id` mints at bind time and
    /// which needs no branch — so an arc that bound before its branch existed
    /// is bound by design (`server.rs`, the `arc_run` door) and gating on the
    /// ref alone nulls it deterministically. A teardown takes both: `git branch
    /// -D` deletes the branch's whole config section, `tugid` included, which
    /// is what makes their absence together mean "gone".
    ///
    /// The config read is only trusted once `for-each-ref` has proved the repo
    /// answers at all: `git config --get-regexp` exits 1 on *no matches*, which
    /// would otherwise read the same as a repo that is not there.
    fn live_arc_records(repo: &str) -> ArcRecords {
        let git = |args: &[&str]| {
            std::process::Command::new("git")
                .arg("-C")
                .arg(repo)
                .args(args)
                .output()
        };
        let Ok(refs) = git(&[
            "for-each-ref",
            "--format=%(refname:short)",
            "refs/heads/tugarc/",
        ]) else {
            return ArcRecords::Unreadable;
        };
        if !refs.status.success() {
            return ArcRecords::Unreadable;
        }
        let mut records: std::collections::HashSet<String> = String::from_utf8_lossy(&refs.stdout)
            .lines()
            .map(str::trim)
            .filter(|l| !l.is_empty())
            .map(str::to_owned)
            .collect();
        if let Ok(config) = git(&["config", "--get-regexp", r"^branch\.tugarc/.*\.tugid$"])
            && config.status.success()
        {
            for line in String::from_utf8_lossy(&config.stdout).lines() {
                // `branch.tugarc/<name>.tugid <value>` — the stem between the
                // `branch.` prefix and the `.tugid` suffix is the legacy key.
                let key = line.split_whitespace().next().unwrap_or_default();
                if let Some(stem) = key
                    .strip_prefix("branch.")
                    .and_then(|k| k.strip_suffix(".tugid"))
                    && !stem.is_empty()
                {
                    records.insert(stem.to_string());
                }
            }
        }
        ArcRecords::Known(records)
    }

    /// A stored binding as it should be *reported*: the pair as written, or
    /// nulls when the arc's record is gone ([P05]).
    ///
    /// The eager clear on a tugcast-side landing covers the card workflow;
    /// this is the lazy half that keeps reads correct when tugcast was never
    /// in the loop — a terminal join, or a crash between teardown and the
    /// CLI's `arc_gone` broadcast.
    ///
    /// A read that cannot see the repo keeps the ledger's answer. Nulling is a
    /// claim — "this arc is gone" — and only evidence may make it; a failed
    /// `git` is the absence of evidence. The wrong direction here blanks the
    /// arc chip on every card at once with nothing saying why, which is the
    /// half of the postmortem that had no instrumentation.
    ///
    /// Every decision traces under `dev::ledger`, because the surface it
    /// governs is a chip going blank and the question asked afterwards is
    /// always "why did it think the arc was gone".
    fn reported_binding(
        records: &ArcRecords,
        arc_id: Option<String>,
        arc_name: Option<String>,
    ) -> (Option<String>, Option<String>) {
        let Some(id) = arc_id else {
            return (None, None);
        };
        match records {
            ArcRecords::Unreadable => {
                tracing::warn!(
                    target: "dev::ledger",
                    event = "ledger.reported_binding.kept_unreadable",
                    arc_id = id.as_str(),
                    "the repo could not be read; keeping the ledger's binding rather than nulling it",
                );
                (Some(id), arc_name)
            }
            ArcRecords::Known(records) => {
                if records.contains(tugarc_core::ops::legacy_owner_key(&id)) {
                    tracing::debug!(
                        target: "dev::ledger",
                        event = "ledger.reported_binding.kept",
                        arc_id = id.as_str(),
                    );
                    (Some(id), arc_name)
                } else {
                    tracing::info!(
                        target: "dev::ledger",
                        event = "ledger.reported_binding.nulled",
                        arc_id = id.as_str(),
                        records = records.len(),
                        "the repo holds no branch and no tugid for this arc",
                    );
                    (None, None)
                }
            }
        }
    }

    /// Delete a landed arc's authored join draft, under every key it could
    /// have been written with: the owner key and its legacy branch-ref form
    /// ([P03]), each across the canonical and as-given project spellings.
    ///
    /// `owner_key` arrives **pre-resolved** and cannot be resolved here.
    /// `git branch -D` takes the branch's whole config section with it,
    /// `tugid` included, so by the time a landing returns, the only key this
    /// function could derive is the legacy one — and the user's authored draft
    /// would survive under a key nothing can name again ([L23], [P05],
    /// Risk R02). The caller captures the key before the teardown.
    pub(crate) fn clear_arc_draft(
        ledger: &crate::session_ledger::SessionLedger,
        project_dir: &str,
        owner_key: &str,
    ) {
        let canonical =
            crate::path_resolver::CanonicalPath::from_raw(std::path::Path::new(project_dir));
        let legacy_key = tugarc_core::ops::legacy_owner_key(owner_key);
        let keys = if legacy_key == owner_key {
            vec![owner_key]
        } else {
            vec![owner_key, legacy_key]
        };
        for key in keys {
            let _ = ledger.delete_changeset_draft("arc", key, canonical.as_str());
            if canonical.as_str() != project_dir {
                let _ = ledger.delete_changeset_draft("arc", key, project_dir);
            }
        }
    }

    /// Broadcast a `changeset_draft_state` error for a request that matched no
    /// eligible entry ([Q02]) — the same wire shape the generation task's
    /// `send_state` emits, down to the `workspace_key` identity, so the client
    /// overlay renders it identically and, crucially, receives it at all.
    fn send_changeset_draft_error(
        control_tx: &broadcast::Sender<Frame>,
        request: &ChangesetDraftRequestPayload,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_draft_state",
            "workspace_key": request.workspace_key,
            "owner_kind": request.owner_kind,
            "owner_id": request.owner_id,
            "state": "error",
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_draft_state serializes"),
        ));
    }

    /// Handle a `changeset_commit` CONTROL request (Spec S03, [P15]):
    /// commit exactly the listed files in an open project's checkout.
    ///
    /// Guards, in order: `project_dir` must match a current
    /// `WorkspaceRegistry` entry (never run git against an arbitrary path
    /// off the wire) and must lie inside a git working tree. The git work —
    /// pathspec-exact staging + commit, empty-list/blank-message refusal —
    /// lives in `run_changeset_commit`. On success the process-global
    /// aggregate bump fires so the card's entries drop the committed files
    /// on the next recompute, and `changeset_commit_ok {sha, receipt}` goes
    /// out; failures broadcast `changeset_commit_err {detail}`.
    async fn do_changeset_commit(&self, request: &ChangesetCommitPayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_commit_err(&self.control_tx, project_dir, "not an open project");
            return;
        }
        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_commit_err(&self.control_tx, project_dir, "not a git repository");
            return;
        }

        // The callsign comes from the ledger, never from the payload — the
        // deck may still be holding the optimistic tag it minted at spawn.
        // The row's callsign and `line_id` are the line's ([P02]), so a commit
        // made inside an arc stage cites the line of work rather than the
        // segment; `Tug-Session-Id` beside it still pins the exact transcript.
        let identity = request
            .session_id
            .as_deref()
            .filter(|s| !s.is_empty())
            .and_then(|id| self.session_ledger.as_ref().map(|l| (l, id)))
            .and_then(|(ledger, id)| match ledger.get(id) {
                Ok(row) => row.map(|r| (r.tag, r.line_id)),
                Err(err) => {
                    warn!(error = %err, session_id = id, "ledger read for commit trailer failed");
                    None
                }
            });
        let tag = identity.as_ref().and_then(|(tag, _)| tag.as_deref());
        let line_id = identity
            .as_ref()
            .map(|(_, line_id)| line_id.as_str())
            .filter(|s| !s.is_empty());
        let message = changeset_commit_message(request, tag, line_id);
        match crate::feeds::changeset::run_changeset_commit(
            dir,
            &request.files,
            &message,
            request.hunks.clone(),
        )
        .await
        {
            Ok(receipt) => {
                self.registry.changeset_all_bump().notify_one();
                let summary = crate::feeds::changeset::format_commit_summary(
                    &receipt.sha,
                    &message,
                    &receipt.files,
                );
                // Persist the landing to the shell ledger so the transcript's
                // commit row survives Maker ▸ Reload and cold boot (restored via
                // `list_shell_exchanges`, [P07]). Only when the deck passed a
                // `session_id` to key the row; a ledger error warns but never
                // fails the commit (R02). No live SHELL frame is emitted — the
                // initiating client paints the live row from `summary` on the
                // `_ok`; other decks converge on their next restore.
                let receipt_id = Self::record_landing_receipt(
                    self.shell_ledger.as_ref(),
                    self.session_ledger.as_ref(),
                    request.session_id.as_deref(),
                    "/commit",
                    &summary,
                    project_dir,
                );
                // The commit as a fact ([P08]). This is the one durable moment
                // that knows the sha, the message, and the file list together
                // without re-running git — today the receipt is built here and
                // thrown away after the broadcast.
                if let Some(sessions) = self.session_ledger.as_ref() {
                    let files: Vec<String> = receipt.files.iter().map(|f| f.path.clone()).collect();
                    let fact = crate::feeds::facts_library::commit_fact(
                        crate::session_ledger::now_millis(),
                        request.session_id.as_deref().filter(|s| !s.is_empty()),
                        &receipt.sha,
                        &message,
                        &files,
                        Some(&receipt.numstat),
                    );
                    if let Err(e) = sessions.record_fact(&fact) {
                        warn!(error = %e, "commit fact write failed");
                    }
                }
                // The landing, to the tripwire engine ([P01], Spec S01). A
                // channel send and nothing more: the branch is the only thing
                // read here that the commit did not already hand back, and
                // the dossier every wire eventually reads is assembled on the
                // engine's own task (Risk R01).
                crate::feeds::tripwire::landed(crate::feeds::tripwire::LandingEvent {
                    repo_root: project_dir.to_string(),
                    branch: tugarc_core::ops::current_branch(dir).unwrap_or_default(),
                    sha: receipt.sha.clone(),
                    kind: crate::feeds::tripwire::LandingKind::Commit,
                    arc: None,
                    session_ids: request
                        .session_id
                        .iter()
                        .filter(|s| !s.is_empty())
                        .cloned()
                        .collect(),
                });
                let body = serde_json::json!({
                    "action": "changeset_commit_ok",
                    "project_dir": project_dir,
                    "sha": receipt.sha,
                    "receipt": receipt.numstat,
                    "summary": summary,
                    "receipt_id": receipt_id,
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("changeset_commit_ok serializes"),
                ));
            }
            Err(detail) => {
                Self::send_changeset_commit_err(&self.control_tx, project_dir, &detail);
            }
        }
    }

    fn send_changeset_commit_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_commit_err",
            "project_dir": project_dir,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_commit_err serializes"),
        ));
    }

    /// Handle a `changeset_claim` CONTROL request: a session claims the listed
    /// files outright, promoting them from "likely" hints (a `perl`/`sed` edit
    /// or a hand save that only left a bracket correlation) into its changeset.
    /// Writes one proof-grade `claim` file event per path, then fires the
    /// process-global aggregate bump so the rows move into the session's entry
    /// on the next recompute. `changeset_claim_ok {claimed}` goes out on
    /// success; `changeset_claim_err {detail}` on a failed guard.
    ///
    /// Guards mirror the other changeset verbs: `project_dir` must be a current
    /// `WorkspaceRegistry` entry. Idempotent — re-claiming writes another proof
    /// row, which composes identically.
    async fn do_changeset_claim(&self, request: &ChangesetClaimPayload) -> serde_json::Value {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            return Self::send_changeset_claim_err(
                &self.control_tx,
                project_dir,
                "not an open project",
            );
        }
        let Some(ledger) = self.session_ledger.as_ref() else {
            return Self::send_changeset_claim_err(&self.control_tx, project_dir, "no ledger");
        };

        let canonical = crate::path_resolver::CanonicalPath::from_raw(dir);
        // The card claims files by their repo-relative key, which passes
        // straight through; the root is what an absolute spelling is measured
        // against, so a claim can no more name a file outside the repo than a
        // captured tool call can.
        let repo_root = crate::feeds::attribution::repo_root_for(dir).await;
        let at = crate::session_ledger::now_millis();
        // A claim is a user gesture in this session — proof of activity.
        // Revive a row the startup demote closed, or the fresh claim rows
        // land under a "dead" owner and the next recompose lifts every one
        // of them straight back into `orphaned` — the treadmill this verb
        // exists to end.
        if let Err(err) = ledger.revive_on_activity(&request.session_id, at) {
            warn!(
                error = %err,
                session_id = %request.session_id,
                "changeset_claim revive_on_activity failed"
            );
        }
        // The claimant is a **line** of work ([P01]), not the one segment id
        // the request arrived under: the fresh rows are written under the
        // line's seat segment (the id everything else answers for the line
        // with), and the sever below keeps every id the line has ever worn,
        // so a claim never severs the claimant's own older rows. A session
        // this ledger has never lined stays keyed by its raw id.
        let line = ledger
            .line_of(&request.session_id)
            .and_then(|line_id| ledger.line_ownership(&line_id).ok().flatten());
        let write_id = line
            .as_ref()
            .map(|l| l.seat_id.clone())
            .unwrap_or_else(|| request.session_id.clone());
        let mut keep_ids: Vec<String> = vec![write_id.clone()];
        if let Some(l) = &line {
            keep_ids.extend(l.segment_ids.iter().filter(|id| **id != l.seat_id).cloned());
        }
        if !keep_ids.contains(&request.session_id) {
            keep_ids.push(request.session_id.clone());
        }
        // One synthetic tool_use_id groups the batch, mirroring how a Bash
        // call's N rows share an id.
        let tool_use_id = format!("claim:{at}");
        let mut rows = Vec::with_capacity(request.files.len());
        for path in &request.files {
            let Some(file_path) = crate::feeds::attribution::repo_relative_key(
                repo_root.as_deref(),
                std::path::Path::new(path),
            ) else {
                warn!(
                    project_dir,
                    path, "changeset_claim path outside the repo; skipped"
                );
                continue;
            };
            rows.push(crate::session_ledger::FileEventRow {
                tug_session_id: write_id.clone(),
                tool_use_id: tool_use_id.clone(),
                file_path,
                tool_name: "Claim".to_string(),
                op: "claimed".to_string(),
                origin: "claim".to_string(),
                ambiguous: false,
                parent_tool_use_id: None,
                project_dir: canonical.as_str().to_string(),
                at,
            });
        }
        // A claim is a whole-file assertion by hand — the user is saying the
        // file is theirs, not which regions of it are — so every claimed row
        // carries a `whole` span, which widens its owner to the whole file at
        // read time ([P12]).
        let spans: Vec<Vec<crate::session_ledger::FileEventSpan>> = rows
            .iter()
            .map(|_| vec![crate::feeds::attribution::whole_span()])
            .collect();
        // The whole gesture is one journaled, transactional batch: `claimed`
        // is the mapped row count or zero, never a partial tally the deck
        // has to interpret.
        let claimed = match ledger.record_file_events_with_spans(&rows, &spans) {
            Ok(()) => rows.len(),
            Err(err) => {
                warn!(error = %err, project_dir, "changeset_claim batch failed");
                0
            }
        };

        // Sever any prior owner ([D120]): a claim asserts sole ownership, so
        // remove other sessions' rows for these paths — a dead originator can't
        // silently re-own the file on re-open, and it leaves the orphaned
        // bucket. The kept set is the claimant's whole line — its fresh rows
        // AND everything written under ids it has since rotated away from.
        // A batch that did not land claims nothing, so it severs nothing.
        if claimed > 0 {
            if let Err(err) =
                ledger.sever_file_ownership_except(canonical.as_str(), &request.files, &keep_ids)
            {
                warn!(error = %err, project_dir, "changeset_claim sever failed");
            }
        }

        self.registry.changeset_all_bump().notify_one();
        // Honesty check: a claim whose claimant this instance's ledger has
        // never seen (a cross-instance or mistyped `--session`) will read as
        // a dead owner on the very next recompose and its files re-orphan.
        // The rows are still written — `changes.db` is machine-global and
        // another instance may hold the session — but the reply must say so
        // rather than hand back a green count that undoes itself ([D120]).
        // The judgment is the line's: any segment live, or any segment
        // seated on an open card, and the claim will hold on the next
        // recompose — even when the id the request arrived under is itself
        // a demoted older segment.
        let claimant = ledger.get(&request.session_id).ok().flatten();
        let claimant_live = line.as_ref().map(|l| l.any_live).unwrap_or(false)
            || claimant
                .as_ref()
                .is_some_and(|r| r.state == crate::session_ledger::SessionState::Live);
        let seated = super::deck_seatings::seated_session_ids();
        let claimant_seated = keep_ids.iter().any(|id| seated.contains(id));
        let warning = if claimed == 0 {
            None
        } else if claimant.is_none() && line.is_none() && !claimant_seated {
            Some(format!(
                "session {} is unknown to this instance's ledger; \
                 the claimed files may surface as orphaned here",
                request.session_id
            ))
        } else if !claimant_live && !claimant_seated {
            Some(format!(
                "session {} is closed and seated on no card; \
                 the claimed files will surface as orphaned until it reopens",
                request.session_id
            ))
        } else {
            None
        };
        let body = serde_json::json!({
            "action": "changeset_claim_ok",
            "project_dir": project_dir,
            "claimed": claimed,
            "warning": warning,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_claim_ok serializes"),
        ));
        body
    }

    /// Broadcast a claim error on CONTROL and return the body, so the
    /// `/api/tell` bridge can hand the same reply to an HTTP caller.
    fn send_changeset_claim_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        detail: &str,
    ) -> serde_json::Value {
        let body = serde_json::json!({
            "action": "changeset_claim_err",
            "project_dir": project_dir,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_claim_err serializes"),
        ));
        body
    }

    /// Handle a `changeset_disclaim` CONTROL request: a session renounces the
    /// listed files, the inverse of a claim. Every row the session holds for
    /// those paths — proof and bracket alike — is deleted in one journaled
    /// record, then the aggregate bump fires so the file re-buckets on the next
    /// recompute: to the other live owner if there is one (which also clears
    /// the SHARED marking), otherwise to unattributed.
    ///
    /// Guards mirror claim: `project_dir` must be a current `WorkspaceRegistry`
    /// entry, a ledger must be present, and each path maps through
    /// `repo_relative_key` with skip-and-warn. Idempotent — disclaiming a file
    /// the session no longer holds deletes nothing and still replies ok.
    async fn do_changeset_disclaim(&self, request: &ChangesetDisclaimPayload) -> serde_json::Value {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            return Self::send_changeset_disclaim_err(
                &self.control_tx,
                project_dir,
                "not an open project",
            );
        }
        let Some(ledger) = self.session_ledger.as_ref() else {
            return Self::send_changeset_disclaim_err(&self.control_tx, project_dir, "no ledger");
        };

        let canonical = crate::path_resolver::CanonicalPath::from_raw(dir);
        let repo_root = crate::feeds::attribution::repo_root_for(dir).await;
        // A disclaim is a user gesture in this session, same as a claim —
        // revive a demoted row so the session's remaining files keep a live
        // owner on the recompose this gesture triggers.
        if let Err(err) =
            ledger.revive_on_activity(&request.session_id, crate::session_ledger::now_millis())
        {
            warn!(
                error = %err,
                session_id = %request.session_id,
                "changeset_disclaim revive_on_activity failed"
            );
        }
        let mut paths = Vec::with_capacity(request.files.len());
        for path in &request.files {
            let Some(file_path) = crate::feeds::attribution::repo_relative_key(
                repo_root.as_deref(),
                std::path::Path::new(path),
            ) else {
                warn!(
                    project_dir,
                    path, "changeset_disclaim path outside the repo; skipped"
                );
                continue;
            };
            paths.push(file_path);
        }

        // The renouncing owner is a line ([P01]): expand the incoming id to
        // every segment the line has worn, so a disclaim empties the whole
        // line's hold on the paths — not just the slice written under the
        // current id, which would leave an older segment silently re-owning
        // the file on the next recompose.
        let mut renouncing_ids: Vec<String> = vec![request.session_id.clone()];
        if let Some(l) = ledger
            .line_of(&request.session_id)
            .and_then(|line_id| ledger.line_ownership(&line_id).ok().flatten())
        {
            renouncing_ids.extend(
                l.segment_ids
                    .into_iter()
                    .filter(|id| *id != request.session_id),
            );
        }
        let disclaimed =
            match ledger.disclaim_file_ownership(canonical.as_str(), &paths, &renouncing_ids) {
                Ok(deleted) => deleted,
                Err(err) => {
                    warn!(error = %err, project_dir, "changeset_disclaim failed");
                    return Self::send_changeset_disclaim_err(
                        &self.control_tx,
                        project_dir,
                        &err.to_string(),
                    );
                }
            };

        self.registry.changeset_all_bump().notify_one();
        let body = serde_json::json!({
            "action": "changeset_disclaim_ok",
            "project_dir": project_dir,
            "disclaimed": disclaimed,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_disclaim_ok serializes"),
        ));
        body
    }

    /// Broadcast a disclaim error on CONTROL and return the body, so the
    /// `/api/tell` bridge can hand the same reply to an HTTP caller.
    fn send_changeset_disclaim_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        detail: &str,
    ) -> serde_json::Value {
        let body = serde_json::json!({
            "action": "changeset_disclaim_err",
            "project_dir": project_dir,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_disclaim_err serializes"),
        ));
        body
    }

    /// Handle a `changeset_join` CONTROL request (Spec S03, [P14]): preview or
    /// execute an arc join via `tugarc-core`.
    ///
    /// Guards match the other changeset verbs: `project_dir` must be a current
    /// `WorkspaceRegistry` entry (never touch an arbitrary path off the wire)
    /// and must be a git working tree. The join itself runs on a blocking
    /// thread (synchronous git subprocesses). A `--preview` mutates nothing and
    /// reports conflicts in memory; a real join that lands a commit fires the
    /// process-global aggregate bump so the arc entry drops from the card on
    /// the next recompute. Broadcasts `changeset_join_ok {…JoinOutcome}` /
    /// `changeset_join_err {detail}`.
    ///
    /// Returns whether a commit actually landed, which is a different fact
    /// from "the request was answered": a preview and a conflict-aborted join
    /// both report `ok` and land nothing. The prompt-answer path reads it to
    /// decide whether the ask it consumed should stay consumed ([P07]).
    async fn do_changeset_join(&self, request: &ChangesetJoinPayload) -> bool {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_join_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not an open project",
            );
            return false;
        }
        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_join_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not a git repository",
            );
            return false;
        }

        // The first word of the run, spoken the moment the handler accepts the
        // press (Spec S01). Everything between here and `join_in`'s own
        // `squash` beat — two synchronous git reads, occupancy, and the whole
        // of the join's preflight inside `spawn_blocking` — took real seconds
        // and narrated none of them. A preview narrates nothing at all, which
        // is the contract `join_in_with_progress` already keeps.
        if !request.preview {
            Self::send_changeset_join_land_delta(
                &self.control_tx,
                project_dir,
                &request.arc,
                "preflight",
                "start",
            );
        }

        // Resolve the arc's identity BEFORE the join runs. `join_in` ends in
        // `git branch -D`, which deletes `branch.tugarc/<name>.tugid` along
        // with the branch — a key read afterwards is the legacy one and names
        // none of the id-keyed rows this landing has to sweep ([L23], [P05],
        // Risk R02).
        let owner_key = tugarc_core::ops::arc_owner_key(dir, &request.arc);
        // The round count belongs to the receipt, and a landed join deletes the
        // branch it is counted from — so it is read here, for the same reason
        // the owner key is.
        let rounds = tugarc_core::arc_detail_entries_in(dir)
            .into_iter()
            .find(|d| d.name == request.arc)
            .map(|d| d.rounds)
            .unwrap_or(0);

        // A join tears the workshop down and deletes the branch under it, so it
        // cannot share the arc with a resolve or a verification (Spec S01). A
        // **preview** touches nothing and never takes the arc — it is the one
        // join shape that is safe to ask for mid-run, and the face asks for it
        // constantly.
        let _occupancy = if request.preview {
            None
        } else {
            match crate::feeds::join_occupancy::acquire(
                &owner_key,
                crate::feeds::join_occupancy::JoinRunKind::Join,
                None,
            ) {
                Ok(guard) => Some(guard),
                Err(detail) => {
                    Self::send_changeset_join_err(
                        &self.control_tx,
                        project_dir,
                        &request.arc,
                        &detail,
                    );
                    return false;
                }
            }
        };

        let dir_owned = dir.to_path_buf();
        let arc = request.arc.clone();
        let opts = tugarc_core::JoinOptions {
            strategy: request.strategy,
            message: request.message.clone(),
            preview: request.preview,
            continue_join: request.continue_join,
            candidate: request.candidate.clone(),
            origin: Some("card".to_string()),
            // Who landed it. tugcast is nobody's session, so the pressing
            // card's id is the only way the squash commit can name the session
            // beside the arc — the two pills a joined commit's History row
            // shows ([P10], Spec S03).
            session_id: request.session_id.clone(),
            // The card has no gesture for breaking a lease, and tugcast's own
            // guard is exact: a card join that reaches the lease refusal is by
            // definition a resolve in another process ([P04], [P05]).
            break_lease: false,
        };
        // The join's own narration ([P03]). It takes real seconds and used to
        // say nothing for all of them — the press landed and the next word was
        // the durable commit message, however long later. These frames are a
        // **liveness hint only**: the `changeset_all_bump()` below stays the
        // carrier of truth, exactly as it already is on the resolve path, so a
        // dropped beat costs the progress line and nothing else.
        let beat_tx = self.control_tx.clone();
        let beat_project_dir = project_dir.to_string();
        let beat_arc = request.arc.clone();
        let result = tokio::task::spawn_blocking(move || {
            tugarc_core::join_in_with_progress(&dir_owned, &arc, opts, |beat, status| {
                Self::send_changeset_join_land_delta(
                    &beat_tx,
                    &beat_project_dir,
                    &beat_arc,
                    beat,
                    status,
                );
            })
        })
        .await;

        match result {
            Ok(Ok(outcome)) => {
                // One line per landing, so a join is attributable afterwards
                // without archaeology. The two joins of 2026-08-15 left no
                // trace in any log, which is why the next incident report was
                // an investigation rather than a read.
                tracing::info!(
                    arc = %outcome.name,
                    base = %outcome.base_branch,
                    previewed = outcome.previewed,
                    commit = outcome.commit_hash.as_deref().unwrap_or("-"),
                    conflicts = outcome.conflicts.len(),
                    blockers = %outcome
                        .blockers
                        .iter()
                        .map(|b| b.kind.as_str())
                        .collect::<Vec<_>>()
                        .join(","),
                    "arc-join: completed"
                );
                // A real join that landed a commit shrinks the changeset set —
                // refresh the card. A preview (or a conflict-aborted join)
                // mutated nothing, so no bump. The landed arc's join draft
                // dies with it ([P14]).
                let landed = !outcome.previewed && outcome.commit_hash.is_some();
                if landed {
                    if let Some(ledger) = self.session_ledger.as_deref() {
                        // Read the lineage BEFORE the bindings are released:
                        // the sessions bound to this arc are the whole of
                        // what a join landing knows about who did the work
                        // (Spec S01), and the very next statement clears them.
                        let lineage = ledger
                            .bound_sessions_by_arc()
                            .ok()
                            .and_then(|by_arc| by_arc.get(&owner_key).cloned())
                            .unwrap_or_default();
                        crate::feeds::tripwire::landed(crate::feeds::tripwire::LandingEvent {
                            repo_root: project_dir.to_string(),
                            branch: outcome.base_branch.clone(),
                            sha: outcome.commit_hash.clone().unwrap_or_default(),
                            kind: crate::feeds::tripwire::LandingKind::Join,
                            arc: Some(outcome.name.clone()),
                            session_ids: lineage,
                        });
                        Self::clear_arc_draft(ledger, project_dir, &owner_key);
                        // The arc the sessions were mated to no longer
                        // exists ([P05]) — release every binding to it.
                        let _ = ledger.clear_arc_bindings_for_arc(&owner_key);
                    }
                    self.registry.changeset_all_bump().notify_one();
                }
                // The landing's receipt (Spec S01) — server-formatted, so the
                // durable row and the live one are the same bytes.
                let mut receipt_id: Option<i64> = None;
                let summary = match (&outcome.commit_hash, outcome.previewed) {
                    (Some(sha), false) => {
                        // The file list is the landing commit against its first
                        // parent, which is only the whole join under `squash`.
                        // A merge landing sha is a merge commit (git suppresses
                        // its diff) and a rebase landing sha is the tip of a
                        // replayed chain — one round. Either would put a list
                        // on the receipt that reads as complete while being
                        // partial, so those strategies carry no list at all.
                        let files = if outcome.strategy == "squash" {
                            crate::feeds::changeset::landing_file_stats(
                                std::path::Path::new(project_dir),
                                sha,
                            )
                            .await
                        } else {
                            Vec::new()
                        };
                        let summary = crate::feeds::changeset::format_join_summary(
                            sha,
                            &outcome.name,
                            &outcome.base_branch,
                            rounds,
                            outcome.message.as_deref().unwrap_or(""),
                            &files,
                            outcome.fit.as_ref(),
                        );
                        receipt_id = Self::record_landing_receipt(
                            self.shell_ledger.as_ref(),
                            self.session_ledger.as_ref(),
                            request.session_id.as_deref(),
                            "/arc-join",
                            &summary,
                            project_dir,
                        );
                        Some(summary)
                    }
                    _ => None,
                };
                let mut body = serde_json::json!({
                    "action": "changeset_join_ok",
                    "project_dir": project_dir,
                    "arc": request.arc,
                    "name": outcome.name,
                    "base_branch": outcome.base_branch,
                    "strategy": outcome.strategy,
                    "commit_hash": outcome.commit_hash,
                    "conflicts": outcome.conflicts,
                    "previewed": outcome.previewed,
                    "summary": summary,
                    // The ledger row the summary was persisted as ([P06]) —
                    // the identity the initiating deck paints its live receipt
                    // under, so a later restore settles that row instead of
                    // seating a second copy of the same landing.
                    "receipt_id": receipt_id,
                    "warnings": outcome.warnings,
                });
                // Additive, exactly as `JoinOutcome` serializes it: the key is
                // absent rather than `[]` when nothing blocks (Spec S03).
                if !outcome.blockers.is_empty()
                    && let Ok(blockers) = serde_json::to_value(&outcome.blockers)
                {
                    body["blockers"] = blockers;
                }
                // Same additive shape: the base-side history behind each
                // conflicted path, present only on a conflicted preview.
                if !outcome.archaeology.is_empty()
                    && let Ok(archaeology) = serde_json::to_value(&outcome.archaeology)
                {
                    body["archaeology"] = archaeology;
                }
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("changeset_join_ok serializes"),
                ));
                landed
            }
            Ok(Err(detail)) => {
                tracing::info!(arc = %request.arc, detail = %detail, "arc-join: refused");
                Self::send_changeset_join_err(&self.control_tx, project_dir, &request.arc, &detail);
                false
            }
            Err(join_err) => {
                Self::send_changeset_join_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &format!("join task failed: {join_err}"),
                );
                false
            }
        }
    }

    /// Persist a landing receipt to the shell ledger ([P06]), the same way the
    /// commit landing does: the row is what makes the transcript's receipt
    /// survive Maker ▸ Reload and cold boot. A missing `session_id` or a
    /// missing ledger skips it — the receipt records the verb, it never gates
    /// it — and a ledger error warns rather than failing the landing.
    ///
    /// Returns the ledger row's `id` when one was written. It rides the `_ok`
    /// frame back to the initiating deck, which paints its live copy of the
    /// receipt under that identity — so the live row and the row a later
    /// restore replays are the same transcript turn, not two copies of one
    /// landing. `None` means nothing was persisted and the deck falls back to
    /// a local identity.
    /// `sessions` is what keys the row to the *line of work* rather than to a
    /// session id that a later rewind-fork will supersede. The deck stays bound
    /// to a forked session's parent until the next relaunch, so without this
    /// resolution a landing recorded in that window lands under an id nothing
    /// will ever ask about again.
    fn record_landing_receipt(
        ledger: Option<&Arc<crate::shell_ledger::ShellLedger>>,
        sessions: Option<&Arc<crate::session_ledger::SessionLedger>>,
        session_id: Option<&str>,
        command: &str,
        summary: &str,
        cwd: &str,
    ) -> Option<i64> {
        let (Some(session_id), Some(ledger)) = (session_id.filter(|s| !s.is_empty()), ledger)
        else {
            return None;
        };
        // The receipt is the **line's** ([P09]); a line-less session keys
        // under its own id.
        let line_id = sessions
            .and_then(|sessions| sessions.line_of(session_id))
            .unwrap_or_else(|| session_id.to_string());
        let session_id = session_id.to_string();
        // The anchor is the turn this receipt follows in the transcript the
        // deck will replay. `session_id` here is the card's own id — the
        // line's *first* segment once the Wheel has rotated it — and the
        // ledger resolves it to the line's live head before reading a file,
        // so a join landed after three rotations seats after the audit's last
        // word and not after the door's. `cwd` is the landing's project dir,
        // which locates that file.
        let anchor_msg_id =
            sessions.and_then(|s| s.latest_assistant_msg_id(&session_id, Some(cwd)));
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        match ledger.record_exchange(&crate::shell_ledger::NewShellExchange {
            tug_session_id: session_id.clone(),
            line_id,
            command: command.to_string(),
            output: summary.to_string(),
            exit_code: Some(0),
            cwd: cwd.to_string(),
            cwd_after: None,
            started_at_ms: now,
            settled_at_ms: now,
            anchor_msg_id,
        }) {
            Ok(id) => Some(id),
            Err(e) => {
                warn!(error = %e, command, "failed to persist a landing to the shell ledger");
                None
            }
        }
    }

    /// Record `model → <selector> in <stage>` when the card is running a live
    /// arc's stage.
    ///
    /// A no-op for every other card: the note is about an arc, and a user
    /// changing models on their own card is not one.
    pub(crate) async fn note_model_switch(&self, session: &str, selector: &str) {
        let Some(ledger) = self.session_ledger.clone() else {
            return;
        };
        let session = session.to_string();
        let selector = selector.to_string();
        let _ = tokio::task::spawn_blocking(move || {
            let Ok(Some(row)) = ledger.get(&session) else {
                return;
            };
            let Some(arc) = row.arc_name.as_deref() else {
                return;
            };
            if ledger.stage_provenance(&session).is_none() {
                return;
            }
            let project = std::path::Path::new(&row.project_dir);
            let Some(record) = tugarc_core::arc::read_arc(project, arc) else {
                return;
            };
            if record.done || record.stopped.is_some() {
                return;
            }
            let Some(stage) = record.current_stage() else {
                return;
            };
            if let Err(e) = tugarc_core::arc::append_arc_note(
                project,
                arc,
                &format!("model → {selector} in {}", stage.as_str()),
            ) {
                warn!(arc = %arc, error = %e, "could not record a mid-stage model switch");
            }
        })
        .await;
    }

    /// The model a card returns to when an arc gives it back — the deck's own
    /// selector, which only a WebSocket client's `model_change` ever writes.
    ///
    /// `None` when the card never chose one, which a caller words as the
    /// account default rather than showing a blank.
    pub async fn deck_model_for(&self, session: &str) -> Option<String> {
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(&TugSessionId::new(session.to_string())).cloned()
        }?;
        let entry = entry_arc.lock().await;
        entry.deck_model.clone()
    }

    /// Persist and announce the arc's terminal receipt ([P12]).
    ///
    /// The arc has no initiating client — nobody asked for this and no `_ok`
    /// frame is owed to anybody — so the two halves a landing gets for free
    /// are done explicitly here: the durable row through the same gateway
    /// every landing uses (so a relaunch replays it like any other ink), and
    /// an unsolicited `arc_receipt` CONTROL frame so the card the arc ran on
    /// paints its live copy now rather than at the next restore. Both carry
    /// the ledger row's id, which is what keeps the live row and the replayed
    /// one one transcript turn rather than two receipts for one arc.
    pub fn record_arc_receipt(&self, session: &str, arc: &str, project_dir: &str, summary: &str) {
        let receipt_id = Self::record_landing_receipt(
            self.shell_ledger.as_ref(),
            self.session_ledger.as_ref(),
            Some(session),
            "/arc-run",
            summary,
            project_dir,
        );
        let body = serde_json::json!({
            "action": "arc_receipt",
            "project_dir": project_dir,
            "arc": arc,
            // The card's own session id, deliberately *not* lineage-resolved:
            // the deck is still bound to the id it was given, and this frame
            // has to find that card. The durable row keyed itself to the head.
            "tug_session_id": session,
            "receipt_id": receipt_id,
            "summary": summary,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("arc_receipt serializes"),
        ));
    }

    /// The card's own session id and supervisor entry for a **segment** id,
    /// walked the way [P01]'s identity model requires.
    ///
    /// The map is keyed by the card's own tug session id, which never moves; a
    /// rotation mints a segment and the ledger's answers are in *that*
    /// vocabulary. The direct key first — before any rotation the two are one
    /// string — then `claude_session_id`, which is the entry's own record of
    /// which segment it is currently running. The same walk
    /// `arc_runner::card_session_for_segment` makes, for the same reason.
    ///
    /// `try_lock` on the entries: this holds the map lock, so an entry another
    /// task is mid-write on is skipped rather than inverted on.
    pub async fn card_entry_for_segment(
        &self,
        segment: &str,
    ) -> Option<(TugSessionId, Arc<Mutex<LedgerEntry>>)> {
        let map = self.ledger.lock().await;
        let direct = TugSessionId::new(segment.to_string());
        if let Some(entry) = map.get(&direct) {
            return Some((direct, Arc::clone(entry)));
        }
        for (key, entry) in map.iter() {
            let Ok(guard) = entry.try_lock() else {
                continue;
            };
            if guard.claude_session_id.as_deref() == Some(segment) {
                drop(guard);
                return Some((key.clone(), Arc::clone(entry)));
            }
        }
        None
    }

    /// Record that the turn now in flight on `segment`'s card has closed a
    /// step. Answers whether an entry was found to record it against.
    pub async fn mark_step_closed_this_turn(&self, segment: &str, step: u32) -> bool {
        let Some((_, entry)) = self.card_entry_for_segment(segment).await else {
            return false;
        };
        entry.lock().await.step_closed_this_turn = Some(step);
        true
    }

    /// The step this turn has already closed on `segment`'s card, if any — the
    /// PreToolUse gate's one question.
    pub async fn step_closed_this_turn(&self, segment: &str) -> Option<u32> {
        let (_, entry) = self.card_entry_for_segment(segment).await?;
        entry.lock().await.step_closed_this_turn
    }

    /// Announce one arc ledger gesture on `session`'s card as durable ink.
    ///
    /// The same two halves `record_arc_receipt` does, for the same reason: a
    /// gesture made by a short-lived CLI process has no initiating client, so
    /// the durable row (which a relaunch replays like any other ink, keyed to
    /// the **line** so a rotation carries it) and the live `arc_note` frame
    /// are both explicit. `command` is the verb as it was typed and `note` the
    /// one sentence, which is what makes the row read as the `$` ink of
    /// somebody having run it — because that is what happened.
    ///
    /// The user watches a run from the card, and before this the only sign of
    /// progression was a stuck indicator (W8 Task 3).
    ///
    /// `segment` is what the verb resolved and what the ledger answers in; the
    /// frame goes out under the **card's** id, because the card's address never
    /// moves and the deck is bound to it. A rotation would otherwise announce
    /// to an id no card in the deck wears — Part IX item 12's shape, one layer
    /// over.
    pub async fn record_arc_note(
        &self,
        segment: &str,
        project_dir: &str,
        command: &str,
        note: &str,
    ) {
        let session = match self.card_entry_for_segment(segment).await {
            Some((card, _)) => card.as_str().to_string(),
            None => segment.to_string(),
        };
        let receipt_id = Self::record_landing_receipt(
            self.shell_ledger.as_ref(),
            self.session_ledger.as_ref(),
            Some(&session),
            command,
            note,
            project_dir,
        );
        let body = serde_json::json!({
            "action": "arc_note",
            "project_dir": project_dir,
            "tug_session_id": session,
            "command": command,
            "note": note,
            "receipt_id": receipt_id,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("arc_note serializes"),
        ));
    }

    fn send_changeset_join_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_join_err",
            "project_dir": project_dir,
            "arc": arc,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_err serializes"),
        ));
    }

    /// Broadcast one join progress beat. A liveness hint only: the
    /// `changeset_all_bump()` a landing ends with stays the carrier of truth,
    /// so a dropped beat costs the progress line and nothing else. The
    /// `project_dir` is echoed verbatim as the request sent it, which is what
    /// keeps the frame correlated to the cell the press opened with no
    /// spelling to reconcile ([L29]).
    fn send_changeset_join_land_delta(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        beat: &str,
        status: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_join_land_delta",
            "project_dir": project_dir,
            "arc": arc,
            "beat": beat,
            "status": status,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_land_delta serializes"),
        ));
    }

    /// Handle a `changeset_join_resolve` CONTROL request (Spec S12, [P31]/[P32]):
    /// run the tugarc-core resolution ladder with the scribe AI rung injected,
    /// streaming per-file progress. The ladder builds a candidate commit off to
    /// the side; the card reviews it and lands it via a follow-up
    /// `changeset_join {candidate}`. Broadcasts the terminal
    /// `changeset_join_resolve_ok {…ResolveOutcome}` /
    /// `changeset_join_resolve_err {detail}`.
    async fn do_changeset_join_resolve(&self, request: &ChangesetJoinResolvePayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_join_resolve_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not an open project",
            );
            return;
        }
        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_join_resolve_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not a git repository",
            );
            return;
        }

        // Take the arc before anything git-shaped happens (Spec S01). A second
        // Resolve press — the shape the false error face used to invite — would
        // otherwise start a second `finish_join` doing `reset --hard` on the
        // workshop the first one's resolver is editing.
        let owner_key = tugarc_core::ops::arc_owner_key(dir, &request.arc);
        // Snapshotted here so a question this run raises stays matched to the
        // head it was raised against, even if a round lands on the arc while
        // the resolver waits for the answer.
        let arc_head = tugarc_core::ops::arc_detail_entry_in(dir, &request.arc)
            .and_then(|detail| tugarc_core::ops::rev_parse(dir, &detail.branch).ok());
        let occupancy = match crate::feeds::join_occupancy::acquire(
            &owner_key,
            crate::feeds::join_occupancy::JoinRunKind::Resolve,
            arc_head,
        ) {
            Ok(guard) => guard,
            Err(detail) => {
                Self::send_changeset_join_admission_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &detail,
                );
                return;
            }
        };

        self.run_resolve_ladder(project_dir, &request.arc, occupancy)
            .await;
    }

    /// The resolution ladder itself, from the scribe rung through the
    /// resolver's audit, ending at an anchored candidate.
    ///
    /// Shared by the `changeset_join_resolve` CONTROL handler and the join
    /// pilot ([P01]), so a reconcile the machine started and one the user
    /// started are literally the same run — the same scribe rung, the same
    /// audit, the same verdict. A second implementation for the pilot would be
    /// two ladders drifting apart, which is exactly what the arc cannot afford:
    /// the whole promise is that what the machine did unprompted is what the
    /// user would have got by pressing.
    ///
    /// **Admission belongs to the caller.** By the time control arrives here
    /// the project has been validated and the arc has been taken through
    /// `join_occupancy`; the guard is handed in and the hold travels with the
    /// work from this point, releasing on every exit including a panic.
    async fn run_resolve_ladder(
        &self,
        project_dir: &str,
        arc_name: &str,
        occupancy: crate::feeds::join_occupancy::JoinOccupancy,
    ) {
        let dir = std::path::Path::new(project_dir);

        // Build the AI rung from the scribe context when one is configured;
        // without it the ladder runs its algorithmic rungs only.
        let merger =
            self.scribe
                .as_ref()
                .map(|scribe| crate::feeds::join_resolve::ScribeFileMerger {
                    spawner: scribe.spawner.clone(),
                    model: scribe.model.clone(),
                    handle: tokio::runtime::Handle::current(),
                    control_tx: self.control_tx.clone(),
                    project_dir: project_dir.to_string(),
                    arc: arc_name.to_string(),
                });

        // The `run` fact is what makes a reload mid-resolve land on a face that
        // still says the resolve is running, so it goes out before the work.
        self.registry.changeset_all_bump().notify_one();

        let dir_owned = dir.to_path_buf();
        let arc = arc_name.to_string();
        let result = tokio::task::spawn_blocking(move || {
            // Last attempt's refusal stops applying the moment this one starts;
            // leaving it standing would render a running resolve under the
            // sentence that ended the one before it.
            tugarc_core::resolve::clear_stuck(&dir_owned, &arc);
            let merger_ref = merger.as_ref().map(|m| m as &dyn tugarc_core::FileMerger);
            tugarc_core::resolve_conflicts(&dir_owned, &arc, merger_ref)
        })
        .await;

        // The ladder's git effects — the candidate ref and its marks — are
        // written by now on every arm, win or lose. Firing the recompute here
        // rather than only on success is what makes the CONTROL reply below a
        // liveness hint instead of the only carrier of the result: CONTROL is
        // droppable by design, and a dropped `_ok` used to lose a real
        // candidate forever. Now it costs the spinner and nothing else.
        self.registry.changeset_all_bump().notify_one();

        match result {
            Ok(Ok(outcome)) => {
                tracing::info!(
                    arc = %arc_name,
                    shape = ?outcome.shape,
                    resolved = outcome.resolved.len(),
                    unresolved = outcome.unresolved.len(),
                    candidate = outcome.candidate_commit.as_deref().unwrap_or("-"),
                    "arc-join: ladder ran"
                );

                // The resolver finishes what the ladder left **and audits what
                // it decided** ([P10]) — so it runs whenever the machine
                // decided anything, including on a ladder that resolved
                // everything. A machine resolution nobody read is the failure
                // class the retired review gate existed for; skipping the audit
                // when the ladder happened to succeed would drop that guarantee
                // rather than relocate it.
                //
                // The trigger is the **audit set** — the paths the squash would
                // have conflicted over, plus whatever the ladder resolved or
                // left — rather than the ladder's exit shape. An arc whose
                // squash conflicts but whose rounds replay cleanly returns both
                // lists empty with a candidate in hand, which is precisely the
                // 2026-08-15 incident shape: a wholesale machine decision that
                // builds green, passing unread.
                let audit_set = crate::feeds::join_resolver::audit_set(&outcome);
                if !audit_set.is_empty() {
                    let ctx = crate::feeds::join_resolver::ResolverContext {
                        repo: dir.to_path_buf(),
                        arc: arc_name.to_string(),
                        project_dir: project_dir.to_string(),
                        model: match &self.scribe {
                            Some(scribe) => scribe.model.clone(),
                            None => Arc::new(|| "sonnet".to_string()),
                        },
                        control_tx: self.control_tx.clone(),
                        bump: self.registry.changeset_all_bump(),
                        // A build with a scribe wired is a build with a real
                        // model available; one without has no business
                        // spawning one, and says so rather than reaching.
                        production: self.scribe.as_ref().map(|_| {
                            Arc::new(crate::feeds::join_resolver::ClaudeJoinResolverSpawner)
                                as Arc<dyn crate::feeds::join_resolver::JoinResolverSpawner>
                        }),
                    };

                    // **Detached, and that is not an optimization.** The
                    // resolver may block on an escalation for as long as the
                    // user takes to answer it, and the answer arrives as
                    // another CONTROL request — so awaiting the flow here would
                    // hold the control path against the very message that
                    // unblocks it. A join waiting on a question would wait
                    // forever, by construction.
                    //
                    // Nothing is lost by returning early, because nothing here
                    // was the result: the candidate, the report, and the
                    // verdict are git facts the feed recomputes from, and the
                    // deltas keep the face moving meanwhile ([P09]).
                    let control_tx = self.control_tx.clone();
                    let bump = self.registry.changeset_all_bump();
                    let dir_owned = dir.to_path_buf();
                    let arc = arc_name.to_string();
                    let project_dir_owned = project_dir.to_string();
                    let outcome_owned = outcome.clone();
                    tokio::spawn(async move {
                        // The hold travels with the work, not with this
                        // handler: the resolve is only over when the detached
                        // task is, and it releases on every exit including a
                        // panic.
                        let _occupancy = occupancy;
                        match crate::feeds::join_resolver::finish_join(&ctx, &outcome_owned).await {
                            Ok(()) => {
                                bump.notify_one();
                                // The resolver finished what the ladder left,
                                // so the ladder's `unresolved` list is no
                                // longer true of anything — and the client
                                // reads a non-empty one as the ladder's dead
                                // end ("still conflicting — resolve by hand").
                                // Reporting the outcome unamended would name
                                // files the resolve just settled.
                                let mut settled = outcome_owned.clone();
                                settled.unresolved.clear();
                                Self::send_changeset_join_resolve_ok(
                                    &control_tx,
                                    &project_dir_owned,
                                    &arc,
                                    &settled,
                                );
                            }
                            Err(detail) => {
                                Self::record_join_stuck(&dir_owned, &arc, &detail);
                                bump.notify_one();
                                tracing::info!(arc = %arc, detail = %detail, "arc-join: resolver stuck");
                                Self::send_changeset_join_resolve_err(
                                    &control_tx,
                                    &project_dir_owned,
                                    &arc,
                                    &detail,
                                );
                            }
                        }
                    });
                    return;
                }

                Self::send_changeset_join_resolve_ok(
                    &self.control_tx,
                    project_dir,
                    arc_name,
                    &outcome,
                );

                // A clean ladder pass ends here. The candidate it produced used
                // to be handed straight to the project's checks, on the theory
                // that a merge with no conflicting file can still fail to
                // build. It can — but the run's ending is where that is asked
                // now, against the tree that will actually land, so the
                // reconcile's job is done the moment the candidate stands.
                drop(occupancy);
            }
            Ok(Err(detail)) => {
                tracing::info!(arc = %arc_name, detail = %detail, "arc-join: ladder refused");
                Self::send_changeset_join_resolve_err(
                    &self.control_tx,
                    project_dir,
                    arc_name,
                    &detail,
                );
            }
            Err(join_err) => {
                Self::send_changeset_join_resolve_err(
                    &self.control_tx,
                    project_dir,
                    arc_name,
                    &format!("resolve task failed: {join_err}"),
                );
            }
        }
    }

    /// Handle a `changeset_join_question_answer` CONTROL request ([P06]):
    /// hand the user's answer to whichever resolve is blocked on it.
    ///
    /// Synchronous, and deliberately: the answer's whole job is to unblock a
    /// task already waiting, and the reply says only whether it reached one.
    /// An answer that reaches nobody — the question expired, the resolve died
    /// — is reported as a refusal with its reason, never swallowed ([L31]).
    fn do_changeset_join_question_answer(&self, request: &ChangesetJoinQuestionAnswerPayload) {
        let delivered = crate::feeds::join_resolver::answer_question(
            &request.request_id,
            request.answer.clone(),
        );
        let body = if delivered {
            serde_json::json!({
                "action": "changeset_join_question_answer_ok",
                "project_dir": request.project_dir,
                "arc": request.arc,
                "request_id": request.request_id,
            })
        } else {
            serde_json::json!({
                "action": "changeset_join_question_answer_err",
                "project_dir": request.project_dir,
                "arc": request.arc,
                "request_id": request.request_id,
                "detail": "that question is no longer waiting for an answer — resolve the join again",
            })
        };
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_question_answer reply serializes"),
        ));
        self.registry.changeset_all_bump().notify_one();
    }

    /// The run's terminal frame: the ladder's outcome, plus who it is about.
    ///
    /// The outcome is serialized whole rather than summarized, which is what
    /// keeps the card's overlay able to say "still conflicting on b.rs" — the
    /// one terminal fact the feed genuinely cannot state, because the arc's
    /// conflicts look identical whether or not a run just tried them.
    fn send_changeset_join_resolve_ok(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        outcome: &tugarc_core::ResolveOutcome,
    ) {
        let mut body = serde_json::to_value(outcome).unwrap_or_else(|_| serde_json::json!({}));
        if let Some(map) = body.as_object_mut() {
            map.insert(
                "action".into(),
                serde_json::Value::String("changeset_join_resolve_ok".into()),
            );
            map.insert(
                "project_dir".into(),
                serde_json::Value::String(project_dir.to_string()),
            );
            map.insert("arc".into(), serde_json::Value::String(arc.to_string()));
        }
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_resolve_ok serializes"),
        ));
    }

    /// Record why a resolve stopped, against the arc head it ran on.
    ///
    /// CONTROL carries the same sentence back as `_err`, but CONTROL is
    /// droppable by design — a dropped frame would leave the face with a join
    /// that will not proceed and no account of why. The durable fact is what
    /// the board renders; the frame is the liveness hint.
    fn record_join_stuck(dir: &std::path::Path, arc: &str, detail: &str) {
        let Ok(head) = tugarc_core::ops::rev_parse(dir, &format!("tugarc/{arc}")) else {
            return;
        };
        tugarc_core::resolve::write_stuck(dir, arc, &head, detail);
    }

    /// Refuse a resolve **before it started**, without disturbing the run that
    /// is the reason for the refusal (Spec S01).
    ///
    /// The distinction is the `admission` flag, and it is load-bearing: this
    /// reply arrives on the same `(project_dir, arc)` cell the live run is
    /// streaming into, so a client that read it as an ordinary failure would
    /// paint the healthy run it was refused *in favour of* as dead — turning a
    /// harmless double press into the false error face this round removes.
    fn send_changeset_join_admission_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_join_resolve_err",
            "project_dir": project_dir,
            "arc": arc,
            "detail": detail,
            "admission": true,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_resolve_err serializes"),
        ));
    }

    /// Clear the base-side work refusing an arc's join ([`resolve_base_in`]).
    ///
    /// It reports on the same two frames the ladder's resolve uses, because
    /// the card is showing one register and a second vocabulary for "the
    /// resolve finished" would be a second thing to keep in step. The bump is
    /// what makes the outcome visible: the blockers are never cached, so one
    /// recompute is the whole of the update.
    async fn do_changeset_join_resolve_base(&self, request: &ChangesetJoinResolvePayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_join_resolve_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not an open project",
            );
            return;
        }

        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_join_resolve_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not a git repository",
            );
            return;
        }

        // Take the arc before anything git-shaped happens (Spec S01). The fold
        // commits on the base and rewrites the paths it folded; a second press
        // landing under the first would fold a tree mid-commit.
        let owner_key = tugarc_core::ops::arc_owner_key(dir, &request.arc);
        let occupancy = match crate::feeds::join_occupancy::acquire(
            &owner_key,
            crate::feeds::join_occupancy::JoinRunKind::ResolveBase,
            None,
        ) {
            Ok(guard) => guard,
            Err(detail) => {
                Self::send_changeset_join_admission_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &detail,
                );
                return;
            }
        };

        // A hold nobody samples is a hold nobody has. `run_kind` is an
        // in-process registry read that only a recompute reaches, and this
        // handler's own bump fires *after* the fold — so with nothing here
        // `join.run` would go from absent to absent and no surface would ever
        // see `resolve-base`. `run_resolve_ladder` says it for its own hold and
        // it is the same reason: the `run` fact is what makes a reload mid-act
        // land on a face that still says the act is running, so it goes out
        // before the work.
        self.registry.changeset_all_bump().notify_one();

        // The attribution the blockers were composed from, read again here
        // rather than trusted from the press: the card's copy is as old as its
        // last recompute, and a session that has since put its hand on the
        // path must still be named in the fold and told about it.
        let live = crate::feeds::changeset::live_base_dirt_for(
            dir,
            &request.arc,
            self.session_ledger.as_deref(),
        )
        .await;
        let live_dirt: std::collections::BTreeMap<String, String> = live
            .iter()
            .map(|(path, (_, name))| (path.clone(), name.clone()))
            .collect();

        let dir_owned = dir.to_path_buf();
        let arc = request.arc.clone();
        let result = tokio::task::spawn_blocking(move || {
            // The hold travels with the work and is released when the fold
            // returns, whichever way it returns — including a panic, which is
            // why it is a guard rather than a pair of calls. It has to be gone
            // before the bump below: that recompute is the one that removes the
            // blocker, and a run still held at that moment would put
            // `run: "resolve-base"` on an entry with nothing running (R02).
            let _held = occupancy;
            tugarc_core::ops::resolve_base_in(&dir_owned, &arc, &live_dirt)
        })
        .await;

        match result {
            Ok(Ok(outcome)) => {
                tracing::info!(
                    arc = %outcome.name,
                    folded = outcome.folded.len(),
                    dropped = outcome.dropped.len(),
                    "arc-resolve-base: cleared"
                );
                self.registry.changeset_all_bump().notify_one();
                // Tell each session whose work rode in the fold ([L31]'s
                // other half): the act happened to *their* files, so the
                // report goes to their transcript, not only to the presser's
                // card. The frame is the same `tug_notice` base-motion's
                // injections announce with — a quiet system row, no turn.
                let mut by_session: std::collections::BTreeMap<&str, Vec<&str>> =
                    std::collections::BTreeMap::new();
                for path in outcome.folded_from.keys() {
                    if let Some((owner_id, _)) = live.get(path) {
                        by_session.entry(owner_id).or_default().push(path);
                    }
                }
                for (session, paths) in by_session {
                    let text = Self::resolve_base_notice_text(
                        &outcome.name,
                        &outcome.base_branch,
                        paths.len(),
                        outcome.committed.as_deref(),
                    );
                    self.code_output.publish_tagged(Frame::new(
                        FeedId::CODE_OUTPUT,
                        crate::feeds::base_motion::bulletin_payload(session, "arc-resolve", &text),
                    ));
                }
                let body =
                    Self::changeset_join_resolve_base_ok_body(project_dir, &outcome.name, &outcome);
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("changeset_join_resolve_base_ok serializes"),
                ));
            }
            Ok(Err(detail)) => {
                Self::send_changeset_join_resolve_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &detail,
                );
            }
            Err(e) => {
                Self::send_changeset_join_resolve_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &format!("the resolve did not run: {e}"),
                );
            }
        }
    }

    /// What the holder of a folded file is told (Spec S04).
    ///
    /// **Tug speaking as Tug**, so it names no command: the act happened on a
    /// surface the reader has, and the way back is a control on that same
    /// surface. The old sentence pointed at `tugtool arc undo` from inside a
    /// row wearing the model's avatar, which got the voice and the remedy
    /// wrong in one line.
    ///
    /// It says the four facts a reader needs to stop worrying: which arc, how
    /// many of *their* files, where they went, and that the disk is untouched.
    /// The count is per-session — the paths this holder owned, not the fold's
    /// whole set — because the sentence says "your".
    fn resolve_base_notice_text(
        arc: &str,
        base: &str,
        files: usize,
        commit: Option<&str>,
    ) -> String {
        let noun = if files == 1 { "file" } else { "files" };
        match commit {
            Some(sha) => format!(
                "Resolve on arc `{arc}` committed your uncommitted edits to {files} {noun} onto {base} as `{}`. Nothing changed on disk. Undo is in your Changes shade.",
                &sha[..sha.len().min(9)]
            ),
            // Nothing was committed, so there is no sha to name and no undo to
            // offer: the paths were the arc's own bytes and dropping them took
            // nothing away.
            None => format!(
                "Resolve on arc `{arc}` dropped your {files} identical {noun} from the base checkout — the arc already carries them. Nothing changed on disk."
            ),
        }
    }

    /// The `changeset_join_resolve_base_ok` frame, built key by key.
    ///
    /// Every field is written by name rather than serialized off
    /// [`ResolveBaseOutcome`], because the outcome's arc field is spelled
    /// `name` while the deck correlates a reply to its cell by `arc` — a frame
    /// serialized whole carried no `arc` at all, and the deck dropped it in
    /// silence on arrival (the 2026-09-03 incident). Naming each key is what
    /// makes the wire contract something a test can read, and the fixture the
    /// test reads it against is shared with the tugdeck suite, so drift on
    /// either side of the mirror fails one of the two.
    ///
    /// `committed` is present only when the fold made a commit. `folded`,
    /// `dropped` and `folded_from` are always present, empty when empty, so
    /// the deck reads counts without guards.
    fn changeset_join_resolve_base_ok_body(
        project_dir: &str,
        arc: &str,
        outcome: &tugarc_core::ops::ResolveBaseOutcome,
    ) -> serde_json::Value {
        let mut body = serde_json::json!({
            "action": "changeset_join_resolve_base_ok",
            "project_dir": project_dir,
            "arc": arc,
            "folded": outcome.folded,
            "dropped": outcome.dropped,
            "folded_from": outcome.folded_from,
            "warnings": outcome.warnings,
        });
        if let Some(commit) = outcome.committed.as_deref() {
            body["committed"] = serde_json::Value::String(commit.to_string());
        }
        body
    }

    fn send_changeset_join_resolve_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_join_resolve_err",
            "project_dir": project_dir,
            "arc": arc,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_resolve_err serializes"),
        ));
    }

    /// Handle a `changeset_join_resolve_base_undo` CONTROL request: put back
    /// the uncommitted base work a fold committed, via
    /// [`tugarc_core::undo_resolve_base_in`].
    ///
    /// It takes no occupancy hold, and that is deliberate rather than an
    /// omission. The fold is a run — it streams, it has a face, and a second
    /// press landing under it would fold a tree mid-commit. An undo is a
    /// compare-and-swap against tips the operation recorded: a second one
    /// finds the op already reversed and refuses by name, which is the same
    /// answer a hold would have produced and one fewer thing to release.
    ///
    /// What it does share with the fold is the bump. Everything it moved is in
    /// git, the blockers are never cached, and the receipt it retires is read
    /// off the op log by the recompute — so the recompute is the whole of the
    /// update, and it fires on the refusal too, since a refusal is proof the
    /// caller's copy of the world was stale.
    async fn do_changeset_join_resolve_base_undo(&self, request: &ChangesetJoinResolvePayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_join_resolve_base_undo_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not an open project",
            );
            return;
        }

        let dir_owned = dir.to_path_buf();
        let arc = request.arc.clone();
        let result = tokio::task::spawn_blocking(move || {
            tugarc_core::undo_resolve_base_in(&dir_owned, &arc)
        })
        .await;

        match result {
            Ok(Ok(outcome)) => {
                tracing::info!(
                    arc = %outcome.arc,
                    reversed = outcome.seq,
                    "arc-resolve-base: undone"
                );
                self.registry.changeset_all_bump().notify_one();
                let mut body = serde_json::json!({
                    "action": "changeset_join_resolve_base_undo_ok",
                    "project_dir": project_dir,
                    "arc": outcome.arc,
                });
                if let Some(tip) = outcome.base_tip.as_deref() {
                    body["base_tip"] = serde_json::Value::String(tip.to_string());
                }
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body)
                        .expect("changeset_join_resolve_base_undo_ok serializes"),
                ));
            }
            Ok(Err(detail)) => {
                self.registry.changeset_all_bump().notify_one();
                Self::send_changeset_join_resolve_base_undo_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &detail,
                );
            }
            Err(e) => {
                Self::send_changeset_join_resolve_base_undo_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &format!("the undo did not run: {e}"),
                );
            }
        }
    }

    /// The undo's own refusal frame, separate from
    /// `changeset_join_resolve_err` because the two say different things about
    /// the same arc: that one reports a resolve that failed and fails the
    /// cell, this one reports a press that changed nothing while whatever the
    /// cell is doing carries on untouched.
    fn send_changeset_join_resolve_base_undo_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_join_resolve_base_undo_err",
            "project_dir": project_dir,
            "arc": arc,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_join_resolve_base_undo_err serializes"),
        ));
    }

    /// Handle a `changeset_discard` CONTROL request: discard an arc (worktree +
    /// branch) without merging, via `tugarc-core`. Same guards as the join
    /// verb; fires the aggregate bump so the arc entry disappears from the
    /// card. Broadcasts `changeset_discard_ok {…}` / `changeset_discard_err`.
    async fn do_changeset_discard(&self, request: &ChangesetDiscardPayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_discard_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not an open project",
            );
            return;
        }
        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_discard_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                "not a git repository",
            );
            return;
        }

        // Resolved before the teardown, for the reason `do_changeset_join`
        // states: `discard_in` deletes the branch and its config with it
        // ([L23], [P05], Risk R02).
        let owner_key = tugarc_core::ops::arc_owner_key(dir, &request.arc);
        // What the discard is about to destroy, read while it still exists —
        // `arc_detail_entries_in` is the only accessor and after the teardown
        // the branch is gone and the subjects are unrecoverable (Spec S02).
        let detail = tugarc_core::arc_detail_entries_in(dir)
            .into_iter()
            .find(|d| d.name == request.arc);
        let discarded_rounds = detail.as_ref().map(|d| d.rounds).unwrap_or(0);
        let discarded_files = detail.as_ref().map(|d| d.files.len() as u32).unwrap_or(0);
        let round_subjects = detail.map(|d| d.round_subjects).unwrap_or_default();

        let dir_owned = dir.to_path_buf();
        let arc = request.arc.clone();
        let result = tokio::task::spawn_blocking(move || {
            tugarc_core::discard_in(&dir_owned, &arc, Some("card"), false)
        })
        .await;

        match result {
            Ok(Ok(outcome)) => {
                tracing::info!(
                    arc = %outcome.name,
                    rounds = discarded_rounds,
                    files = discarded_files,
                    documents_kept = outcome.documents_kept.is_some(),
                    "arc-discard: completed"
                );
                // The discarded arc's join draft dies with it ([P14]) — a
                // reused name must never inherit the dead arc's message.
                if let Some(ledger) = self.session_ledger.as_deref() {
                    Self::clear_arc_draft(ledger, project_dir, &owner_key);
                    // As on the join path: the arc is gone, so its bindings
                    // go with it ([P05]).
                    let _ = ledger.clear_arc_bindings_for_arc(&owner_key);
                }
                self.registry.changeset_all_bump().notify_one();
                // The discard's receipt (Spec S02): the header names what was
                // destroyed, the body lists the subjects the preflight showed.
                let summary = crate::feeds::changeset::format_discard_summary(
                    &outcome.name,
                    discarded_rounds,
                    discarded_files,
                    &round_subjects,
                    outcome.documents_kept.as_deref(),
                );
                let receipt_id = Self::record_landing_receipt(
                    self.shell_ledger.as_ref(),
                    self.session_ledger.as_ref(),
                    request.session_id.as_deref(),
                    "/arc-discard",
                    &summary,
                    project_dir,
                );
                let body = serde_json::json!({
                    "action": "changeset_discard_ok",
                    "project_dir": project_dir,
                    "arc": request.arc,
                    "name": outcome.name,
                    "summary": summary,
                    "receipt_id": receipt_id,
                    "warnings": outcome.warnings,
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("changeset_discard_ok serializes"),
                ));
            }
            Ok(Err(detail)) => {
                Self::send_changeset_discard_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &detail,
                );
            }
            Err(join_err) => {
                Self::send_changeset_discard_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    &format!("discard task failed: {join_err}"),
                );
            }
        }
    }

    fn send_changeset_discard_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_discard_err",
            "project_dir": project_dir,
            "arc": arc,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_discard_err serializes"),
        ));
    }

    /// Handle a `changeset_replay` CONTROL request: replay an arc's rounds onto
    /// its base branch's current tip, via `tugarc-core`. Same two guards as the
    /// discard verb; fires the aggregate bump so the row's divergence facts
    /// recompute. Broadcasts `changeset_replay_ok {…}` / `changeset_replay_err`.
    ///
    /// Nothing is written to the ledger and no draft or binding is cleared: a
    /// replay destroys nothing and owns no draft, so the discard's cleanup has
    /// no analogue here. `replay_onto` is a compare-and-swap over the worktree's
    /// cleanliness and HEAD, so a press that races the base-motion engine
    /// touches nothing and reports `deferred` or `current`.
    ///
    /// A `conflicted` outcome is still an `_ok`: the replay ran and reported,
    /// and the conflict is the arc's state rather than the verb's failure.
    /// `_err` carries the two guards and an `Err` from the op, which
    /// `replay_onto` returns only for an arc that does not exist.
    async fn do_changeset_replay(&self, request: &ChangesetReplayPayload) {
        let project_dir = request.project_dir.as_str();
        let dir = std::path::Path::new(project_dir);

        if self.registry.find_entry_by_path(dir).is_none() {
            Self::send_changeset_replay_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                request.session_id.as_deref(),
                "not an open project",
            );
            return;
        }
        if !crate::feeds::git::is_within_git_worktree(dir).await {
            Self::send_changeset_replay_err(
                &self.control_tx,
                project_dir,
                &request.arc,
                request.session_id.as_deref(),
                "not a git repository",
            );
            return;
        }

        let dir_owned = dir.to_path_buf();
        let arc = request.arc.clone();
        let result =
            tokio::task::spawn_blocking(move || tugarc_core::replay_onto(&dir_owned, &arc)).await;

        match result {
            Ok(Ok(outcome)) => {
                self.registry.changeset_all_bump().notify_one();
                let mut body = serde_json::json!({
                    "action": "changeset_replay_ok",
                    "project_dir": project_dir,
                    "arc": request.arc,
                    "session_id": request.session_id,
                });
                // The outcome serializes itself — its own `#[serde(tag =
                // "outcome")]` supplies the word, and the variant's fields carry
                // the only text a refusal can be read from.
                let serialized = serde_json::to_value(&outcome).expect("replay outcome serializes");
                if let (Some(target), Some(fields)) = (body.as_object_mut(), serialized.as_object())
                {
                    for (key, value) in fields {
                        target.insert(key.clone(), value.clone());
                    }
                }
                tracing::info!(
                    arc = %request.arc,
                    outcome = %serialized.get("outcome").and_then(|v| v.as_str()).unwrap_or("-"),
                    "arc-replay: completed"
                );
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("changeset_replay_ok serializes"),
                ));
            }
            Ok(Err(detail)) => {
                Self::send_changeset_replay_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    request.session_id.as_deref(),
                    &detail,
                );
            }
            Err(join_err) => {
                Self::send_changeset_replay_err(
                    &self.control_tx,
                    project_dir,
                    &request.arc,
                    request.session_id.as_deref(),
                    &format!("replay task failed: {join_err}"),
                );
            }
        }
    }

    fn send_changeset_replay_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        arc: &str,
        session_id: Option<&str>,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_replay_err",
            "project_dir": project_dir,
            "arc": arc,
            "session_id": session_id,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_replay_err serializes"),
        ));
    }

    fn send_changeset_git_init_ok(control_tx: &broadcast::Sender<Frame>, project_dir: &str) {
        let body = serde_json::json!({
            "action": "changeset_git_init_ok",
            "project_dir": project_dir,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_git_init_ok serializes"),
        ));
    }

    fn send_changeset_git_init_err(
        control_tx: &broadcast::Sender<Frame>,
        project_dir: &str,
        detail: &str,
    ) {
        let body = serde_json::json!({
            "action": "changeset_git_init_err",
            "project_dir": project_dir,
            "detail": detail,
        });
        let _ = control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("changeset_git_init_err serializes"),
        ));
    }

    /// Handle a `list_card_bindings` CONTROL request. Reads every
    /// resumable ledger row (see `list_with_card_id` for the filter)
    /// and broadcasts a `list_card_bindings_ok` response. The
    /// client-side `restoreDevSessions` consumes this on startup and
    /// reconnect to re-assert per-card bindings. Multiple rows can
    /// share a `card_id` (sequential sessions on that card); the
    /// client picks the newest per card.
    /// Answer "which of these sessions does this ledger hold?" ([D132]).
    ///
    /// The read path behind every citation chip. A commit's trailers name a
    /// session by full uuid or by the citation's 8-char short id, and whether
    /// that session is *findable* has to be a ledger answer: deciding it from
    /// whatever the client happened to have cached makes the same commit's chip
    /// resolvable or slashed depending on which listings ran this run, which is
    /// not a fact about the reference.
    ///
    /// Answers positively and negatively in one frame — the `unknown` list is
    /// what lets the client cache a miss instead of re-asking forever. A
    /// ledger-less build answers everything unknown rather than staying silent,
    /// for the same reason `list_card_bindings` answers empty: a client sitting
    /// on `pending` forever is the one outcome with no rendering.
    async fn do_resolve_sessions(&self, ids: &[String]) {
        let mut sessions = Vec::new();
        let mut unknown: Vec<&str> = Vec::new();
        match self.session_ledger.as_ref() {
            Some(ledger) => match ledger.resolve_session_ids(ids) {
                Ok(resolved) => {
                    for (queried, row) in &resolved {
                        // The segment's usage rides the answer, so a surface
                        // that resolves a cited id gets the numbers in the same
                        // round trip rather than asking a second time. `None`
                        // for a segment that recorded no telemetry.
                        let usage = ledger.usage_for(&row.session_id).unwrap_or(None);
                        sessions.push(serde_json::json!({
                            // Keyed by what was asked, so the client can match
                            // an answer back to the citation it read — a short
                            // id and the row's full id are different strings.
                            "queried": queried,
                            "session": row,
                            "usage": usage,
                        }));
                    }
                    for id in ids {
                        if !resolved.iter().any(|(queried, _)| queried == id.trim()) {
                            unknown.push(id.as_str());
                        }
                    }
                }
                Err(err) => {
                    warn!(error = %err, "resolve_sessions: ledger read failed");
                    let body = serde_json::json!({
                        "action": "resolve_sessions_err",
                        "ids": ids,
                        "reason": "ledger_read_failed",
                    });
                    let _ = self.control_tx.send(Frame::new(
                        FeedId::CONTROL,
                        serde_json::to_vec(&body).expect("resolve_sessions_err serializes"),
                    ));
                    return;
                }
            },
            None => unknown.extend(ids.iter().map(String::as_str)),
        }
        let body = serde_json::json!({
            "action": "resolve_sessions_ok",
            "sessions": sessions,
            "unknown": unknown,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("resolve_sessions_ok serializes"),
        ));
    }

    async fn do_list_card_bindings(&self) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            // No ledger wired — emit an empty response so a confused
            // client doesn't sit on a pending state forever.
            let body = serde_json::json!({
                "action": "list_card_bindings_ok",
                "bindings": serde_json::Value::Array(Vec::new()),
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("list_card_bindings_ok serializes"),
            ));
            return;
        };
        // One row per **line** ([P06]), each seated on the segment a restore
        // should resume. A card that has lived through eight id changes is one
        // binding here, not eight.
        let lines = match ledger.list_lines_with_card() {
            Ok(l) => l,
            Err(err) => {
                warn!(error = %err, "list_card_bindings failed");
                let body = serde_json::json!({
                    "action": "list_card_bindings_err",
                    "reason": "ledger_read_failed",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("list_card_bindings_err serializes"),
                ));
                return;
            }
        };
        // Snapshot the live-session map so we can answer `is_alive` for
        // each row without N round-trip lock acquisitions. A session is
        // "alive" when its in-memory ledger entry is `Spawning` or
        // `Live` — i.e. there is (or imminently will be) a tugcode
        // subprocess holding the session's runtime state, including any
        // in-flight turn or pending control_request. `Idle`, `Errored`,
        // and `Closed` are all "not alive" — there's no subprocess to
        // resume into, so the client should fall through to the
        // `turn_count > 0` JSONL-replay path or to a fresh spawn.
        //
        // This flag is the missing signal that lets the client tell
        // "in-flight first turn" (resume-able, no JSONL yet) apart from
        // "Start Fresh + quit" (fresh-spawn-and-bind-project). Both have
        // `turn_count == 0`; only the live one has `is_alive == true`.
        let live_session_ids: std::collections::HashSet<String> = {
            let live = self.ledger.lock().await;
            let mut alive = std::collections::HashSet::with_capacity(live.len());
            for (sid, entry_arc) in live.iter() {
                let entry = entry_arc.lock().await;
                if matches!(entry.spawn_state, SpawnState::Spawning | SpawnState::Live) {
                    alive.insert(sid.0.clone());
                }
            }
            alive
        };
        // Direct JSONL-presence signal. `turn_count` (the ledger's live
        // `record_turn` counter) is an unreliable proxy for "has a transcript
        // to resume": claude writes the JSONL itself, so a session can carry a
        // full on-disk transcript while the ledger count stays 0 (the turns
        // never flowed through a live `turn_complete`). A restore that trusts
        // `turn_count` then mis-routes such a session to a `new`-mode spawn,
        // whose `--session-id` collides with the existing JSONL and crash-loops
        // the card to `errored`. `has_jsonl` stats the exact file the resume
        // would target, so the client can gate on the real thing. Targeted
        // per-card stats (not a boot walk) under a directory the app already
        // reads — no new TCC surface.
        let claude_root = ledger.claude_projects_root().to_path_buf();
        // One pair of git reads per distinct repo among the bound rows, so a
        // binding whose arc has since been joined or discarded reads as
        // unbound ([P05]) without a git call per row.
        let arc_records_by_project: std::collections::HashMap<String, ArcRecords> = {
            let projects: std::collections::HashSet<String> = lines
                .iter()
                .filter(|(_, segment, _)| segment.arc_id.is_some())
                .map(|(_, segment, _)| segment.project_dir.clone())
                .collect();
            tokio::task::spawn_blocking(move || {
                projects
                    .into_iter()
                    .map(|project| {
                        let records = Self::live_arc_records(&project);
                        (project, records)
                    })
                    .collect()
            })
            .await
            .unwrap_or_default()
        };
        // A project the map has no entry for was never asked — a panicked
        // blocking task, or a row whose spelling drifted out of the set. That
        // is `Unreadable`, not "no arcs": the old empty-set default here was
        // the second way a valid binding got nulled.
        let unasked = ArcRecords::Unreadable;
        let bindings: Vec<serde_json::Value> = lines
            .into_iter()
            .filter_map(|(line, segment, turn_count)| {
                let card_id = line.card_id.clone()?;
                let (arc_id, arc_name) = Self::reported_binding(
                    arc_records_by_project
                        .get(&segment.project_dir)
                        .unwrap_or(&unasked),
                    segment.arc_id,
                    segment.arc_name,
                );
                // Liveness and the transcript are the **seated segment's**:
                // they are facts about the file a resume would open, not about
                // the line.
                let is_alive = live_session_ids.contains(&segment.session_id);
                let has_jsonl = {
                    let (dir, _canonical) = crate::session_ledger::claude_project_dir(
                        &claude_root,
                        &segment.project_dir,
                    );
                    let path = dir.join(format!("{}.jsonl", segment.session_id));
                    crate::external_sessions::stat_size_mtime(&path)
                        .is_some_and(|(size, _mtime)| size > 0)
                };
                Some(serde_json::json!({
                    "card_id": card_id,
                    "line_id": line.line_id,
                    "session_id": segment.session_id,
                    "project_dir": segment.project_dir,
                    "state": segment.state,
                    // The line's turns, summed across its segments: what the
                    // conversation holds, not what its newest id holds.
                    "turn_count": turn_count,
                    "is_alive": is_alive,
                    "has_jsonl": has_jsonl,
                    "name": line.name,
                    "name_user_set": line.name_user_set,
                    "tag": line.tag,
                    "synopsis": segment.synopsis,
                    "arc_id": arc_id,
                    "arc_name": arc_name,
                }))
            })
            .collect();
        let body = serde_json::json!({
            "action": "list_card_bindings_ok",
            "bindings": bindings,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_card_bindings_ok serializes"),
        ));
    }

    /// Handle a `request_replay` CONTROL request per [D12]. Forwards
    /// `{"type":"request_replay"}` to the per-session tugcode subprocess
    /// over its existing CODE_INPUT channel (the same `input_tx` the
    /// dispatcher uses for `user_message`). Tugcode's IPC loop dispatches
    /// the verb to its `runReplay()` method, whose re-entrancy guard
    /// (Step R1a) drops a redundant request that arrives mid-replay.
    ///
    /// State-dependent delivery:
    ///
    /// * `Live` — forward immediately to `input_tx`.
    /// * `Spawning` — push at the **front** of `entry.queue`; the
    ///   bridge's `session_init` promote-and-drain critical section
    ///   forwards it to `input_tx` before any user input that may
    ///   have been buffered alongside (Step R4 / [D12]).
    /// * `Idle` — log skipped(idle); no claude to send to.
    /// * `Errored` — log skipped(errored); subprocess gone.
    /// * `Closed` — log skipped(closed); subprocess gone.
    ///
    /// **Front-push rationale**: cold boot races a `request_replay`
    /// dispatch against the user's first submit. If the dispatch
    /// arrives during the Spawning window and the user types
    /// instantly afterward, the dispatcher will queue the user's
    /// CODE_INPUT into the same per-session queue. FIFO drain would
    /// deliver the user_message first, putting tugcode in an
    /// in-flight turn that races with the request_replay — exactly
    /// the Smoke D shape that [Phase A-R3](arc/tugplan-dev-transcript-resume.md#phase-a-r3)
    /// owns. Front-push ensures replay always precedes user input
    /// from the same Spawning window — the natural ordering since
    /// the verb is "rehydrate the freshly-mounted store" and the
    /// store should be rehydrated before user-facing work begins.
    async fn do_request_replay(
        &self,
        tug_session_id: &TugSessionId,
        window: Option<serde_json::Value>,
    ) {
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            match ledger.get(tug_session_id) {
                Some(e) => e.clone(),
                None => {
                    tracing::info!(
                        target: "dev::session-lifecycle",
                        event = "request_replay.skipped",
                        tug_session_id = %tug_session_id,
                        reason = "unknown",
                    );
                    return;
                }
            }
        };

        // An arc's history is spread across one JSONL per stage, so a card
        // that replays only its own shows a transcript beginning in the
        // middle. Walk the fork edges parent-ward and hand tugcode the chain
        // ([P10]). `None` for every card that is not an arc — which is nearly
        // all of them, and their request stays byte-identical.
        let lineage = {
            let (claude_session_id, project_dir) = {
                let entry = entry_arc.lock().await;
                (entry.claude_session_id.clone(), entry.project_dir.clone())
            };
            // Seed the lookup with the id the spawn actually resumes. A resume
            // onto a card the ledger has never seen inserts a fresh entry whose
            // `claude_session_id` is still `None` — tugcode's `session_init`
            // fills it, and the replay is queued during the spawning window,
            // before that. The tug id is the right seed there for the same
            // reason the spawner and the `line_id` derivation already take it:
            // for an un-forked session the two ids are equal, and a resume names
            // the segment it wants by its tug id. Ownership does not move — this
            // is a read, and `session_init` stays the one writer.
            claude_session_id
                .or_else(|| Some(tug_session_id.to_string()))
                .as_deref()
                .and_then(|id| replay_lineage(self.sessions_recorder.as_ref(), id, &project_dir))
        };

        // Remember what this request walked, so the `replay_complete` stamp
        // can sum the turn counts of exactly these files rather than
        // recomputing a chain and hoping it matches ([B02]). Written before
        // the frame is forwarded *or* queued, because the queued path is the
        // relaunch one — the very path a rotated card restores by. A request
        // that carries no lineage writes `None`, which is the tip-alone sum
        // and today's behaviour exactly.
        {
            let mut entry = entry_arc.lock().await;
            entry.replayed_lineage = lineage.as_ref().map(|entries| {
                entries
                    .iter()
                    .filter_map(|e| {
                        e.get("sessionId")
                            .and_then(|v| v.as_str())
                            .map(str::to_owned)
                    })
                    .collect()
            });
        }

        // Build the wire frame once; the body is the same regardless of
        // whether we forward immediately (Live) or queue (Spawning). The
        // optional recency `window` is forwarded verbatim — the supervisor
        // doesn't interpret it; tugcode validates the shape at its handler
        // boundary. The no-window, no-lineage path stays byte-identical to
        // the legacy full-replay request.
        let body: Vec<u8> = if window.is_none() && lineage.is_none() {
            b"{\"type\":\"request_replay\"}".to_vec()
        } else {
            let mut payload = serde_json::Map::new();
            payload.insert("type".into(), serde_json::json!("request_replay"));
            if let Some(w) = &window {
                payload.insert("window".into(), w.clone());
            }
            if let Some(l) = &lineage {
                payload.insert("lineage".into(), serde_json::json!(l));
            }
            serde_json::to_vec(&serde_json::Value::Object(payload))
                .expect("request_replay payload serializes")
        };
        let frame = Frame::new(FeedId::CODE_INPUT, body);

        // For the Spawning branch we need the entry mutex held while we
        // mutate `queue`. For the Live branch we want to release the
        // mutex before the (potentially blocking) mpsc send. Branch
        // inside the lock: Spawning enqueues here; Live takes a snapshot
        // of `input_tx` and sends after dropping the lock.
        let snapshot = {
            let mut entry = entry_arc.lock().await;
            match entry.spawn_state {
                SpawnState::Spawning => {
                    let push_result = entry.queue.push_front(frame);
                    if push_result == QueuePush::Overflow {
                        // Per-session queue capacity is bounded; an
                        // overflowing front-push means the dispatcher
                        // already crammed the queue with user input
                        // during the Spawning window. Log loudly — this
                        // is rare and indicates the user is typing
                        // faster than tugcode can spawn. The verb is
                        // dropped; the cold-boot transcript may show
                        // empty until the next dispatch (e.g. a
                        // subsequent reload).
                        tracing::warn!(
                            target: "dev::session-lifecycle",
                            event = "request_replay.skipped",
                            tug_session_id = %tug_session_id,
                            reason = "spawning_queue_overflow",
                        );
                        return;
                    }
                    tracing::info!(
                        target: "dev::session-lifecycle",
                        event = "request_replay.queued",
                        tug_session_id = %tug_session_id,
                        reason = "spawning_window",
                    );
                    return;
                }
                SpawnState::Live => entry.input_tx.clone(),
                SpawnState::Idle | SpawnState::Errored | SpawnState::Closed => {
                    let reason = match entry.spawn_state {
                        SpawnState::Idle => "idle",
                        SpawnState::Errored => "errored",
                        SpawnState::Closed => "closed",
                        _ => unreachable!(),
                    };
                    tracing::info!(
                        target: "dev::session-lifecycle",
                        event = "request_replay.skipped",
                        tug_session_id = %tug_session_id,
                        reason = reason,
                    );
                    return;
                }
            }
        };

        // Live branch continues here with the entry lock released.
        // `snapshot` is `Option<mpsc::Sender<Frame>>`.
        //
        // Live but no `input_tx` is a programming error — `Live` means
        // the bridge promoted the entry past `session_init` and the
        // worker installs `input_tx` before that promotion. Treat as
        // a skip on the user-visible path and warn loudly so the
        // condition surfaces in tracing.
        let Some(tx) = snapshot else {
            tracing::warn!(
                target: "dev::session-lifecycle",
                event = "request_replay.skipped",
                tug_session_id = %tug_session_id,
                reason = "no_input_tx",
            );
            return;
        };

        if let Err(e) = tx.send(frame).await {
            warn!(
                tug_session_id = %tug_session_id,
                error = %e,
                "request_replay: send to input_tx failed",
            );
            return;
        }
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "request_replay.dispatched",
            tug_session_id = %tug_session_id,
        );
    }

    /// Handle a `trash_session` CONTROL request. Refuses if the row is
    /// currently live (per [D03] / picker UX). Emits `session_updated
    /// { removed: true }` on success — the recorder broadcasts that frame
    /// internally; this handler emits the matching `trash_session_ok`
    /// response so the requesting client can resolve its pending action.
    /// Persist a per-turn telemetry block. Tugdeck → tugcast inbound
    /// CONTROL action driven by the reducer's `handleTurnComplete`
    /// (live path only — replayed turns aren't re-persisted). The
    /// claude `session_id` is the row's PK; we resolve it from the
    /// ledger entry keyed by `tug_session_id` (the wire-side
    /// identifier the client uses).
    ///
    /// The write is fire-and-forget at the wire level — no ack frame
    /// is broadcast. The client doesn't wait on confirmation; the
    /// row's reason for existing is to survive the next reload, not
    /// the next render. A `LedgerError` here is logged at `warn`
    /// (telemetry, not a user-visible failure).
    ///
    /// Three quietly-dropped cases — all benign:
    ///   1. No `SessionLedger` configured (test harnesses without
    ///      persistence). Nothing to do.
    ///   2. Ledger entry not found for `tug_session_id` (the session
    ///      was already evicted or never spawned through this
    ///      supervisor). Nothing to write to.
    ///   3. Ledger entry exists but `claude_session_id` is `None`
    ///      (handshake not yet complete). The reducer should never
    ///      reach `handleTurnComplete` before `session_init` lands,
    ///      so this branch is defensive — if it ever fires, log and
    ///      drop. The next live turn whose `session_init` precedes
    ///      it will write a fresh row.
    async fn do_record_turn_telemetry(&self, parsed: RecordTurnTelemetryPayload) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            return;
        };
        let claude_id = {
            let outer = self.ledger.lock().await;
            let Some(entry_arc) = outer.get(&parsed.tug_session_id) else {
                tracing::warn!(
                    target: "dev::telemetry",
                    event = "record_turn_telemetry.skipped",
                    tug_session_id = %parsed.tug_session_id,
                    msg_id = %parsed.msg_id,
                    reason = "session_not_found",
                );
                return;
            };
            let entry = entry_arc.lock().await;
            entry.claude_session_id.clone()
        };
        let Some(claude_id) = claude_id else {
            tracing::warn!(
                target: "dev::telemetry",
                event = "record_turn_telemetry.skipped",
                tug_session_id = %parsed.tug_session_id,
                msg_id = %parsed.msg_id,
                reason = "no_claude_session_id",
            );
            return;
        };
        let row = crate::session_ledger::TurnTelemetryRow {
            session_id: claude_id,
            msg_id: parsed.msg_id,
            input_tokens: parsed.cost_input_tokens,
            output_tokens: parsed.cost_output_tokens,
            cache_creation_input_tokens: parsed.cost_cache_creation_input_tokens,
            cache_read_input_tokens: parsed.cost_cache_read_input_tokens,
            total_cost_usd: parsed.cost_total_cost_usd,
            wall_clock_ms: parsed.wall_clock_ms,
            awaiting_approval_ms: parsed.awaiting_approval_ms,
            transport_downtime_ms: parsed.transport_downtime_ms,
            active_ms: parsed.active_ms,
            ttft_ms: parsed.ttft_ms,
            ttftc_ms: parsed.ttftc_ms,
            reconnect_count: parsed.reconnect_count,
            max_stream_gap_ms: parsed.max_stream_gap_ms,
            ended_at: parsed.ended_at,
            session_init_tokens: parsed.session_init_tokens,
        };
        if let Err(err) = ledger.record_turn_telemetry(&row) {
            crate::ledger_integrity::health::note_error("sessions", &err);
            tracing::warn!(
                target: "dev::telemetry",
                error = %err,
                session_id = %row.session_id,
                msg_id = %row.msg_id,
                "record_turn_telemetry ledger write failed",
            );
            return;
        }
        // Every ledger write pushes the row it changed, and this is the write
        // that was exempt. It is also the one whose fact a receipt reads: the
        // deck records telemetry after the turn commits, one round trip past
        // the after-turn push, so without this the stage that just finished
        // would carry a total missing its last turn until something else moved.
        // The push is built after the write, so it carries the row it made.
        if let Ok(Some(session_row)) = ledger.get(&row.session_id) {
            let metrics = ledger.scan_metrics_for(&row.session_id).unwrap_or(None);
            let usage = ledger.usage_for(&row.session_id).unwrap_or(None);
            let _ = self
                .control_tx
                .send(build_session_updated_frame(&session_row, metrics, usage));
        }
    }

    /// Persist the latest `/context`-style breakdown payload for a
    /// session via the SessionLedger. Mirrors
    /// {@link do_record_turn_telemetry} structurally: resolve
    /// `tug_session_id → claude_session_id`, UPSERT one row keyed by
    /// claude session id. The three quietly-dropped cases — no
    /// ledger configured, no session entry, no claude_session_id —
    /// log at telemetry level and return without raising.
    async fn do_record_context_breakdown(&self, parsed: RecordContextBreakdownPayload) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            return;
        };
        let claude_id = {
            let outer = self.ledger.lock().await;
            let Some(entry_arc) = outer.get(&parsed.tug_session_id) else {
                tracing::warn!(
                    target: "dev::telemetry",
                    event = "record_context_breakdown.skipped",
                    tug_session_id = %parsed.tug_session_id,
                    reason = "session_not_found",
                );
                return;
            };
            let entry = entry_arc.lock().await;
            entry.claude_session_id.clone()
        };
        let Some(claude_id) = claude_id else {
            tracing::warn!(
                target: "dev::telemetry",
                event = "record_context_breakdown.skipped",
                tug_session_id = %parsed.tug_session_id,
                reason = "no_claude_session_id",
            );
            return;
        };
        if let Err(err) =
            ledger.record_context_breakdown(&claude_id, &parsed.payload_bytes, parsed.captured_at)
        {
            tracing::warn!(
                target: "dev::telemetry",
                error = %err,
                session_id = %claude_id,
                "record_context_breakdown ledger write failed",
            );
        }
    }

    /// Persist one indicator-tone triple transition via the
    /// SessionLedger. Structurally mirrors
    /// {@link do_record_context_breakdown}: resolve
    /// `tug_session_id → claude_session_id`, hand the row to the
    /// ledger. The ledger's per-session dedupe is the SQL-layer
    /// safety net for races where the client-side prev/new compare
    /// in `dispatch()` doesn't get the chance to skip a redundant
    /// write (e.g., two near-simultaneous dispatches that both see
    /// the same previous state).
    ///
    /// The three quietly-dropped cases — no ledger configured, no
    /// session entry, no claude_session_id — log at telemetry level
    /// and return without raising; mirrors the context-breakdown
    /// handler.
    async fn do_record_session_state_change(&self, parsed: RecordSessionStateChangePayload) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            return;
        };
        let claude_id = {
            let outer = self.ledger.lock().await;
            let Some(entry_arc) = outer.get(&parsed.tug_session_id) else {
                tracing::warn!(
                    target: "dev::telemetry",
                    event = "record_session_state_change.skipped",
                    tug_session_id = %parsed.tug_session_id,
                    reason = "session_not_found",
                );
                return;
            };
            let entry = entry_arc.lock().await;
            entry.claude_session_id.clone()
        };
        let Some(claude_id) = claude_id else {
            tracing::warn!(
                target: "dev::telemetry",
                event = "record_session_state_change.skipped",
                tug_session_id = %parsed.tug_session_id,
                reason = "no_claude_session_id",
            );
            return;
        };
        if let Err(err) = ledger.record_session_state_change(
            &claude_id,
            parsed.at_ms,
            &parsed.phase,
            &parsed.transport_state,
            parsed.interrupt_in_flight,
        ) {
            tracing::warn!(
                target: "dev::telemetry",
                error = %err,
                session_id = %claude_id,
                "record_session_state_change ledger write failed",
            );
        }
    }

    /// Handle a `list_session_state_changes` CONTROL request. Reads
    /// every persisted triple-transition row for the resolved claude
    /// session id and broadcasts a `list_session_state_changes_ok`
    /// response carrying the rows oldest-first by `id`. The client-
    /// side reader correlates by the `tug_session_id` field, which
    /// is echoed verbatim from the request.
    ///
    /// Empty arrays are valid responses: a fresh session that has
    /// never had a triple change yet has no rows; the client should
    /// render a "no history" state.
    ///
    /// Errors broadcast `list_session_state_changes_err
    /// { tug_session_id, reason }`. When no `session_ledger` is wired
    /// the response is an empty array. When the in-memory map cannot
    /// resolve a `claude_session_id` (no session entry, or a resumed
    /// entry whose id has not landed yet) the read falls back to
    /// `tug_session_id` as the ledger key — identical to the claude
    /// id by the post-Phase-B invariant — so the persisted history
    /// survives a tugdeck reload that races the resume handshake. A
    /// genuinely unknown id still reads as an empty array; the popover
    /// renders the same "no history yet" state either way.
    async fn do_list_session_state_changes(&self, parsed: ListSessionStateChangesPayload) {
        let tug_session_id_str = parsed.tug_session_id.as_str().to_owned();
        let Some(ledger) = self.session_ledger.as_ref() else {
            let body = serde_json::json!({
                "action": "list_session_state_changes_ok",
                "tug_session_id": tug_session_id_str,
                "rows": serde_json::Value::Array(Vec::new()),
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("list_session_state_changes_ok serializes"),
            ));
            return;
        };
        let resolved_claude_id = {
            let outer = self.ledger.lock().await;
            match outer.get(&parsed.tug_session_id) {
                Some(entry_arc) => {
                    let entry = entry_arc.lock().await;
                    entry.claude_session_id.clone()
                }
                None => None,
            }
        };
        // Resolve the ledger key. The in-memory entry may not yet carry
        // the resumed session's claude id — after a tugdeck reload the
        // popover's `list_session_state_changes` request can race ahead
        // of the resume handshake that sets `claude_session_id`. Post-
        // Phase-B the tug and claude session ids are identical by
        // invariant, and `session_state_changes` rows are keyed by the
        // claude id, so falling back to `tug_session_id` recovers the
        // persisted history instead of returning a spurious empty array
        // (the popover's "no state changes recorded" bug after reload).
        // A genuinely unknown id still yields an empty ledger read —
        // the same "no history yet" the client renders either way.
        let claude_id = resolved_claude_id.unwrap_or_else(|| tug_session_id_str.clone());
        let rows = match ledger.list_session_state_changes(&claude_id) {
            Ok(r) => r,
            Err(err) => {
                warn!(error = %err, session_id = %claude_id, "list_session_state_changes failed");
                let body = serde_json::json!({
                    "action": "list_session_state_changes_err",
                    "tug_session_id": tug_session_id_str,
                    "reason": "ledger_read_failed",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("list_session_state_changes_err serializes"),
                ));
                return;
            }
        };
        let wire_rows: Vec<serde_json::Value> = rows
            .into_iter()
            .map(|r| {
                serde_json::json!({
                    "at_ms": r.at_ms,
                    "phase": r.phase,
                    "transport_state": r.transport_state,
                    "interrupt_in_flight": r.interrupt_in_flight,
                })
            })
            .collect();
        let body = serde_json::json!({
            "action": "list_session_state_changes_ok",
            "tug_session_id": tug_session_id_str,
            "rows": wire_rows,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_session_state_changes_ok serializes"),
        ));
    }

    /// Handle a `list_pulse_lines` CONTROL request — the deck's
    /// PULSE-ledger tail read (the pulse-store sends it on mount, then
    /// stays live off the PULSE feed). App-scoped: no session id.
    /// Broadcasts `list_pulse_lines_ok { lines: PulseLineRow[] }`,
    /// oldest-first; a missing ledger yields an empty array (the "no
    /// history yet" state, same conduct as the state-changes read).
    ///
    /// The read is per-scope, not a flat app-wide tail: the deck filters
    /// what it gets by session, so a flat tail hands one chatty session's
    /// lines to every card and leaves the quiet ones blank.
    async fn do_list_pulse_lines(&self) {
        let lines = self
            .session_ledger
            .as_ref()
            .map(|ledger| {
                ledger
                    .list_pulse_lines_per_scope(
                        crate::feeds::pulse::PULSE_TAIL_LEN,
                        crate::feeds::pulse::PULSE_LEDGER_CAP,
                    )
                    .unwrap_or_else(|err| {
                        warn!(error = %err, "list_pulse_lines failed");
                        Vec::new()
                    })
            })
            .unwrap_or_default();
        let body = serde_json::json!({
            "action": "list_pulse_lines_ok",
            "lines": lines,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_pulse_lines_ok serializes"),
        ));
    }

    /// Handle a `list_overview_posts` CONTROL request — the Overview card's
    /// history read, both the mount-time tail and each older page the reader
    /// scrolls back for. App-scoped: the channel belongs to the app, not to a
    /// session, even though a Observer post names the session it narrates.
    ///
    /// Request: `{ before_id?, limit? }`. No `before_id` is the tail (the
    /// original behavior, so an older client asking for nothing gets exactly
    /// what it always got); a `before_id` is the page immediately older than
    /// that row. `limit` defaults to the standard tail length.
    ///
    /// Broadcasts `list_overview_posts_ok { posts, has_more, before_id? }`,
    /// posts oldest-first; a missing ledger yields an empty array — the "no
    /// history yet" state, same conduct as the pulse read.
    ///
    /// **`before_id` is echoed verbatim, and that echo is load-bearing.** This
    /// response goes out on the CONTROL *broadcast* bus with no request
    /// correlation of any kind — which cost nothing while the only read was an
    /// idempotent tail that replaced the list with itself. A page is not
    /// idempotent: applied twice it prepends twice. The echo is what lets the
    /// client tell a tail from a page, and its own page from anyone else's.
    async fn do_list_overview_posts(&self, before_id: Option<i64>, limit: Option<usize>) {
        let limit = limit
            .filter(|n| *n > 0)
            .unwrap_or(crate::feeds::observer::OVERVIEW_TAIL_LEN);
        let (posts, has_more) = self
            .session_ledger
            .as_ref()
            .map(|ledger| {
                ledger
                    .list_overview_posts_page(before_id, limit)
                    .unwrap_or_else(|err| {
                        warn!(error = %err, "list_overview_posts failed");
                        (Vec::new(), false)
                    })
            })
            .unwrap_or_default();
        let body = serde_json::json!({
            "action": "list_overview_posts_ok",
            "posts": posts,
            "has_more": has_more,
            "before_id": before_id,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_overview_posts_ok serializes"),
        ));
    }

    /// Attach the shell-exchange ledger (the read side of the
    /// `list_shell_exchanges` CONTROL op). Called once in `main.rs` before the
    /// supervisor is shared.
    pub fn set_shell_ledger(&mut self, ledger: Arc<crate::shell_ledger::ShellLedger>) {
        self.shell_ledger = Some(ledger);
    }

    /// Attach the refs ledger (the read side of the `list_refs` CONTROL op).
    /// Called once in `main.rs` before the supervisor is shared.
    pub fn set_refs_ledger(&mut self, ledger: Arc<crate::refs_ledger::RefsLedger>) {
        self.refs_ledger = Some(ledger);
    }

    /// Attach the changeset scribe (the maintained-draft engine's backend).
    /// Called once in `main.rs` before the supervisor is shared.
    pub fn set_scribe(&mut self, scribe: ScribeContext) {
        self.scribe = Some(scribe);
    }

    /// Store the aggregate CHANGESET_ALL watch receiver for the on-demand draft
    /// path (#draft-engine, [P03]). No background loop is spawned — generation
    /// runs only on an explicit `changeset_draft_request`, off the latest frame
    /// this receiver holds. `do_changeset_draft_request` reads it back and
    /// resolves `tug_session_id → claude_session_id` from this supervisor's
    /// in-memory ledger entries at request time.
    pub fn start_draft_engine(
        self: &Arc<Self>,
        watch_rx: watch::Receiver<Frame>,
        _cancel: CancellationToken,
    ) {
        let _ = self.changeset_watch.set(watch_rx);
    }

    /// Handle a `list_shell_exchanges { tug_session_id, since_ms? }` CONTROL
    /// request — the deck's shell-restore read. Broadcasts
    /// `list_shell_exchanges_ok { tug_session_id, exchanges, total, max_seq,
    /// answered }`, oldest-first.
    ///
    /// `total` and `max_seq` are the completeness pair: the deck compares
    /// `exchanges.length` against `total` and only settles its restore when
    /// they agree. Without them an empty array from a mistimed request is
    /// indistinguishable from a session that genuinely has no rows — which is
    /// exactly how a transcript comes back short and silent. `answered` is
    /// false when there is no ledger at all, so "no ledger" never reads as
    /// "no rows".
    async fn do_list_shell_exchanges(&self, tug_session_id: &str, since_ms: Option<i64>) {
        let started = std::time::Instant::now();
        // Read the line of work, answer the asker. The deck routes a response
        // back to the store that asked by matching the echoed
        // `tug_session_id`, so the query resolves and the echo does not.
        let head = self.resolve_ink_line(tug_session_id);
        let read = self.shell_ledger.as_ref().map(|ledger| {
            let rows = ledger
                .list_exchanges_since(&head, since_ms)
                .unwrap_or_else(|err| {
                    warn!(error = %err, %tug_session_id, "list_shell_exchanges failed");
                    Vec::new()
                });
            let (total, max_seq) = ledger
                .exchange_census(&head, since_ms)
                .unwrap_or_else(|err| {
                    warn!(error = %err, %tug_session_id, "shell exchange census failed");
                    (rows.len() as i64, 0)
                });
            (rows, total, max_seq)
        });
        let answered = read.is_some();
        let (exchanges, total, max_seq) = read.unwrap_or_else(|| (Vec::new(), 0, 0));
        // The load-bearing diagnostic for a transcript that came back short:
        // ground truth for "what did the server actually hand this session".
        debug!(
            %tug_session_id,
            since_ms = ?since_ms,
            rows = exchanges.len(),
            total,
            max_seq,
            answered,
            elapsed_ms = started.elapsed().as_millis() as u64,
            "list_shell_exchanges"
        );
        let body = serde_json::json!({
            "action": "list_shell_exchanges_ok",
            "tug_session_id": tug_session_id,
            "exchanges": exchanges,
            "total": total,
            "max_seq": max_seq,
            "answered": answered,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_shell_exchanges_ok serializes"),
        ));
    }

    /// The session id durable ink for `tug_session_id` is keyed under: its
    /// lineage head, or the id itself when nothing has forked it (or no
    /// session ledger is configured).
    ///
    /// Durable ink is keyed by **line** ([P09]), so a read issued under any
    /// segment's id — including a superseded one the deck is still bound to —
    /// finds the whole conversation's rows. A session this ledger has never
    /// seen keys under its own id, which is the only key its own writer used.
    fn resolve_ink_line(&self, tug_session_id: &str) -> String {
        match self.session_ledger.as_ref() {
            Some(sessions) => sessions
                .line_of(tug_session_id)
                .unwrap_or_else(|| tug_session_id.to_string()),
            None => tug_session_id.to_string(),
        }
    }

    /// Handle a `list_refs { tug_session_id }` CONTROL request — the deck's
    /// refs-restore read. Broadcasts `list_refs_ok { tug_session_id, run }`,
    /// where `run` is the session's latest completed run or `null` (a missing
    /// ledger, or a session that has never searched).
    async fn do_list_refs(&self, tug_session_id: &str) {
        // Resolved query, unresolved echo — see `do_list_shell_exchanges`.
        let head = self.resolve_ink_line(tug_session_id);
        let run = self.refs_ledger.as_ref().and_then(|ledger| {
            ledger.list_refs(&head).unwrap_or_else(|err| {
                warn!(error = %err, %tug_session_id, "list_refs failed");
                None
            })
        });
        let body = serde_json::json!({
            "action": "list_refs_ok",
            "tug_session_id": tug_session_id,
            "run": run,
        });
        let _ = self.control_tx.send(Frame::new(
            FeedId::CONTROL,
            serde_json::to_vec(&body).expect("list_refs_ok serializes"),
        ));
    }

    /// Handle a `trash_session` CONTROL request. For ledger rows this
    /// deletes the row and moves the JSONL to in-place trash (the
    /// ledger refuses live rows). For external sessions — no ledger
    /// row, `project_dir` supplied by the picker — the JSONL move is
    /// the whole operation. Both paths are gated on terminal liveness.
    async fn do_trash_session(&self, session_id: &str, project_dir: Option<&str>) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            let body = serde_json::json!({
                "action": "trash_session_err",
                "session_id": session_id,
                "reason": "no_ledger",
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("trash_session_err serializes"),
            ));
            return;
        };
        // Terminal-liveness gate: trashing moves the JSONL out from
        // under any process holding the session — refuse while a live
        // terminal process is registered against it, mirroring the
        // ledger's own live-row refusal.
        let registry_root = self.terminal_registry_root();
        let sid = session_id.to_owned();
        let held = tokio::task::spawn_blocking(move || {
            Self::read_terminal_live_sessions(registry_root.as_deref()).contains_key(&sid)
        })
        .await
        .unwrap_or(false);
        if held {
            let body = serde_json::json!({
                "action": "trash_session_err",
                "session_id": session_id,
                "reason": "session_live_in_terminal",
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("trash_session_err serializes"),
            ));
            return;
        }
        match ledger.trash(session_id) {
            Ok(_) => {
                let _ = self
                    .control_tx
                    .send(build_session_removed_frame(session_id));
                let body = serde_json::json!({
                    "action": "trash_session_ok",
                    "session_id": session_id,
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_session_ok serializes"),
                ));
            }
            Err(crate::session_ledger::LedgerError::InvalidState(_)) => {
                let body = serde_json::json!({
                    "action": "trash_session_err",
                    "session_id": session_id,
                    "reason": "session_is_live",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_session_err serializes"),
                ));
            }
            Err(crate::session_ledger::LedgerError::NotFound(_)) => {
                // No ledger row. With a project_dir in the payload this
                // is an external session: the JSONL move is the whole
                // trash operation.
                if let Some(pd) = project_dir {
                    let ledger_arc = Arc::clone(ledger);
                    let pd_owned = pd.to_owned();
                    let sid = session_id.to_owned();
                    let moved = tokio::task::spawn_blocking(move || {
                        ledger_arc.trash_external_jsonl(&pd_owned, &sid)
                    })
                    .await
                    .unwrap_or(None);
                    if moved.is_some() {
                        let _ = self
                            .control_tx
                            .send(build_session_removed_frame(session_id));
                        let body = serde_json::json!({
                            "action": "trash_session_ok",
                            "session_id": session_id,
                        });
                        let _ = self.control_tx.send(Frame::new(
                            FeedId::CONTROL,
                            serde_json::to_vec(&body).expect("trash_session_ok serializes"),
                        ));
                        return;
                    }
                }
                let body = serde_json::json!({
                    "action": "trash_session_err",
                    "session_id": session_id,
                    "reason": "not_found",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_session_err serializes"),
                ));
            }
            Err(err) => {
                warn!(error = %err, session_id, "trash_session ledger error");
                let body = serde_json::json!({
                    "action": "trash_session_err",
                    "session_id": session_id,
                    "reason": "ledger_write_failed",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_session_err serializes"),
                ));
            }
        }
    }

    /// Handle a `rename_session` CONTROL request. Writes the name to the
    /// **line** ([P11]) and broadcasts a `session_updated` for the segment a
    /// restore would seat, so the chooser + the Z4B session chip pick it up
    /// live, then acks `rename_session_ok` / `_err`.
    ///
    /// Both acks carry the name they were asked for. CONTROL is a broadcast and
    /// the client renames optimistically, so the name is what lets it tell this
    /// ack from the one for a rename it has already superseded — and a refusal
    /// no client can place is a refusal it cannot undo.
    ///
    /// **The newest naming gesture wins**: a spelling another line already
    /// wears is taken from it rather than refused ([P11]). Each displaced line
    /// gets the same treatment the renamed one does — a `session_renamed` fact
    /// recording the loss, and a `session_updated` push so its chip falls back
    /// to its callsign without a re-fetch — and the ack's `displaced` list
    /// names them so the gesture can say whose name it took.
    async fn do_rename_session(&self, line_id: &str, name: Option<&str>) {
        let refuse = |reason: &str| {
            let body = serde_json::json!({
                "action": "rename_session_err",
                "line_id": line_id,
                "name": name,
                "reason": reason,
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("rename_session_err serializes"),
            ));
        };
        let Some(ledger) = self.session_ledger.as_ref() else {
            refuse("no_ledger");
            return;
        };
        // Read the name being replaced before it is gone — a rename fact that
        // said only the new name would be half the event.
        let Some(line) = ledger.get_line(line_id).ok().flatten() else {
            refuse("not_found");
            return;
        };
        let old_name = line.name;
        match ledger.rename(line_id, name) {
            Ok(displaced) => {
                // The fact files under the segment a resume would seat. The
                // fact base is keyed by session id, and that segment is the id
                // every other fact about this conversation is landing under.
                let segment = ledger.resume_segment_for_line(line_id).ok().flatten();
                if let Some(segment) = segment.as_ref() {
                    if let Err(err) =
                        ledger.record_fact(&crate::feeds::facts_library::session_renamed_fact(
                            crate::session_ledger::now_millis(),
                            &segment.session_id,
                            old_name.as_deref(),
                            name,
                        ))
                    {
                        warn!(error = %err, line_id, "rename fact write failed");
                    }
                    // Push the updated row so the chooser + chip reflect the
                    // rename without a re-fetch. The row is re-read rather than
                    // reused: the name reaches it through the line join ([P02]),
                    // so the copy taken before the write still carries the old
                    // one.
                    if let Ok(Some(row)) = ledger.get(&segment.session_id) {
                        // The scan-cache lookup rides the rename push too — see
                        // `build_session_updated_frame` for why omitting it
                        // would blank a known size and zero a scan-derived turn
                        // count. The usage lookup rides it for the same reason.
                        let metrics = ledger.scan_metrics_for(&segment.session_id).unwrap_or(None);
                        let usage = ledger.usage_for(&segment.session_id).unwrap_or(None);
                        let _ = self
                            .control_tx
                            .send(build_session_updated_frame(&row, metrics, usage));
                    }
                }
                // Every line the name was taken from is un-taught the same way
                // the renamed one is taught: the loss is a fact on its own
                // conversation, and the push is what makes its chip fall back
                // to the callsign live. The name it lost is the spelling that
                // was asked for — there is nothing else it could have been.
                for holder in &displaced {
                    let Some(segment) = ledger
                        .resume_segment_for_line(&holder.line_id)
                        .ok()
                        .flatten()
                    else {
                        continue;
                    };
                    if let Err(err) =
                        ledger.record_fact(&crate::feeds::facts_library::session_renamed_fact(
                            crate::session_ledger::now_millis(),
                            &segment.session_id,
                            name,
                            None,
                        ))
                    {
                        warn!(
                            error = %err,
                            line_id = holder.line_id.as_str(),
                            "displaced-rename fact write failed"
                        );
                    }
                    if let Ok(Some(row)) = ledger.get(&segment.session_id) {
                        let metrics = ledger.scan_metrics_for(&segment.session_id).unwrap_or(None);
                        let usage = ledger.usage_for(&segment.session_id).unwrap_or(None);
                        let _ = self
                            .control_tx
                            .send(build_session_updated_frame(&row, metrics, usage));
                    }
                }
                let body = serde_json::json!({
                    "action": "rename_session_ok",
                    "line_id": line_id,
                    "name": name,
                    // The lines that lost this name to the gesture, so the
                    // bulletin can say who it was taken from ([P11]).
                    "displaced": displaced
                        .iter()
                        .map(|holder| serde_json::json!({
                            "line_id": holder.line_id,
                            "tag": holder.tag,
                        }))
                        .collect::<Vec<_>>(),
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("rename_session_ok serializes"),
                ));
            }
            Err(crate::session_ledger::LedgerError::NotFound(_)) => refuse("not_found"),
            Err(err) => {
                warn!(error = %err, line_id, "rename_session ledger error");
                refuse("ledger_write_failed");
            }
        }
    }

    /// Handle a `set_session_private` CONTROL request ([P05], [Q01]).
    ///
    /// Writes the flag, pushes the row so the chip shows the resting state, and
    /// acks `set_session_private_ok` / `_err`. **No fact is recorded for the
    /// toggle itself** — recording the act of hiding would leak the hiding.
    ///
    /// The refusal carries the value it refused, the way the ack carries the
    /// value it wrote. The client toggles from what it holds, so a refused
    /// write's prior state is the negation of the request — and without that
    /// value on the wire the client cannot tell a refused "make it private"
    /// from a refused "make it public", which are opposite states to put back.
    async fn do_set_session_private(&self, session_id: &str, private: bool) {
        let err = |reason: &str| {
            serde_json::json!({
                "action": "set_session_private_err",
                "session_id": session_id,
                "private": private,
                "reason": reason,
            })
        };
        let Some(ledger) = self.session_ledger.as_ref() else {
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&err("no_ledger")).expect("set_session_private_err serializes"),
            ));
            return;
        };
        match ledger.set_session_private(session_id, private) {
            Ok(()) => {
                if let Ok(Some(row)) = ledger.get(session_id) {
                    let metrics = ledger.scan_metrics_for(session_id).unwrap_or(None);
                    let usage = ledger.usage_for(session_id).unwrap_or(None);
                    let _ = self
                        .control_tx
                        .send(build_session_updated_frame(&row, metrics, usage));
                }
                let body = serde_json::json!({
                    "action": "set_session_private_ok",
                    "session_id": session_id,
                    "private": private,
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("set_session_private_ok serializes"),
                ));
            }
            Err(crate::session_ledger::LedgerError::NotFound(_)) => {
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&err("not_found"))
                        .expect("set_session_private_err serializes"),
                ));
            }
            Err(e) => {
                warn!(error = %e, session_id, "set_session_private ledger error");
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&err("ledger_write_failed"))
                        .expect("set_session_private_err serializes"),
                ));
            }
        }
    }

    /// Handle a `trash_project_dir_sessions` CONTROL request. Drops every
    /// non-live row whose `project_dir` matches the request, broadcasts a
    /// `session_updated { removed: true }` per dropped id, and returns a
    /// count via `trash_project_dir_sessions_ok`. Used by the recents-
    /// eviction → ledger-eviction coupling.
    async fn do_trash_project_dir_sessions(&self, project_dir: &str) {
        let Some(ledger) = self.session_ledger.as_ref() else {
            let body = serde_json::json!({
                "action": "trash_project_dir_sessions_err",
                "project_dir": project_dir,
                "reason": "no_ledger",
            });
            let _ = self.control_tx.send(Frame::new(
                FeedId::CONTROL,
                serde_json::to_vec(&body).expect("trash_project_dir_sessions_err serializes"),
            ));
            return;
        };
        match ledger.trash_for_project_dir(project_dir) {
            Ok(dropped) => {
                for id in &dropped {
                    let _ = self.control_tx.send(build_session_removed_frame(id));
                }
                let body = serde_json::json!({
                    "action": "trash_project_dir_sessions_ok",
                    "project_dir": project_dir,
                    "count": dropped.len(),
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_project_dir_sessions_ok serializes"),
                ));
            }
            Err(err) => {
                warn!(error = %err, project_dir, "trash_for_project_dir failed");
                let body = serde_json::json!({
                    "action": "trash_project_dir_sessions_err",
                    "project_dir": project_dir,
                    "reason": "ledger_write_failed",
                });
                let _ = self.control_tx.send(Frame::new(
                    FeedId::CONTROL,
                    serde_json::to_vec(&body).expect("trash_project_dir_sessions_err serializes"),
                ));
            }
        }
    }

    /// Handle a `reset_session` CONTROL action.
    ///
    /// [D11]: reset preserves the workspace binding. We kill the current
    /// tugcode bridge (so a hung or misbehaving subprocess is torn down)
    /// but do NOT call `registry.release` or `registry.get_or_create`.
    /// The ledger entry stays in place — same `workspace_key`, same
    /// `project_dir`, same crash budget, same latest_metadata replay — so
    /// that the user's workspace feeds (file watcher, git poller) are
    /// never observably interrupted.
    ///
    /// On the wire we publish `closed` then `pending`, matching the
    /// historical close-then-spawn shape. The subsequent `spawning` /
    /// `live` frames are published by `spawn_session_worker` when the
    /// next CODE_INPUT frame arrives and the dispatcher transitions
    /// `Idle → Spawning`.
    async fn do_reset_session(
        &self,
        card_id: &str,
        tug_session_id: &TugSessionId,
        _client_id: ClientId,
    ) {
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            match ledger.get(tug_session_id) {
                Some(e) => e.clone(),
                None => return,
            }
        };

        // Cancel the current bridge worker and reset the per-session
        // state so the next CODE_INPUT can re-drive Idle → Spawning. The
        // workspace_key, project_dir, crash_budget, and latest_metadata
        // fields are intentionally preserved.
        //
        // Reset invalidates `claude_session_id` (in-memory clear +
        // tugbank delete) and flips `session_mode` back to `New` so the
        // next spawn is fresh. Without the mode flip, a card whose
        // session_mode was `Resume` would still spawn `--session-mode
        // resume`, and tugcode would fall back to `--resume <session_id>`
        // — finding the JSONL still on disk and restoring the
        // conversation the user explicitly asked to discard. The
        // invalidate-then-cancel ordering closes the persistence gap
        // before the bridge can be re-spawned: even if the cancel races
        // an overlapping CODE_INPUT, the next spawn sees `New` mode and
        // no claude_session_id, so it spawns truly fresh.
        //
        // Terminal-state guard: if a concurrent `close_session` won the
        // race and flipped the entry to `Closed`, reset must not
        // resurrect it. Bail out silently — the caller's reset is
        // meaningless for a dead session, and flipping back to `Idle`
        // would confuse any worker that later observed the stale Arc.
        // Captured before the clear below: the reset fact names the session
        // being discarded, and after this block there is no id left to name it
        // by.
        let mut cleared_claude_id: Option<String> = None;
        let resurrected = {
            let mut entry = entry_arc.lock().await;
            if entry.spawn_state == SpawnState::Closed {
                false
            } else {
                cleared_claude_id = entry.claude_session_id.clone();
                entry.claude_session_id = None;
                entry.session_mode = super::agent_bridge::SessionMode::New;
                entry.cancel.cancel();
                entry.cancel = CancellationToken::new();
                entry.spawn_state = SpawnState::Idle;
                // Reset makes the entry fresh, and that includes forgetting
                // that a child ever ran on it: a `/clear` is the user taking
                // the card, which the arc's taken-card arm has a better
                // receipt for than "its session ended". Without this the
                // gesture would read as a death at the very next sweep.
                entry.ever_live_here = false;
                entry.input_tx = None;
                true
            }
        };
        if !resurrected {
            return;
        }

        tracing::info!(
            target: "dev::session-lifecycle",
            event = "reset_session.cleared",
            card_id = card_id,
            tug_session_id = %tug_session_id,
        );

        // One fact for the reset. The closed→pending pair published below is
        // the card's state machine talking, not two more events — and the
        // ledger row is not transitioned here, so no `session.closed` fact
        // fires alongside it.
        if let (Some(ledger), Some(claude_id)) = (self.session_ledger.as_ref(), &cleared_claude_id)
        {
            let handle = ledger
                .get(claude_id)
                .ok()
                .flatten()
                .and_then(|row| row.tag)
                .unwrap_or_else(|| claude_id.clone());
            if let Err(err) = ledger.record_fact(&crate::feeds::facts_library::session_reset_fact(
                crate::session_ledger::now_millis(),
                claude_id,
                &handle,
            )) {
                warn!(error = %err, "reset fact write failed");
            }
        }

        self.session_state.publish_tagged(build_session_state_frame(
            tug_session_id,
            "closed",
            None,
        ));
        self.session_state.publish_tagged(build_session_state_frame(
            tug_session_id,
            "pending",
            None,
        ));
    }

    /// CODE_INPUT dispatcher task. Consumes CODE_INPUT frames from a single
    /// mpsc receiver (fed by the router in Step 8), parses `tug_session_id`,
    /// and routes each frame based on the ledger entry's `SpawnState`.
    pub async fn dispatcher_task(self: Arc<Self>, mut rx: mpsc::Receiver<Frame>) {
        while let Some(frame) = rx.recv().await {
            self.dispatch_one(frame).await;
        }
    }

    /// Dispatch a single CODE_INPUT frame. Extracted from `dispatcher_task` so
    /// tests can exercise the routing logic without spinning up a task + mpsc.
    pub async fn dispatch_one(&self, frame: Frame) {
        // Extract `tug_session_id` from the payload.
        let tug_session_id = match parse_tug_session_id(&frame.payload) {
            Some(id) => TugSessionId::new(id),
            None => {
                warn!("dispatcher: CODE_INPUT frame missing tug_session_id, dropping");
                return;
            }
        };

        // Inspect the payload's top-level fields once; the user_message
        // intercept below reads `type`, `text`, and `attachments` from
        // the same parse. A malformed payload yields `None`, which the
        // intercept treats as "skip the user_message branch and fall
        // through to the existing routing" — same as a payload whose
        // `type` is not `user_message`.
        let inspected = super::payload_inspector::InspectedPayload::from_slice(&frame.payload);

        // Look up the ledger entry.
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(&tug_session_id).cloned()
        };

        let Some(entry_arc) = entry_arc else {
            // No intent record — the client must `spawn_session` via CONTROL
            // before sending CODE_INPUT.
            let _ = self
                .control_tx
                .send(build_session_unknown_frame(&tug_session_id));
            return;
        };

        // ── user_message intercept ──────────────────────────────────────────
        //
        // For inbound `user_message` frames: mint an internal `journal_id`
        // and persist a pending row to the submission journal, then
        // forward the frame **unchanged**. Order is load-bearing:
        // row-persisted-before-forwarded. A failure before the forward
        // drops the inbound frame (the supervisor emits a CONTROL error);
        // a forwarded frame with no row is structurally impossible because
        // the forward only happens after `Ok` from `insert_pending_turn`.
        // The journal id is internal to tugcast — not surfaced on the
        // wire, never seen by tugcode (the merger reconciles by
        // session-scoped FIFO, not by id). Other CODE_INPUT types —
        // `tool_approval`, `interrupt`, `permission_mode`, `model_change`,
        // `session_command`, `stop_task`, `request_replay` — fall through
        // unchanged. See [DM08] / [Step 5.3](#step-5-3) in the
        // mid-turn-replay plan.
        if let Some("user_message") = inspected.as_ref().and_then(|i| i.msg_type()) {
            let inspected = inspected.as_ref().expect("checked Some above");
            let user_text = inspected.text.clone().unwrap_or_default();
            let user_attachments = inspected.attachments.clone().unwrap_or_default();
            let journal_id = uuid::Uuid::new_v4().to_string();
            let now = crate::session_ledger::now_millis();
            match self.sessions_recorder.insert_pending_turn(
                tug_session_id.as_str(),
                &journal_id,
                &user_text,
                &user_attachments,
                now,
            ) {
                Ok(()) => {
                    // A turn is opening: from here until the merger sees the
                    // closing `turn_complete` / `turn_cancelled`, the activity
                    // sampler attributes this session's OS work.
                    //
                    // And it is an *asked* turn ([P02]) — the one kind the arc
                    // runner's quiet-turn horizon may count against a stage.
                    {
                        let mut entry = entry_arc.lock().await;
                        entry.turn_active = true;
                        entry.turn_opener = Some(TurnOpener::Prompt);
                    }
                    // A door prompt binds with the keystroke, so the card
                    // reads `ARC` before the door's first tool call rather
                    // than after its last one. Anything else is untouched.
                    if let Some(arc) = arc_door_target(&user_text) {
                        self.bind_arc_at_the_door(&tug_session_id, &entry_arc, arc)
                            .await;
                    }
                }
                Err(err) => {
                    warn!(
                        error = %err,
                        tug_session_id = %tug_session_id,
                        "dispatcher: insert_pending_turn failed; dropping user_message",
                    );
                    let _ = self
                        .control_tx
                        .send(build_ledger_failure_frame(&tug_session_id));
                    return;
                }
            }
        }

        // ── the deck's own model selector ───────────────────────────────────
        //
        // Every frame a WebSocket client sends passes through here, and only
        // through here — the arc's runner puts its frames straight on
        // `input_tx`. So this is the one place that can tell the deck's choice
        // of model from the arc's, which is exactly the distinction [P15]'s
        // restore needs: when the arc ends, the card goes back to the last
        // model its user picked, not the one the last stage ran on.
        if let Some("model_change") = inspected.as_ref().and_then(|i| i.msg_type()) {
            if let Some(model) = parse_model_selector(&frame.payload) {
                // A *change*, not a repaint: writing a note when the selector
                // already equals `deck_model` would put a line in the log for
                // a no-op.
                let changed = {
                    let mut entry = entry_arc.lock().await;
                    let changed = entry.deck_model.as_deref() != Some(model.as_str());
                    entry.deck_model = Some(model.clone());
                    changed
                };
                // A switch mid-stage is real and belongs in the record, so it
                // goes where a switch belongs: the arc log, which `tugtool
                // arc record` prints and the Arcs card reads.
                //
                // The transcript's stage divider is deliberately **not**
                // touched, and `stage_model` on the session row is not
                // rewritten. The divider's subject is what the stage was
                // *seated* on, which stays true forever. Live it is one-shot
                // ink minted from the rotation's `session_segment` frame; on restore it is
                // composed from `stage_provenance`. Moving one and not the
                // other would make the live divider and the restored one
                // disagree about the same boundary — a new resting lie in
                // place of the old one — and moving the live one means editing
                // durable ink, which this codebase does not do.
                if changed {
                    self.note_model_switch(tug_session_id.as_str(), &model)
                        .await;
                }
            }
        }

        // Decide the routing action under the per-session lock. We extract
        // the decision and release the lock before doing any await-heavy
        // work (mpsc send, broadcast publish, spawn_session_worker).
        let decision: Decision = {
            let mut entry = entry_arc.lock().await;
            match entry.spawn_state {
                SpawnState::Idle => {
                    // This thread owns the Idle → Spawning transition per
                    // [R02]. Transition, queue the frame for the worker,
                    // and tell the caller to spawn.
                    entry.spawn_state.try_transition(SpawnState::Spawning).ok();
                    // Idle-entry invariant: the queue is freshly minted
                    // empty, so push always succeeds. If this ever fails
                    // we've bungled the invariant and the frame would be
                    // silently dropped — log loudly rather than panic.
                    match entry.queue.push(frame) {
                        QueuePush::Ok => {}
                        QueuePush::Overflow => {
                            tracing::error!(
                                session = %tug_session_id,
                                "BUG: Idle ledger entry had a non-empty queue on first CODE_INPUT"
                            );
                        }
                    }
                    Decision::Spawn
                }
                SpawnState::Spawning => {
                    // Buffer the frame until the worker drains.
                    match entry.queue.push(frame) {
                        QueuePush::Ok => Decision::Drop,
                        QueuePush::Overflow => Decision::Backpressure,
                    }
                }
                SpawnState::Live => {
                    if let Some(tx) = entry.input_tx.clone() {
                        Decision::Forward(tx, frame)
                    } else {
                        warn!("dispatcher: Live state but no input_tx set");
                        drop(frame);
                        Decision::Drop
                    }
                }
                SpawnState::Errored | SpawnState::Closed => {
                    warn!(
                        state = ?entry.spawn_state,
                        "dispatcher: dropping frame in terminal state"
                    );
                    drop(frame);
                    Decision::Drop
                }
            }
        };

        let decision_label = match &decision {
            Decision::Drop => "drop",
            Decision::Spawn => "spawn",
            Decision::Forward(_, _) => "forward",
            Decision::Backpressure => "backpressure",
        };
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "supervisor.dispatch_decision",
            tug_session_id = %tug_session_id,
            decision = decision_label,
        );
        match decision {
            Decision::Drop => {}
            Decision::Spawn => self.spawn_session_worker(&tug_session_id).await,
            Decision::Forward(tx, frame) => {
                let _ = tx.send(frame).await;
            }
            Decision::Backpressure => {
                let _ = self
                    .control_tx
                    .send(build_backpressure_frame(&tug_session_id));
            }
        }
    }

    /// Open a **provisional** job at a launching `tool_use` the deck would
    /// count as background work ([P04]).
    ///
    /// The latch arms here rather than at the `task_started` that follows,
    /// because the window `open_jobs` exists to cover starts at the launch.
    /// This used to only *record* the id in a side set, leaving the session
    /// readable as quiet between the launch and its confirmation; the
    /// incident's six background completions each lived in that gap.
    ///
    /// Replay-guarded like the fold itself: a `replay_batch`'s historical
    /// launches describe calls whose jobs died with the session that ran them.
    pub(super) async fn record_job_launch(&self, session_id: &TugSessionId, payload: &[u8]) {
        let Some(tool_use_id) = parse_background_launch(payload) else {
            return;
        };
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(session_id).cloned()
        };
        let Some(entry_arc) = entry_arc else {
            return;
        };
        let mut entry = entry_arc.lock().await;
        if entry.replay_brackets_open != 0 {
            return;
        }
        entry
            .open_jobs
            .insert(launch_key(&tool_use_id), std::time::Instant::now());
        tracing::debug!(
            target: "dev::ledger",
            event = "job_launched",
            session_id = %session_id,
            tool_use_id = %tool_use_id,
            open_jobs = entry.open_jobs.len(),
        );
    }

    /// Refresh an open job's liveness stamp from a `task_progress` heartbeat,
    /// so the reaper can tell silent-but-running work from a job whose
    /// terminal frame the wire never delivered. A tick for a job that is not
    /// open — a foreground subagent's, or one already closed — changes
    /// nothing.
    async fn refresh_job_stamp(&self, session_id: &TugSessionId, payload: &[u8]) {
        let Ok(value) = serde_json::from_slice::<serde_json::Value>(payload) else {
            return;
        };
        if value.get("type").and_then(|t| t.as_str()) != Some("task_progress") {
            return;
        }
        let Some(task_id) = nonempty_task_id(&value) else {
            return;
        };
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(session_id).cloned()
        };
        let Some(entry_arc) = entry_arc else {
            return;
        };
        let mut entry = entry_arc.lock().await;
        if let Some(stamp) = entry.open_jobs.get_mut(&task_id) {
            *stamp = std::time::Instant::now();
        }
    }

    /// Fold one `task_started` / `task_updated` / `wake_started` frame into the
    /// session's set of open background jobs, and answer whether that left it
    /// **quiet**.
    ///
    /// Quiet is the whole reason this exists: a turn ends when the model stops
    /// speaking, and the test sweep it backgrounded goes on running. Between
    /// those two moments the session looks idle and is not, and an arc offered
    /// for joining in that window is work nobody has finished checking.
    ///
    /// Guarded on the replay bracket for the same reason the turn edge is: a
    /// `replay_batch` carries historical `task_started` frames whose jobs died
    /// with the session that ran them, and folding those in would open jobs
    /// that can never close.
    ///
    /// Returns `false` for every frame that is not a job edge, for a session
    /// with no ledger entry, and for an edge that leaves work still running —
    /// so the caller's release path fires on exactly the transition into quiet.
    pub(super) async fn apply_job_edge(&self, session_id: &TugSessionId, payload: &[u8]) -> bool {
        let Some(edge) = parse_job_edge(payload) else {
            return false;
        };
        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(session_id).cloned()
        };
        let Some(entry_arc) = entry_arc else {
            return false;
        };
        let mut entry = entry_arc.lock().await;
        if entry.replay_brackets_open != 0 {
            return false;
        }
        match edge {
            JobEdge::Opened(task) => {
                // Gated on the launching call ([Q01], resolved by the Step 1
                // capture): the frame carries no backgrounded discriminant, so
                // a provisional `launch:` entry is the only honest evidence.
                // An unmatched `task_started` opens nothing — the launch
                // cannot have gone unobserved, because the merger consumes
                // each session's whole stream from registration and a
                // background job cannot outlive the claude process that
                // launched it, so every live `task_started` follows its
                // `tool_use` on the same stream; the replayed kind never
                // reaches this point (the bracket guard above). What an
                // unmatched frame actually is, is the foreground shape this
                // gate exists to refuse.
                //
                // The match is a **re-key**, not an open: the provisional
                // entry's stamp moves onto the `task_id`, so the reaper
                // clocks the job from the launch it actually began at rather
                // than from its confirmation.
                let launched = parse_task_started_launch_id(payload)
                    .and_then(|id| entry.open_jobs.remove(&launch_key(&id)));
                let Some(stamp) = launched else {
                    tracing::debug!(
                        target: "dev::ledger",
                        event = "job_open_rejected",
                        session_id = %session_id,
                        task_id = %task,
                        "task_started with no observed background launch — \
                         foreground work, not a job to track",
                    );
                    return false;
                };
                entry.open_jobs.insert(task.clone(), stamp);
                tracing::debug!(
                    target: "dev::ledger",
                    event = "job_opened",
                    session_id = %session_id,
                    task_id = %task,
                    frame = frame_family(payload),
                    open_jobs = entry.open_jobs.len(),
                );
            }
            JobEdge::Closed(task) => {
                let was_open = entry.open_jobs.remove(&task).is_some();
                // A wake means the model is speaking again, so the gap every
                // provisional entry was holding open is over — including the
                // scheduler's own re-init wake, which names no job at all.
                // Without this a launch whose `task_started` never arrived
                // would sit until the reaper, and the session would read busy
                // through turns it was plainly working.
                let mut provisional_closed = 0usize;
                if frame_family(payload) == "wake_started" {
                    entry.open_jobs.retain(|key, _| {
                        let provisional = key.starts_with(LAUNCH_KEY_PREFIX);
                        if provisional {
                            provisional_closed += 1;
                        }
                        !provisional
                    });
                }
                tracing::debug!(
                    target: "dev::ledger",
                    event = "job_closed",
                    session_id = %session_id,
                    task_id = %task,
                    frame = frame_family(payload),
                    was_open,
                    provisional_closed,
                    open_jobs = entry.open_jobs.len(),
                );
            }
        }
        entry.is_quiet()
    }

    /// Apply the per-frame journal intercept the merger runs on every
    /// outbound CODE_OUTPUT frame, **after** the wire-side broadcast has
    /// fired. Narrowed in [Step 5.3](#step-5-3) to a session-scoped FIFO
    /// mark-seen: every `turn_complete` / `turn_cancelled` frame deletes
    /// the oldest pending row in the session's journal. The frame is
    /// forwarded unchanged — this intercept does not read or write any
    /// payload field except the top-level `type` discriminator.
    ///
    /// Branches on the payload's top-level `type`:
    ///
    /// - `turn_complete` or `turn_cancelled` — call
    ///   [`SessionsRecorder::delete_oldest_pending_for_session`]. On
    ///   `Ok(Some)`, an info trace; on `Ok(None)` a warn
    ///   (`turn_complete_no_pending_journal_row` — claude responded for
    ///   a turn the journal didn't see, e.g. resume-of-an-existing-
    ///   conversation where the new tugcode picks up mid-stream); on
    ///   `Err`, a `warn!` (the frame has already been forwarded; the
    ///   wire is the source of truth, the journal lagging by one update
    ///   is telemetry).
    /// - any other type — no-op.
    ///
    /// `record_turn` (the existing trait method that bumps
    /// `sessions.turn_count`) continues to fire from `agent_bridge.rs`
    /// on the same `turn_complete` event — this intercept is additive
    /// and the two writes hit different tables.
    fn apply_outbound_turn_intercept(&self, session_id: &TugSessionId, frame: &Frame) {
        let Some(inspected) =
            super::payload_inspector::InspectedPayload::from_slice(&frame.payload)
        else {
            return;
        };
        match inspected.msg_type() {
            Some("turn_complete") | Some("turn_cancelled") => {
                let kind = inspected.msg_type().unwrap_or("");
                match self
                    .sessions_recorder
                    .delete_oldest_pending_for_session(session_id.as_str())
                {
                    Ok(Some(row)) => {
                        tracing::debug!(
                            target: "dev::ledger",
                            event = "merger.journal_row_deleted",
                            session_id = %session_id,
                            kind,
                            journal_id = %row.journal_id,
                        );
                    }
                    Ok(None) => {
                        warn!(
                            target: "dev::ledger",
                            event = "turn_complete_no_pending_journal_row",
                            session_id = %session_id,
                            kind,
                            "merger: {kind} for a session whose journal has no pending rows; \
                             frame forwarded unchanged",
                        );
                    }
                    Err(err) => {
                        warn!(
                            error = %err,
                            session_id = %session_id,
                            kind,
                            "merger: delete_oldest_pending_for_session failed (frame already forwarded)",
                        );
                    }
                }
            }
            _ => {}
        }
    }

    /// Per-bridge merger task. Consumes registrations from
    /// `merger_register_rx` and fans in each per-session output mpsc into
    /// the shared CODE_OUTPUT broadcast, the SESSION_SIDEBAND broadcast
    /// ([D14]), and `LedgerEntry::latest_metadata` (per-session). Runs until
    /// `cancel` is fired OR the register channel closes AND every
    /// per-session stream has drained.
    pub async fn merger_task(
        self: Arc<Self>,
        mut register_rx: mpsc::Receiver<MergerRegistration>,
        cancel: CancellationToken,
    ) {
        use tokio_stream::StreamMap;
        let mut streams: StreamMap<TugSessionId, ReceiverStream<Frame>> = StreamMap::new();
        // Once `register_rx` yields `None` (all senders dropped), we disable
        // that select arm so it doesn't spin-return on every iteration. If
        // all per-session streams have also drained by that point the task
        // exits cleanly; otherwise it keeps servicing in-flight streams
        // until they close.
        let mut register_closed = false;
        loop {
            if register_closed && streams.is_empty() {
                return;
            }
            tokio::select! {
                _ = cancel.cancelled() => return,
                maybe_register = register_rx.recv(), if !register_closed => {
                    match maybe_register {
                        Some((id, rx)) => {
                            streams.insert(id, ReceiverStream::new(rx));
                        }
                        None => {
                            // Register side dropped — disable the arm and
                            // fall through. Existing streams continue to
                            // drain; the top-of-loop guard exits once they
                            // are all gone.
                            register_closed = true;
                        }
                    }
                }
                maybe_frame = streams.next(), if !streams.is_empty() => {
                    let Some((id, frame)) = maybe_frame else { continue };
                    // Divert `activity_delta` frames off CODE_OUTPUT onto the
                    // ACTIVITY feed ([P13], [P15]). The payload already carries
                    // its `tug_session_id` (spliced in `relay_session_io`), so
                    // we only re-tag `FeedId::ACTIVITY` — mirroring the
                    // SESSION_SIDEBAND rewrap below, but a DIVERT not a copy:
                    // the sample must never ride the CODE_OUTPUT transcript
                    // stream or its shared ReplayBuffer (a replayed activity
                    // sample would strobe the deck's live meter). Skipping the
                    // journal gate is correct too — activity frames are not
                    // turn-completion markers.
                    if is_activity_delta(&frame.payload) {
                        self.activity
                            .publish_tagged(Frame::new(FeedId::ACTIVITY, frame.payload));
                        continue;
                    }
                    // Forward to shared CODE_OUTPUT broadcast (feeds the
                    // shared router-level replay ring per [D06], unchanged).
                    // The inbound frame is already tagged `CODE_OUTPUT` by
                    // `relay_session_io` so this send passes through
                    // unchanged.
                    self.code_output.publish_tagged(frame.clone());
                    // Turn-boundary tracking for the activity sampler: the
                    // closing `turn_complete` / `turn_cancelled` ends OS-work
                    // attribution; `wake_started` opens a wake turn (which has
                    // no inbound `user_message` to open it). Clearing is gated
                    // on no replay bracket being open — a `replay_batch`'s
                    // embedded historical `turn_complete` text matches the
                    // needle but must not end a live turn (`replay_started`
                    // has already incremented the bracket counter by the time
                    // the batch flows through here).
                    // The session's resident context window, which the arc
                    // reads at a step boundary to decide a compaction or a
                    // rotation. Both frames that carry usage write it: a
                    // `streaming_usage` keeps it current inside the turn, and
                    // the turn-final `cost_update` is the authoritative last
                    // write — and a `compact_boundary` retires it, because a
                    // compaction leaves the held number measuring a context
                    // that is gone.
                    if let Some(update) = context_window_update(&frame.payload) {
                        let entry_arc = {
                            let ledger = self.ledger.lock().await;
                            ledger.get(&id).cloned()
                        };
                        if let Some(entry_arc) = entry_arc {
                            let mut entry = entry_arc.lock().await;
                            match update {
                                ContextWindowUpdate::Measured(window) => {
                                    entry.context_window_tokens = Some(window)
                                }
                                // A replayed boundary is history: it says a
                                // compaction happened once, not that this
                                // session's context just came down. Guarded
                                // for the same reason the turn edge above is.
                                ContextWindowUpdate::Retired => {
                                    if entry.replay_brackets_open == 0 {
                                        entry.context_window_tokens = None;
                                    }
                                }
                            }
                        }
                    }
                    // claude's whole background roster. Logged rather than
                    // folded: the supervisor's `open_jobs` is built from
                    // edges, and this frame is the independent statement of
                    // the same fact — so a session stuck busy, or gone quiet
                    // early, is answerable from one log rather than from a
                    // reproduction.
                    if is_background_tasks_changed(&frame.payload) {
                        tracing::debug!(
                            target: "dev::ledger",
                            event = "background_tasks_changed",
                            session_id = %id,
                            payload_len = frame.payload.len(),
                        );
                    }
                    // A background job opening or closing. Tracked beside the
                    // turn flag because the two together are what "finished"
                    // means: a turn that ends with a test sweep still running
                    // has not finished anything yet. Guarded on the replay
                    // bracket for the same reason the turn edge is — a
                    // `replay_batch` carries historical `task_started` frames
                    // whose jobs died with the session that ran them.
                    if is_task_edge(&frame.payload) {
                        // The last job reporting with no wake behind it — a
                        // `Monitor` timeout ends that way — is the moment the
                        // session goes quiet, and nothing else will speak for
                        // it. So the work parked behind it is released on the
                        // same channels the turn edge uses.
                        if self.apply_job_edge(&id, &frame.payload).await {
                            if let Some(tx) = self.turn_complete_tx.get() {
                                let _ = tx.try_send(id.to_string());
                            }
                            if let Some(tx) = self.arc_tick_tx.get() {
                                let _ = tx.try_send(id.to_string());
                            }
                            self.registry.changeset_all_bump().notify_one();
                        }
                    }
                    // A launching `tool_use` the deck would count as
                    // background work — recorded so the `task_started` it
                    // produces can pass the gate in `apply_job_edge`. Replay
                    // is guarded inside: a historical launch must not arm the
                    // gate for a live frame.
                    if is_tool_use(&frame.payload) {
                        self.record_job_launch(&id, &frame.payload).await;
                    }
                    // A background agent's heartbeat — not a job edge, but it
                    // proves the job is alive, which is what keeps the reaper
                    // off genuinely long-running work.
                    if is_task_progress(&frame.payload) {
                        self.refresh_job_stamp(&id, &frame.payload).await;
                    }
                    if is_turn_end(&frame.payload) || is_wake_started(&frame.payload) {
                        let entry_arc = {
                            let ledger = self.ledger.lock().await;
                            ledger.get(&id).cloned()
                        };
                        if let Some(entry_arc) = entry_arc {
                            let mut entry = entry_arc.lock().await;
                            if is_wake_started(&frame.payload) {
                                entry.turn_active = true;
                                // The harness opened this one, not the stage's
                                // asker ([P02]).
                                entry.turn_opener = Some(TurnOpener::Wake);
                            } else if entry.replay_brackets_open == 0 {
                                entry.turn_active = false;
                                entry.turns_ended += 1;
                                // Split the count by what opened the turn. An
                                // unrecorded opener — a turn inherited across a
                                // restart — counts as a prompt, which is
                                // today's behaviour and the direction R05
                                // accepts.
                                if entry.turn_opener == Some(TurnOpener::Wake) {
                                    entry.wake_turns_ended += 1;
                                } else {
                                    entry.prompt_turns_ended += 1;
                                }
                                entry.turn_opener = None;
                                entry.turn_api_error = turn_ended_in_api_error(&frame.payload);
                                entry.turn_cancelled = turn_ended_in_user_cancel(&frame.payload);
                                // The turn boundary the arc demands has
                                // been reached: whatever this turn closed is
                                // no longer *this* turn's business, and the
                                // gate opens again (W8).
                                entry.step_closed_this_turn = None;
                                drop(entry);
                                // The session went idle: an arc parked behind it
                                // because the gate refuses to move a branch
                                // mid-turn can now be caught up.
                                if let Some(tx) = self.turn_complete_tx.get() {
                                    let _ = tx.try_send(id.to_string());
                                }
                                // The same edge, for the arc runner ([P05]):
                                // a stage finishes by finishing a turn, and
                                // that is the moment its documents have just
                                // changed.
                                if let Some(tx) = self.arc_tick_tx.get() {
                                    let _ = tx.try_send(id.to_string());
                                }
                                // And again for the wheel ([P04]): a
                                // rotation asked for from inside this turn was
                                // parked rather than performed, precisely so
                                // it lands here instead of killing the claude
                                // that asked for it.
                                if let Some(tx) = self.wheel_tick_tx.get() {
                                    let _ = tx.try_send(id.to_string());
                                }
                            }
                        }
                    }
                    // Per-session system_metadata capture + broadcast per
                    // [D14]. CRITICAL: rewrap as `FeedId::SESSION_SIDEBAND`
                    // before publishing / storing. `Frame::encode()`
                    // serializes `Frame.feed_id` as the first wire byte, so
                    // a subscriber registered via
                    // `register_stream(FeedId::SESSION_SIDEBAND, ...)`
                    // would otherwise receive a frame tagged CODE_OUTPUT and
                    // route it to the wrong client-side store. Both the
                    // live publish AND the `latest_metadata` slot used by
                    // event-driven replay in `do_spawn_session` must hold
                    // the SESSION_SIDEBAND-tagged Frame.
                    if is_system_metadata(&frame.payload) {
                        let meta_frame =
                            Frame::new(FeedId::SESSION_SIDEBAND, frame.payload.clone());
                        let entry_arc = {
                            let ledger = self.ledger.lock().await;
                            ledger.get(&id).cloned()
                        };
                        if let Some(entry_arc) = entry_arc {
                            let mut entry = entry_arc.lock().await;
                            entry.latest_metadata = Some(meta_frame.clone());
                        }
                        self.session_sideband.publish_tagged(meta_frame);
                    } else if is_session_capabilities(&frame.payload) {
                        // Turn-free `initialize` capabilities ([#step-2a]).
                        // Rewrap onto SESSION_SIDEBAND (same rationale as
                        // `system_metadata`: the FeedStore keeps only the
                        // latest payload per feed, and the client routes by
                        // wire feed-id) so the session card's metadata store
                        // receives it. Retained in its own per-session slot
                        // (`latest_capabilities`, distinct from the
                        // `latest_metadata` system_metadata slot) so a card
                        // that binds after the one-shot broadcast — reconnect,
                        // HMR remount — gets the model list replayed on bind.
                        let cap_frame =
                            Frame::new(FeedId::SESSION_SIDEBAND, frame.payload.clone());
                        let entry_arc = {
                            let ledger = self.ledger.lock().await;
                            ledger.get(&id).cloned()
                        };
                        if let Some(entry_arc) = entry_arc {
                            let mut entry = entry_arc.lock().await;
                            entry.latest_capabilities = Some(cap_frame.clone());
                        }
                        // Persist alongside the in-memory slot so the
                        // catalog survives a tugcast restart: the slot dies
                        // with the process, and a resumed session's next
                        // handshake is health-gated (~2s after spawn at
                        // best) — the sqlite row bridges that window at
                        // bind time (`persisted_capabilities_replay_frame`).
                        // Best-effort like `record_session_metadata`: a
                        // write failure degrades to the pre-persistence
                        // behavior, never blocks the live broadcast.
                        if let Some(sql) = self.session_ledger.as_ref() {
                            let captured_at = std::time::SystemTime::now()
                                .duration_since(std::time::UNIX_EPOCH)
                                .map(|d| d.as_millis() as i64)
                                .unwrap_or(0);
                            if let Err(e) = sql.record_session_capabilities(
                                id.as_str(),
                                &cap_frame.payload,
                                captured_at,
                            ) {
                                warn!(
                                    session_id = %id,
                                    error = %e,
                                    "record_session_capabilities failed; broadcasting without persistence"
                                );
                            }
                        }
                        self.session_sideband.publish_tagged(cap_frame);
                    } else if is_rate_limit_event(&frame.payload) {
                        // Per-turn subscription-quota broadcast ([#step-3]).
                        // Rewrap onto SESSION_SIDEBAND (same rationale as
                        // `system_metadata` / `session_capabilities`: the
                        // FeedStore keeps only the latest payload per feed and
                        // the client routes by wire feed-id) so the session card's
                        // metadata store — not the high-churn CODE_OUTPUT
                        // transcript store — receives it. Retained in its own
                        // per-session slot (`latest_rate_limit`) so a card that
                        // binds after the last broadcast (reconnect, HMR
                        // remount) replays the quota state on bind, which
                        // matters most when the session is hard rate-limited
                        // and cannot start a turn to refresh it.
                        let rl_frame =
                            Frame::new(FeedId::SESSION_SIDEBAND, frame.payload.clone());
                        let entry_arc = {
                            let ledger = self.ledger.lock().await;
                            ledger.get(&id).cloned()
                        };
                        if let Some(entry_arc) = entry_arc {
                            let mut entry = entry_arc.lock().await;
                            entry.latest_rate_limit = Some(rl_frame.clone());
                        }
                        self.session_sideband.publish_tagged(rl_frame);
                    }
                    // Forward-before-mutate: the wire-side broadcast above
                    // is the user-visible signal and must not be delayed
                    // by a database write. The journal mark-seen here is
                    // best-effort telemetry from the user's perspective;
                    // it becomes load-bearing only on the next runReplay,
                    // by which time the write has long since committed.
                    //
                    // Step 5.10: process_outbound_frame_journal_gate first
                    // updates the per-session replay-bracket counter from
                    // replay_started / replay_complete markers, then gates
                    // apply_outbound_turn_intercept on `replay_brackets_open == 0`
                    // so replay-emitted committed-turn frames don't pop
                    // the user's pending journal row.
                    self.process_outbound_frame_journal_gate(&id, &frame).await;
                }
            }
        }
    }

    /// Bracket-aware wrapper around [`Self::apply_outbound_turn_intercept`].
    /// Tracks per-session `LedgerEntry::replay_brackets_open` based on the
    /// `replay_started` / `replay_complete` frames the merger forwards,
    /// and gates the FIFO journal-pop intercept on the counter being zero.
    ///
    /// Why this gate exists (mid-turn-replay
    /// [Step 5.10](arc/tugplan-dev-mid-turn-replay.md#step-5)):
    /// `runReplay`'s `translateJsonlSession` emits `turn_complete` frames
    /// for every committed turn in the JSONL. Those frames flow through
    /// the merger task on the same path live `turn_complete`s do.
    /// Step 5.3's pure-FIFO intercept (`delete_oldest_pending_for_session`)
    /// can't tell replay-emitted from live, and the FIRST replay
    /// `turn_complete` to arrive on a session with a still-pending journal
    /// row pops that row — destroying the never-drop guarantee for any
    /// inflight submission whose runReplay fires while it's still pending.
    /// The HMR-mid-stream regression in the plan's close-out manual
    /// smoke surfaced this. The gate suppresses the intercept while the
    /// counter is non-zero.
    ///
    /// Counter (not bool) for defense-in-depth against bridge-crash-mid-
    /// replay: a bridge that emits `replay_started` and dies (kill -9,
    /// panic, OOM before `runReplay`'s `finally` runs) would, with a
    /// bool, leave the gate stuck-open forever and silently drop every
    /// future live journal-pop. The counter shape doesn't fix that
    /// directly — a stuck-non-zero counter has the same effect — but it
    /// makes a stray `replay_complete` on a closed bracket a no-op
    /// (saturating-decrement at 0) instead of underflowing a bool into
    /// "open" state. tugcode's `runReplay` re-entrancy guard prevents
    /// legitimate overlapping brackets, so in healthy operation the
    /// counter is 0 between brackets and 1 during a bracket.
    async fn process_outbound_frame_journal_gate(&self, session_id: &TugSessionId, frame: &Frame) {
        let Some(inspected) =
            super::payload_inspector::InspectedPayload::from_slice(&frame.payload)
        else {
            return;
        };
        let msg_type = inspected.msg_type();
        // Match before grabbing the entry — `_` covers most frames and
        // we don't need to touch the ledger map for them.
        match msg_type {
            Some("replay_started")
            | Some("replay_complete")
            | Some("turn_complete")
            | Some("turn_cancelled") => {}
            _ => return,
        }

        let entry_arc = {
            let ledger = self.ledger.lock().await;
            ledger.get(session_id).cloned()
        };
        let Some(entry_arc) = entry_arc else { return };

        match msg_type {
            Some("replay_started") => {
                let mut entry = entry_arc.lock().await;
                entry.replay_brackets_open = entry.replay_brackets_open.saturating_add(1);
                tracing::debug!(
                    target: "dev::ledger",
                    event = "merger.replay_bracket_open",
                    session_id = %session_id,
                    depth = entry.replay_brackets_open,
                );
            }
            Some("replay_complete") => {
                let mut entry = entry_arc.lock().await;
                entry.replay_brackets_open = entry.replay_brackets_open.saturating_sub(1);
                tracing::debug!(
                    target: "dev::ledger",
                    event = "merger.replay_bracket_close",
                    session_id = %session_id,
                    depth = entry.replay_brackets_open,
                );
            }
            Some("turn_complete") | Some("turn_cancelled") => {
                let in_replay = {
                    let entry = entry_arc.lock().await;
                    entry.replay_brackets_open > 0
                };
                if in_replay {
                    tracing::debug!(
                        target: "dev::ledger",
                        event = "merger.intercept_skipped_in_replay_bracket",
                        session_id = %session_id,
                        kind = msg_type.unwrap_or(""),
                    );
                } else {
                    self.apply_outbound_turn_intercept(session_id, frame);
                    let claude_id = {
                        let entry = entry_arc.lock().await;
                        entry.claude_session_id.clone()
                    };
                    if let Some(claude_id) = claude_id {
                        self.spawn_session_metrics_refresh(claude_id);
                    }
                }
            }
            _ => unreachable!("filtered above"),
        }
    }

    /// Kick the turn-end scan-metrics refresh for a session, detached ([D132]).
    ///
    /// A turn ending is exactly when a masthead's activity line is read, and it
    /// was exactly when the scan-derived turn count and size were most stale —
    /// the picker scan was their only production writer. This re-derives both
    /// for the one session and pushes them.
    ///
    /// Detached and on a blocking thread: the frame the user is waiting for has
    /// already been forwarded by the time the merger reaches here, and the
    /// refresh is file I/O plus a parse, which must not occupy the merger's
    /// single loop. Every failure is silence — the numbers then stay exactly as
    /// stale as they were before this path existed, which is not a regression.
    ///
    /// Keyed by the **claude** session id, because that is what both the ledger
    /// row and the JSONL filename are keyed by.
    fn spawn_session_metrics_refresh(&self, claude_session_id: String) {
        let Some(ledger) = self.session_ledger.clone() else {
            return;
        };
        let control_tx = self.control_tx.clone();
        tokio::task::spawn_blocking(move || {
            let Ok(Some(row)) = ledger.get(&claude_session_id) else {
                return;
            };
            let Some(metrics) = crate::external_sessions::refresh_session_metrics(
                &ledger,
                &row.project_dir,
                &claude_session_id,
            ) else {
                // Nothing changed on disk, or the file is unreadable. Either
                // way there is no new number to announce.
                return;
            };
            // Re-read: the refresh just moved `turn_count` on this row.
            let Ok(Some(row)) = ledger.get(&claude_session_id) else {
                return;
            };
            let usage = ledger.usage_for(&claude_session_id).unwrap_or(None);
            let _ = control_tx.send(build_session_updated_frame(&row, Some(metrics), usage));
        });
    }

    /// Spawn the per-session agent bridge. Creates per-session stdin/stdout
    /// mpscs, registers the output rx with the merger, installs `input_tx`
    /// in the ledger entry, and launches [`run_session_bridge`] in a
    /// detached tokio task. The bridge task supervises the subprocess
    /// lifecycle (handshake, crash budget, splice stamping) per [D07].
    ///
    /// # Ledger state transitions
    ///
    /// Unlike Step 5's scaffold, this function does **not** promote the
    /// ledger entry to `SpawnState::Live`. The state stays at `Spawning`
    /// until the bridge reads `session_init` from the subprocess — at that
    /// point the bridge itself performs the atomic promote (flip state,
    /// drain the per-session queue into `input_tx`, publish the wire
    /// `SESSION_STATE = live` frame) inside a single ledger-entry lock
    /// acquisition. This keeps ledger `Live` and wire `live` semantically
    /// identical ("handshake succeeded and Claude reported its session_id")
    /// and eliminates the window where the dispatcher could forward frames
    /// to an un-handshaken subprocess through a bridge that had not yet
    /// started pumping stdin.
    ///
    /// While the state is `Spawning`, the dispatcher's `Spawning` branch
    /// buffers CODE_INPUT into `LedgerEntry::queue`. The bridge's
    /// `session_init` promote drains that queue into `input_tx` atomically
    /// with the state flip, so frame order is preserved across the
    /// transition.
    ///
    /// # Ordering invariant
    ///
    /// 1. Lookup the ledger entry.
    /// 2. Register the per-session output receiver with the merger.
    /// 3. *Only then* install `input_tx`.
    ///
    /// Install `input_tx` only after merger registration: if the merger has died and the
    /// register send fails after `input_tx` is installed, the dispatcher
    /// would happily forward frames into a Sender whose Receiver is owned
    /// by nothing. Registering first means a dead merger is detected
    /// before any visible ledger state is mutated.
    pub async fn spawn_session_worker(&self, tug_session_id: &TugSessionId) {
        tracing::info!(
            target: "dev::session-lifecycle",
            event = "supervisor.spawn_worker_start",
            tug_session_id = %tug_session_id,
        );
        let entry_arc = {
            let map = self.ledger.lock().await;
            match map.get(tug_session_id) {
                Some(e) => e.clone(),
                None => return,
            }
        };

        let (input_tx, input_rx) = mpsc::channel::<Frame>(256);
        let (merger_per_session_tx, merger_per_session_rx) = mpsc::channel::<Frame>(256);

        // Register the per-session output receiver with the merger
        // BEFORE touching ledger state. A dead merger is detected here and
        // short-circuits the spawn with no ledger mutation — preventing
        // the B2-class bug where a failed register would leave `input_tx`
        // set against a Receiver that no merger owns.
        if self
            .merger_register_tx
            .send((tug_session_id.clone(), merger_per_session_rx))
            .await
            .is_err()
        {
            warn!(
                session = %tug_session_id,
                "merger register channel closed; flipping session to errored"
            );
            // Transition the entry out of Spawning so subsequent CODE_INPUT
            // drops (via the dispatcher's terminal-state branch) rather
            // than stalls forever in the queue.
            let mut entry = entry_arc.lock().await;
            if entry.spawn_state == SpawnState::Spawning {
                entry.spawn_state = SpawnState::Errored;
                drop(entry);
                self.session_state.publish_tagged(build_session_state_frame(
                    tug_session_id,
                    "errored",
                    Some("merger_unavailable"),
                ));
            }
            return;
        }

        // Install the dispatcher-side sender and clone the
        // cancellation token. Do **not** drain the queue or transition to
        // Live — that's the bridge's job on `session_init` (see above).
        //
        // Reset `replay_brackets_open` to zero on every bridge respawn.
        // The counter tracks `replay_started` / `replay_complete` markers
        // emitted by the bridge's `runReplay`. A bridge that died between
        // emitting `replay_started` and `replay_complete` would leave
        // the counter stuck non-zero — the new bridge's brackets would
        // then nest into the stale outer bracket and the gate would
        // skip live `turn_complete`s indefinitely. Reset here closes
        // the stuck-state risk: each fresh bridge starts with a clean
        // gate, regardless of whether the previous bridge crashed
        // mid-replay.
        let cancel_for_bridge = {
            let mut entry = entry_arc.lock().await;
            if entry.spawn_state != SpawnState::Spawning {
                // Another task already handled the transition (or the
                // entry was closed out from under us). The stream we just
                // registered is orphaned — when `merger_per_session_tx`
                // drops at end of function, the merger's ReceiverStream
                // will yield None and be auto-removed from the StreamMap.
                return;
            }
            entry.input_tx = Some(input_tx.clone());
            entry.replay_brackets_open = 0;
            entry.cancel.clone()
        };
        // `input_tx` is stashed in the ledger entry; the bridge drains it
        // via the per-session queue on session_init. Drop our local clone
        // so only the dispatcher owns the send side after this point.
        drop(input_tx);

        self.session_state.publish_tagged(build_session_state_frame(
            tug_session_id,
            "spawning",
            None,
        ));

        // Launch the real bridge in a detached task.
        let spawner = (self.spawner_factory)();
        let state_tx = self.session_state.sender();
        let control_tx_for_bridge = Some(self.control_tx.clone());
        let tug_session_id_owned = tug_session_id.clone();
        let entry_arc_bridge = entry_arc.clone();
        // Per-session workspace path. Read from the ledger entry so
        // each session's tugcode subprocess gets its own cwd. Also
        // thread `session_mode` so the tugcode subprocess receives
        // `--session-mode new|resume`. The sessions recorder lets the
        // bridge transition the ledger row when it sees `session_init`,
        // `result`, `resume_failed`, or terminal teardown on the IPC stream.
        let (project_dir, session_mode, permission_mode) = {
            let entry = entry_arc.lock().await;
            (
                entry.project_dir.clone(),
                entry.session_mode,
                entry.permission_mode.clone(),
            )
        };
        let sessions_recorder = self.sessions_recorder.clone();
        let session_ledger_for_bridge = self.session_ledger.clone();
        let changeset_bumper_for_bridge =
            crate::feeds::changeset::ChangesetBumper::new(Arc::clone(&self.registry));
        tokio::spawn(async move {
            run_session_bridge(
                tug_session_id_owned,
                entry_arc_bridge,
                input_rx,
                merger_per_session_tx,
                state_tx,
                control_tx_for_bridge,
                spawner,
                project_dir,
                session_mode,
                permission_mode,
                sessions_recorder,
                session_ledger_for_bridge,
                changeset_bumper_for_bridge,
                cancel_for_bridge,
                DEFAULT_RETRY_DELAY,
            )
            .await;
        });
    }

    /// Drop per-client affinity state on WebSocket teardown. Does NOT touch
    /// ledger state or tugbank — a client disconnecting is not a session
    /// close.
    pub async fn on_client_disconnect(&self, client_id: ClientId) {
        {
            let mut cs = self.client_sessions.lock().await;
            cs.remove(&client_id);
        }
        // A departed deck's seatings must not keep counting toward the
        // changeset's liveness — drop them (and recompute) with the socket.
        if super::deck_seatings::drop_deck_seatings(client_id) {
            self.registry.changeset_all_bump().notify_one();
        }
    }

    /// Re-materialize ledger entries from the sqlite-backed
    /// [`SessionLedger`].
    ///
    /// Called once at startup from `main.rs`. Walks every resumable row
    /// (see [`SessionLedger::list_with_card_id`] for the filter) and
    /// inserts a fresh `Idle` [`LedgerEntry`] for each `session_id`
    /// that is not already present in the in-memory ledger map.
    /// Returns the number of entries that were newly inserted.
    ///
    /// Per [F15] this path does **not**:
    ///
    /// - touch `client_sessions` — the rebind has no WebSocket client, so
    ///   any sentinel `ClientId` inserted here would be a permanent ghost
    ///   with no cleanup trigger. Real clients connecting after startup
    ///   send their own `spawn_session` CONTROL frames via [D14]'s normal
    ///   flow, which populate `client_sessions` for the real client_id.
    /// - mutate the sqlite ledger — the helper is strictly read-only.
    /// - publish any `SESSION_STATE` frames — the rebound entries are
    ///   unobservable until a real client subsequently calls `spawn_session`
    ///   for one of them, at which point the existing entry is reused and
    ///   the normal `pending` publish fires.
    pub async fn rebind_from_ledger(&self) -> Result<usize, crate::session_ledger::LedgerError> {
        let Some(ledger_db) = self.session_ledger.as_ref() else {
            return Ok(0);
        };
        let rows = ledger_db.list_with_card_id()?;
        let mut inserted = 0usize;
        // We acquire workspaces via `registry.get_or_create` outside the
        // ledger mutex (it takes its own std::sync::Mutex internally), so
        // we can't hold the ledger across the loop. Iterate per-record:
        // validate → get_or_create → lock ledger briefly → insert.
        for row in rows {
            let Some(card_id) = row.card_id.clone() else {
                continue;
            };
            let project_dir = PathBuf::from(&row.project_dir);

            // Adopt the canonical workspace key persisted on the ledger row
            // rather than recomputing it from `project_dir`. Recomputing via
            // `registry.canonical_key` runs `std::fs::metadata` + `canonicalize`
            // on the project directory, touching the filesystem for every
            // historical project on boot — enough to trip a macOS TCC consent
            // prompt for any dir under Desktop / Documents / Downloads or
            // reached through a firmlink. The stored key was canonicalized by
            // `get_or_create` when the session first bound and written by
            // `record_spawn`; it is exactly what a recompute would yield, minus
            // the fs touch. The workspace itself is still registered lazily —
            // only when a client actually re-spawns the session
            // (`do_spawn_session` → `get_or_create`), which also re-validates
            // the directory and rejects a since-removed path, so deferring
            // validation here costs nothing beyond a harmless stale in-memory
            // entry until the next spawn.
            if row.workspace_key.is_empty() {
                warn!(
                    card_id,
                    session_id = row.session_id.as_str(),
                    path = ?project_dir,
                    "rebind: dropping ledger row with empty workspace_key"
                );
                continue;
            }
            let workspace_key = WorkspaceKey::from_canonical(&row.workspace_key);

            // The ledger row's `session_id` is claude's id (post
            // session_init). Use it as the tug_session_id for the
            // rebound entry — for un-forked sessions the two ids are
            // identical, and for forked sessions claude's id is what
            // `--resume <id>` accepts so the next spawn will work
            // against the JSONL on disk regardless.
            let tug_session_id = TugSessionId::new(row.session_id.clone());

            // Resume mode is the always-correct restore intent: we have
            // a recorded session, the client wants its history. The
            // defense-in-depth path in `do_spawn_session` upgrades
            // legacy entries to the client's requested mode when
            // `spawn_state == Idle`, so a fresh-mode spawn from the
            // picker against the same id still works.
            let rebound_mode = SessionMode::Resume;

            // Insert the ledger entry — or skip if one already exists (this
            // function is idempotent per [F15]). No workspace to release:
            // `canonical_key` registered nothing.
            let mut ledger = self.ledger.lock().await;
            if ledger.contains_key(&tug_session_id) {
                continue;
            }
            let mut entry = LedgerEntry::new(
                tug_session_id.clone(),
                workspace_key,
                project_dir,
                rebound_mode,
                CrashBudget::new(3, Duration::from_secs(60)),
            );
            // Carry the persisted `claude_session_id` so the first
            // spawn after rebind threads `--resume-session <id>` through
            // the spawner. The ledger's session_id IS claude's id post
            // session_init.
            entry.claude_session_id = Some(row.session_id.clone());
            entry.turns_ended = u32::try_from(row.turn_count).unwrap_or(0);
            // The row records turns, not their openers, so the seed reads them
            // all as asked ([P02], Risk R05) — the same conservative direction
            // an unrecorded opener takes at a turn's end.
            entry.prompt_turns_ended = entry.turns_ended;
            entry.wake_turns_ended = 0;
            entry.turn_opener = None;
            // Carry the card binding so the live-elsewhere check fires
            // correctly on a cross-card resume request after rebind.
            entry.card_id = Some(card_id.clone());
            // The line the rebound entry is on ([P04]) — read off the row, so
            // a session restored from the ledger at boot attaches its next
            // segment to the line it already belongs to.
            entry.line_id = Some(row.line_id.clone());
            tracing::info!(
                target: "dev::session-lifecycle",
                event = "rebind.entry",
                card_id = card_id.as_str(),
                tug_session_id = %tug_session_id,
                rebound_mode = rebound_mode.as_wire_str(),
                mode_source = "ledger",
                claude_session_id = row.session_id.as_str(),
            );
            ledger.insert(tug_session_id, Arc::new(Mutex::new(entry)));
            inserted += 1;
        }
        Ok(inserted)
    }

    /// Install this supervisor as the join pilot's runner ([P01]).
    ///
    /// Called once from startup, after the supervisor is in its `Arc`. The
    /// handle is weak: the pilot is a process-global and must not be what keeps
    /// a supervisor alive.
    pub fn register_pilot_runner(self: &Arc<Self>) {
        crate::feeds::join_pilot::register_runner(Box::new(SupervisorPilotRunner {
            supervisor: Arc::downgrade(self),
        }));
    }
}

/// The join pilot's runner, backed by the supervisor ([P01]).
///
/// The pilot's predicate runs on the changeset recompute, which is a cache with
/// no route back to the supervisor — and the scribe context, the CONTROL
/// sender, and the recompute bump all live on the supervisor. This is the
/// bridge, and it is deliberately thin: it performs no admission and no mark
/// work, both of which the pilot already did under its occupancy guard.
struct SupervisorPilotRunner {
    supervisor: std::sync::Weak<AgentSupervisor>,
}

#[async_trait::async_trait]
impl crate::feeds::join_pilot::PilotRunner for SupervisorPilotRunner {
    async fn reconcile(
        &self,
        project_dir: &str,
        arc: &str,
        occupancy: crate::feeds::join_occupancy::JoinOccupancy,
    ) {
        let Some(supervisor) = self.supervisor.upgrade() else {
            return;
        };
        // The very same ladder a `changeset_join_resolve` press runs — scribe
        // rung and resolver audit, ending at a standing candidate.
        supervisor
            .run_resolve_ladder(project_dir, arc, occupancy)
            .await;
    }
}

