    /// Correctness must not ride a droppable channel.
    ///
    /// CONTROL is `LagPolicy::Warn` — a frame may simply not arrive, and a lost
    /// `_ok` used to lose a real candidate forever. Here every CONTROL send
    /// fails outright (no receiver at all), and the resolve still has to land
    /// in git and still has to show up in the state the feed composes.
    #[tokio::test]
    async fn a_resolve_survives_losing_every_control_frame() {
        use std::process::Command;

        fn git(dir: &std::path::Path, args: &[&str]) {
            let ok = Command::new("git")
                .current_dir(dir)
                .args(args)
                .status()
                .unwrap()
                .success();
            assert!(ok, "git {args:?} failed");
        }

        let (sup, _state_rx, _meta_rx, control_rx) = make_supervisor_with_store();

        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        git(&root, &["init", "-b", "main"]);
        git(&root, &["config", "user.name", "t"]);
        git(&root, &["config", "user.email", "t@t"]);
        std::fs::write(root.join("f.txt"), "A\n").unwrap();
        git(&root, &["add", "-A"]);
        git(&root, &["commit", "-m", "base"]);
        git(&root, &["branch", "tugarc/demo"]);
        git(&root, &["config", "branch.tugarc/demo.tugbase", "main"]);
        git(&root, &["switch", "-q", "tugarc/demo"]);
        std::fs::write(root.join("f.txt"), "B\n").unwrap();
        git(&root, &["commit", "-am", "r1"]);
        git(&root, &["switch", "-q", "main"]);
        std::fs::write(root.join("f.txt"), "C\n").unwrap();
        git(&root, &["commit", "-am", "main to C"]);

        let stub = root.join("stub-driver.sh");
        std::fs::write(&stub, "#!/bin/sh\nprintf 'RESOLVED\\n' > \"$4\"\n").unwrap();
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&stub, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        git(
            &root,
            &["config", "tugarc.mergedriver", &stub.to_string_lossy()],
        );

        let cancel = CancellationToken::new();
        let _entry = sup.registry.get_or_create(&root, cancel.clone()).unwrap();
        let root_str = root.to_string_lossy().to_string();

        // Every CONTROL frame this handler sends is now dropped on the floor.
        drop(control_rx);

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_join_resolve",
            "project_dir": root_str,
            "arc": "demo",
        }))
        .unwrap();
        sup.handle_control("changeset_join_resolve", &payload, 1)
            .await;

        // The result is in git regardless, and the composition the feed runs
        // reports it — which is the whole point of moving terminal truth off
        // CONTROL and onto the replayed snapshot feed.
        let detail = tugarc_core::ops::arc_detail_entry_in(&root, "demo").expect("detail");
        let branch = tugarc_core::ops::current_branch(&root).unwrap();
        let state = crate::feeds::join_board::join_state_for(
            &root,
            &detail,
            &branch,
            &std::collections::BTreeMap::new(),
            &crate::feeds::join_board::standing_resolve_receipts(&root),
        );
        assert_eq!(state.phase, "resolved", "{state:?}");
        assert!(
            state.candidate.is_some(),
            "the candidate survived: {state:?}"
        );
        assert!(
            tugarc_core::resolve::read_candidate(&root, "demo").is_some(),
            "and it is anchored in git"
        );

        cancel.cancel();
    }

    /// A fake scribe that streams one delta and returns a fixed message.
    struct DraftScribe(String);
    impl crate::scribe::ScribeSpawner for DraftScribe {
        fn run(
            &self,
            _model: String,
            _prompt: String,
            deltas: crate::scribe::ScribeDeltas,
        ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<String, String>> + Send>>
        {
            let s = self.0.clone();
            Box::pin(async move {
                if let Some(tx) = deltas {
                    let _ = tx.send(s.clone());
                }
                Ok(s)
            })
        }
    }

    /// A one-session snapshot. `project_dir` is the raw checkout (the git cwd
    /// the engine runs in) and `workspace_key` is the canonical identity every
    /// draft frame, registry entry, and ledger row is keyed by — production
    /// keeps them apart, so the fixture does too.
    fn draft_session_snapshot(
        project_dir: &str,
        workspace_key: &str,
    ) -> tugcast_core::types::WorkspacesChangesetSnapshot {
        use tugcast_core::types::{
            ChangesetEntry, ChangesetFile, ChangesetSnapshot, ProjectChangeset,
            WorkspacesChangesetSnapshot,
        };
        let entry = ChangesetEntry::Session {
            owner_id: "s1".to_string(),
            line_id: None,
            display_name: "s1".to_string(),
            live: true,
            files: vec![ChangesetFile {
                path: "a.txt".to_string(),
                git_status: "M".to_string(),
                op: "edit".to_string(),
                origin: "exact".to_string(),
                shared: false,
                last_touched: 1,
                own_hunks: Vec::new(),
                contested_hunks: Vec::new(),
                shared_with: Vec::new(),
                added: None,
                deleted: None,
            }],
            draft: None,
        };
        WorkspacesChangesetSnapshot {
            ledger_degraded: false,
            projects: vec![ProjectChangeset {
                project_dir: project_dir.to_string(),
                display_name: "proj".to_string(),
                no_repo: false,
                snapshot: ChangesetSnapshot {
                    workspace_key: workspace_key.to_string(),
                    branch: "main".to_string(),
                    ahead: 0,
                    behind: 0,
                    head_sha: String::new(),
                    head_message: String::new(),
                    changesets: vec![entry],
                    unattributed: vec![],
                    orphaned: vec![],
                },
                unattributed_draft: None,
                document_arcs: vec![],
            }],
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn changeset_draft_request_spawns_generation_over_snapshot() {
        use std::process::Command;

        fn git(dir: &std::path::Path, args: &[&str]) {
            let ok = Command::new("git")
                .current_dir(dir)
                .args(args)
                .status()
                .unwrap()
                .success();
            assert!(ok, "git {args:?} failed");
        }

        let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        sup.set_scribe(ScribeContext {
            spawner: Arc::new(DraftScribe("Draft message\n".to_string())),
            model: Arc::new(|| "haiku".to_string()),
        });

        // A repo with a committed file and one tracked modification.
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        git(&root, &["init", "-b", "main"]);
        git(&root, &["config", "user.name", "t"]);
        git(&root, &["config", "user.email", "t@t"]);
        std::fs::write(root.join("a.txt"), "base\n").unwrap();
        git(&root, &["add", "-A"]);
        git(&root, &["commit", "-m", "base"]);
        std::fs::write(root.join("a.txt"), "changed\n").unwrap();

        let cancel = CancellationToken::new();
        let _entry = sup.registry.get_or_create(&root, cancel.clone()).unwrap();
        let root_str = root.to_string_lossy().to_string();

        // Store the aggregate watch frame the request resolves against.
        let (_wtx, wrx) = watch::channel(Frame::new(
            FeedId::CHANGESET_ALL,
            serde_json::to_vec(&draft_session_snapshot(&root_str, &root_str)).unwrap(),
        ));
        sup.changeset_watch.set(wrx).ok();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_draft_request",
            "workspace_key": root_str,
            "owner_kind": "session",
            "owner_id": "s1",
        }))
        .unwrap();
        // Generation is detached: handle_control returns before it runs, so we
        // poll the CONTROL broadcast for the drafting→ready sequence.
        sup.handle_control("changeset_draft_request", &payload, 1)
            .await;

        let mut saw_drafting = false;
        let mut saw_ready = false;
        for _ in 0..40 {
            let frame = tokio::time::timeout(std::time::Duration::from_secs(10), control_rx.recv())
                .await
                .expect("a control frame")
                .expect("sender alive");
            let body: serde_json::Value = serde_json::from_slice(&frame.payload).unwrap();
            if body["action"] == "changeset_draft_state" {
                match body["state"].as_str() {
                    Some("drafting") => saw_drafting = true,
                    Some("ready") => {
                        saw_ready = true;
                        break;
                    }
                    _ => {}
                }
            }
        }
        assert!(saw_drafting, "a drafting state streamed");
        assert!(saw_ready, "a ready state landed");

        let row = sup
            .session_ledger
            .as_ref()
            .unwrap()
            .changeset_draft("session", "s1", &root_str)
            .unwrap()
            .expect("draft row persisted");
        assert_eq!(row.message, "Draft message");

        cancel.cancel();
    }

    #[tokio::test]
    async fn changeset_draft_request_nothing_to_generate_replies_error() {
        let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        sup.set_scribe(ScribeContext {
            spawner: Arc::new(DraftScribe("unused".to_string())),
            model: Arc::new(|| "haiku".to_string()),
        });

        // An empty snapshot surfaces no eligible entry for the requested owner.
        let empty = tugcast_core::types::WorkspacesChangesetSnapshot {
            projects: vec![],
            ledger_degraded: false,
        };
        let (_wtx, wrx) = watch::channel(Frame::new(
            FeedId::CHANGESET_ALL,
            serde_json::to_vec(&empty).unwrap(),
        ));
        sup.changeset_watch.set(wrx).ok();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_draft_request",
            "workspace_key": "/nope",
            "owner_kind": "session",
            "owner_id": "s1",
        }))
        .unwrap();
        sup.handle_control("changeset_draft_request", &payload, 1)
            .await;

        // The error reply is synchronous — readable right after the call.
        let frame = tokio::time::timeout(std::time::Duration::from_secs(5), control_rx.recv())
            .await
            .expect("a control frame")
            .expect("sender alive");
        let body: serde_json::Value = serde_json::from_slice(&frame.payload).unwrap();
        assert_eq!(body["action"], "changeset_draft_state");
        assert_eq!(body["state"], "error");
        // The detail names the owner that could not be placed, which is the
        // whole of what a rotated card needs to see ([B04]).
        assert_eq!(
            body["detail"],
            crate::feeds::draft_engine::unmatched_owner_detail("s1")
        );
        assert_eq!(body["owner_id"], "s1");
    }

    /// A cancel with no in-flight generation still broadcasts the terminal
    /// `cancelled` state: it is the client's only exit from a `drafting`
    /// overlay whose terminal frame was lost, so it must always be answered.
    #[tokio::test]
    async fn changeset_draft_cancel_with_nothing_in_flight_still_replies_cancelled() {
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_draft_cancel",
            "workspace_key": "/nope",
            "owner_kind": "session",
            "owner_id": "s1",
        }))
        .unwrap();
        sup.handle_control("changeset_draft_cancel", &payload, 1)
            .await;

        let frame = tokio::time::timeout(std::time::Duration::from_secs(5), control_rx.recv())
            .await
            .expect("a control frame")
            .expect("sender alive");
        let body: serde_json::Value = serde_json::from_slice(&frame.payload).unwrap();
        assert_eq!(body["action"], "changeset_draft_state");
        assert_eq!(body["state"], "cancelled");
        assert_eq!(body["owner_id"], "s1");
    }

    /// Every terminal draft frame is addressed by `workspace_key`, and by
    /// nothing else. The client overlay map compares this string literally and
    /// has no gateway to reconcile a second spelling with, so a frame that
    /// carried a raw `project_dir` instead would land on a key nothing reads —
    /// which is how a `drafting` overlay latches the composer read-only with
    /// no exit ([L29]).
    #[tokio::test]
    async fn terminal_draft_frames_are_addressed_by_workspace_key() {
        for (verb, state) in [
            ("changeset_draft_request", "error"),
            ("changeset_draft_cancel", "cancelled"),
        ] {
            let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
            sup.session_ledger = Some(Arc::new(
                crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
            ));
            sup.set_scribe(ScribeContext {
                spawner: Arc::new(DraftScribe("unused".to_string())),
                model: Arc::new(|| "haiku".to_string()),
            });
            let empty = tugcast_core::types::WorkspacesChangesetSnapshot {
                projects: vec![],
                ledger_degraded: false,
            };
            let (_wtx, wrx) = watch::channel(Frame::new(
                FeedId::CHANGESET_ALL,
                serde_json::to_vec(&empty).unwrap(),
            ));
            sup.changeset_watch.set(wrx).ok();

            let payload = serde_json::to_vec(&serde_json::json!({
                "action": verb,
                "workspace_key": "/canonical/ws",
                "owner_kind": "session",
                "owner_id": "s1",
            }))
            .unwrap();
            sup.handle_control(verb, &payload, 1).await;

            let frame = tokio::time::timeout(std::time::Duration::from_secs(5), control_rx.recv())
                .await
                .expect("a control frame")
                .expect("sender alive");
            let body: serde_json::Value = serde_json::from_slice(&frame.payload).unwrap();
            assert_eq!(body["state"], state, "{verb} terminal state");
            assert_eq!(body["workspace_key"], "/canonical/ws", "{verb} identity");
            assert!(
                body.get("project_dir").is_none(),
                "{verb} must not address a client by a raw project_dir"
            );
        }
    }

    /// A payload that names only a `project_dir` is refused outright rather
    /// than resolved by guesswork — the whole point of the key being canonical
    /// is that there is nothing left to guess.
    #[tokio::test]
    async fn draft_request_without_workspace_key_is_refused() {
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_draft_request",
            "project_dir": "/u/src/tugtool",
            "owner_kind": "session",
            "owner_id": "s1",
        }))
        .unwrap();
        assert!(matches!(
            parse_changeset_draft_request_payload(&payload),
            Err(ControlError::InvalidProjectDir {
                reason: "missing_workspace_key"
            })
        ));
    }

    #[tokio::test]
    async fn changeset_draft_set_partially_upserts_and_clears() {
        let (mut sup, _state_rx, _meta_rx, _control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        let ledger = sup.session_ledger.clone().unwrap();

        // A message write creates the row with the edited pin.
        let payload = serde_json::to_vec(&serde_json::json!({
            "workspace_key": "/proj",
            "owner_kind": "session",
            "owner_id": "s1",
            "message": "Hand-tuned message",
            "edited": true,
        }))
        .unwrap();
        sup.handle_control("changeset_draft_set", &payload, 1).await;
        let row = ledger
            .changeset_draft("session", "s1", "/proj")
            .unwrap()
            .expect("row created");
        assert_eq!(row.message, "Hand-tuned message");
        assert!(row.edited);
        assert!(row.selection.is_none());

        // A selection-only write keeps the message and the edited pin
        // (edited is monotonic through this verb).
        let payload = serde_json::to_vec(&serde_json::json!({
            "workspace_key": "/proj",
            "owner_kind": "session",
            "owner_id": "s1",
            "selection": {"include": ["a.rs"], "exclude": []},
            "edited": false,
        }))
        .unwrap();
        sup.handle_control("changeset_draft_set", &payload, 1).await;
        let row = ledger
            .changeset_draft("session", "s1", "/proj")
            .unwrap()
            .unwrap();
        assert_eq!(row.message, "Hand-tuned message");
        assert!(row.edited, "edited survives a selection-only write");
        assert!(row.selection.as_deref().unwrap().contains("a.rs"));

        // An explicit null clears the selection without touching the message.
        let payload = serde_json::to_vec(&serde_json::json!({
            "workspace_key": "/proj",
            "owner_kind": "session",
            "owner_id": "s1",
            "selection": serde_json::Value::Null,
            "edited": false,
        }))
        .unwrap();
        sup.handle_control("changeset_draft_set", &payload, 1).await;
        let row = ledger
            .changeset_draft("session", "s1", "/proj")
            .unwrap()
            .unwrap();
        assert!(row.selection.is_none());
        assert_eq!(row.message, "Hand-tuned message");

        // `clear` deletes the row (the post-landing path).
        let payload = serde_json::to_vec(&serde_json::json!({
            "workspace_key": "/proj",
            "owner_kind": "session",
            "owner_id": "s1",
            "edited": false,
            "clear": true,
        }))
        .unwrap();
        sup.handle_control("changeset_draft_set", &payload, 1).await;
        assert!(
            ledger
                .changeset_draft("session", "s1", "/proj")
                .unwrap()
                .is_none()
        );
    }

    // --- session↔arc binding (Spec S03/S04, [P05], [P08]) ----------------

    fn git_in(dir: &std::path::Path, args: &[&str]) {
        let ok = std::process::Command::new("git")
            .current_dir(dir)
            .args(args)
            .status()
            .unwrap()
            .success();
        assert!(ok, "git {args:?} failed");
    }

    /// A repo with one commit and one `tugarc/<name>` branch, plus the
    /// creation id a bind would mint.
    fn repo_with_arc(name: &str) -> (tempfile::TempDir, std::path::PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        git_in(&root, &["init", "-b", "main"]);
        git_in(&root, &["config", "user.name", "t"]);
        git_in(&root, &["config", "user.email", "t@t"]);
        std::fs::write(root.join("a.txt"), "base\n").unwrap();
        git_in(&root, &["add", "-A"]);
        git_in(&root, &["commit", "-m", "base"]);
        git_in(&root, &["branch", &format!("tugarc/{name}")]);
        (dir, root)
    }

    /// Insert a live session row bound to nothing yet.
    fn seed_live_session(
        ledger: &crate::session_ledger::SessionLedger,
        session_id: &str,
        card_id: &str,
        project_dir: &str,
    ) {
        ledger
            .record_spawn(
                session_id,
                project_dir,
                project_dir,
                card_id,
                crate::session_ledger::now_millis(),
                session_id,
                None,
            )
            .unwrap();
    }

    /// bind → the binding shows on the restore round-trip → unbind → nulls.
    #[tokio::test]
    async fn bind_arc_round_trips_through_the_card_bindings_listing() {
        let (_dir, root) = repo_with_arc("demo");
        let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        let ledger = sup.session_ledger.clone().unwrap();
        let project = root.to_string_lossy().to_string();
        seed_live_session(&ledger, "sess-1", "card-1", &project);

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "bind_arc",
            "tug_session_id": "sess-1",
            "project_dir": project,
            "arc": "demo",
        }))
        .unwrap();
        sup.handle_control("bind_arc", &payload, 1).await;

        let arc_id = ledger.get("sess-1").unwrap().unwrap().arc_id.unwrap();
        assert!(
            arc_id.starts_with("tugarc/demo#"),
            "bind is a write path, so it mints the id: {arc_id}"
        );
        while control_rx.try_recv().is_ok() {}

        // The restore round-trip carries the pair.
        sup.do_list_card_bindings().await;
        let body = next_action(&mut control_rx, "list_card_bindings_ok").await;
        assert_eq!(body["bindings"][0]["arc_id"], arc_id);
        assert_eq!(body["bindings"][0]["arc_name"], "demo");

        // Unbind nulls them.
        let payload = serde_json::to_vec(&serde_json::json!({"tug_session_id": "sess-1"})).unwrap();
        sup.handle_control("unbind_arc", &payload, 1).await;
        sup.do_list_card_bindings().await;
        let body = next_action(&mut control_rx, "list_card_bindings_ok").await;
        assert!(body["bindings"][0]["arc_id"].is_null());
        assert!(body["bindings"][0]["arc_name"].is_null());
    }

    /// The door prompt's token parse: exactly the four door spellings, then a
    /// well-formed arc name, and nothing else reads as a door.
    #[test]
    fn arc_door_target_reads_exactly_the_four_doors() {
        for door in ["/arc", "/arc-plan", "/tugplug:arc", "/tugplug:arc-plan"] {
            assert_eq!(
                super::arc_door_target(&format!("{door} demo-arc2")),
                Some("demo-arc2"),
                "{door}"
            );
            assert_eq!(
                super::arc_door_target(&format!("  {door}   demo  \n")),
                Some("demo"),
                "{door} with stray whitespace"
            );
        }
        // Not a door.
        for text in [
            "/arc-join demo",
            "/arc-bind demo",
            "/tugplug:draft demo",
            "/commit",
            "arc demo",
            "please /arc demo",
            "",
        ] {
            assert_eq!(super::arc_door_target(text), None, "{text:?}");
        }
        // A door with no name, with a name that is not one, or with an idea
        // whose first word merely looks like one.
        for text in [
            "/arc",
            "/arc-plan   ",
            "/arc make the ring pulse",
            "/arc demo sharpen this",
            "/arc a",
            "/arc demo_arc",
            "/arc Demo",
            "/arc status",
            "/arc --plan",
        ] {
            assert_eq!(super::arc_door_target(text), None, "{text:?}");
        }
    }

    /// **[B02]'s second step.** A door prompt binds the session at submit
    /// time, through the intercept that already writes `turn_active`; an
    /// ordinary prompt binds nothing.
    #[tokio::test]
    async fn a_door_prompt_binds_the_session_at_submit_time() {
        let (_dir, root) = repo_with_arc("demo");
        let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        let ledger = sup.session_ledger.clone().unwrap();
        let project = root.to_string_lossy().to_string();
        seed_live_session(&ledger, "sess-1", "card-1", &project);
        let tug_id = TugSessionId::new("sess-1");
        let entry = insert_ledger_entry(&sup, &tug_id).await;
        entry.lock().await.project_dir = root.clone();

        let prompt = |text: &str| {
            let body = serde_json::json!({
                "tug_session_id": "sess-1",
                "type": "user_message",
                "text": text,
            });
            Frame::new(FeedId::CODE_INPUT, serde_json::to_vec(&body).unwrap())
        };

        sup.dispatch_one(prompt("/tugplug:draft demo")).await;
        assert!(
            ledger.get("sess-1").unwrap().unwrap().arc_id.is_none(),
            "an ordinary prompt binds nothing"
        );
        while control_rx.try_recv().is_ok() {}

        sup.dispatch_one(prompt("/arc demo")).await;
        let row = ledger.get("sess-1").unwrap().unwrap();
        assert!(
            row.arc_id
                .as_deref()
                .unwrap_or("")
                .starts_with("tugarc/demo#"),
            "the door prompt bound the session with the keystroke: {:?}",
            row.arc_id
        );
        assert_eq!(row.arc_name.as_deref(), Some("demo"));
        let body = next_action(&mut control_rx, "bind_arc_ok").await;
        assert_eq!(body["tug_session_id"], "sess-1");
        assert_eq!(body["arc_name"], "demo");
        assert!(
            root.join(".tug/arcs/demo").is_dir(),
            "the bind minted the directory the aggregate lists"
        );
    }

    /// A binding whose arc branch is gone reads as unbound even when nothing
    /// swept the row — the lazy half of [P05], which is what keeps reads
    /// correct after a terminal join tugcast never saw.
    #[tokio::test]
    async fn a_binding_to_a_deleted_arc_reads_as_unbound() {
        let (_dir, root) = repo_with_arc("demo");
        let (mut sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        let ledger = sup.session_ledger.clone().unwrap();
        let project = root.to_string_lossy().to_string();
        seed_live_session(&ledger, "sess-1", "card-1", &project);
        ledger
            .set_arc_binding("sess-1", Some(("tugarc/demo#1-abc", "demo")))
            .unwrap();

        git_in(&root, &["branch", "-D", "tugarc/demo"]);

        sup.do_list_card_bindings().await;
        let body = next_action(&mut control_rx, "list_card_bindings_ok").await;
        assert!(
            body["bindings"][0]["arc_id"].is_null(),
            "an arc that no longer exists is not a mating"
        );
    }

    /// **The [L27] pin.** Closing a session returns the acquisition its bind
    /// made, so an arc whose cards have all closed reports zero mated sessions
    /// and reads as *unbound* ([P08]).
    #[test]
    fn closing_a_bound_session_releases_its_binding() {
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        for (session, card) in [("sess-1", "card-1"), ("sess-2", "card-2")] {
            seed_live_session(&ledger, session, card, "/proj");
            ledger
                .set_arc_binding(session, Some(("tugarc/demo#1-abc", "demo")))
                .unwrap();
        }

        ledger.mark_closed("sess-1").unwrap();
        assert!(ledger.get("sess-1").unwrap().unwrap().arc_id.is_none());
        assert_eq!(
            ledger.get("sess-2").unwrap().unwrap().arc_id.as_deref(),
            Some("tugarc/demo#1-abc"),
            "the other session's binding is untouched"
        );

        ledger.mark_closed("sess-2").unwrap();
        assert!(
            ledger.get("sess-2").unwrap().unwrap().arc_id.is_none(),
            "with every card closed the arc is unbound, not still mated"
        );
    }

    /// **The [L29] pin.** `/api/arc` resolves `project_dir` through the
    /// gateway, so a non-canonical spelling reaches the same session row as
    /// the canonical one — the CLI never canonicalizes.
    #[cfg(unix)]
    #[tokio::test]
    async fn api_arc_bind_resolves_a_non_canonical_project_spelling() {
        let (_dir, root) = repo_with_arc("demo");
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        seed_live_session(&ledger, "sess-1", "card-1", &root.to_string_lossy());

        let link_dir = tempfile::tempdir().unwrap();
        let link = link_dir.path().join("linked-repo");
        std::os::unix::fs::symlink(&root, &link).unwrap();

        let canonical = crate::path_resolver::resolve_to_claude_form(&link);
        let outcome = crate::arc_api::bind(&ledger, &canonical, "sess-1", "demo");
        assert!(matches!(
            outcome,
            crate::arc_api::ArcApiOutcome::Bound { .. }
        ));

        let arc_id = ledger.get("sess-1").unwrap().unwrap().arc_id.unwrap();
        // The id was minted in the *real* repo, reachable through the link.
        assert_eq!(
            tugarc_core::ops::arc_owner_key(&root, "demo"),
            arc_id,
            "the symlink spelling resolved to the same repo the canonical one names"
        );
    }

    /// A session may only bind an arc in its **own** project ([D147]).
    ///
    /// The Arcs card's Bind control has always said this to the user ("This arc
    /// belongs to …") and the server took it on trust — so any short-lived CLI
    /// process on the machine could rebind a live session to an arc in a
    /// directory that session had never seen. It happened: an app-test's
    /// `arc bind` walked the instance registry, found the developer's live
    /// Tug, and mated their session to a scratch arc in a temp dir, which
    /// then evaporated with the fixture and left the masthead blank.
    #[test]
    fn api_arc_bind_refuses_a_arc_in_another_project() {
        let (_dir, root) = repo_with_arc("demo");
        let (_elsewhere_dir, elsewhere) = repo_with_arc("stranger");
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        seed_live_session(&ledger, "sess-1", "card-1", &root.to_string_lossy());

        let refused = crate::arc_api::bind(&ledger, &elsewhere, "sess-1", "stranger");
        match refused {
            crate::arc_api::ArcApiOutcome::Error(message) => assert!(
                message.contains("cannot bind"),
                "the refusal names what it refused: {message}"
            ),
            _ => panic!("a cross-project bind must be refused, not written"),
        }
        assert!(
            ledger.get("sess-1").unwrap().unwrap().arc_id.is_none(),
            "and it left the session's own binding alone"
        );

        // The same session's own project still binds, so the guard costs the
        // ordinary path nothing.
        assert!(matches!(
            crate::arc_api::bind(&ledger, &root, "sess-1", "demo"),
            crate::arc_api::ArcApiOutcome::Bound { .. }
        ));
    }

    /// A bind for a session this instance's ledger does not hold answers
    /// `unknown_session`, so the CLI's try-each-instance loop continues
    /// silently ([P04]).
    #[test]
    fn api_arc_bind_for_a_foreign_session_reports_unknown_session() {
        let (_dir, root) = repo_with_arc("demo");
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        assert!(matches!(
            crate::arc_api::bind(&ledger, &root, "not-mine", "demo"),
            crate::arc_api::ArcApiOutcome::UnknownSession
        ));
        assert!(matches!(
            crate::arc_api::unbind(&ledger, "not-mine"),
            crate::arc_api::ArcApiOutcome::UnknownSession
        ));
    }

    /// `arc_gone` sweeps the bindings and the id-keyed draft, and reports how
    /// many bindings it cleared.
    #[test]
    fn api_arc_gone_clears_bindings_and_the_draft_and_counts_them() {
        let (_dir, root) = repo_with_arc("demo");
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        let project = root.to_string_lossy().to_string();
        let owner_key = "tugarc/demo#1-abc";
        for (session, card) in [("sess-1", "card-1"), ("sess-2", "card-2")] {
            seed_live_session(&ledger, session, card, &project);
            ledger
                .set_arc_binding(session, Some((owner_key, "demo")))
                .unwrap();
        }
        ledger
            .upsert_changeset_draft(&crate::session_ledger::ChangesetDraftRow {
                owner_kind: "arc".to_string(),
                owner_id: owner_key.to_string(),
                project_dir: crate::path_resolver::CanonicalPath::from_raw(&root)
                    .as_str()
                    .to_string(),
                fingerprint: "fp".to_string(),
                message: "Land it".to_string(),
                updated_at: 1,
                edited: true,
                selection: None,
            })
            .unwrap();

        let outcome = crate::arc_api::arc_gone(&ledger, &root, owner_key);
        assert!(matches!(
            outcome,
            crate::arc_api::ArcApiOutcome::Cleared { cleared: 2, .. }
        ));
        assert!(ledger.get("sess-1").unwrap().unwrap().arc_id.is_none());
        assert!(ledger.get("sess-2").unwrap().unwrap().arc_id.is_none());
        assert!(
            ledger
                .changeset_draft(
                    "arc",
                    owner_key,
                    crate::path_resolver::CanonicalPath::from_raw(&root).as_str()
                )
                .unwrap()
                .is_none()
        );
    }

    /// **The [L23] pin.** A join resolves the arc's owner key *before* the
    /// teardown and sweeps with it, so the user's authored draft and every
    /// binding row are gone once the branch — and with it the `tugid` in its
    /// config — no longer exists (Risk R02).
    ///
    /// The ordering is the whole mitigation. Resolve the key after
    /// `join_in` returns and `arc_owner_key` can only answer with the legacy
    /// form, which matches neither row; the assertions below would then fail
    /// on rows nothing left in the system is able to name.
    #[tokio::test]
    async fn joining_a_arc_sweeps_its_draft_and_bindings_after_the_branch_is_gone() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        git_in(&root, &["init", "-b", "main"]);
        git_in(&root, &["config", "user.name", "t"]);
        git_in(&root, &["config", "user.email", "t@t"]);
        std::fs::write(root.join("a.txt"), "base\n").unwrap();
        git_in(&root, &["add", "-A"]);
        git_in(&root, &["commit", "-m", "base"]);

        // A real arc, with a round, so the join has something to land.
        let worktree = root.join(".tug/worktrees/demo");
        git_in(
            &root,
            &[
                "worktree",
                "add",
                "-q",
                "-b",
                "tugarc/demo",
                worktree.to_str().unwrap(),
            ],
        );
        std::fs::write(worktree.join("b.txt"), "work\n").unwrap();
        git_in(&worktree, &["add", "-A"]);
        git_in(&worktree, &["commit", "-m", "round"]);
        let owner_key = tugarc_core::ops::ensure_arc_id(&root, "demo").unwrap();
        assert!(owner_key.contains('#'), "id-qualified: {owner_key}");

        let (mut sup, _state_rx, _meta_rx, _control_rx) = make_supervisor_with_store();
        sup.session_ledger = Some(Arc::new(
            crate::session_ledger::SessionLedger::open_in_memory().unwrap(),
        ));
        let ledger = sup.session_ledger.clone().unwrap();
        let project = root.to_string_lossy().to_string();
        seed_live_session(&ledger, "sess-1", "card-1", &project);
        ledger
            .set_arc_binding("sess-1", Some((&owner_key, "demo")))
            .unwrap();
        let draft_project = crate::path_resolver::CanonicalPath::from_raw(&root)
            .as_str()
            .to_string();
        ledger
            .upsert_changeset_draft(&crate::session_ledger::ChangesetDraftRow {
                owner_kind: "arc".to_string(),
                owner_id: owner_key.clone(),
                project_dir: draft_project.clone(),
                fingerprint: "fp".to_string(),
                message: "Land the demo work".to_string(),
                updated_at: 1,
                edited: true,
                selection: None,
            })
            .unwrap();

        let cancel = CancellationToken::new();
        let _entry = sup.registry.get_or_create(&root, cancel.clone()).unwrap();
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "changeset_join",
            "project_dir": project,
            "arc": "demo",
            // The subject is the teardown's sweep, not the verification gate.
        }))
        .unwrap();
        sup.handle_control("changeset_join", &payload, 1).await;

        // The teardown really happened — the branch and its config are gone,
        // so nothing could re-derive the key from here.
        assert_eq!(
            tugarc_core::ops::arc_owner_key(&root, "demo"),
            "tugarc/demo",
            "the branch config died with the branch"
        );
        assert!(
            ledger
                .changeset_draft("arc", &owner_key, &draft_project)
                .unwrap()
                .is_none(),
            "the id-keyed draft was swept with the key captured before teardown"
        );
        assert!(
            ledger.get("sess-1").unwrap().unwrap().arc_id.is_none(),
            "the binding to the landed arc was released"
        );
    }

    /// Read CONTROL frames until one carries `action`, or fail.
    async fn next_action(
        control_rx: &mut broadcast::Receiver<Frame>,
        action: &str,
    ) -> serde_json::Value {
        for _ in 0..40 {
            let frame = tokio::time::timeout(std::time::Duration::from_secs(5), control_rx.recv())
                .await
                .expect("a control frame")
                .expect("sender alive");
            let body: serde_json::Value = serde_json::from_slice(&frame.payload).unwrap();
            if body["action"] == action {
                return body;
            }
        }
        panic!("no {action} frame");
    }

    #[tokio::test]
    async fn releasing_or_joining_a_arc_clears_its_draft() {
        let ledger = crate::session_ledger::SessionLedger::open_in_memory().unwrap();
        let seed = |owner_id: &str| {
            ledger
                .upsert_changeset_draft(&crate::session_ledger::ChangesetDraftRow {
                    owner_kind: "arc".to_string(),
                    owner_id: owner_id.to_string(),
                    project_dir: "/proj".to_string(),
                    fingerprint: "fp".to_string(),
                    message: "Join the snippets work".to_string(),
                    updated_at: 1,
                    edited: true,
                    selection: None,
                })
                .unwrap();
        };
        // One row under each key: the id-qualified one this build writes, and
        // the bare branch ref an older build left behind ([P03]).
        seed("tugarc/snippets");
        seed("tugarc/snippets#1723500000000-a1b2c3");

        AgentSupervisor::clear_arc_draft(&ledger, "/proj", "tugarc/snippets#1723500000000-a1b2c3");

        // A same-named future arc starts with no inherited draft ([P14]) —
        // under either key, or the haunting comes back in a form no
        // `draft clear` can reach.
        for key in ["tugarc/snippets", "tugarc/snippets#1723500000000-a1b2c3"] {
            assert!(
                ledger
                    .changeset_draft("arc", key, "/proj")
                    .unwrap()
                    .is_none(),
                "row under {key} survived the landing"
            );
        }
    }

