    #[tokio::test]
    async fn test_spawn_session_success_ack_includes_workspace_key() {
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();

        // The first frame on the control feed should be the success ack
        // with an echoed `workspace_key`.
        let ack = control_rx.try_recv().expect("spawn_session_ok ack");
        assert_eq!(ack.feed_id, FeedId::CONTROL);
        let v: serde_json::Value = serde_json::from_slice(&ack.payload).unwrap();
        assert_eq!(v["action"], "spawn_session_ok");
        assert_eq!(v["card_id"], "card-1");
        assert_eq!(v["tug_session_id"], "sess-1");
        let wk = v["workspace_key"].as_str().expect("workspace_key string");
        assert!(!wk.is_empty());
        // The ack's workspace_key must equal the canonical form produced
        // by WorkspaceRegistry::get_or_create, which is what tugcast
        // splices into FILETREE/FILESYSTEM/GIT frames. Load the live
        // entry from the ledger and cross-check.
        let tug_id = TugSessionId::new("sess-1");
        let entry_arc = sup.ledger.lock().await.get(&tug_id).unwrap().clone();
        let entry = entry_arc.lock().await;
        assert_eq!(wk, entry.workspace_key.as_ref());
    }

    #[tokio::test]
    async fn test_two_sessions_same_workspace_share_entry() {
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control("spawn_session", &spawn_payload("card-a", "sess-a"), 10)
            .await
            .expect_handled();
        sup.handle_control("spawn_session", &spawn_payload("card-b", "sess-b"), 20)
            .await
            .expect_handled();
        // Drain the two ack frames.
        let _ = control_rx.try_recv();
        let _ = control_rx.try_recv();

        // Same project_dir → same workspace entry; the registry map has
        // exactly one entry.
        assert_eq!(registry_map_len(&sup), 1);

        // Both ledger entries bind to the same workspace_key.
        let ledger = sup.ledger.lock().await;
        let entry_a = ledger.get(&TugSessionId::new("sess-a")).unwrap().clone();
        let entry_b = ledger.get(&TugSessionId::new("sess-b")).unwrap().clone();
        drop(ledger);
        let key_a = entry_a.lock().await.workspace_key.as_ref().to_string();
        let key_b = entry_b.lock().await.workspace_key.as_ref().to_string();
        assert_eq!(key_a, key_b);
    }

    #[tokio::test]
    async fn test_close_session_releases_workspace() {
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();
        let _ = control_rx.try_recv(); // drain ack
        assert_eq!(registry_map_len(&sup), 1);

        sup.handle_control("close_session", &close_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();

        // Refcount should have hit zero; the workspace is removed.
        assert_eq!(registry_map_len(&sup), 0);
        assert!(sup.ledger.lock().await.is_empty());
    }

    #[tokio::test]
    async fn test_reset_session_preserves_workspace() {
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();
        let _ = control_rx.try_recv(); // drain ack

        // Capture the `Arc<WorkspaceEntry>` from the registry map BEFORE
        // reset so the post-reset comparison can use `Arc::ptr_eq` — a
        // stricter invariant than comparing workspace_key strings alone
        // (which can't distinguish release-and-reacquire from preserve).
        let tug_id = TugSessionId::new("sess-1");
        let workspace_key = {
            let ledger = sup.ledger.lock().await;
            let entry_arc = ledger.get(&tug_id).unwrap().clone();
            drop(ledger);
            entry_arc.lock().await.workspace_key.clone()
        };
        let workspace_entry_before = sup
            .registry
            .inner_for_test()
            .get(&workspace_key)
            .expect("workspace entry present before reset")
            .clone();

        sup.handle_control("reset_session", &reset_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();

        // [D11]: the workspace entry survives reset. Map still holds 1.
        assert_eq!(registry_map_len(&sup), 1);

        // Strict: the post-reset `Arc<WorkspaceEntry>` must be the SAME
        // Arc, not a replacement with the same key.
        let workspace_entry_after = sup
            .registry
            .inner_for_test()
            .get(&workspace_key)
            .expect("workspace entry present after reset")
            .clone();
        assert!(
            Arc::ptr_eq(&workspace_entry_before, &workspace_entry_after),
            "reset must preserve the exact Arc<WorkspaceEntry>, not just the key"
        );

        // And the ledger entry's workspace_key is unchanged.
        let workspace_key_after = {
            let ledger = sup.ledger.lock().await;
            let entry_arc = ledger.get(&tug_id).unwrap().clone();
            drop(ledger);
            entry_arc.lock().await.workspace_key.clone()
        };
        assert_eq!(workspace_key.as_ref(), workspace_key_after.as_ref());
    }

    #[tokio::test]
    async fn test_two_sessions_two_workspaces_do_not_share() {
        // Two TempDirs → two distinct canonical paths → two distinct
        // `WorkspaceEntry` Arcs. Belt-and-suspenders for the invariant
        // that `get_or_create` really does dedupe by path, and that
        // `test_two_sessions_same_workspace_share_entry` isn't passing
        // because the dedup logic is stuck in a one-workspace rut.
        let tmp_a = tempfile::TempDir::new().expect("tempdir a");
        let tmp_b = tempfile::TempDir::new().expect("tempdir b");
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control(
            "spawn_session",
            &spawn_payload_in("card-a", "sess-a", tmp_a.path().to_str().unwrap()),
            10,
        )
        .await
        .expect_handled();
        sup.handle_control(
            "spawn_session",
            &spawn_payload_in("card-b", "sess-b", tmp_b.path().to_str().unwrap()),
            20,
        )
        .await
        .expect_handled();
        let _ = control_rx.try_recv(); // drain both acks
        let _ = control_rx.try_recv();

        // Two distinct workspaces in the registry.
        assert_eq!(registry_map_len(&sup), 2);

        // Distinct workspace_key strings on the ledger entries.
        let ledger = sup.ledger.lock().await;
        let entry_a = ledger.get(&TugSessionId::new("sess-a")).unwrap().clone();
        let entry_b = ledger.get(&TugSessionId::new("sess-b")).unwrap().clone();
        drop(ledger);
        let key_a = entry_a.lock().await.workspace_key.clone();
        let key_b = entry_b.lock().await.workspace_key.clone();
        assert_ne!(
            key_a.as_ref(),
            key_b.as_ref(),
            "distinct TempDirs must produce distinct workspace_keys"
        );

        // Strict: the two `Arc<WorkspaceEntry>` instances are distinct.
        let map = sup.registry.inner_for_test();
        let ws_a = map.get(&key_a).unwrap().clone();
        let ws_b = map.get(&key_b).unwrap().clone();
        drop(map);
        assert!(
            !Arc::ptr_eq(&ws_a, &ws_b),
            "distinct workspaces must be distinct Arcs"
        );
    }

    #[tokio::test]
    async fn test_spawn_session_reconnect_releases_refcount() {
        // Duplicate spawn on the same `tug_session_id` is a reconnect.
        // The second spawn's `get_or_create` bumps the workspace refcount
        // to 2, but the reconnect path in `do_spawn_session` releases the
        // extra refcount because the existing ledger entry already holds
        // one. Without that release, the refcount would leak one per
        // reconnect and the workspace would never tear down on close.
        //
        // This test nails that release-on-reconnect contract: the
        // registry map must still hold exactly one entry with
        // `ref_count == 1` after the second spawn.
        use std::sync::atomic::Ordering;
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();
        let _ = control_rx.try_recv(); // drain ack

        // Reconnect: same tug_session_id (and same project_dir), new card.
        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 11)
            .await
            .expect_handled();
        let _ = control_rx.try_recv(); // drain second ack

        assert_eq!(registry_map_len(&sup), 1);

        // Read the single WorkspaceEntry and assert its refcount is 1,
        // not 2. A leak would show up as 2 here.
        let map = sup.registry.inner_for_test();
        assert_eq!(map.len(), 1);
        let (_key, ws) = map.iter().next().expect("one entry");
        assert_eq!(
            ws.ref_count.load(Ordering::Relaxed),
            1,
            "reconnect must release the just-acquired refcount"
        );
    }

    #[tokio::test]
    async fn test_spawn_resume_of_rebound_entry_keeps_workspace() {
        // The restore bug: an entry rebound from the ledger holds NO workspace
        // refcount (rebind registers no workspace, by design). Its first resume
        // spawn hits `inserted == false`; the old code read that as "a refcount
        // is already held" and released the one Phase 0 just acquired — dropping
        // the fresh workspace's ONLY refcount and tearing it down. The resumed
        // project then vanished from the registry (and the changeset aggregate /
        // git-log resolution). With per-entry refcount ownership, the rebound
        // entry ADOPTS the Phase-0 refcount on its first spawn, so it survives.
        use std::sync::atomic::Ordering;
        let (sup, _state_rx, _meta_rx, mut control_rx) = make_supervisor_with_store();

        // Simulate `rebind_from_ledger`: an Idle, Resume entry present in the
        // in-memory ledger, bound to a card, holding no workspace refcount.
        let sid = TugSessionId::new("reb-sess");
        let mut entry = LedgerEntry::new(
            sid.clone(),
            WorkspaceKey::from_canonical(test_project_dir()),
            PathBuf::from(test_project_dir()),
            SessionMode::Resume,
            CrashBudget::new(3, Duration::from_secs(60)),
        );
        entry.card_id = Some("card-r".to_string());
        entry.claude_session_id = Some("reb-sess".to_string());
        assert!(
            !entry.holds_workspace_refcount,
            "a rebound entry starts holding no workspace refcount"
        );
        sup.ledger
            .lock()
            .await
            .insert(sid.clone(), Arc::new(Mutex::new(entry)));

        // Registry is empty until the first real spawn registers the workspace.
        assert_eq!(registry_map_len(&sup), 0);

        // First resume spawn of the rebound entry.
        sup.handle_control("spawn_session", &resume_payload("card-r", "reb-sess"), 10)
            .await
            .expect_handled();
        let _ = control_rx.try_recv();

        // The workspace is registered and SURVIVES (was torn down before the fix).
        assert_eq!(
            registry_map_len(&sup),
            1,
            "the rebound resume must keep its workspace registered"
        );
        let ref_count = {
            let map = sup.registry.inner_for_test();
            let (_key, ws) = map.iter().next().expect("one workspace");
            ws.ref_count.load(Ordering::Relaxed)
        };
        assert_eq!(
            ref_count, 1,
            "the entry adopts exactly one workspace refcount"
        );

        // The entry now records ownership of that refcount.
        let e = sup.ledger.lock().await.get(&sid).unwrap().clone();
        assert!(
            e.lock().await.holds_workspace_refcount,
            "the entry adopted the Phase-0 refcount"
        );
    }

    // ── LedgerSessionsRecorder lifecycle ─────────────────────────────────────
    //
    // These tests exercise the recorder against a real in-memory
    // [`SessionLedger`] — no mocks, no call-count assertions. The contract
    // under test is "when the trait method runs, the ledger row reaches the
    // expected state." Each test traces one CRUD trajectory.

    use crate::session_ledger::{SessionLedger, SessionState as LedgerState};

    fn fresh_ledger_recorder() -> (Arc<SessionLedger>, Arc<dyn SessionsRecorder>) {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let recorder: Arc<dyn SessionsRecorder> =
            Arc::new(LedgerSessionsRecorder::new(Arc::clone(&ledger)));
        (ledger, recorder)
    }

    #[test]
    fn ledger_recorder_record_inserts_live_row() {
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        let row = ledger.get("claude-abc").unwrap().expect("row");
        assert_eq!(row.workspace_key, "ws-1");
        assert_eq!(row.project_dir, "/proj/x");
        assert_eq!(row.card_id.as_deref(), Some("card-1"));
        assert_eq!(row.state, LedgerState::Live);
        assert_eq!(row.turn_count, 0);
    }

    // ── reported_binding: what makes a stored binding readable as gone ───────

    /// An arc whose branch is there reads bound, and one nothing knows about
    /// reads unbound. The two ordinary cases.
    #[test]
    fn a_binding_is_reported_when_its_arc_has_a_record() {
        let records = ArcRecords::Known(["tugarc/demo".to_string()].into_iter().collect());
        assert_eq!(
            AgentSupervisor::reported_binding(
                &records,
                Some("tugarc/demo#1755-aabbcc".into()),
                Some("demo".into()),
            ),
            (Some("tugarc/demo#1755-aabbcc".into()), Some("demo".into())),
        );
        assert_eq!(
            AgentSupervisor::reported_binding(
                &records,
                Some("tugarc/joined#1755-ddeeff".into()),
                Some("joined".into()),
            ),
            (None, None),
            "an arc the repo has no record of is gone, and the chip should say so",
        );
    }

    /// A repo that could not be read keeps the ledger's answer.
    ///
    /// Nulling is a claim — "this arc is gone" — and only evidence may make
    /// it. The old gate could not tell a failed `git` from a repo with no
    /// arcs in it, so a moved checkout or a stale `project_dir` spelling
    /// blanked the arc chip on every card at once, with nothing said.
    #[test]
    fn an_unreadable_repo_keeps_the_ledgers_binding_rather_than_nulling_it() {
        assert_eq!(
            AgentSupervisor::reported_binding(
                &ArcRecords::Unreadable,
                Some("tugarc/demo#1755-aabbcc".into()),
                Some("demo".into()),
            ),
            (Some("tugarc/demo#1755-aabbcc".into()), Some("demo".into())),
        );
        assert_eq!(
            AgentSupervisor::reported_binding(&ArcRecords::Unreadable, None, None),
            (None, None),
            "and an unbound row stays unbound; there is nothing to keep",
        );
    }

    /// The pre-branch arc binding, which the branch-only gate nulled every
    /// time.
    ///
    /// `tugtool arc run` binds through `ensure_arc_id`, which mints the
    /// owner key as git config and needs no branch — so between that bind and
    /// the arc's creation the binding is valid and has no `tugarc/<name>`
    /// ref. Gating on the ref alone made the card read unbound for that whole
    /// window, deterministically.
    #[test]
    fn a_pre_branch_arc_binding_is_reported_from_its_tugid_alone() {
        let repo = tempfile::tempdir().unwrap();
        git_init(repo.path());
        run_git(
            repo.path(),
            &["config", "branch.tugarc/arc.tugid", "1755-aabbcc"],
        );

        let records = AgentSupervisor::live_arc_records(repo.path().to_str().unwrap());
        assert!(matches!(records, ArcRecords::Known(_)));
        assert_eq!(
            AgentSupervisor::reported_binding(
                &records,
                Some("tugarc/arc#1755-aabbcc".into()),
                Some("arc".into()),
            ),
            (Some("tugarc/arc#1755-aabbcc".into()), Some("arc".into())),
            "an arc with a tugid and no branch yet is bound by design",
        );
    }

    /// A branch with no tugid — the legacy, pre-id shape — still reads as a
    /// record. Neither half is required; their absence *together* is what
    /// means gone, because a teardown takes both.
    #[test]
    fn a_branch_without_a_tugid_is_still_a_record() {
        let repo = tempfile::tempdir().unwrap();
        git_init(repo.path());
        run_git(repo.path(), &["commit", "--allow-empty", "-m", "root"]);
        run_git(repo.path(), &["branch", "tugarc/legacy"]);

        let records = AgentSupervisor::live_arc_records(repo.path().to_str().unwrap());
        assert_eq!(
            AgentSupervisor::reported_binding(
                &records,
                Some("tugarc/legacy".into()),
                Some("legacy".into()),
            ),
            (Some("tugarc/legacy".into()), Some("legacy".into())),
        );
    }

    /// A readable repo with no arcs in it answers `Known` and empty — a real
    /// answer, and the one that must stay distinct from not having been asked.
    #[test]
    fn a_repo_with_no_arcs_answers_known_and_empty() {
        let repo = tempfile::tempdir().unwrap();
        git_init(repo.path());

        match AgentSupervisor::live_arc_records(repo.path().to_str().unwrap()) {
            ArcRecords::Known(records) => assert!(records.is_empty()),
            ArcRecords::Unreadable => panic!("a readable repo with no arcs is not unreadable"),
        }
    }

    /// A path that is not a repo at all is `Unreadable`. This is the shape a
    /// stale `project_dir` spelling takes, and the one the old gate read as
    /// "every arc is gone".
    #[test]
    fn a_path_that_is_not_a_repo_is_unreadable() {
        let dir = tempfile::tempdir().unwrap();
        assert!(matches!(
            AgentSupervisor::live_arc_records(dir.path().to_str().unwrap()),
            ArcRecords::Unreadable,
        ));
    }

    fn run_git(repo: &std::path::Path, args: &[&str]) {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(args)
            .output()
            .expect("git runs");
        assert!(out.status.success(), "git {args:?}: {out:?}");
    }

    fn git_init(repo: &std::path::Path) {
        run_git(repo, &["init", "--quiet", "-b", "main"]);
        run_git(repo, &["config", "user.email", "t@example.com"]);
        run_git(repo, &["config", "user.name", "T"]);
    }

    /// The rotation seat's two frames, in the order the deck needs them.
    ///
    /// `bind_arc_ok` names a segment minted moments ago, and the deck routes
    /// it by walking segment → line → card. Sent first, that walk resolves
    /// nothing and the announcement is dropped on the floor — the card keeps
    /// wearing "unbound" for the rest of its arc. So the row push, which is
    /// how the deck learns the pair at all, goes first; and the push must
    /// still come *after* the seat's write, or it would report a null arc
    /// about a row that is bound.
    #[tokio::test]
    async fn the_rotation_seat_pushes_the_row_before_it_announces_the_mating() {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let (control_tx, mut rx) = broadcast::channel(64);
        let bump = Arc::new(Notify::new());
        let recorder = LedgerSessionsRecorder::with_broadcast(Arc::clone(&ledger), control_tx)
            .with_changeset_bump(Arc::clone(&bump));

        // The shape a rotation leaves: the line's old segment holds the
        // binding, and the Wheel has just minted a fresh one on the same card.
        ledger
            .record_spawn("seg-old", "ws-1", "/proj/x", "card-1", 1, "line-1", None)
            .unwrap();
        ledger
            .set_arc_binding("seg-old", Some(("tugarc/demo#1", "demo")))
            .unwrap();
        while rx.try_recv().is_ok() {}

        recorder.record(SessionRecord {
            session_id: "seg-new",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: Some("line-1"),
        });

        let actions: Vec<serde_json::Value> = std::iter::from_fn(|| rx.try_recv().ok())
            .filter_map(|frame| serde_json::from_slice::<serde_json::Value>(&frame.payload).ok())
            .collect();
        let position = |action: &str| {
            actions
                .iter()
                .position(|v| v.get("action").and_then(|a| a.as_str()) == Some(action))
                .unwrap_or_else(|| panic!("no `{action}` frame among {actions:?}"))
        };
        assert!(
            position("session_updated") < position("bind_arc_ok"),
            "the deck cannot resolve an announcement about a segment it has not met",
        );

        let push = &actions[position("session_updated")];
        assert_eq!(push["session_id"], "seg-new");
        assert_eq!(
            push["fields"]["line_id"], "line-1",
            "the pair the deck's segment → line → card walk is made of",
        );

        let announce = &actions[position("bind_arc_ok")];
        assert_eq!(announce["tug_session_id"], "seg-new");
        assert_eq!(announce["arc_id"], "tugarc/demo#1");
        assert_eq!(announce["arc_name"], "demo");
        assert_eq!(
            announce["line_id"], "line-1",
            "and it carries its own routing, for a deck that missed the push",
        );
        assert_eq!(announce["card_id"], "card-1");

        // The masthead's arc index derives from CHANGESET_ALL, and a seat
        // moves which segment the arc reports as bound.
        tokio::time::timeout(std::time::Duration::from_millis(200), bump.notified())
            .await
            .expect("the seat rings the aggregate bump every other binding writer rings");

        // And the binding moved rather than being copied.
        assert!(ledger.get("seg-old").unwrap().unwrap().arc_id.is_none());
    }

    /// An ordinary spawn — no binding anywhere on the line — announces
    /// nothing and rings nothing. The seat is for the rotation alone.
    #[tokio::test]
    async fn an_unbound_spawn_announces_no_mating() {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let (control_tx, mut rx) = broadcast::channel(64);
        let bump = Arc::new(Notify::new());
        let recorder = LedgerSessionsRecorder::with_broadcast(Arc::clone(&ledger), control_tx)
            .with_changeset_bump(Arc::clone(&bump));

        recorder.record(SessionRecord {
            session_id: "seg-solo",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: Some("line-1"),
        });

        let actions: Vec<String> = std::iter::from_fn(|| rx.try_recv().ok())
            .filter_map(|frame| serde_json::from_slice::<serde_json::Value>(&frame.payload).ok())
            .filter_map(|v| v.get("action").and_then(|a| a.as_str()).map(String::from))
            .collect();
        assert!(actions.iter().any(|a| a == "session_updated"));
        assert!(!actions.iter().any(|a| a == "bind_arc_ok"), "{actions:?}");
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(50), bump.notified())
                .await
                .is_err(),
            "nothing moved, so there is nothing to recompose",
        );
    }

    /// The ledger (the source of truth for sessions) publishes a "sessions
    /// changed" signal on every session-lifecycle write, so a delegate — the
    /// CHANGESET_ALL aggregate — recomputes on a spawn / turn / close with no
    /// poll. Driven through the recorder (the production write path) to prove
    /// the whole chain: recorder → ledger write → published signal.
    #[tokio::test]
    async fn ledger_publishes_change_on_session_lifecycle() {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let signal = Arc::new(Notify::new());
        ledger.set_change_signal(Arc::clone(&signal));
        let recorder = LedgerSessionsRecorder::new(Arc::clone(&ledger));

        let expect_ping = |signal: Arc<Notify>, what: &'static str| async move {
            tokio::time::timeout(std::time::Duration::from_millis(200), signal.notified())
                .await
                .unwrap_or_else(|_| panic!("{what} must publish a sessions-changed signal"));
        };

        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        expect_ping(Arc::clone(&signal), "record (spawn)").await;

        recorder.record_turn("claude-abc");
        expect_ping(Arc::clone(&signal), "record_turn").await;

        recorder.mark_closed("claude-abc");
        expect_ping(Arc::clone(&signal), "mark_closed").await;
    }

    #[test]
    fn ledger_recorder_record_user_prompt_overwrites_snippet() {
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        recorder.record_user_prompt("claude-abc", "hello world");
        let row = ledger.get("claude-abc").unwrap().unwrap();
        assert_eq!(row.last_user_prompt.as_deref(), Some("hello world"));

        // Subsequent calls overwrite — the picker shows the latest prompt.
        recorder.record_user_prompt("claude-abc", "second turn");
        let row = ledger.get("claude-abc").unwrap().unwrap();
        assert_eq!(row.last_user_prompt.as_deref(), Some("second turn"));
    }

    #[test]
    fn ledger_recorder_record_turn_then_close_full_lifecycle() {
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        // Live turns touch recency only; the count is the engine reconcile
        // ([P08]). Reconcile to 3, then live turns leave the count untouched.
        recorder.set_turn_count("claude-abc", 3);
        recorder.record_turn("claude-abc");
        recorder.record_turn("claude-abc");
        recorder.mark_closed("claude-abc");

        let row = ledger.get("claude-abc").unwrap().expect("row");
        assert_eq!(row.turn_count, 3);
        assert_eq!(row.state, LedgerState::Closed);
        // card_id is preserved across mark_closed under the new
        // semantics — the persisted row keeps the binding so client-side
        // restore can reconstruct it.
        assert_eq!(row.card_id.as_deref(), Some("card-1"));
    }

    /// A session ends once. Several paths call `mark_closed` for one ending —
    /// a close after a startup demote, a teardown after the close — and the
    /// lifecycle fact hangs off whether a row really moved, not off the call.
    #[test]
    fn ledger_recorder_records_one_ending_however_often_close_is_called() {
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });

        recorder.mark_closed("claude-abc");
        recorder.mark_closed("claude-abc");
        recorder.mark_closed("claude-abc");

        let endings = ledger
            .facts_for_test()
            .into_iter()
            .filter(|(kind, _, _)| kind == "session.closed")
            .count();
        assert_eq!(endings, 1, "one ending in the fact base");
        assert_eq!(
            ledger.get("claude-abc").unwrap().unwrap().state,
            LedgerState::Closed
        );
    }

    #[test]
    fn ledger_recorder_mark_failed_retains_row() {
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        recorder.mark_failed("claude-abc");

        let row = ledger.get("claude-abc").unwrap().expect("row retained");
        assert_eq!(row.state, LedgerState::Failed);
        assert_eq!(row.card_id.as_deref(), Some("card-1"));
    }

    #[test]
    fn ledger_recorder_record_turn_no_op_after_close() {
        // Late `result` events that arrive after the user closes the card
        // must not mutate the ledger row — the row is "done."
        let (ledger, recorder) = fresh_ledger_recorder();
        recorder.record(SessionRecord {
            session_id: "claude-abc",
            workspace_key: "ws-1",
            project_dir: "/proj/x",
            card_id: "card-1",
            tag: None,
            line_id: None,
        });
        recorder.mark_closed("claude-abc");
        recorder.record_turn("claude-abc");
        let row = ledger.get("claude-abc").unwrap().expect("row");
        assert_eq!(row.turn_count, 0);
        assert_eq!(row.state, LedgerState::Closed);
    }

    // ── do_close_session ↔ ledger integration ────────────────────────────────

    /// `do_close_session` reads `entry.claude_session_id` and dispatches
    /// `mark_closed` to the recorder. With a real ledger plugged in, the
    /// row's state must transition.
    #[tokio::test]
    async fn close_session_marks_ledger_row_closed_when_claude_id_present() {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let recorder: Arc<dyn SessionsRecorder> =
            Arc::new(LedgerSessionsRecorder::new(Arc::clone(&ledger)));

        let (state_tx, _state_rx) = broadcast::channel(64);
        let (meta_tx, _meta_rx) = broadcast::channel(8);
        let (code_tx, _code_rx) = broadcast::channel(8);
        let (control_tx, _control_rx) = broadcast::channel(64);
        let registry = Arc::new(WorkspaceRegistry::new_for_test());
        let cancel = CancellationToken::new();
        let (sup, mut register_rx) = AgentSupervisor::new(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            stall_spawner_factory(),
            AgentSupervisorConfig::default(),
            registry,
            cancel,
        );
        // Drain merger registrations like make_supervisor_with_store does.
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });

        // Spawn the session through the normal CONTROL path so the entry is
        // populated correctly. Then manually set `claude_session_id` to
        // simulate that `session_init` was observed (which the bridge would
        // have done in production).
        sup.handle_control("spawn_session", &spawn_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();
        // Pre-seed the ledger so `mark_closed` has a row to transition.
        ledger
            .record_spawn(
                "claude-1",
                "/some/workspace",
                "/some/workspace",
                "card-1",
                1_700_000_000_000,
                "claude-1",
                None,
            )
            .unwrap();
        {
            let outer = sup.ledger.lock().await;
            let entry_arc = outer
                .get(&TugSessionId::new("sess-1"))
                .expect("entry")
                .clone();
            drop(outer);
            let mut entry = entry_arc.lock().await;
            entry.claude_session_id = Some("claude-1".to_owned());
        }

        sup.handle_control("close_session", &close_payload("card-1", "sess-1"), 10)
            .await
            .expect_handled();

        let row = ledger.get("claude-1").unwrap().expect("row");
        assert_eq!(row.state, LedgerState::Closed);
        assert_eq!(row.card_id.as_deref(), Some("card-1"));
    }

    // ── CONTROL ledger ops ───────────────────────────────────────────────────
    //
    // These tests exercise the new `list_sessions`, `trash_session`, and
    // `trash_workspace_sessions` actions end-to-end through the supervisor's
    // `handle_control` path. The supervisor is built with a real
    // `SessionLedger` in scope; the tests assert the broadcast frames the
    // CONTROL feed emits and the ledger row state after each action.

    /// Build a supervisor with a real ledger + a recorder that emits push
    /// frames on writes. Returns the supervisor, ledger, and the CONTROL
    /// receiver so tests can read the broadcast traffic.
    fn make_supervisor_with_ledger() -> (
        Arc<AgentSupervisor>,
        Arc<SessionLedger>,
        broadcast::Receiver<Frame>,
    ) {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        make_supervisor_for_ledger(ledger, None)
    }

    /// Harness variant for union/liveness tests: a ledger with a real
    /// tempdir claude-projects root, and an injectable terminal
    /// registry root. The default registry root is a nonexistent path
    /// so tests never read the developer's real `~/.claude/sessions`.
    fn make_supervisor_for_ledger(
        ledger: Arc<SessionLedger>,
        terminal_registry_root: Option<std::path::PathBuf>,
    ) -> (
        Arc<AgentSupervisor>,
        Arc<SessionLedger>,
        broadcast::Receiver<Frame>,
    ) {
        let (state_tx, _state_rx) = broadcast::channel(64);
        let (meta_tx, _meta_rx) = broadcast::channel(8);
        let (code_tx, _code_rx) = broadcast::channel(8);
        let (control_tx, control_rx) = broadcast::channel(128);
        let recorder: Arc<dyn SessionsRecorder> = Arc::new(LedgerSessionsRecorder::with_broadcast(
            Arc::clone(&ledger),
            control_tx.clone(),
        ));
        let registry = Arc::new(WorkspaceRegistry::new_for_test());
        let cancel = CancellationToken::new();
        let config = AgentSupervisorConfig {
            terminal_registry_root: Some(terminal_registry_root.unwrap_or_else(|| {
                std::path::PathBuf::from("/nonexistent/tugcast-test-terminal-registry")
            })),
            ..AgentSupervisorConfig::default()
        };
        let (sup, mut register_rx) = AgentSupervisor::new_with_ledger(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            Some(Arc::clone(&ledger)),
            stall_spawner_factory(),
            config,
            registry,
            cancel,
        );
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });
        (Arc::new(sup), ledger, control_rx)
    }

    /// Drain until the **settled** `list_sessions_ok` — the phase-2 emit
    /// carrying the full union (`scanning: false`). `do_list_sessions`
    /// emits twice: a phase-1 `{ scanning: true }` with ledger rows only,
    /// then this one once the external scan completes. Tests asserting on
    /// external/union rows must wait for the settled frame.
    async fn drain_until_list_sessions_settled(
        rx: &mut broadcast::Receiver<Frame>,
    ) -> serde_json::Value {
        // The settled frame is sent from a detached phase-2 task, so we
        // must `await` (yield to the runtime) rather than `try_recv` — the
        // task only runs while this test awaits. Bounded by a timeout so a
        // never-arriving frame surfaces as a panic, not a hang.
        for _ in 0..256 {
            let frame =
                match tokio::time::timeout(std::time::Duration::from_secs(10), rx.recv()).await {
                    Ok(Ok(f)) => f,
                    _ => break,
                };
            if let Ok(v) = serde_json::from_slice::<serde_json::Value>(&frame.payload) {
                let is_ok = v.get("action").and_then(|a| a.as_str()) == Some("list_sessions_ok");
                let settled = v.get("scanning").and_then(|s| s.as_bool()) == Some(false);
                if is_ok && settled {
                    return v;
                }
            }
        }
        panic!("settled `list_sessions_ok` (scanning:false) not observed");
    }

    fn drain_until_action(rx: &mut broadcast::Receiver<Frame>, action: &str) -> serde_json::Value {
        // Pull frames off the broadcast until we find one whose `action`
        // matches; ignore the others. Bounded loop so a missing frame
        // surfaces as a panic on the receiver's empty error rather than a
        // hang.
        for _ in 0..64 {
            let Ok(frame) = rx.try_recv() else { break };
            if let Ok(v) = serde_json::from_slice::<serde_json::Value>(&frame.payload) {
                if v.get("action").and_then(|a| a.as_str()) == Some(action) {
                    return v;
                }
            }
        }
        panic!("CONTROL frame with action `{action}` not observed");
    }

    /// `set_session_private` writes the flag, acks, and pushes the row so the
    /// chip can show a resting state ([P05], [Q01]). No fact is recorded for
    /// the toggle — recording the act of hiding would leak the hiding.
    #[tokio::test]
    async fn set_session_private_acks_and_pushes_the_flag() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();
        ledger
            .record_spawn("sess", "ws-1", "/proj", "card-A", 1_000, "sess", None)
            .unwrap();
        let facts_before = ledger.facts_for_test().len();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "set_session_private",
            "session_id": "sess",
            "private": true,
        }))
        .unwrap();
        sup.handle_control("set_session_private", &payload, 10)
            .await
            .expect_handled();

        let ack = drain_until_action(&mut rx, "set_session_private_ok");
        assert_eq!(ack["session_id"], "sess");
        assert_eq!(ack["private"], true);
        assert!(ledger.is_session_private("sess").unwrap());
        assert_eq!(
            ledger.facts_for_test().len(),
            facts_before,
            "the toggle itself is not a fact"
        );

        // Turning it back off is the same verb; the push carries the new value.
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "set_session_private",
            "session_id": "sess",
            "private": false,
        }))
        .unwrap();
        sup.handle_control("set_session_private", &payload, 10)
            .await
            .expect_handled();
        let pushed = drain_until_action(&mut rx, "session_updated");
        assert_eq!(pushed["fields"]["private"], false);
        assert!(!ledger.is_session_private("sess").unwrap());
    }

    #[tokio::test]
    async fn set_session_private_on_an_unknown_session_errs() {
        let (sup, _ledger, mut rx) = make_supervisor_with_ledger();
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "set_session_private",
            "session_id": "nope",
            "private": true,
        }))
        .unwrap();
        sup.handle_control("set_session_private", &payload, 10)
            .await
            .expect_handled();
        let err = drain_until_action(&mut rx, "set_session_private_err");
        assert_eq!(err["reason"], "not_found");
    }

    /// A refusal names the value it refused in either direction. The client
    /// puts back the negation of that value, so an omitted or one-sided field
    /// would leave a failed un-private toggle showing "public" over a session
    /// the ledger still holds private.
    #[tokio::test]
    async fn a_refused_toggle_names_the_value_it_refused() {
        let (sup, _ledger, mut rx) = make_supervisor_with_ledger();
        for requested in [true, false] {
            let payload = serde_json::to_vec(&serde_json::json!({
                "action": "set_session_private",
                "session_id": "nope",
                "private": requested,
            }))
            .unwrap();
            sup.handle_control("set_session_private", &payload, 10)
                .await
                .expect_handled();
            let err = drain_until_action(&mut rx, "set_session_private_err");
            assert_eq!(err["session_id"], "nope");
            assert_eq!(err["private"], requested);
        }
    }

    /// Both rename acks name the rename they answer. The client renames
    /// optimistically off a broadcast feed, so an ack it cannot place is one it
    /// cannot act on — and the refusal is the only thing that puts the replaced
    /// name back.
    #[tokio::test]
    async fn rename_acks_carry_the_name_they_answer() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();
        ledger
            .record_spawn("sess", "ws-1", "/proj", "card-A", 1_000, "line-A", None)
            .unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "rename_session",
            "line_id": "line-A",
            "name": "harbor light",
        }))
        .unwrap();
        sup.handle_control("rename_session", &payload, 10)
            .await
            .expect_handled();
        let ack = drain_until_action(&mut rx, "rename_session_ok");
        assert_eq!(ack["line_id"], "line-A");
        assert_eq!(ack["name"], "harbor light");

        // A cleared name acks as null — the same value the request carried.
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "rename_session",
            "line_id": "line-A",
            "name": "   ",
        }))
        .unwrap();
        sup.handle_control("rename_session", &payload, 10)
            .await
            .expect_handled();
        let ack = drain_until_action(&mut rx, "rename_session_ok");
        assert!(ack["name"].is_null());

        // And the refusal names it too.
        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "rename_session",
            "line_id": "nope",
            "name": "harbor light",
        }))
        .unwrap();
        sup.handle_control("rename_session", &payload, 10)
            .await
            .expect_handled();
        let err = drain_until_action(&mut rx, "rename_session_err");
        assert_eq!(err["reason"], "not_found");
        assert_eq!(err["name"], "harbor light");
    }

    /// A rename onto a name another line wears TAKES it ([P11]): the newest
    /// gesture wins, the previous holder falls back to its callsign, and the
    /// ack names whom the name was taken from so the gesture can say so.
    #[tokio::test]
    async fn rename_by_line_takes_a_taken_name() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();
        ledger
            .record_spawn("first", "ws-1", "/proj", "card-A", 1_000, "line-A", None)
            .unwrap();
        ledger
            .record_spawn("second", "ws-1", "/proj", "card-B", 1_000, "line-B", None)
            .unwrap();
        ledger.rename("line-A", Some("harbor light")).unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "rename_session",
            "line_id": "line-B",
            "name": "harbor light",
        }))
        .unwrap();
        sup.handle_control("rename_session", &payload, 10)
            .await
            .expect_handled();

        let ack = drain_until_action(&mut rx, "rename_session_ok");
        assert_eq!(ack["line_id"], "line-B");
        assert_eq!(ack["displaced"][0]["line_id"], serde_json::json!("line-A"));
        assert_eq!(
            ack["displaced"][0]["tag"],
            serde_json::json!(
                ledger
                    .get("first")
                    .unwrap()
                    .unwrap()
                    .tag
                    .expect("the displaced line wears a callsign")
            )
        );

        // The name moved: the previous holder lost it, the renamed line wears
        // it.
        assert_eq!(ledger.get("first").unwrap().unwrap().name, None);
        assert!(!ledger.get("first").unwrap().unwrap().name_user_set);
        assert_eq!(
            ledger.get("second").unwrap().unwrap().name.as_deref(),
            Some("harbor light")
        );
    }

    /// The name lands on the **line**, so every segment of it reads the new
    /// name — including one recorded after the rename. That is the whole
    /// point of addressing the write by line: a card that rotates its claude
    /// id mid-conversation does not go back to being untitled.
    #[tokio::test]
    async fn a_rename_lands_on_the_line_and_every_segment_reads_it() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();
        ledger
            .record_spawn("root", "ws-1", "/proj", "card-A", 1_000, "line-A", None)
            .unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "rename_session",
            "line_id": "line-A",
            "name": "harbor light",
        }))
        .unwrap();
        sup.handle_control("rename_session", &payload, 10)
            .await
            .expect_handled();
        drain_until_action(&mut rx, "rename_session_ok");

        // A rotation joins the line after the rename has already landed.
        ledger
            .record_spawn("stage", "ws-1", "/proj", "card-A", 2_000, "line-A", None)
            .unwrap();
        assert_eq!(
            ledger.get("stage").unwrap().unwrap().name.as_deref(),
            Some("harbor light"),
            "the segment reads the line's name through the join"
        );
        assert_eq!(
            ledger.get("root").unwrap().unwrap().name.as_deref(),
            Some("harbor light")
        );
    }

    /// `list_card_bindings` returns every non-failed row carrying a
    /// `card_id`, including rows with `turn_count == 0`. The wire
    /// shape includes `turn_count` so the client can branch:
    /// `mode=resume` for rows with history (claude has a JSONL),
    /// `mode=new` for zero-turn rows (no JSONL but the card→project
    /// binding should be preserved across relaunches).
    #[tokio::test]
    async fn list_card_bindings_returns_all_card_rows_with_turn_count() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();

        // A card whose user picked Start Fresh and quit before any
        // prompt: spawned (record_spawn fires on session_init) but
        // never had a turn.
        ledger
            .record_spawn(
                "empty",
                "ws-1",
                "/proj/alpha",
                "card-A",
                1_000,
                "empty",
                None,
            )
            .unwrap();
        ledger.mark_closed("empty").unwrap();

        // A card with a real conversation (count from the engine reconcile).
        ledger
            .record_spawn("real", "ws-1", "/proj/beta", "card-B", 2_000, "real", None)
            .unwrap();
        ledger.set_turn_count("real", 1, 3_000).unwrap();
        ledger.mark_closed("real").unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_card_bindings",
        }))
        .unwrap();
        sup.handle_control("list_card_bindings", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_card_bindings_ok");
        let bindings = response["bindings"].as_array().expect("bindings array");
        assert_eq!(
            bindings.len(),
            2,
            "both rows surface — client decides resume vs new on turn_count. \
             response: {response}",
        );
        let by_card: std::collections::HashMap<&str, &serde_json::Value> = bindings
            .iter()
            .map(|b| (b["card_id"].as_str().unwrap(), b))
            .collect();
        let empty = by_card["card-A"];
        assert_eq!(empty["session_id"], "empty");
        assert_eq!(empty["project_dir"], "/proj/alpha");
        assert_eq!(empty["turn_count"], 0);
        let real = by_card["card-B"];
        assert_eq!(real["session_id"], "real");
        assert_eq!(real["project_dir"], "/proj/beta");
        assert_eq!(real["turn_count"], 1);

        // Both rows are mark_closed and never live-registered in the
        // in-memory supervisor map, so neither is "alive". The flag
        // must still appear on the wire (consumers gate on it).
        assert_eq!(empty["is_alive"], false);
        assert_eq!(real["is_alive"], false);
    }

    /// A card that has lived through several claude ids is **one** binding,
    /// seated on the segment a restore should resume ([P06]) and carrying the
    /// line's identity and the line's summed turns ([P01]). Eight bindings for
    /// one card is the shape this model exists to remove.
    #[tokio::test]
    async fn list_card_bindings_returns_one_row_per_line_seated_on_the_resume_segment() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();

        // The line's root: closed, with turns of its own.
        ledger
            .record_spawn("root", "ws-1", "/proj", "card-A", 1_000, "line-A", None)
            .unwrap();
        ledger.set_turn_count("root", 4, 1_500).unwrap();
        ledger.mark_closed("root").unwrap();
        // A stage the card rotated into, still live and used later.
        ledger
            .record_spawn("stage", "ws-1", "/proj", "card-A", 2_000, "line-A", None)
            .unwrap();
        ledger.set_turn_count("stage", 3, 2_500).unwrap();
        ledger.rename("line-A", Some("harbor light")).unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_card_bindings",
        }))
        .unwrap();
        sup.handle_control("list_card_bindings", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_card_bindings_ok");
        let bindings = response["bindings"].as_array().expect("bindings array");
        assert_eq!(bindings.len(), 1, "one line, one binding: {response}");
        let binding = &bindings[0];
        assert_eq!(binding["card_id"], "card-A");
        assert_eq!(binding["line_id"], "line-A");
        assert_eq!(
            binding["session_id"], "stage",
            "the live segment is the resume target"
        );
        assert_eq!(
            binding["turn_count"], 7,
            "the line's turns, not the seated segment's"
        );
        assert_eq!(binding["name"], "harbor light");
        assert_eq!(
            binding["tag"],
            serde_json::json!(
                ledger
                    .get_line("line-A")
                    .unwrap()
                    .expect("the line exists")
                    .tag
            )
        );
    }

    /// `resolve_sessions { ids }` answers both ways in one frame — the found
    /// rows keyed by what was asked, and the misses named as misses so the
    /// client can cache a negative instead of re-asking on every repaint
    /// ([D132]).
    #[tokio::test]
    async fn resolve_sessions_answers_hits_and_misses_in_one_frame() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();
        let full = "f6e43925-1a2b-4c3d-8e9f-0a1b2c3d4e5f";
        ledger
            .record_spawn(
                full,
                "ws-1",
                "/proj/alpha",
                "card-A",
                1_000,
                full,
                Some("stocky-pixie"),
            )
            .unwrap();

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "resolve_sessions",
            // The full uuid a `Tug-Session-Id` carries, the 8-char token a
            // citation carries, and a session written on another machine.
            "ids": [full, "f6e43925", "0badf00d"],
        }))
        .unwrap();
        sup.handle_control("resolve_sessions", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "resolve_sessions_ok");
        let sessions = response["sessions"].as_array().expect("sessions array");
        assert_eq!(sessions.len(), 2, "response: {response}");
        // Keyed by the asked-for spelling; the row carries the whole identity,
        // callsign included, so the chip renders the ledger's own word.
        assert_eq!(sessions[0]["queried"], full);
        assert_eq!(sessions[0]["session"]["session_id"], full);
        assert_eq!(sessions[0]["session"]["tag"], "stocky-pixie");
        assert_eq!(sessions[1]["queried"], "f6e43925");
        assert_eq!(sessions[1]["session"]["session_id"], full);
        // The miss is stated rather than merely omitted.
        assert_eq!(
            response["unknown"].as_array().expect("unknown array"),
            &vec![serde_json::json!("0badf00d")],
        );
    }

    /// A malformed request is refused, and a well-formed one naming nothing is
    /// answered — a client sitting on `pending` forever is the one outcome with
    /// no rendering at all.
    #[tokio::test]
    async fn resolve_sessions_refuses_a_malformed_payload_and_answers_an_empty_one() {
        let (sup, _ledger, mut rx) = make_supervisor_with_ledger();
        let bad = serde_json::to_vec(&serde_json::json!({
            "action": "resolve_sessions",
        }))
        .unwrap();
        assert!(matches!(
            sup.handle_control("resolve_sessions", &bad, 10).await,
            ControlOutcome::Error(_),
        ));

        let empty = serde_json::to_vec(&serde_json::json!({
            "action": "resolve_sessions",
            "ids": [],
        }))
        .unwrap();
        sup.handle_control("resolve_sessions", &empty, 10)
            .await
            .expect_handled();
        let response = drain_until_action(&mut rx, "resolve_sessions_ok");
        assert!(response["sessions"].as_array().expect("array").is_empty());
        assert!(response["unknown"].as_array().expect("array").is_empty());
    }

    /// `list_shell_exchanges { tug_session_id }` broadcasts
    /// `list_shell_exchanges_ok { tug_session_id, exchanges: [...] }` with the
    /// session's rows oldest-first — the deck's shell-restore tail read.
    #[tokio::test]
    async fn list_shell_exchanges_returns_the_session_tail() {
        // Build a supervisor with a shell ledger holding two exchanges.
        let shell_ledger = Arc::new(crate::shell_ledger::ShellLedger::open_in_memory().unwrap());
        for (cmd, code) in [("echo a", Some(0)), ("false", Some(1))] {
            shell_ledger
                .record_exchange(&crate::shell_ledger::NewShellExchange {
                    tug_session_id: "s1".to_string(),
                    line_id: "s1".to_string(),
                    command: cmd.to_string(),
                    output: format!("out:{cmd}\n"),
                    exit_code: code,
                    cwd: "/proj".to_string(),
                    cwd_after: Some("/proj".to_string()),
                    started_at_ms: 1,
                    settled_at_ms: 2,
                    anchor_msg_id: None,
                })
                .unwrap();
        }

        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let (state_tx, _s) = broadcast::channel(64);
        let (meta_tx, _m) = broadcast::channel(8);
        let (code_tx, _c) = broadcast::channel(8);
        let (control_tx, mut rx) = broadcast::channel(128);
        let recorder: Arc<dyn SessionsRecorder> = Arc::new(LedgerSessionsRecorder::with_broadcast(
            Arc::clone(&ledger),
            control_tx.clone(),
        ));
        let (mut sup, mut register_rx) = AgentSupervisor::new_with_ledger(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            Some(Arc::clone(&ledger)),
            stall_spawner_factory(),
            AgentSupervisorConfig::default(),
            Arc::new(WorkspaceRegistry::new_for_test()),
            CancellationToken::new(),
        );
        sup.set_shell_ledger(Arc::clone(&shell_ledger));
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_shell_exchanges",
            "tug_session_id": "s1",
        }))
        .unwrap();
        sup.handle_control("list_shell_exchanges", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_shell_exchanges_ok");
        assert_eq!(response["tug_session_id"], "s1");
        let exchanges = response["exchanges"].as_array().expect("exchanges array");
        assert_eq!(exchanges.len(), 2);
        // Oldest-first.
        assert_eq!(exchanges[0]["command"], "echo a");
        assert_eq!(exchanges[0]["exit_code"], 0);
        assert_eq!(exchanges[1]["command"], "false");
        assert_eq!(exchanges[1]["exit_code"], 1);
        assert_eq!(exchanges[1]["seq"], 2);
    }

    /// `list_refs { tug_session_id }` broadcasts `list_refs_ok
    /// { tug_session_id, run }` carrying the session's latest completed run —
    /// the deck's refs-restore read. A session that has never searched gets a
    /// null run rather than an error.
    #[tokio::test]
    async fn list_refs_returns_the_sessions_latest_run() {
        let refs_ledger = Arc::new(crate::refs_ledger::RefsLedger::open_in_memory().unwrap());
        refs_ledger
            .record_run(&crate::refs_ledger::NewRefsRun {
                tug_session_id: "s1".to_string(),
                line_id: "s1".to_string(),
                run_id: "run-1".to_string(),
                op_kind: "search".to_string(),
                command: "/search needle".to_string(),
                refs: vec![crate::feeds::text_ref::TextRef::content(
                    1,
                    "src/a.ts",
                    12,
                    vec![(4, 10)],
                    crate::feeds::text_ref::LinePreview::whole("    needle"),
                )],
                settled_at_ms: 7,
                anchor_msg_id: None,
            })
            .unwrap();

        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let (state_tx, _s) = broadcast::channel(64);
        let (meta_tx, _m) = broadcast::channel(8);
        let (code_tx, _c) = broadcast::channel(8);
        let (control_tx, mut rx) = broadcast::channel(128);
        let recorder: Arc<dyn SessionsRecorder> = Arc::new(LedgerSessionsRecorder::with_broadcast(
            Arc::clone(&ledger),
            control_tx.clone(),
        ));
        let (mut sup, mut register_rx) = AgentSupervisor::new_with_ledger(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            Some(Arc::clone(&ledger)),
            stall_spawner_factory(),
            AgentSupervisorConfig::default(),
            Arc::new(WorkspaceRegistry::new_for_test()),
            CancellationToken::new(),
        );
        sup.set_refs_ledger(Arc::clone(&refs_ledger));
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });

        let ask = |session: &str| {
            serde_json::to_vec(&serde_json::json!({
                "action": "list_refs",
                "tug_session_id": session,
            }))
            .unwrap()
        };

        sup.handle_control("list_refs", &ask("s1"), 10)
            .await
            .expect_handled();
        let response = drain_until_action(&mut rx, "list_refs_ok");
        assert_eq!(response["tug_session_id"], "s1");
        assert_eq!(response["run"]["run_id"], "run-1");
        assert_eq!(response["run"]["op_kind"], "search");
        assert_eq!(response["run"]["refs"][0]["path"], "src/a.ts");
        assert_eq!(response["run"]["refs"][0]["line"], 12);
        assert_eq!(
            response["run"]["refs"][0]["columns"],
            serde_json::json!([[4, 10]]),
        );

        sup.handle_control("list_refs", &ask("s-never"), 10)
            .await
            .expect_handled();
        let empty = drain_until_action(&mut rx, "list_refs_ok");
        assert!(empty["run"].is_null());
    }

    /// `list_overview_posts` broadcasts `list_overview_posts_ok { posts: [...] }`
    /// oldest-first — the Overview card's mount-time tail, after which it stays
    /// live off the OVERVIEW feed. App-scoped: the channel belongs to the app,
    /// not to a session, so the request carries no session id.
    #[tokio::test]
    async fn list_overview_posts_returns_the_channel_tail() {
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        for body in ["the older post", "the newer post"] {
            ledger
                .record_overview_post(&tugcast_core::OverviewPost {
                    id: None,
                    at_ms: 1,
                    author: tugcast_core::OverviewAuthor::Observer,
                    session_id: Some("s1".to_string()),
                    wake_reason: Some("turn-end".to_string()),
                    body: body.to_string(),
                    refs: Vec::new(),
                    elapsed_ms: None,
                    project_dir: None,
                    attachments: Vec::new(),
                    request_id: None,
                    transient: false,
                })
                .unwrap();
        }

        let (state_tx, _s) = broadcast::channel(64);
        let (meta_tx, _m) = broadcast::channel(8);
        let (code_tx, _c) = broadcast::channel(8);
        let (control_tx, mut rx) = broadcast::channel(128);
        let recorder: Arc<dyn SessionsRecorder> = Arc::new(LedgerSessionsRecorder::with_broadcast(
            Arc::clone(&ledger),
            control_tx.clone(),
        ));
        let (sup, mut register_rx) = AgentSupervisor::new_with_ledger(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            Some(Arc::clone(&ledger)),
            stall_spawner_factory(),
            AgentSupervisorConfig::default(),
            Arc::new(WorkspaceRegistry::new_for_test()),
            CancellationToken::new(),
        );
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_overview_posts",
        }))
        .unwrap();
        sup.handle_control("list_overview_posts", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_overview_posts_ok");
        let posts = response["posts"].as_array().expect("posts array");
        assert_eq!(posts.len(), 2);
        assert_eq!(posts[0]["body"], "the older post");
        assert_eq!(posts[1]["body"], "the newer post");
        assert_eq!(posts[1]["author"], "observer");
        assert_eq!(posts[1]["wake_reason"], "turn-end");
        assert!(
            posts[1]["id"].is_i64(),
            "a persisted post carries its rowid onto the wire",
        );
    }

