    /// A `changeset_commit` with a `session_id` persists exactly one `/commit`
    /// row to the shell ledger whose `output` is the server-formatted summary
    /// echoed on `changeset_commit_ok` ([P07], S02); a commit without a
    /// `session_id` writes no row (R02).
    #[tokio::test]
    async fn changeset_commit_persists_the_landing_to_the_shell_ledger() {
        fn git(dir: &std::path::Path, args: &[&str]) {
            let out = std::process::Command::new("git")
                .arg("-C")
                .arg(dir)
                .args(args)
                .output()
                .expect("run git");
            assert!(
                out.status.success(),
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&out.stderr)
            );
        }

        let temp = tempfile::tempdir().expect("tempdir");
        let repo = temp.path().canonicalize().expect("canonicalize");
        git(&repo, &["init", "-q", "-b", "main"]);
        git(&repo, &["config", "user.email", "t@t"]);
        git(&repo, &["config", "user.name", "t"]);
        std::fs::write(repo.join("a.txt"), "one\n").unwrap();
        git(&repo, &["add", "."]);
        git(&repo, &["commit", "-q", "-m", "init"]);

        let shell_ledger = Arc::new(crate::shell_ledger::ShellLedger::open_in_memory().unwrap());
        let ledger = Arc::new(SessionLedger::open_in_memory().expect("ledger open"));
        let (state_tx, _s) = broadcast::channel(64);
        let (meta_tx, _m) = broadcast::channel(8);
        let (code_tx, _c) = broadcast::channel(8);
        let (control_tx, mut rx) = broadcast::channel(128);
        let recorder: Arc<dyn SessionsRecorder> = Arc::new(LedgerSessionsRecorder::with_broadcast(
            Arc::clone(&ledger),
            control_tx.clone(),
        ));
        let registry = Arc::new(WorkspaceRegistry::new_for_test());
        registry
            .get_or_create(&repo, CancellationToken::new())
            .expect("register repo");
        let (mut sup, mut register_rx) = AgentSupervisor::new_with_ledger(
            SessionScopedFeed::from_sender(FeedId::SESSION_STATE, state_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::SESSION_SIDEBAND, meta_tx, LagPolicy::Warn),
            SessionScopedFeed::from_sender(FeedId::CODE_OUTPUT, code_tx, LagPolicy::Warn),
            SessionScopedFeed::new(FeedId::ACTIVITY, 64, LagPolicy::Warn),
            control_tx,
            recorder,
            Some(Arc::clone(&ledger)),
            stall_spawner_factory(),
            AgentSupervisorConfig::default(),
            registry,
            CancellationToken::new(),
        );
        sup.set_shell_ledger(Arc::clone(&shell_ledger));
        tokio::spawn(async move { while register_rx.recv().await.is_some() {} });

        // Commit with a session_id → one ledger row keyed by the session.
        std::fs::write(repo.join("a.txt"), "one\ntwo\n").unwrap();
        let request = ChangesetCommitPayload {
            project_dir: repo.to_string_lossy().into_owned(),
            files: vec!["a.txt".to_string()],
            message: "Add a second line".to_string(),
            session_id: Some("sess".to_string()),
            hunks: None,
        };
        sup.do_changeset_commit(&request).await;

        let ok = drain_until_action(&mut rx, "changeset_commit_ok");
        let summary = ok["summary"].as_str().expect("summary on _ok");
        assert!(summary.starts_with("committed "), "summary: {summary}");
        assert!(summary.contains("1 file(s) · +1 −0"), "summary: {summary}");

        let rows = shell_ledger
            .list_exchanges_since("sess", None)
            .expect("list");
        assert_eq!(rows.len(), 1, "exactly one /commit row");
        assert_eq!(rows[0].command, "/commit");
        assert_eq!(rows[0].exit_code, Some(0));
        assert_eq!(rows[0].cwd, request.project_dir);
        // The ledger row's output is byte-identical to the live summary.
        assert_eq!(rows[0].output, summary);

        // A commit without a session_id writes no row.
        std::fs::write(repo.join("a.txt"), "one\ntwo\nthree\n").unwrap();
        let bare = ChangesetCommitPayload {
            project_dir: repo.to_string_lossy().into_owned(),
            files: vec!["a.txt".to_string()],
            message: "Add a third line".to_string(),
            session_id: None,
            hunks: None,
        };
        sup.do_changeset_commit(&bare).await;
        let _ = drain_until_action(&mut rx, "changeset_commit_ok");
        assert_eq!(
            shell_ledger
                .list_exchanges_since("sess", None)
                .expect("list")
                .len(),
            1,
            "the session-less commit added no ledger row",
        );
    }

    /// `list_card_bindings` reports `is_alive: true` for a session
    /// whose subprocess entry in the in-memory ledger is in the
    /// `Spawning` or `Live` state. This is the third signal the client
    /// uses to decide `mode=resume` for an **in-flight first turn** —
    /// a session that has zero committed turns (`turn_count == 0`) but
    /// holds an active claude subprocess with mid-turn state (e.g. a
    /// pending `AskUserQuestion`). Without `is_alive`, the client's
    /// `turn_count`-only gate would mistake the in-flight case for
    /// "Start Fresh + quit" and spawn a fresh session, orphaning the
    /// live one.
    #[tokio::test]
    async fn list_card_bindings_reports_is_alive_for_live_sessions() {
        let (sup, ledger, mut rx) = make_supervisor_with_ledger();

        // Two rows in sqlite, both with `turn_count == 0`. The
        // difference between them is whether the in-memory ledger
        // entry exists in a Live state.
        ledger
            .record_spawn(
                "live",
                "ws-1",
                "/proj/alive",
                "card-Live",
                1_000,
                "live",
                None,
            )
            .unwrap();
        ledger
            .record_spawn(
                "dead",
                "ws-1",
                "/proj/dead",
                "card-Dead",
                2_000,
                "dead",
                None,
            )
            .unwrap();

        // Promote "live" into the supervisor's in-memory ledger as
        // `Live`. "dead" stays out of the map — its sqlite row is the
        // only trace.
        {
            let mut map = sup.ledger.lock().await;
            let entry = LedgerEntry {
                spawn_state: SpawnState::Live,
                ..LedgerEntry::new(
                    TugSessionId("live".to_string()),
                    WorkspaceKey::from_test_str("ws-1"),
                    std::path::PathBuf::from("/proj/alive"),
                    SessionMode::New,
                    CrashBudget::new(3, std::time::Duration::from_secs(60)),
                )
            };
            map.insert(
                TugSessionId("live".to_string()),
                std::sync::Arc::new(tokio::sync::Mutex::new(entry)),
            );
        }

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_card_bindings",
        }))
        .unwrap();
        sup.handle_control("list_card_bindings", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_card_bindings_ok");
        let bindings = response["bindings"].as_array().expect("bindings array");
        let by_card: std::collections::HashMap<&str, &serde_json::Value> = bindings
            .iter()
            .map(|b| (b["card_id"].as_str().unwrap(), b))
            .collect();
        let live = by_card["card-Live"];
        let dead = by_card["card-Dead"];
        assert_eq!(live["turn_count"], 0);
        assert_eq!(live["is_alive"], true);
        assert_eq!(dead["turn_count"], 0);
        assert_eq!(dead["is_alive"], false);
    }

    /// `list_card_bindings` reports `has_jsonl: true` for a session whose
    /// on-disk transcript exists under `claude_projects_root`, and `false`
    /// for one with no file — the reliable resume signal, independent of the
    /// ledger's `turn_count`. The regression it guards: a session with a
    /// transcript but `turn_count == 0` (claude wrote the JSONL outside a
    /// live `record_turn`) was mis-routed on restore to a `mode=new` spawn
    /// whose `--session-id` collided and crash-looped the card to `errored`.
    #[tokio::test]
    async fn list_card_bindings_reports_has_jsonl_from_disk() {
        let tmp = tempfile::tempdir().unwrap();
        let claude_root = tmp.path().join("projects");
        let ledger = Arc::new(
            SessionLedger::open_with_claude_root(
                tmp.path().join("sessions.db"),
                claude_root.clone(),
            )
            .unwrap(),
        );
        let (sup, ledger, mut rx) = make_supervisor_for_ledger(ledger, None);

        // Both rows have `turn_count == 0`; only "withfile" has a transcript
        // on disk.
        ledger
            .record_spawn(
                "withfile",
                "ws-1",
                "/proj/withfile",
                "card-With",
                1_000,
                "withfile",
                None,
            )
            .unwrap();
        ledger
            .record_spawn(
                "nofile",
                "ws-1",
                "/proj/nofile",
                "card-No",
                2_000,
                "nofile",
                None,
            )
            .unwrap();
        seed_external_jsonl(&claude_root, "/proj/withfile", "withfile", "resume me");

        let payload = serde_json::to_vec(&serde_json::json!({
            "action": "list_card_bindings",
        }))
        .unwrap();
        sup.handle_control("list_card_bindings", &payload, 10)
            .await
            .expect_handled();

        let response = drain_until_action(&mut rx, "list_card_bindings_ok");
        let bindings = response["bindings"].as_array().expect("bindings array");
        let by_card: std::collections::HashMap<&str, &serde_json::Value> = bindings
            .iter()
            .map(|b| (b["card_id"].as_str().unwrap(), b))
            .collect();
        assert_eq!(by_card["card-With"]["turn_count"], 0);
        assert_eq!(
            by_card["card-With"]["has_jsonl"], true,
            "a session with an on-disk transcript reports has_jsonl"
        );
        assert_eq!(
            by_card["card-No"]["has_jsonl"], false,
            "a session with no transcript reports has_jsonl false"
        );
    }

    /// [`AgentSupervisor::session_is_content_empty`] — the predicate that
    /// routes a spawn away from `resume`. It answers `true` only when the
    /// ledger row holds nothing AND no transcript exists on disk; either
    /// signal of content keeps the session resumable.
    #[tokio::test]
    async fn session_is_content_empty_needs_both_a_blank_row_and_no_transcript() {
        let tmp = tempfile::tempdir().unwrap();
        let claude_root = tmp.path().join("projects");
        let ledger = Arc::new(
            SessionLedger::open_with_claude_root(
                tmp.path().join("sessions.db"),
                claude_root.clone(),
            )
            .unwrap(),
        );
        let (sup, ledger, _rx) = make_supervisor_for_ledger(ledger, None);

        // Never prompted, no transcript — the abandoned session.
        ledger
            .record_spawn(
                "blank",
                "ws-1",
                "/proj/blank",
                "card-1",
                1_000,
                "blank",
                None,
            )
            .unwrap();
        // Never prompted per the ledger, but claude wrote a transcript.
        ledger
            .record_spawn(
                "ondisk",
                "ws-1",
                "/proj/ondisk",
                "card-2",
                2_000,
                "ondisk",
                None,
            )
            .unwrap();
        seed_external_jsonl(&claude_root, "/proj/ondisk", "ondisk", "resume me");
        // No transcript yet, but the ledger recorded the user's prompt.
        ledger
            .record_spawn(
                "prompted",
                "ws-1",
                "/proj/prompted",
                "card-3",
                3_000,
                "prompted",
                None,
            )
            .unwrap();
        ledger.record_user_prompt("prompted", "hello").unwrap();

        assert!(
            sup.session_is_content_empty(&TugSessionId("blank".into()), "/proj/blank"),
            "a blank row with no transcript holds nothing to resume"
        );
        assert!(
            !sup.session_is_content_empty(&TugSessionId("ondisk".into()), "/proj/ondisk"),
            "an on-disk transcript keeps the session resumable"
        );
        assert!(
            !sup.session_is_content_empty(&TugSessionId("prompted".into()), "/proj/prompted"),
            "a recorded prompt keeps the session resumable"
        );
        assert!(
            !sup.session_is_content_empty(&TugSessionId("unknown".into()), "/proj/unknown"),
            "a session the ledger has never seen is left to the request's mode"
        );
    }

    /// A `resume` spawn for a session that holds nothing is spawned fresh
    /// under the same id — the card opens instead of failing into the
    /// picker's "couldn't resume the previous session" alert. A session with
    /// content still resumes.
    #[tokio::test]
    async fn spawn_session_resume_of_an_empty_session_spawns_fresh() {
        let tmp = tempfile::tempdir().unwrap();
        let ledger = Arc::new(
            SessionLedger::open_with_claude_root(
                tmp.path().join("sessions.db"),
                tmp.path().join("projects"),
            )
            .unwrap(),
        );
        let (sup, ledger, _rx) = make_supervisor_for_ledger(ledger, None);

        ledger
            .record_spawn(
                "empty",
                "ws-1",
                test_project_dir(),
                "card-1",
                1_000,
                "empty",
                None,
            )
            .unwrap();
        ledger
            .record_spawn(
                "full",
                "ws-1",
                test_project_dir(),
                "card-2",
                2_000,
                "full",
                None,
            )
            .unwrap();
        ledger.record_user_prompt("full", "hello").unwrap();

        sup.handle_control("spawn_session", &resume_payload("card-1", "empty"), 10)
            .await
            .expect_handled();
        sup.handle_control("spawn_session", &resume_payload("card-2", "full"), 10)
            .await
            .expect_handled();

        let modes = {
            let live = sup.ledger.lock().await;
            let mut modes = Vec::new();
            for id in ["empty", "full"] {
                let entry = live
                    .get(&TugSessionId::new(id))
                    .expect("entry")
                    .lock()
                    .await;
                modes.push(entry.session_mode);
            }
            modes
        };
        assert_eq!(
            modes[0],
            SessionMode::New,
            "a session with no content and no transcript is spawned fresh"
        );
        assert_eq!(
            modes[1],
            SessionMode::Resume,
            "a session with recorded content is still resumed"
        );
    }

    /// The `Idle`-entry spawn-mode reconciliation ([`reconcile_idle_session_mode`]):
    /// the client request normally wins, but a `New` request never downgrades an
    /// entry that still holds a persisted `claude_session_id` (that spawn would
    /// `--session-id`-collide with the existing transcript).
    #[test]
    fn reconcile_idle_session_mode_holds_resume_against_a_new_collision() {
        use SessionMode::{New, Resume};
        // The bug shape: rebound as Resume, client (mis)requests New while a
        // claude session id is persisted → hold Resume.
        assert_eq!(reconcile_idle_session_mode(Resume, New, true), Resume);
        // No persisted id (a genuine fresh/discarded session) → honor New.
        assert_eq!(reconcile_idle_session_mode(Resume, New, false), New);
        // A resume request is always honored, id present or not.
        assert_eq!(reconcile_idle_session_mode(New, Resume, true), Resume);
        assert_eq!(reconcile_idle_session_mode(New, Resume, false), Resume);
    }

